                .alert(isPresented: $showingAlert) {
                    Alert(title: Text("Tips"),
                          message: Text(alertMessage),
                          dismissButton: .default(Text("OK")))
                }
            }
        }
        .accentColor(Color(red: 70 / 255, green: 130 / 255, blue: 220 / 255))
