                    .font(.caption2)
                    .foregroundColor(.gray)
                Text(fmt(vm.cashBuyingPower))
                    .font(.subheadline)
                    .foregroundColor(.white.opacity(0.8))
            }
            .frame(maxWidth: .infinity, alignment: .leading)

            // 右侧：今日变动
