    }
    private func fmtChange(_ v: Double) -> String {
        let sign = v >= 0 ? "+" : "−"
        return String(format: "\(sign)$%.0f", abs(v))
    }
    private func fmtPct(_ p: Double) -> String {
        String(format: "(%.2f%%)", p)
    }

