    "name": "TopETFs Scraper",
    "version": "1.0",
    "description": "Scrapes ETF data from Yahoo Finance",
    "permissions": [
        "activeTab",
        "scripting",
        "downloads",
        "storage"
    ],
    "host_permissions": [
        "https://finance.yahoo.com/*"
    ],
    "action": {
        "default_popup": "popup.html"
    },
    "background": {
        "service_worker": "background.js"
    },
    "content_scripts": [
        {
            "matches": [
                "https://finance.yahoo.com/markets/etfs/top/*"
            ],
            "js": [
                "content.js"
            ]
        }
    ]
}

document.addEventListener('DOMContentLoaded', function () {
    const statusDiv = document.getElementById('status');
    // Remove the line below:
    // const startButton = document.getElementById('startScrapeButton');

    function addLogMessage(message, type = 'info') {
        const logItem = document.createElement('div');
        logItem.className = `log-item ${type}`;
        logItem.textContent = message;
        statusDiv.appendChild(logItem);
        statusDiv.scrollTop = statusDiv.scrollHeight; // Auto-scroll to the latest message
    }

    // Add the message sending logic here to start scraping automatically
    addLogMessage('Popup loaded. Starting scraping process automatically.', 'info');
    chrome.runtime.sendMessage({ action: 'startYahooScraping' }, function (response) {
        if (chrome.runtime.lastError) {
            addLogMessage(`Error starting scraping: ${chrome.runtime.lastError.message}`, 'error');
            // If there's an error starting, maybe show a retry message or similar
        } else if (response && response.status === 'started') {
            addLogMessage('Background process for Yahoo ETFs initiated.', 'info');
        } else {
            addLogMessage('Failed to start background process or no response.', 'error');
        }
    });


    // Listen for status updates and CSV download requests
    chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
        if (message.type === 'statusUpdate') { // Changed from 'status' to avoid conflict
            addLogMessage(message.text, message.logType || 'info');
            // Remove the line below:
            // if (message.completed) {
            //     startButton.disabled = false;
            //     startButton.textContent = 'Start Scraping ETFs';
            // }
        } else if (message.type === 'csvData') {
            // This part handles the download triggered by background.js
            const blob = new Blob([message.data], { type: 'text/csv;charset=utf-8;' });
            const url = URL.createObjectURL(blob);

            // Create a temporary link to trigger download
            const a = document.createElement('a');
            a.style.display = 'none';
            a.href = url;
            a.download = message.filename;
            document.body.appendChild(a);
            a.click();

            // Clean up
            setTimeout(() => {
                document.body.removeChild(a);
                URL.revokeObjectURL(url);
                addLogMessage(`Download initiated for "${message.filename}". Check your downloads folder.`, 'success');
            }, 100);
        }
        // It's important to return true if you intend to send a response asynchronously
        // However, in this specific listener, we are mostly receiving, so it might not be strictly necessary
        // unless a specific message type expects a direct response from the popup.
        // For safety and good practice, especially if any message type might need it:
        sendResponse({ received: true });
        return true;
    });
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
    if (message.action === 'scrapeYahooETFs') {
        console.log("Yahoo ETF Scraper: content.js - 'scrapeYahooETFs' action received for URL:", window.location.href);
        try {
            const results = [];
            let targetTable = null;

            // --- 更稳健的表格选择逻辑 ---
            console.log("Yahoo ETF Scraper: content.js - Attempting to find the target table...");

            // 优先尝试1: 通过更具体的 data-testid (如果存在)
            // Yahoo Finance 列表格通常在 <div data-testid="scr-res-table"> 下
            const scrResTableDiv = document.querySelector('div[data-testid="scr-res-table"]');
            if (scrResTableDiv) {
                targetTable = scrResTableDiv.querySelector('table');
                if (targetTable) {
                    console.log("Yahoo ETF Scraper: content.js - Table found via 'scr-res-table' data-testid.");
                }
            }

            // 尝试2: 通过 'top-etfs-table' data-testid (之前的尝试)
            if (!targetTable) {
                const topEtfsTableDiv = document.querySelector('div[data-testid="top-etfs-table"]');
                if (topEtfsTableDiv) {
                    targetTable = topEtfsTableDiv.querySelector('table');
                    if (targetTable) {
                        console.log("Yahoo ETF Scraper: content.js - Table found via 'top-etfs-table' data-testid.");
                    }
                }
            }

            // 尝试3: 查找包含特定表头文本的表格 (更灵活的文本匹配)
            if (!targetTable) {
                console.log("Yahoo ETF Scraper: content.js - Table not found by data-testid, trying header content matching.");
                const tables = document.querySelectorAll('table');
                for (let table of tables) {
                    const headers = Array.from(table.querySelectorAll('thead th'));
                    const headerTexts = headers.map(th => th.textContent.trim().toLowerCase());

                    // 检查是否包含 "symbol" 和 "name" (不区分大小写)
                    const hasSymbolHeader = headerTexts.some(text => text.includes('symbol'));
                    const hasNameHeader = headerTexts.some(text => text.includes('name'));
                    const hasPriceHeader = headerTexts.some(text => text.includes('price')); // 可选，增加确定性
                    const hasBodyRows = table.querySelector('tbody tr');

                    if (hasSymbolHeader && hasNameHeader && hasPriceHeader && hasBodyRows) {
                        targetTable = table;
                        console.log("Yahoo ETF Scraper: content.js - Target table found by flexible header text matching.");
                        break;
                    }
                }
            }

            // 尝试4: 查找页面上主要的、包含多行数据的表格 (作为最后的备选)
            // 这个选择器 W(100%) 是 Yahoo Finance 中常见的表格宽度类，但仍需谨慎
            if (!targetTable) {
                console.log("Yahoo ETF Scraper: content.js - Table still not found, trying class 'W(100%)' and row count.");
                const tables = document.querySelectorAll('table.W\\(100\\%\\)'); // 需要转义括号
                if (tables.length === 1 && tables[0].querySelector('tbody tr')) { // 如果页面只有一个这样的主表格
                    targetTable = tables[0];
                    console.log("Yahoo ETF Scraper: content.js - Table found by single 'W(100%)' class.");
                } else if (tables.length > 0) { // 如果有多个，选包含最多数据行的那个
                    let maxRows = 0;
                    let potentialTable = null;
                    tables.forEach(tbl => {
                        const rowCount = tbl.querySelectorAll('tbody tr').length;
                        if (rowCount > maxRows) {
                            maxRows = rowCount;
                            potentialTable = tbl;
                        }
                    });
                    if (potentialTable && maxRows > 0) { // 至少要有一行数据
                        targetTable = potentialTable;
                        console.log(`Yahoo ETF Scraper: content.js - Table found by 'W(100%)' class and max rows (${maxRows}).`);
                    }
                }
            }


            if (targetTable) {
                console.log("Yahoo ETF Scraper: content.js - Target table identified:", targetTable);
                const rows = targetTable.querySelectorAll('tbody tr');
                console.log(`Yahoo ETF Scraper: content.js - Found ${rows.length} rows in the table.`);

                rows.forEach((row, rowIndex) => {
                    try {
                        const cells = row.querySelectorAll('td');
                        if (cells.length === 0) {
                            // console.warn(`Yahoo ETF Scraper: content.js - Row ${rowIndex} has no cells, skipping.`);
                            return;
                        }

                        let symbol = null, name = null, price = null, volume = null;

                        // --- 数据提取逻辑 (使用 aria-label 辅助定位，如果存在) ---
                        // Symbol (通常在第一列)
                        const symbolCell = row.querySelector('td[aria-label="Symbol"]') || cells[0];
                        if (symbolCell) {
                            const symbolLink = symbolCell.querySelector('a[data-testid="table-cell-ticker"]');
                            if (symbolLink) {
                                const symbolSpan = symbolLink.querySelector('span.symbol');
                                symbol = symbolSpan ? symbolSpan.textContent.trim() : symbolLink.textContent.trim();
                            } else { // 如果没有链接，直接取单元格文本
                                symbol = symbolCell.textContent.trim();
                            }
                        }

                        // Name (通常在第二列)
                        const nameCell = row.querySelector('td[aria-label="Name"]') || cells[1];
                        if (nameCell) {
                            const nameDiv = nameCell.querySelector('div[title]');
                            name = nameDiv ? nameDiv.getAttribute('title').trim() : nameCell.textContent.trim();
                        }

                        // Price (查找包含 fin-streamer[data-field="regularMarketPrice"])
                        // 遍历所有单元格，直到找到包含价格的 fin-streamer
                        for (let i = 0; i < cells.length; i++) {
                            const priceStreamer = cells[i].querySelector('fin-streamer[data-field="regularMarketPrice"]');
                            if (priceStreamer) {
                                price = priceStreamer.getAttribute('data-value');
                                break;
                            }
                        }

                        // Volume (查找包含 fin-streamer[data-field="regularMarketVolume"])
                        for (let i = 0; i < cells.length; i++) {
                            const volumeStreamer = cells[i].querySelector('fin-streamer[data-field="regularMarketVolume"]');
                            if (volumeStreamer) {
                                volume = volumeStreamer.getAttribute('data-value');
                                break;
                            }
                        }

                        if (volume) {
                            volume = volume.replace(/,/g, '');
                        }

                        // console.log(`Yahoo ETF Scraper: content.js - Row ${rowIndex}: Symbol='${symbol}', Name='${name}', Price='${price}', Volume='${volume}'`);

                        if (symbol && name && price && volume) {
                            results.push({ symbol, name, price, volume });
                        } else {
                            // console.warn(`Yahoo ETF Scraper: content.js - Row ${rowIndex}: Missing some data. S:${symbol}, N:${name}, P:${price}, V:${volume}`);
                        }
                    } catch (e) {
                        console.error(`Yahoo ETF Scraper: content.js - Error processing row ${rowIndex}:`, e, row.innerHTML);
                    }
                });
                console.log(`Yahoo ETF Scraper: content.js - Successfully processed ${results.length} ETFs from this page.`);
                sendResponse({ success: true, data: results });
            } else {
                console.error("Yahoo ETF Scraper: content.js - Target table NOT found after all attempts for URL:", window.location.href);
                sendResponse({ success: false, error: 'Could not find the target ETF table on the page.' });
            }
        } catch (error) {
            console.error('Yahoo ETF Scraper: content.js - Critical error in scrapeYahooETFs:', error);
            sendResponse({ success: false, error: error.message });
        }
        return true;
    }
});

// Array to store scraped data
let allYahooETFData = [];

// Function to update status in popup
function updatePopupStatus(text, logType = 'info', completed = false) {
    chrome.runtime.sendMessage({
        type: 'statusUpdate', // Changed from 'status'
        text: text,
        logType: logType, // Changed from 'status'
        completed: completed
    }).catch(error => console.log("Error sending status to popup:", error)); // Catch if popup is not open
}

// Function to scrape data from a tab for Yahoo Finance
async function scrapeYahooETFFromTab(tabId, url) {
    try {
        updatePopupStatus(`Navigating to ${url}`, 'info');
        // Navigate to the URL
        await chrome.tabs.update(tabId, { url: url });

        // Wait for the page to load - Yahoo can be slow and dynamic
        // Consider a more robust wait if needed (e.g., waiting for a specific element)
        await new Promise(resolve => {
            const listener = (tabIdUpdated, changeInfo) => {
                if (tabIdUpdated === tabId && changeInfo.status === 'complete') {
                    chrome.tabs.onUpdated.removeListener(listener);
                    // Additional delay for dynamic content loading
                    setTimeout(resolve, 5000); // Increased delay for Yahoo
                }
            };
            chrome.tabs.onUpdated.addListener(listener);
        });

        updatePopupStatus(`Page loaded: ${url}. Attempting to scrape...`, 'info');
        // Execute content script to scrape data
        const results = await chrome.tabs.sendMessage(tabId, { action: 'scrapeYahooETFs' });

        if (results && results.success) {
            updatePopupStatus(`Successfully scraped ${results.data.length} ETFs from ${url}`, 'success');
            allYahooETFData = [...allYahooETFData, ...results.data];
            return true;
        } else {
            const errorMsg = results ? results.error : "No response from content script.";
            updatePopupStatus(`Failed to scrape data from ${url}: ${errorMsg}`, 'error');
            return false;
        }
    } catch (error) {
        updatePopupStatus(`Error scraping from ${url}: ${error.message}`, 'error');
        console.error(`Error in scrapeYahooETFFromTab for ${url}:`, error);
        return false;
    }
}

// Function to generate CSV from data
function generateETFCSV(data) {
    // CSV header
    let csv = 'Symbol,Name,Price,Volume\n';

    // Add each row
    data.forEach(item => {
        const symbol = item.symbol ? `"${item.symbol.replace(/"/g, '""')}"` : '';
        const name = item.name ? `"${item.name.replace(/"/g, '""')}"` : '';
        const price = item.price ? `"${item.price.replace(/"/g, '""')}"` : '';
        const volume = item.volume ? `"${item.volume.replace(/"/g, '""')}"` : '';
        csv += `${symbol},${name},${price},${volume}\n`;
    });
    return csv;
}

// Function to send CSV data to popup for download
function downloadCSVViaPopup(csvData, filename) {
    chrome.runtime.sendMessage({
        type: 'csvData',
        data: csvData,
        filename: filename
    }).catch(error => {
        updatePopupStatus(`Error sending CSV to popup for download: ${error.message}. You might need to open the popup.`, 'error');
        // Fallback or alternative download method could be implemented here if needed
        // For now, we'll just log it.
        console.error("Error sending CSV to popup:", error);
    });
}


// Main function to coordinate the Yahoo ETF scraping process
async function startYahooScrapingProcess() {
    updatePopupStatus('Starting Yahoo ETF scraping process...', 'info');
    allYahooETFData = []; // Reset data for a new scrape

    let tab;
    try {
        // Create a new tab for scraping. It's better to keep it active for debugging.
        // For production, you might set active: false, but ensure content scripts still work.
        tab = await chrome.tabs.create({ active: false, url: 'about:blank' });

        const urls = [
            "https://finance.yahoo.com/markets/etfs/top/?start=0&count=100",
            "https://finance.yahoo.com/markets/etfs/top/?start=100&count=100",
            "https://finance.yahoo.com/markets/etfs/top/?start=200&count=100",
            "https://finance.yahoo.com/markets/etfs/top/?start=300&count=100",
            "https://finance.yahoo.com/markets/etfs/top/?start=400&count=100",
            "https://finance.yahoo.com/markets/etfs/top/?start=500&count=100"
        ];

        for (const url of urls) {
            const success = await scrapeYahooETFFromTab(tab.id, url);
            if (!success) {
                updatePopupStatus(`Skipping remaining URLs due to error on ${url}.`, 'error');
                break; // Optional: stop if one page fails
            }
            // Optional: add a small delay between page loads if needed
            await new Promise(resolve => setTimeout(resolve, 1000));
        }

        if (allYahooETFData.length > 0) {
            updatePopupStatus(`Generating CSV with ${allYahooETFData.length} ETF records...`, 'info');
            const csv = generateETFCSV(allYahooETFData);
            const now = new Date();
            const year = now.getFullYear().toString().slice(-2); // 获取年份的后两位，例如 2025 -> 25
            const month = (now.getMonth() + 1).toString().padStart(2, '0'); // 获取月份 (0-11)，所以 +1，并补零到两位，例如 5 -> 05
            const day = now.getDate().toString().padStart(2, '0'); // 获取日期，并补零到两位，例如 21 -> 21
            const timestamp = `${year}${month}${day}`; // 拼接成 YYMMDD 格式，例如 250521
            const filename = `topetf_${timestamp}.csv`;

            // Instead of chrome.downloads.download, send to popup.js
            downloadCSVViaPopup(csv, filename);
            // updatePopupStatus(`CSV file "${filename}" download initiated via popup.`, 'success', true); // This message is now in popup.js
        } else {
            updatePopupStatus('No ETF data was scraped. Cannot generate CSV.', 'error', true);
        }

    } catch (error) {
        updatePopupStatus(`Critical error in Yahoo ETF scraping process: ${error.message}`, 'error', true);
        console.error("Critical error in startYahooScrapingProcess:", error);
    } finally {
        if (tab && tab.id) {
            try {
                // Optional: close the tab after scraping is done or if an error occurs
                // For debugging, you might want to leave it open.
                await chrome.tabs.remove(tab.id);
                updatePopupStatus('Scraping tab closed.', 'info');
            } catch (closeError) {
                console.error("Error closing tab:", closeError);
            }
        }
        updatePopupStatus('Yahoo ETF scraping process finished.', 'info', true);
    }
}

// Listen for messages from popup
chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
    if (message.action === 'startYahooScraping') {
        startYahooScrapingProcess();
        sendResponse({ status: 'started' });
        return true; // Indicates that the response will be sent asynchronously
    }
    // It's good practice to return true if you might send an async response for other actions too.
    return true;
});

