            const timestamp = `${year}${month}${day}`; // 拼接成 YYMMDD 格式，例如 250521
            const filename = `topetf_${timestamp}.csv`;

            // Instead of chrome.downloads.download, send to popup.js
            downloadCSVViaPopup(csv, filename);
