                    console.log("Yahoo ETF Scraper: content.js - Table found via 'scr-res-table' data-testid.");
                }
            }

            // 尝试2: 通过 'top-etfs-table' data-testid (之前的尝试)
            if (!targetTable) {
                const topEtfsTableDiv = document.querySelector('div[data-testid="top-etfs-table"]');
                if (topEtfsTableDiv) {
                    targetTable = topEtfsTableDiv.querySelector('table');
                    if (targetTable) {
                        console.log("Yahoo ETF Scraper: content.js - Table found via 'top-etfs-table' data-testid.");
                    }
                }
            }

            // 尝试3: 查找包含特定表头文本的表格 (更灵活的文本匹配)
            if (!targetTable) {
                console.log("Yahoo ETF Scraper: content.js - Table not found by data-testid, trying header content matching.");
                const tables = document.querySelectorAll('table');
                for (let table of tables) {
                    const headers = Array.from(table.querySelectorAll('thead th'));
                    const headerTexts = headers.map(th => th.textContent.trim().toLowerCase());

                    // 检查是否包含 "symbol" 和 "name" (不区分大小写)
                    const hasSymbolHeader = headerTexts.some(text => text.includes('symbol'));
                    const hasNameHeader = headerTexts.some(text => text.includes('name'));
                    const hasPriceHeader = headerTexts.some(text => text.includes('price')); // 可选，增加确定性
                    const hasBodyRows = table.querySelector('tbody tr');

                    if (hasSymbolHeader && hasNameHeader && hasPriceHeader && hasBodyRows) {
                        targetTable = table;
                        console.log("Yahoo ETF Scraper: content.js - Target table found by flexible header text matching.");
                        break;
                    }
                }
            }

            // 尝试4: 查找页面上主要的、包含多行数据的表格 (作为最后的备选)
            // 这个选择器 W(100%) 是 Yahoo Finance 中常见的表格宽度类，但仍需谨慎
            if (!targetTable) {
                console.log("Yahoo ETF Scraper: content.js - Table still not found, trying class 'W(100%)' and row count.");
                const tables = document.querySelectorAll('table.W\\(100\\%\\)'); // 需要转义括号
                if (tables.length === 1 && tables[0].querySelector('tbody tr')) { // 如果页面只有一个这样的主表格
                    targetTable = tables[0];
                    console.log("Yahoo ETF Scraper: content.js - Table found by single 'W(100%)' class.");
                } else if (tables.length > 0) { // 如果有多个，选包含最多数据行的那个
                    let maxRows = 0;
                    let potentialTable = null;
                    tables.forEach(tbl => {
                        const rowCount = tbl.querySelectorAll('tbody tr').length;
                        if (rowCount > maxRows) {
                            maxRows = rowCount;
                            potentialTable = tbl;
                        }
                    });
                    if (potentialTable && maxRows > 0) { // 至少要有一行数据
                        targetTable = potentialTable;
                        console.log(`Yahoo ETF Scraper: content.js - Table found by 'W(100%)' class and max rows (${maxRows}).`);
                    }
                }
            }


            if (targetTable) {
                console.log("Yahoo ETF Scraper: content.js - Target table identified:", targetTable);

                // --- 获取表头并映射列名到索引 ---
                const headers = Array.from(targetTable.querySelectorAll('thead th'));
                headers.forEach((th, index) => {
                    const text = th.textContent.trim().toLowerCase();
                    // 我们需要更灵活地匹配，因为表头文本可能会变化
                    if (text.includes('symbol')) headerIndexMap.symbol = index;
                    else if (text.includes('name')) headerIndexMap.name = index;
                    // "price (intraday)" 或 "price"
                    else if (text.includes('price')) headerIndexMap.price = index;
                    else if (text.includes('volume')) headerIndexMap.volume = index;
                    // 你可以根据需要添加更多列的映射
                });

                console.log("Yahoo ETF Scraper: content.js - Header index map:", headerIndexMap);

                // 检查关键列是否都已映射，如果某些列的表头找不到，则提取会失败
                if (headerIndexMap.symbol === undefined || headerIndexMap.name === undefined || headerIndexMap.price === undefined || headerIndexMap.volume === undefined) {
                    console.error("Yahoo ETF Scraper: content.js - Critical headers (symbol, name, price, volume) not found or mapped. Check table structure and header texts.");
                    sendResponse({ success: false, error: "Critical headers not found in table.", data: [] });
                    return true; // 确保异步响应被发送
                }


                const rows = targetTable.querySelectorAll('tbody tr');
                console.log(`Yahoo ETF Scraper: content.js - Found ${rows.length} rows in the table.`);

                rows.forEach((row, rowIndex) => {
                    try {
                        const cells = row.querySelectorAll('td');
                        if (cells.length === 0) {
                            console.warn(`Yahoo ETF Scraper: content.js - Row ${rowIndex} has no cells, skipping.`);
                            return;
                        }

                        let symbol = null, name = null, price = null, rawVol = null;

                        // --- 新的数据提取逻辑 ---

                        // Symbol
                        if (cells[headerIndexMap.symbol]) {
                            // 尝试更具体的选择器，如果存在的话
                            const symbolLink = cells[headerIndexMap.symbol].querySelector('a[data-testid="table-cell-ticker"]');
                            if (symbolLink) {
                                symbol = symbolLink.textContent.trim();
                            } else {
                                symbol = cells[headerIndexMap.symbol].textContent.trim();
                            }
                            // console.log(`Yahoo ETF Scraper: content.js - Row ${rowIndex} - Raw Symbol Cell Content:`, cells[headerIndexMap.symbol].innerHTML);
                            // console.log(`Yahoo ETF Scraper: content.js - Row ${rowIndex} - Extracted Symbol:`, symbol);
                        } else {
                            console.warn(`Yahoo ETF Scraper: content.js - Row ${rowIndex} - Symbol cell not found using index ${headerIndexMap.symbol}.`);
                        }

                        // Name
                        if (cells[headerIndexMap.name]) {
                            // 雅虎财经的名称有时在 title 属性中，有时直接是文本
                            const nameDivWithTitle = cells[headerIndexMap.name].querySelector('div[title]');
                            if (nameDivWithTitle && nameDivWithTitle.getAttribute('title')) {
                                name = nameDivWithTitle.getAttribute('title').trim();
                            } else {
                                name = cells[headerIndexMap.name].textContent.trim();
                            }
                            // console.log(`Yahoo ETF Scraper: content.js - Row ${rowIndex} - Raw Name Cell Content:`, cells[headerIndexMap.name].innerHTML);
                            // console.log(`Yahoo ETF Scraper: content.js - Row ${rowIndex} - Extracted Name:`, name);
                        } else {
                            console.warn(`Yahoo ETF Scraper: content.js - Row ${rowIndex} - Name cell not found using index ${headerIndexMap.name}.`);
                        }

                        // Price
                        // 页面上的价格通常是动态加载的，但如果结构改变，我们需要直接从DOM中获取
                        // 你的HTML片段显示价格是 "105.63"
                        if (cells[headerIndexMap.price]) {
                            const priceCell = cells[headerIndexMap.price];
                            // 优先尝试从具有特定 data-field 的 fin-streamer 获取 value
                            let priceStreamer = priceCell.querySelector('fin-streamer[data-field="regularMarketPrice"]');
                            if (priceStreamer) {
                                if (priceStreamer.hasAttribute('value') && priceStreamer.getAttribute('value').trim() !== "") {
                                    price = priceStreamer.getAttribute('value').trim();
                                } else {
                                    // 如果 value 属性为空或不存在，则取该 fin-streamer 的 textContent
                                    price = priceStreamer.textContent.trim();
                                }
                            } else {
                                // 如果找不到特定的 fin-streamer，尝试获取单元格内第一个看起来像数字的文本
                                // 这通常是价格本身，避免获取到后面的变化量和百分比
                                const cellText = priceCell.textContent.trim();
                                // 正则表达式匹配开头的数字 (可能包含小数点)
                                const priceMatch = cellText.match(/^[\d\.]+/);
                                if (priceMatch) {
                                    price = priceMatch[0];
                                } else {
                                    // 如果还是没匹配到，记录警告，price 将为 null
                                    console.warn(`Yahoo ETF Scraper: content.js - Row ${rowIndex} - Could not extract price from cell content: '${cellText}' using fallback.`);
                                    price = priceCell.textContent.trim(); // 作为最后的手段，取全部内容，但通常不应到这一步
                                }
                            }
                            // console.log(`Yahoo ETF Scraper: content.js - Row ${rowIndex} - Raw Price Cell Content:`, priceCell.innerHTML);
                            // console.log(`Yahoo ETF Scraper: content.js - Row ${rowIndex} - Extracted Price:`, price);
                        } else {
                            console.warn(`Yahoo ETF Scraper: content.js - Row ${rowIndex} - Price cell not found using index ${headerIndexMap.price}.`);
                        }


                        // Volume
                        // 页面上的成交量也是动态的
                        // 你的HTML片段显示成交量是 "2.327M"

                        if (cells[headerIndexMap.volume]) {
                            let vs = cells[headerIndexMap.volume].querySelector(
                                'fin-streamer[data-field="regularMarketVolume"], fin-streamer[data-field="volume"]'
                            );
                            if (vs && vs.hasAttribute('value') && vs.getAttribute('value').trim() !== "") {
                                rawVol = vs.getAttribute('value').trim();
                            } else {
                                rawVol = cells[headerIndexMap.volume].textContent.trim();
                            }
                        }
                        // 把 rawVol 传给 normalizeVolume 得到最终 volume
                        const volume = normalizeVolume(rawVol);

                        // 最后 push 的时候用 volume 而不是 rawVol
                        if (symbol && name && price !== null && volume !== null) {
                            results.push({ symbol, name, price, volume });
                        }
                    } catch (e) {
                        console.error(`Yahoo ETF Scraper: content.js - Error processing row ${rowIndex}:`, e, "Row HTML:", row.innerHTML);
                    }
                });

                console.log(`Yahoo ETF Scraper: content.js - Successfully scraped ${results.length} ETFs from current page.`);
                sendResponse({ success: true, data: results });

            } else {
                console.error("Yahoo ETF Scraper: content.js - Target table could not be found on the page.");
                sendResponse({ success: false, error: "Table not found on page.", data: [] });
            }
        } catch (error) {
            console.error("Yahoo ETF Scraper: content.js - Error in 'scrapeYahooETFs' message handler:", error);
            sendResponse({ success: false, error: error.message, data: [] });
        }
        return true; // Indicate that the response will be sent asynchronously
    }
});

// Array to store scraped data
let allYahooETFData = [];

// Function to update status in popup
function updatePopupStatus(text, logType = 'info', completed = false) {
    chrome.runtime.sendMessage({
        type: 'statusUpdate', // Changed from 'status'
        text: text,
        logType: logType, // Changed from 'status'
        completed: completed
    }).catch(error => console.log("Error sending status to popup:", error)); // Catch if popup is not open
}

// Function to scrape data from a tab for Yahoo Finance
async function scrapeYahooETFFromTab(tabId, url) {
    try {
        updatePopupStatus(`Navigating to ${url}`, 'info');
        // Navigate to the URL
        await chrome.tabs.update(tabId, { url: url });

        // Wait for the page to load - Yahoo can be slow and dynamic
        // Consider a more robust wait if needed (e.g., waiting for a specific element)
        await new Promise(resolve => {
            const listener = (tabIdUpdated, changeInfo) => {
                if (tabIdUpdated === tabId && changeInfo.status === 'complete') {
                    chrome.tabs.onUpdated.removeListener(listener);
                    // Additional delay for dynamic content loading
                    setTimeout(resolve, 5000); // Increased delay for Yahoo
                }
            };
            chrome.tabs.onUpdated.addListener(listener);
        });

        updatePopupStatus(`Page loaded: ${url}. Attempting to scrape...`, 'info');
        // Execute content script to scrape data
        const results = await chrome.tabs.sendMessage(tabId, { action: 'scrapeYahooETFs' });

        if (results && results.success) {
            updatePopupStatus(`Successfully scraped ${results.data.length} ETFs from ${url}`, 'success');
            allYahooETFData = [...allYahooETFData, ...results.data];
            return true;
        } else {
            const errorMsg = results ? results.error : "No response from content script.";
            updatePopupStatus(`Failed to scrape data from ${url}: ${errorMsg}`, 'error');
            return false;
        }
    } catch (error) {
        updatePopupStatus(`Error scraping from ${url}: ${error.message}`, 'error');
        console.error(`Error in scrapeYahooETFFromTab for ${url}:`, error);
        return false;
    }
}

// Function to generate CSV from data
function generateETFCSV(data) {
    // CSV header
    let csv = 'Symbol,Name,Price,Volume\n';

    // Add each row
    data.forEach(item => {
        const symbol = item.symbol ? `"${item.symbol.replace(/"/g, '""')}"` : '';
        const name = item.name ? `"${item.name.replace(/"/g, '""')}"` : '';
        const price = item.price ? `"${item.price.replace(/"/g, '""')}"` : '';
        const volume = item.volume ? `"${item.volume.replace(/"/g, '""')}"` : '';
        csv += `${symbol},${name},${price},${volume}\n`;
    });
    return csv;
}

// Function to send CSV data to popup for download
function downloadCSVViaPopup(csvData, filename) {
    chrome.runtime.sendMessage({
        type: 'csvData',
        data: csvData,
        filename: filename
    }).catch(error => {
        updatePopupStatus(`Error sending CSV to popup for download: ${error.message}. You might need to open the popup.`, 'error');
        // Fallback or alternative download method could be implemented here if needed
        // For now, we'll just log it.
        console.error("Error sending CSV to popup:", error);
    });
}


// Main function to coordinate the Yahoo ETF scraping process
async function startYahooScrapingProcess() {
    updatePopupStatus('Starting Yahoo ETF scraping process...', 'info');
    allYahooETFData = []; // Reset data for a new scrape

    let tab;
    try {
        // Create a new tab for scraping. It's better to keep it active for debugging.
        // For production, you might set active: false, but ensure content scripts still work.
        tab = await chrome.tabs.create({ active: false, url: 'about:blank' });

        const urls = [
            "https://finance.yahoo.com/markets/etfs/top/?start=0&count=100",
            "https://finance.yahoo.com/markets/etfs/top/?start=100&count=100",
            "https://finance.yahoo.com/markets/etfs/top/?start=200&count=100",
            "https://finance.yahoo.com/markets/etfs/top/?start=300&count=100",
            "https://finance.yahoo.com/markets/etfs/top/?start=400&count=100",
            "https://finance.yahoo.com/markets/etfs/top/?start=500&count=100"
        ];

        for (const url of urls) {
            const success = await scrapeYahooETFFromTab(tab.id, url);
            if (!success) {
                updatePopupStatus(`Skipping remaining URLs due to error on ${url}.`, 'error');
                break; // Optional: stop if one page fails
            }
            // Optional: add a small delay between page loads if needed
            await new Promise(resolve => setTimeout(resolve, 1000));
        }

        if (allYahooETFData.length > 0) {
            updatePopupStatus(`Generating CSV with ${allYahooETFData.length} ETF records...`, 'info');
            const csv = generateETFCSV(allYahooETFData);
            const now = new Date();
            const year = now.getFullYear().toString().slice(-2); // 获取年份的后两位，例如 2025 -> 25
            const month = (now.getMonth() + 1).toString().padStart(2, '0'); // 获取月份 (0-11)，所以 +1，并补零到两位，例如 5 -> 05
            const day = now.getDate().toString().padStart(2, '0'); // 获取日期，并补零到两位，例如 21 -> 21
            const timestamp = `${year}${month}${day}`; // 拼接成 YYMMDD 格式，例如 250521
            const filename = `topetf_${timestamp}.csv`;

            // Instead of chrome.downloads.download, send to popup.js
            downloadCSVViaPopup(csv, filename);
            // updatePopupStatus(`CSV file "${filename}" download initiated via popup.`, 'success', true); // This message is now in popup.js
        } else {
            updatePopupStatus('No ETF data was scraped. Cannot generate CSV.', 'error', true);
        }

    } catch (error) {
        updatePopupStatus(`Critical error in Yahoo ETF scraping process: ${error.message}`, 'error', true);
        console.error("Critical error in startYahooScrapingProcess:", error);
    } finally {
        if (tab && tab.id) {
            try {
                // Optional: close the tab after scraping is done or if an error occurs
                // For debugging, you might want to leave it open.
                await chrome.tabs.remove(tab.id);
                updatePopupStatus('Scraping tab closed.', 'info');
            } catch (closeError) {
                console.error("Error closing tab:", closeError);
            }
        }
        updatePopupStatus('Yahoo ETF scraping process finished.', 'info', true);
    }
}

// Listen for messages from popup
chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
    if (message.action === 'startYahooScraping') {
        startYahooScrapingProcess();
        sendResponse({ status: 'started' });
        return true; // Indicates that the response will be sent asynchronously
    }
    // It's good practice to return true if you might send an async response for other actions too.
    return true;
});

import SwiftUI
import Foundation

// MARK: - Models

struct IndicesSector: Identifiable, Codable {
    var id: String { name }
    let name: String
    let symbols: [IndicesSymbol]
    var subSectors: [IndicesSector]? // 添加子分组

    private enum CodingKeys: String, CodingKey {
        case name, symbols
    }

    init(name: String, symbols: [IndicesSymbol], subSectors: [IndicesSector]? = nil) {
        self.name = name
        self.symbols = symbols
        self.subSectors = subSectors
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.name = try container.decode(String.self, forKey: .name)
        self.symbols = try container.decode([IndicesSymbol].self, forKey: .symbols)
        self.subSectors = nil
    }
}


struct IndicesSymbol: Identifiable, Codable {
    var id: String { symbol }  // 使用symbol作为唯一标识符
    let symbol: String
    let name: String
    var value: String
    var tags: [String]?

    private enum CodingKeys: String, CodingKey {
        case symbol, name, value, tags
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.symbol = try container.decode(String.self, forKey: .symbol)
        self.name = try container.decode(String.self, forKey: .name)
        self.value = try container.decode(String.self, forKey: .value)
        self.tags = try container.decodeIfPresent([String].self, forKey: .tags)
    }

    init(symbol: String, name: String, value: String, tags: [String]?) {
        self.symbol = symbol
        self.name = name
        self.value = value
        self.tags = tags
    }
}

struct DynamicCodingKeys: CodingKey {
    var stringValue: String
    var intValue: Int? { return nil }

    init?(stringValue: String) { self.stringValue = stringValue }
    init?(intValue: Int) { return nil }
}

struct SectorsPanel: Decodable {
    let sectors: [IndicesSector]

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: DynamicCodingKeys.self)
        var sectors: [IndicesSector] = []

        let orderedKeys = container.allKeys
            .map { $0.stringValue }
            .sorted()

        for key in orderedKeys {
            let codingKey = DynamicCodingKeys(stringValue: key)!
            let symbolsContainer = try container.nestedContainer(keyedBy: DynamicCodingKeys.self, forKey: codingKey)
            let orderedSymbolKeys = symbolsContainer.allKeys
                .map { $0.stringValue }
                .sorted()

            if key == "Economics" {
                // 原 Economics 分组特殊处理
                var groupedSymbols: [String: [IndicesSymbol]] = [:]

                for symbolKey in orderedSymbolKeys {
                    let symbolCodingKey = DynamicCodingKeys(stringValue: symbolKey)!
                    let symbolValue = try symbolsContainer.decode(String.self, forKey: symbolCodingKey)

                    // 按前缀数字分组
                    if let prefixNumber = symbolValue.split(separator: " ").first,
                       let _ = Int(prefixNumber) {
                        let group = String(prefixNumber)
                        let symbolName = symbolValue.split(separator: " ")[1]
                        let symbol = IndicesSymbol(
                            symbol: symbolKey,
                            name: String(symbolName),
                            value: "",
                            tags: nil
                        )

                        if groupedSymbols[group] == nil {
                            groupedSymbols[group] = []
                        }
                        groupedSymbols[group]?.append(symbol)
                    }
                }

                let subSectors = groupedSymbols.sorted(by: { $0.key < $1.key }).map { group, groupSymbols in
                    IndicesSector(name: group, symbols: groupSymbols)
                }

                let economicsSector = IndicesSector(
                    name: key,
                    symbols: [],
                    subSectors: subSectors
                )
                sectors.append(economicsSector)
            } else if key == "Commodities" {
                // Commodities 分组特殊处理：添加“重要”子分组，把 CrudeOil 和 Huangjin 放到其中
                var importantSymbols: [IndicesSymbol] = []
                var normalSymbols: [IndicesSymbol] = []

                for symbolKey in orderedSymbolKeys {
                    let symbolCodingKey = DynamicCodingKeys(stringValue: symbolKey)!
                    let symbolName = try symbolsContainer.decode(String.self, forKey: symbolCodingKey)
                    let symbol = IndicesSymbol(symbol: symbolKey, name: symbolName, value: "", tags: nil)

                    if symbolKey == "CrudeOil" || symbolKey == "Huangjin" {
                        importantSymbols.append(symbol)
                    } else {
                        normalSymbols.append(symbol)
                    }
                }

                if !importantSymbols.isEmpty {
                    var subSectors: [IndicesSector] = []
                    // “重要”子分组
                    subSectors.append(IndicesSector(name: "重要", symbols: importantSymbols))
                    // 若还有其他 symbol，则增加“其他”子分组
                    if !normalSymbols.isEmpty {
                        subSectors.append(IndicesSector(name: "其他", symbols: normalSymbols))
                    }
                    let commoditiesSector = IndicesSector(name: key, symbols: [], subSectors: subSectors)
                    sectors.append(commoditiesSector)
                } else if !normalSymbols.isEmpty {
                    // 如果没有重要 symbol，则常规处理
                    let commoditiesSector = IndicesSector(name: key, symbols: normalSymbols)
                    sectors.append(commoditiesSector)
                }
            } else if key == "Currencies" {
                // Currencies 分组特殊处理：添加“重要”子分组，把 USDJPY 和 USDCNY 和 DXY 和 CNYI 放到其中
                var importantSymbols: [IndicesSymbol] = []
                var normalSymbols: [IndicesSymbol] = []

                for symbolKey in orderedSymbolKeys {
                    let symbolCodingKey = DynamicCodingKeys(stringValue: symbolKey)!
                    let symbolName = try symbolsContainer.decode(String.self, forKey: symbolCodingKey)
                    let symbol = IndicesSymbol(symbol: symbolKey, name: symbolName, value: "", tags: nil)

                    if symbolKey == "USDJPY" || symbolKey == "USDCNY" || symbolKey == "DXY" || symbolKey == "CNYI" || symbolKey == "JPYI" || symbolKey == "CHFI" || symbolKey == "EURI" {
                        importantSymbols.append(symbol)
                    } else {
                        normalSymbols.append(symbol)
                    }
                }

                if !importantSymbols.isEmpty {
                    var subSectors: [IndicesSector] = []
                    // “重要”子分组
                    subSectors.append(IndicesSector(name: "重要", symbols: importantSymbols))
                    // 如果还有其他 symbol，则增加“其他”子分组
                    if !normalSymbols.isEmpty {
                        subSectors.append(IndicesSector(name: "其他", symbols: normalSymbols))
                    }
                    let currenciesSector = IndicesSector(name: key, symbols: [], subSectors: subSectors)
                    sectors.append(currenciesSector)
                } else if !normalSymbols.isEmpty {
                    // 如果没有特别的 symbol，则常规处理
                    let currenciesSector = IndicesSector(name: key, symbols: normalSymbols)
                    sectors.append(currenciesSector)
                }
            } else {
                // 其他分组常规处理
                var symbols: [IndicesSymbol] = []
                for symbolKey in orderedSymbolKeys {
                    let symbolCodingKey = DynamicCodingKeys(stringValue: symbolKey)!
                    let symbolName = try symbolsContainer.decode(String.self, forKey: symbolCodingKey)
                    symbols.append(IndicesSymbol(
                        symbol: symbolKey,
                        name: symbolName,
                        value: "",
                        tags: nil
                    ))
                }

                if !symbols.isEmpty {
                    let sector = IndicesSector(name: key, symbols: symbols)
                    sectors.append(sector)
                }
            }
        }

        self.sectors = sectors
    }
}

