    let groupName: String
    private let verticalPadding: CGFloat = 20  // 上下各20点的边距

    @State private var chartData: [DatabaseManager.PriceData] = []
    @State private var sampledChartData: [DatabaseManager.PriceData] = [] // 采样后的数据
