// ==================== 新增的视图：用于全屏缩放和拖动图片 ====================
struct ZoomableImageView: View {
    let imageName: String
    @Binding var isPresented: Bool // 用于关闭视图

    // 状态变量
    @State private var scale: CGFloat = 1.0
    @State private var offset: CGSize = .zero
    @State private var lastScale: CGFloat = 1.0
    @State private var lastOffset: CGSize = .zero

    var body: some View {
        let fullPath = "news_images/\(imageName)"

        // 缩放手势
        let magnificationGesture = MagnificationGesture()
            .onChanged { value in
                let delta = value / lastScale
                lastScale = value
                scale *= delta
            }
            .onEnded { _ in
                lastScale = 1.0
                // 限制最小缩放为1倍
                if scale < 1.0 {
                    withAnimation(.spring()) {
                        scale = 1.0
                        offset = .zero
                        lastOffset = .zero
                    }
                }
            }

        // 拖动手势
        let dragGesture = DragGesture()
            .onChanged { value in
                offset = CGSize(width: lastOffset.width + value.translation.width,
                                height: lastOffset.height + value.translation.height)
            }
            .onEnded { _ in
                lastOffset = offset
            }

        // 双击重置手势
        let doubleTapGesture = TapGesture(count: 2)
            .onEnded {
                withAnimation(.spring()) {
                    scale = 1.0
                    offset = .zero
                    lastScale = 1.0
                    lastOffset = .zero
                }
            }

        ZStack {
            // 黑色背景
            Color.black
                .edgesIgnoringSafeArea(.all)
                .onTapGesture {
                    // 单击背景关闭视图
                    isPresented = false
                }

            // 图片
            if let uiImage = UIImage(named: fullPath) {
                Image(uiImage: uiImage)
                    .resizable()
                    .scaledToFit()
                    .scaleEffect(scale)
                    .offset(offset)
                    // 只有当图片被放大时才允许拖动
//                    .gesture(scale > 1 ? dragGesture : nil)
                    // 必须将缩放手势和双击手势组合起来
                    // `simultaneously(with:)` 允许两个手势同时识别
                    .gesture(SimultaneousGesture(magnificationGesture, doubleTapGesture))
                    .gesture(scale > 1.001 ? dragGesture : nil)
            } else {
                // 如果图片加载失败，显示错误信息并允许关闭
                VStack(spacing: 20) {
                    Text("图片无法加载")
                        .foregroundColor(.white)
                    Button("关闭") {
                        isPresented = false
                    }
                    .foregroundColor(.blue)
                }
            }

            // 右上角的关闭按钮
            VStack {
                HStack {
                    Spacer()
                    Button(action: {
                        isPresented = false
                    }) {
                        Image(systemName: "xmark.circle.fill")
                            .font(.largeTitle)
                            .foregroundColor(.white.opacity(0.7))
                            .background(Color.black.opacity(0.5).clipShape(Circle()))
                    }
                    .padding()
                }
                Spacer()
            }
        }
    }
}

import SwiftUI

/// 一个容器视图，管理当前文章的显示和切换逻辑
struct ArticleContainerView: View {
    // 从列表页传入的初始文章和上下文信息
    let initialArticle: Article
    let navigationContext: NavigationContext // 标记是从哪里来的

    @ObservedObject var viewModel: NewsViewModel

    // 使用 @State 来管理当前正在显示的文章
    @State private var currentArticle: Article
    @State private var currentSourceName: String

    // 控制提示信息的显示状态
    @State private var showToast = false

    // 定义导航上下文，以区分不同的文章列表
    enum NavigationContext {
        case fromSource(String) // 来自特定来源，值为来源名称
        case fromAllArticles      // 来自“所有文章”列表
    }

    // 自定义初始化方法
    init(article: Article, sourceName: String, context: NavigationContext, viewModel: NewsViewModel) {
        self.initialArticle = article
        self.navigationContext = context
        self.viewModel = viewModel

        // 使用 State 的初始值包装器来设置初始状态
        self._currentArticle = State(initialValue: article)
        self._currentSourceName = State(initialValue: sourceName)
    }

    var body: some View {
        ZStack(alignment: .bottom) {
            // 核心内容：文章详情页
            ArticleDetailView(
                article: currentArticle,
                sourceName: currentSourceName,
                viewModel: viewModel,
                // 传递一个闭包作为请求下一篇的回调
                requestNextArticle: {
                    self.switchToNextArticle()
                }
            )
            .id(currentArticle.id) // 使用 .id() 来确保当 currentArticle 改变时，整个 DetailView 被重新创建，触发动画
            .transition(.asymmetric(
                insertion: .move(edge: .bottom).combined(with: .opacity),
                removal: .move(edge: .top).combined(with: .opacity))
            )

            // 如果需要显示提示，则在底部显示
            if showToast {
                Text("该分组内已无未阅读的文章存在了")
                    .font(.subheadline)
                    .padding()
                    .background(Color.black.opacity(0.7))
                    .foregroundColor(.white)
                    .cornerRadius(10)
                    .padding(.bottom, 50)
                    .transition(.opacity.animation(.easeInOut))
            }
        }
        .navigationTitle(currentSourceName)
        .navigationBarTitleDisplayMode(.inline)
    }

    /// 切换到下一篇文章的逻辑
    private func switchToNextArticle() {
        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name):
            sourceNameToSearch = name
        case .fromAllArticles:
            sourceNameToSearch = nil
        }

        // 调用 ViewModel 查找下一篇文章
        if let next = viewModel.findNextArticle(after: currentArticle.id, inSource: sourceNameToSearch) {
            // 如果找到了，用动画更新当前文章状态
            withAnimation(.easeInOut(duration: 0.5)) {
                self.currentArticle = next.article
                self.currentSourceName = next.sourceName
            }
        } else {
            // 如果没找到，显示提示信息
            withAnimation {
                showToast = true
            }
            // 2秒后自动隐藏提示
            DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
                withAnimation {
                    showToast = false
                }
            }
        }
    }
}

