// ==================== 新增的视图：用于全屏缩放和拖动图片 ====================
struct ZoomableImageView: View {
    let imageName: String
    @Binding var isPresented: Bool // 用于关闭视图

    // 状态变量
    @State private var scale: CGFloat = 1.0
    @State private var offset: CGSize = .zero
    @State private var lastScale: CGFloat = 1.0
    @State private var lastOffset: CGSize = .zero

    var body: some View {
        let fullPath = "news_images/\(imageName)"

        // 缩放手势
        let magnificationGesture = MagnificationGesture()
            .onChanged { value in
                let delta = value / lastScale
                lastScale = value
                scale *= delta
            }
            .onEnded { _ in
                lastScale = 1.0
                // 限制最小缩放为1倍
                if scale < 1.0 {
                    withAnimation(.spring()) {
                        scale = 1.0
                        offset = .zero
                        lastOffset = .zero
                    }
                }
            }

        // 拖动手势
        let dragGesture = DragGesture()
            .onChanged { value in
                offset = CGSize(width: lastOffset.width + value.translation.width,
                                height: lastOffset.height + value.translation.height)
            }
            .onEnded { _ in
                lastOffset = offset
            }

        // 双击重置手势
        let doubleTapGesture = TapGesture(count: 2)
            .onEnded {
                withAnimation(.spring()) {
                    scale = 1.0
                    offset = .zero
                    lastScale = 1.0
                    lastOffset = .zero
                }
            }

        ZStack {
            // 黑色背景
            Color.black
                .edgesIgnoringSafeArea(.all)
                .onTapGesture {
                    // 单击背景关闭视图
                    isPresented = false
                }

            // 图片
            if let uiImage = UIImage(named: fullPath) {
                Image(uiImage: uiImage)
                    .resizable()
                    .scaledToFit()
                    .scaleEffect(scale)
                    .offset(offset)
                    // 只有当图片被放大时才允许拖动
//                    .gesture(scale > 1 ? dragGesture : nil)
                    // 必须将缩放手势和双击手势组合起来
                    // `simultaneously(with:)` 允许两个手势同时识别
                    .gesture(SimultaneousGesture(magnificationGesture, doubleTapGesture))
                    .gesture(scale > 1.001 ? dragGesture : nil)
            } else {
                // 如果图片加载失败，显示错误信息并允许关闭
                VStack(spacing: 20) {
                    Text("图片无法加载")
                        .foregroundColor(.white)
