    let topic: String
    let article: String
    let images: [String]

    // `isRead` 状态不在JSON中，所以我们自定义解码过程
    var isRead: Bool = false

    // 定义JSON中的键，这样解码器就知道要解析哪些字段
    enum CodingKeys: String, CodingKey {
        case topic, article, images
    }
}

