import SwiftUI

enum ArticleFilterMode: String, CaseIterable {
    case unread = "Unread"
    case read = "Read"
}

struct ArticleListView: View {
    let source: NewsSource
    @ObservedObject var viewModel: NewsViewModel

    @State private var filterMode: ArticleFilterMode = .unread

    private var filteredArticles: [Article] {
        switch filterMode {
        case .unread:
            return source.articles.filter { !$0.isRead }
        case .read:
            return source.articles.filter { $0.isRead }
        }
    }

    // ===== 新增 (1/2): 计算未读和已读文章数量 =====
    // 计算该来源下未读文章的数量
    private var unreadCount: Int {
        source.articles.filter { !$0.isRead }.count
    }

    // 计算该来源下已读文章的数量
    private var readCount: Int {
        source.articles.filter { $0.isRead }.count
    }
    // ===========================================

    var body: some View {
        VStack {
            ScrollViewReader { proxy in
                List {
                    Text(formattedDate())
                        .font(.caption)
                        .foregroundColor(.gray)
                        .padding(.top)
                        .listRowSeparator(.hidden)

                    ForEach(filteredArticles) { article in
                        NavigationLink(destination: ArticleContainerView(
                            article: article,
                            sourceName: source.name,
                            context: .fromSource(source.name),
                            viewModel: viewModel
                        )) {
                            VStack(alignment: .leading, spacing: 8) {
                                Text(source.name)
                                    .font(.caption)
                                    .foregroundColor(.gray)
                                Text(article.topic)
                                    .fontWeight(.semibold)
                                    .foregroundColor(article.isRead ? .gray : .primary)
                            }
                            .padding(.vertical, 8)
                            .contextMenu {
                                if article.isRead {
                                    Button {
                                        viewModel.markAsUnread(articleID: article.id)
                                    } label: {
                                        Label("标记为未读", systemImage: "circle")
                                    }
                                } else {
                                    Button {
                                        viewModel.markAsRead(articleID: article.id)
                                    } label: {
                                        Label("标记为已读", systemImage: "checkmark.circle")
                                    }
                                }
                            }
                        }
                        .listRowSeparator(.hidden)
                        .id(article.id)
                    }
                }
                .listStyle(PlainListStyle())
                .navigationTitle("Unread")
                .navigationBarTitleDisplayMode(.inline)
                .onAppear {
                    if let lastID = viewModel.lastViewedArticleID {
                        if filteredArticles.contains(where: { $0.id == lastID }) {
                            withAnimation {
                                proxy.scrollTo(lastID, anchor: .center)
                            }
                        }
                    }
                }
            }

            // ===== 修改 (2/2): 在 Picker 中显示文章数量 =====
            Picker("Filter", selection: $filterMode) {
                ForEach(ArticleFilterMode.allCases, id: \.self) { mode in
                    // 根据当前的 mode，决定显示哪个数量
                    let count = (mode == .unread) ? unreadCount : readCount
                    // 使用字符串插值来构建带数量的文本
                    Text("\(mode.rawValue) (\(count))")
                        .tag(mode)
                }
            }
            .pickerStyle(.segmented)
            .padding(.horizontal)
            .padding(.bottom, 8)
            // ===============================================
        }
    }

    private func formattedDate() -> String {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "zh_CN")

        if Calendar.current.isDateInToday(Date()) {
            formatter.dateFormat = "EEEE, MMMM d, yyyy"
            return "TODAY, \(formatter.string(from: Date()).uppercased())"
        } else if Calendar.current.isDateInYesterday(Date()) {
            return "YESTERDAY"
        } else {
            formatter.dateFormat = "EEEE, MMMM d, yyyy"
            return formatter.string(from: Date()).uppercased()
        }
    }
}

struct AllArticlesListView: View {
    @ObservedObject var viewModel: NewsViewModel

    @State private var filterMode: ArticleFilterMode = .unread

    // ===== 新增 (与 ArticleListView 类似的逻辑) =====
    // 计算所有来源下未读文章的总数
    private var totalUnreadCount: Int {
        viewModel.sources.flatMap { $0.articles }.filter { !$0.isRead }.count
    }

    // 计算所有来源下已读文章的总数
    private var totalReadCount: Int {
        viewModel.sources.flatMap { $0.articles }.filter { $0.isRead }.count
    }
    // ==============================================

    var body: some View {
        VStack {
            ScrollViewReader { proxy in
                List {
                    ForEach(viewModel.sources) { source in
                        let articlesToDisplay = source.articles.filter { article in
                            switch filterMode {
                            case .unread:
                                return !article.isRead
                            case .read:
                                return article.isRead
                            }
                        }

                        if !articlesToDisplay.isEmpty {
                            ForEach(articlesToDisplay) { article in
                                NavigationLink(destination: ArticleContainerView(
                                    article: article,
                                    sourceName: source.name,
                                    context: .fromAllArticles,
                                    viewModel: viewModel
                                )) {
                                    VStack(alignment: .leading, spacing: 8) {
                                        Text(source.name)
                                            .font(.caption)
                                            .foregroundColor(.gray)
                                        Text(article.topic)
                                            .fontWeight(.semibold)
                                            .foregroundColor(article.isRead ? .gray : .primary)
                                    }
                                    .padding(.vertical, 8)
                                    .contextMenu {
                                        if article.isRead {
                                            Button {
                                                viewModel.markAsUnread(articleID: article.id)
                                            } label: {
                                                Label("标记为未读", systemImage: "circle")
                                            }
                                        } else {
                                            Button {
                                                viewModel.markAsRead(articleID: article.id)
                                            } label: {
                                                Label("标记为已读", systemImage: "checkmark.circle")
                                            }
                                        }
                                    }
                                }
                                .listRowSeparator(.hidden)
                                .id(article.id)
                            }
                        }
                    }
                }
                .listStyle(PlainListStyle())
                .navigationBarTitleDisplayMode(.inline)
                .onAppear {
                    if let lastID = viewModel.lastViewedArticleID {
                        let allFilteredArticles = viewModel.sources.flatMap { $0.articles }.filter {
                            filterMode == .unread ? !$0.isRead : $0.isRead
                        }
                        if allFilteredArticles.contains(where: { $0.id == lastID }) {
                            withAnimation {
                                proxy.scrollTo(lastID, anchor: .center)
                            }
                        }
                    }
                }
            }

            // ===== 修改 (与 ArticleListView 相同的逻辑) =====
            Picker("Filter", selection: $filterMode) {
                ForEach(ArticleFilterMode.allCases, id: \.self) { mode in
                    let count = (mode == .unread) ? totalUnreadCount : totalReadCount
                    Text("\(mode.rawValue) (\(count))")
                        .tag(mode)
                }
            }
            .pickerStyle(.segmented)
            .padding(.horizontal)
            .padding(.bottom, 8)
            // =============================================
        }
    }
}

import Foundation

struct BuildInfo {
    // 这个值将被我们的构建脚本动态替换
    static let buildDate: String = "2025-01-01"
}

import Foundation

class DataManager {
    static let shared = DataManager()

    private let fileManager = FileManager.default
    private let documentsDirectory: URL
    private let processedBuildsKey = "processedBuildsKey"

    private init() {
        // 获取应用的 Documents 目录路径
        guard let url = fileManager.urls(for: .documentDirectory, in: .userDomainMask).first else {
            fatalError("无法访问 Documents 目录")
        }
        self.documentsDirectory = url
        print("应用数据存储路径: \(self.documentsDirectory.path)")
    }

    /// 检查并迁移 Bundle 中的新内容到 Documents 目录
    func migrateContentIfNeeded() {
        let currentBuildDate = BuildInfo.buildDate
        var processedBuilds = UserDefaults.standard.stringArray(forKey: processedBuildsKey) ?? []

        // 如果当前构建日期已经处理过，则无需任何操作
        if processedBuilds.contains(currentBuildDate) {
            print("内容批次 '\(currentBuildDate)' 已处理，无需迁移。")
            return
        }

        print("检测到新内容批次: '\(currentBuildDate)'，开始迁移...")

        // 1. 迁移 onews.json
        guard let sourceJsonUrl = Bundle.main.url(forResource: "onews", withExtension: "json") else {
            print("警告: 在 Bundle 中未找到 onews.json，跳过 JSON 迁移。")
            return // 如果没有json，后续也无意义
        }
        let destinationJsonUrl = documentsDirectory.appendingPathComponent("onews_\(currentBuildDate).json")

        do {
            try fileManager.copyItem(at: sourceJsonUrl, to: destinationJsonUrl)
            print("成功复制 onews.json 到: \(destinationJsonUrl.path)")
        } catch {
            print("错误: 复制 onews.json 失败: \(error)")
            // 如果JSON复制失败，我们不应该继续，因为没有数据源
            return
        }

        // 2. 迁移 news_images 目录
        guard let sourceImagesUrl = Bundle.main.url(forResource: "news_images", withExtension: nil) else {
            print("警告: 在 Bundle 中未找到 news_images 目录，跳过图片迁移。")
            // 即使没有图片，新闻内容也可能有效，所以我们继续
            markBuildAsProcessed(currentBuildDate)
            return
        }
        let destinationImagesUrl = documentsDirectory.appendingPathComponent("news_images_\(currentBuildDate)")

        do {
            try fileManager.copyItem(at: sourceImagesUrl, to: destinationImagesUrl)
            print("成功复制 news_images 目录到: \(destinationImagesUrl.path)")
        } catch {
            print("错误: 复制 news_images 目录失败: \(error)")
        }

        // 标记此构建日期为已处理
        markBuildAsProcessed(currentBuildDate)
    }

    private func markBuildAsProcessed(_ buildDate: String) {
        var processedBuilds = UserDefaults.standard.stringArray(forKey: processedBuildsKey) ?? []
        if !processedBuilds.contains(buildDate) {
            processedBuilds.append(buildDate)
            UserDefaults.standard.set(processedBuilds, forKey: processedBuildsKey)
            print("已将 '\(buildDate)' 标记为已处理。")
        }
    }

    /// 从 Documents 目录加载所有新闻数据
    func loadAllNewsSources() -> [NewsSource] {
        var allSources: [String: NewsSource] = [:]
        let decoder = JSONDecoder()

        do {
            let directoryContents = try fileManager.contentsOfDirectory(at: documentsDirectory, includingPropertiesForKeys: nil)

            // 筛选出所有 onews_YYYY-MM-DD.json 文件
            let jsonFiles = directoryContents.filter { $0.lastPathComponent.starts(with: "onews_") && $0.pathExtension == "json" }

            for jsonFileUrl in jsonFiles {
                // 从文件名中提取日期作为批次ID
                let fileName = jsonFileUrl.lastPathComponent
                let batchID = fileName.replacingOccurrences(of: "onews_", with: "").replacingOccurrences(of: ".json", with: "")

                guard let data = try? Data(contentsOf: jsonFileUrl) else { continue }
                guard let decoded = try? decoder.decode([String: [Article]].self, from: data) else { continue }

                for (sourceName, articles) in decoded {
                    // 为每篇文章设置其所属的批次ID
                    var articlesWithBatchID = articles
                    for i in articlesWithBatchID.indices {
                        articlesWithBatchID[i].batchID = batchID
                    }

                    if var existingSource = allSources[sourceName] {
                        // 如果来源已存在，则追加文章
                        existingSource.articles.append(contentsOf: articlesWithBatchID)
                        allSources[sourceName] = existingSource
                    } else {
                        // 如果是新来源，则创建
                        allSources[sourceName] = NewsSource(name: sourceName, articles: articlesWithBatchID)
                    }
                }
            }
        } catch {
            print("加载新闻数据失败: \(error)")
        }

        // 返回合并后的数据，并按来源名称排序
        return allSources.values.sorted { $0.name < $1.name }
    }

    /// 获取特定文章图片的完整路径
    static func getImagePath(for imageName: String, in batchID: String) -> URL? {
        guard let documentsDirectory = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask).first else {
            return nil
        }
        return documentsDirectory
            .appendingPathComponent("news_images_\(batchID)")
            .appendingPathComponent(imageName)
    }
}

