struct ZoomableImageView: View {
    let imageName: String
    @Binding var isPresented: Bool

    // 新增：保存结果状态
    @State private var showSaveAlert = false
    @State private var saveAlertMessage = ""

    var body: some View {
        ZStack {
            // 黑色背景
            Color.black
                .edgesIgnoringSafeArea(.all)

            // 图片滚动 & 缩放
            // ZoomableScrollView 内部已经处理了双击手势，所以我们不需要在这里添加
            ZoomableScrollView(imageName: imageName)

            // 关闭按钮（右上角）
            VStack {
                HStack {
                    Spacer()
                    Button(action: { isPresented = false }) {
                        Image(systemName: "xmark.circle.fill")
                            .font(.largeTitle)
                            .foregroundColor(.white.opacity(0.7))
                            .background(Color.black.opacity(0.5).clipShape(Circle()))
                    }
                    .padding()
                }
                Spacer()
            }

            // 下载按钮（右下角）
            VStack {
                Spacer()
                HStack {
                    Spacer()
                    Button(action: saveImageToPhotoLibrary) {
                        Image(systemName: "arrow.down.circle.fill")
                            .font(.largeTitle)
                            .foregroundColor(.white.opacity(0.7))
                            .background(Color.black.opacity(0.5).clipShape(Circle()))
                    }
                    .padding()
                }
            }
        }
        // ==================== 修改点 1: 移除单击手势，添加拖拽手势 ====================
        // .onTapGesture { isPresented = false } // <- 移除这一行
        .gesture(
            DragGesture().onEnded { value in
                // 检查垂直方向的拖动距离
                // 如果向下滑动超过 100 个点，则关闭视图
                if value.translation.height > 100 {
                    isPresented = false
                }
            }
        )
        // =======================================================================
        // 保存结果弹窗
        .alert(isPresented: $showSaveAlert) {
            Alert(title: Text(saveAlertMessage))
        }
    }

    // MARK: - 保存图片到相册 (这部分逻辑保持不变)
    private func saveImageToPhotoLibrary() {
        let fullPath = "news_images/\(imageName)"
        guard let uiImage = UIImage(named: fullPath) else {
          saveAlertMessage = "图片加载失败，无法保存"
          showSaveAlert = true
          return
        }

        guard let imageData = uiImage.jpegData(compressionQuality: 1.0) else {
          saveAlertMessage = "图片转换失败"
          showSaveAlert = true
          return
        }

        let requestAuth: (@escaping (PHAuthorizationStatus) -> Void) -> Void = { callback in
          if #available(iOS 14, *) {
            PHPhotoLibrary.requestAuthorization(for: .addOnly, handler: callback)
          } else {
            PHPhotoLibrary.requestAuthorization(callback)
          }
        }

        requestAuth { status in
          DispatchQueue.main.async {
            switch status {
            case .authorized, .limited:
              PHPhotoLibrary.shared().performChanges {
                let creationRequest = PHAssetCreationRequest.forAsset()
                let options = PHAssetResourceCreationOptions()
                creationRequest.addResource(
                  with: .photo,
                  data: imageData,
                  options: options
                )
              } completionHandler: { success, error in
                DispatchQueue.main.async {
                  if success {
                    saveAlertMessage = "已保存到相册"
                  } else {
                    saveAlertMessage = "保存失败：\(error?.localizedDescription ?? "未知错误")"
                  }
                  showSaveAlert = true
                }
              }
            case .denied, .restricted:
              saveAlertMessage = "没有相册权限，保存失败"
              showSaveAlert = true
            case .notDetermined:
              saveAlertMessage = "相册权限未确定"
              showSaveAlert = true
            @unknown default:
              saveAlertMessage = "未知的相册权限状态"
              showSaveAlert = true
            }
          }
        }
      }
}

// 这部分代码已经实现了双击缩放功能，无需修改
struct ZoomableScrollView: UIViewRepresentable {
    let imageName: String

    // 1. 创建底层的 UIView (UIScrollView)
    func makeUIView(context: Context) -> UIScrollView {
        let fullPath = "news_images/\(imageName)"
        guard let image = UIImage(named: fullPath) else {
            // 如果图片加载失败，返回一个空的 scroll view
            return UIScrollView()
        }

        // 创建 ScrollView 和 ImageView
        let scrollView = UIScrollView()
        let imageView = UIImageView(image: image)
        imageView.contentMode = .scaleAspectFit
        imageView.translatesAutoresizingMaskIntoConstraints = false

        // 将 ImageView 添加到 ScrollView
        scrollView.addSubview(imageView)

        // 设置 AutoLayout 约束
        NSLayoutConstraint.activate([
            imageView.widthAnchor.constraint(equalTo: scrollView.widthAnchor),
            imageView.heightAnchor.constraint(equalTo:scrollView.heightAnchor),
            imageView.centerXAnchor.constraint(equalTo: scrollView.centerXAnchor),
            imageView.centerYAnchor.constraint(equalTo: scrollView.centerYAnchor)
        ])

        // 配置 ScrollView
        scrollView.delegate = context.coordinator // 设置代理以启用缩放
        scrollView.maximumZoomScale = 5.0 // 最大缩放倍数
        scrollView.minimumZoomScale = 1.0 // 最小缩放倍数
        scrollView.bouncesZoom = true // 允许缩放时有弹性效果
        scrollView.showsHorizontalScrollIndicator = false
        scrollView.showsVerticalScrollIndicator = false

        // 关联 Coordinator 和 ImageView
        context.coordinator.imageView = imageView

        // 添加双击手势
        let doubleTapGesture = UITapGestureRecognizer(target: context.coordinator, action: #selector(Coordinator.handleDoubleTap))
        doubleTapGesture.numberOfTapsRequired = 2
        scrollView.addGestureRecognizer(doubleTapGesture)

        return scrollView
    }

    // 2. 当 SwiftUI 状态变化时更新 UIView
    func updateUIView(_ uiView: UIScrollView, context: Context) {
        // 在这个简单场景下，我们不需要在视图更新时做什么
    }

    // 3. 创建 Coordinator
    func makeCoordinator() -> Coordinator {
        Coordinator(self)
    }

    // 4. Coordinator 类，用于处理代理回调和手势
    class Coordinator: NSObject, UIScrollViewDelegate {
        var parent: ZoomableScrollView
        var imageView: UIImageView?

        init(_ parent: ZoomableScrollView) {
            self.parent = parent
        }

        // 这个代理方法告诉 ScrollView 应该缩放哪个子视图
        func viewForZooming(in scrollView: UIScrollView) -> UIView? {
            return imageView
        }

        // 双击手势的处理方法
        @objc func handleDoubleTap(_ gesture: UITapGestureRecognizer) {
            guard let scrollView = gesture.view as? UIScrollView else { return }

            if scrollView.zoomScale > scrollView.minimumZoomScale {
                // 如果当前已放大，则恢复到原始大小
                scrollView.setZoomScale(scrollView.minimumZoomScale, animated: true)
            } else {
                // 如果当前是原始大小，则在双击位置放大
                let point = gesture.location(in: imageView)
                // 放大到最大倍数的一半，这是一个固定的倍率
                let zoomRect = zoomRect(for: scrollView, with: point, scale: scrollView.maximumZoomScale / 2)
                scrollView.zoom(to: zoomRect, animated: true)
            }
        }

        // 计算双击后要放大的区域
        private func zoomRect(for scrollView: UIScrollView, with point: CGPoint, scale: CGFloat) -> CGRect {
            let newSize = CGSize(
                width: scrollView.frame.width / scale,
                height: scrollView.frame.height / scale
            )
            let newOrigin = CGPoint(
                x: point.x - newSize.width / 2.0,
                y: point.y - newSize.height / 2.0
            )
            return CGRect(origin: newOrigin, size: newSize)
        }
    }
}

import SwiftUI

struct ArticleContainerView: View {
    let initialArticle: Article
    let navigationContext: NavigationContext

    @ObservedObject var viewModel: NewsViewModel

    @State private var currentArticle: Article
    @State private var currentSourceName: String

    // 1. 用于在当前页面生命周期内，实时更新未读计数的局部状态变量
    @State private var liveUnreadCount: Int

    // 2. 用于累积在本次查看会话中所有被读过的文章ID
    @State private var readArticleIDsInThisSession: Set<UUID> = []

    @State private var showNoNextToast = false
    @State private var showNoPreviousToast = false

    enum NavigationContext {
        case fromSource(String)
        case fromAllArticles
    }

    // 这个计算属性现在只用于初始化
    private var initialUnreadCount: Int {
        switch navigationContext {
        case .fromAllArticles:
            return viewModel.totalUnreadCount
        case .fromSource(let sourceName):
            return viewModel.sources.first { $0.name == sourceName }?.unreadCount ?? 0
        }
    }

    // 我们需要自定义 init 来正确初始化新的 @State 变量 liveUnreadCount
    init(article: Article, sourceName: String, context: NavigationContext, viewModel: NewsViewModel) {
        self.initialArticle = article
        self.navigationContext = context
        self.viewModel = viewModel

        // 初始化内部状态
        self._currentArticle = State(initialValue: article)
        self._currentSourceName = State(initialValue: sourceName)

        // 根据上下文计算初始的未读数，并用它来初始化 liveUnreadCount
        let baseCount: Int
        switch context {
        case .fromAllArticles:
            baseCount = viewModel.totalUnreadCount
        case .fromSource(let name):
            baseCount = viewModel.sources.first { $0.name == name }?.unreadCount ?? 0
        }
        self._liveUnreadCount = State(initialValue: baseCount)
    }

    var body: some View {
        ZStack(alignment: .bottom) {
            // 将我们实时的、局部的未读数传递给详情页
            ArticleDetailView(
                article: currentArticle,
                sourceName: currentSourceName,
                unreadCount: liveUnreadCount, // <- 使用局部状态
                viewModel: viewModel,
                requestNextArticle: {
                    self.switchToNextArticle()
                },
                requestPreviousArticle: {
                    self.switchToPreviousArticle()
                }
            )
            .id(currentArticle.id)
            .transition(.asymmetric(
                insertion: .move(edge: .bottom).combined(with: .opacity),
                removal: .move(edge: .top).combined(with: .opacity))
            )

            if showNoNextToast {
                ToastView(message: "该分组内已无更多文章")
            }

            if showNoPreviousToast {
                ToastView(message: "这已经是第一篇文章了")
            }
        }
        // --- 已移除: .onAppear ---
        // .onAppear 修饰符已完全删除，不再更新 lastViewedArticleID

        // --- .onDisappear 逻辑保持不变 ---
        .onDisappear {
            // 当视图最终消失时，将当前正在看的文章也加入待处理集合
            // 我们需要检查这篇文章是否本身就是未读的
            if !currentArticle.isRead {
                readArticleIDsInThisSession.insert(currentArticle.id)
            }

            // 一次性将所有在本次会话中读过的文章ID提交给ViewModel
            for articleID in readArticleIDsInThisSession {
                viewModel.markAsRead(articleID: articleID)
            }
        }
        // --- 修改: .onChange ---
        .onChange(of: currentArticle.id) { oldValue, newValue in
            // --- 已移除 ---
            // 更新 lastViewedArticleID 的代码行已被删除
            // viewModel.lastViewedArticleID = newValue

            // 当文章切换时，我们处理刚刚离开的文章 (oldValue)

            // 检查这篇文章是否本身是未读的，并且我们还没有处理过它
            let wasArticleUnread = !viewModel.sources.flatMap { $0.articles }.first { $0.id == oldValue }!.isRead
            let isNewToSession = !readArticleIDsInThisSession.contains(oldValue)

            if wasArticleUnread && isNewToSession {
                // 如果它确实是篇新的未读文章，那么：
                // 1. 将局部未读数减 1，立即更新UI
                liveUnreadCount -= 1
                // 2. 将它的ID加入待处理集合，以便在最后统一提交
                readArticleIDsInThisSession.insert(oldValue)
            }
        }
    }

    /// 切换到下一篇文章的逻辑
    private func switchToNextArticle() {
        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        if let next = viewModel.findNextArticle(after: currentArticle.id, inSource: sourceNameToSearch) {
            withAnimation(.easeInOut(duration: 0.4)) {
                self.currentArticle = next.article
                self.currentSourceName = next.sourceName
            }
        } else {
            showToast { shouldShow in self.showNoNextToast = shouldShow }
        }
    }

    /// 切换到上一篇文章的逻辑
    private func switchToPreviousArticle() {
        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        if let prev = viewModel.findPreviousArticle(before: currentArticle.id, inSource: sourceNameToSearch) {
            withAnimation(.interactiveSpring(response: 0.4, dampingFraction: 0.8)) {
                self.currentArticle = prev.article
                self.currentSourceName = prev.sourceName
            }
        } else {
            showToast { shouldShow in self.showNoPreviousToast = shouldShow }
        }
    }

    /// 辅助函数，接收一个“设置器”闭包来显示和隐藏提示
    private func showToast(setter: @escaping (Bool) -> Void) {
        setter(true)
        DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
            withAnimation {
                setter(false)
            }
        }
    }
}

