    let sourceName: String
    // ==================== 新增属性 ====================
    /// 接收从父视图传递过来的未读文章数量
    let unreadCount: Int
    // ===============================================
    @ObservedObject var viewModel: NewsViewModel
    var requestNextArticle: () -> Void
