    private func loadMarketCapData() {
        // 从数据库加载数据，而不是从 marketcap_pe.txt 文件
        // 注意：根据您的描述，表名为 "MNSPP " (末尾有空格)，如果实际没有，请移除
        let allMarketCapInfo = DatabaseManager.shared.fetchAllMarketCapData(from: "MNSPP")

        // 检查是否有数据返回
        if allMarketCapInfo.isEmpty {
            self.errorMessage = "未能从数据库 MNSPP 表加载到市值数据。"
            return
        }

        // 清空旧数据
        var newData: [String: MarketCapDataItem] = [:]

        // 遍历从数据库获取的结果
        for info in allMarketCapInfo {
            // 将数据库查询结果转换为 MarketCapDataItem
            let item = MarketCapDataItem(
                marketCap: info.marketCap,
                peRatio: info.peRatio,
                pb: info.pb
            )
            // 将数据存入字典，键为大写的 symbol
            newData[info.symbol.uppercased()] = item
        }

        // 在主线程更新 @Published 属性
        DispatchQueue.main.async {
            self.marketCapData = newData
        }
    }

    private func loadCompareData() {
        guard let url = Bundle.main.url(forResource: "Compare_All", withExtension: "txt") else {
            self.errorMessage = "Compare_All.txt 文件未找到"
            return
        }
        do {
            let text = try String(contentsOf: url, encoding: .utf8)
            let lines = text.split(separator: "\n")

            var originalCaseData: [String: String] = [:]
            var upperCaseMap: [String: String] = [:]

            for line in lines {
                let parts = line.split(separator: ":")
                if parts.count >= 2 {
                    let symbol = String(parts[0].trimmingCharacters(in: .whitespaces))
                    let value = String(parts[1].trimmingCharacters(in: .whitespaces))
                    originalCaseData[symbol] = value
                    upperCaseMap[symbol.uppercased()] = value
                }
            }
            compareData = upperCaseMap.merging(originalCaseData) { (_, new) in new }
        } catch {
            self.errorMessage = "加载 Compare_All.txt 失败: \(error.localizedDescription)"
        }
    }

    private func cleanSymbol(_ symbol: String) -> String {
        let pattern = "^([A-Za-z-]+)"
        guard let regex = try? NSRegularExpression(pattern: pattern, options: []),
              let match = regex.firstMatch(in: symbol, options: [], range: NSRange(location: 0, length: symbol.count)),
              let range = Range(match.range(at: 1), in: symbol) else {
            return symbol
        }
        return String(symbol[range])
    }

    private func parseStockLine(_ line: String) -> Stock? {
        let pattern = "^(.*?)\\s+(\\S+)\\s*:\\s*([+-]?[\\d\\.]+%)\\s*(.*)$"
        let regex = try? NSRegularExpression(pattern: pattern, options: [])
        guard let match = regex?.firstMatch(in: line, options: [], range: NSRange(location: 0, length: line.utf16.count)) else { return nil }

        guard let groupNameRange = Range(match.range(at: 1), in: line),
              let symbolRange = Range(match.range(at: 2), in: line),
              let valueRange = Range(match.range(at: 3), in: line),
              let descRange = Range(match.range(at: 4), in: line) else { return nil }

        let groupName = String(line[groupNameRange])
        let rawSymbol = String(line[symbolRange])
        let cleanedSymbol = cleanSymbol(rawSymbol)
        let value = String(line[valueRange])
        let desc = String(line[descRange])

        return Stock(groupName: groupName, rawSymbol: rawSymbol, symbol: cleanedSymbol, value: value, descriptions: desc)
    }

    private func parseETFLine(_ line: String) -> ETF? {
        let parts = line.split(separator: ":")
        guard parts.count >= 2 else { return nil }

        let rawSymbol = String(parts[0].trimmingCharacters(in: .whitespaces))
        let cleanedSymbol = cleanSymbol(rawSymbol)
        let rest = parts[1].trimmingCharacters(in: .whitespaces)

        let pattern = "^([+-]?[\\d\\.]+%)\\s+\\d+\\s+[+-]?[\\d\\.]+%\\s+(.*)$"
        let regex = try? NSRegularExpression(pattern: pattern, options: [])
        guard let match = regex?.firstMatch(in: rest, options: [], range: NSRange(location: 0, length: rest.utf16.count)) else { return nil }

        guard let valueRange = Range(match.range(at: 1), in: rest),
              let descRange = Range(match.range(at: 2), in: rest) else { return nil }

        let value = String(rest[valueRange])
        let descriptions = String(rest[descRange])

        return ETF(groupName: "ETFs", rawSymbol: rawSymbol, symbol: cleanedSymbol, value: value, descriptions: descriptions)
    }
}

import SwiftUI
import Combine

struct EarningReleaseView: View {
  @EnvironmentObject var dataService: DataService

  struct DateGroup: Identifiable {
    let id: String; let date: String; let items: [EarningRelease]
  }

  @State private var expandedSections: [String: Bool] = [:]
    // 新增：用于控制搜索页面显示的状态变量
    @State private var showSearchView = false

  private var groupedReleases: [DateGroup] {
    let dict = Dictionary(grouping: dataService.earningReleases, by: { $0.date })
    var groups: [DateGroup] = []
    for (date, items) in dict {
      groups.append(.init(id: date, date: date, items: items))
    }
    groups.sort { $0.date < $1.date }
    return groups
  }

  var body: some View {
    List {
      ForEach(groupedReleases) { group in
        Section(header: sectionHeader(for: group)) {
          if expandedSections[group.date] ?? true {
            ForEach(group.items) { item in
              sectionRow(for: item)
            }
          }
        }
      }
    }
    .navigationTitle("财报发布")
    .onAppear {
      dataService.loadData()
      initializeExpandedStates()
    }
    // 用 onReceive 监听 @Published 值的变化
    .onReceive(dataService.$earningReleases) { _ in
      initializeExpandedStates()
    }

      // 新增：在导航栏添加工具栏
      .toolbar {
          ToolbarItem(placement: .navigationBarTrailing) {
              Button(action: {
                  // 点击按钮时，触发导航
                  showSearchView = true
              }) {
                  Image(systemName: "magnifyingglass")
              }
          }
      }
      // 新增：定义导航的目标视图
      .navigationDestination(isPresented: $showSearchView) {
          // 传入 dataService 并设置 isSearchActive 为 true，让搜索框自动激活
          SearchView(isSearchActive: true, dataService: dataService)
      }
  }

    // MARK: - Section Header

    @ViewBuilder
    private func sectionHeader(for group: DateGroup) -> some View {
        HStack {
            Text(group.date)
                .font(.headline)
                .foregroundColor(.primary)
            Spacer()
            // 直接显示 chevron
            Image(systemName: (expandedSections[group.date] ?? true)
                  ? "chevron.down"
                  : "chevron.right")
                .foregroundColor(.secondary)
        }
        .padding(.vertical, 5)
        // 让整个 HStack 区域都能点
        .contentShape(Rectangle())
        .onTapGesture {
            // 切换折叠/展开
            let isExpanded = expandedSections[group.date] ?? true
            withAnimation {
                expandedSections[group.date] = !isExpanded
            }
        }
    }

    // MARK: - Section Row

    private func sectionRow(for item: EarningRelease) -> some View {
        // 拿到分组名
        let groupName = dataService.getCategory(for: item.symbol) ?? "Stocks"
        return NavigationLink(destination: ChartView(symbol: item.symbol, groupName: groupName)) {
            VStack(alignment: .leading, spacing: 4) {
                Text(item.symbol)
                    .font(.system(.body, design: .monospaced))
                    .foregroundColor(item.color)
                if let tags = getTags(for: item.symbol), !tags.isEmpty {
                    Text(tags.joined(separator: ", "))
                        .font(.footnote)
                        .foregroundColor(.secondary)
                        .lineLimit(2)
                        .multilineTextAlignment(.leading)
                        .fixedSize(horizontal: false, vertical: true)
                }
            }
            .padding(.vertical, 2)
        }
    }

    // MARK: - 初始化每组的“默认展开状态”

    private func initializeExpandedStates() {
        for group in groupedReleases {
            // 只有还没设置过的组，才根据条目数设初始值
            if expandedSections[group.date] == nil {
                // 超过 5 条折叠(false)，否则展开(true)
                expandedSections[group.date] = (group.items.count <= 5)
            }
        }
    }

    // MARK: - 获取 Tags

    private func getTags(for symbol: String) -> [String]? {
        if let stockTags = dataService.descriptionData?
            .stocks.first(where: { $0.symbol.uppercased() == symbol.uppercased() })?.tag {
            return stockTags
        }
        if let etfTags = dataService.descriptionData?
            .etfs.first(where: { $0.symbol.uppercased() == symbol.uppercased() })?.tag {
            return etfTags
        }
        return nil
    }
}

