class SimilarViewModel: ObservableObject {
    @Published var relatedSymbols: [RelatedSymbol] = []
    @Published var errorMessage: String? = nil
    @Published var isLoading: Bool = false

    private var cancellables = Set<AnyCancellable>()
    private let symbol: String

    init(symbol: String) {
        self.symbol = symbol
        loadSimilarSymbols()
    }

    private func loadSimilarSymbols() {
        isLoading = true
        DispatchQueue.global(qos: .userInitiated).async {
            // 加载数据
            let dataService = DataService1.shared

            // 获取 tags_weight 数据
            dataService.loadWeightGroups()

            // 获取 symbol 的 tags 及权重
            let targetTagsWithWeight = self.findTagsBySymbol(symbol: self.symbol, data: dataService.descriptionData1)

            guard !targetTagsWithWeight.isEmpty else {
                DispatchQueue.main.async {
                    self.errorMessage = "未找到该 symbol 的 tags"
                    self.isLoading = false
                }
                return
            }

            // 查找相似的 symbols
            let relatedSymbolsDict = self.findSymbolsByTags(targetTagsWithWeight: targetTagsWithWeight, weightGroups: dataService.tagsWeightConfig, data: dataService.descriptionData1)

            // 移除原始 symbol
            var stocks = relatedSymbolsDict["stocks"] ?? []
            var etfs = relatedSymbolsDict["etfs"] ?? []
            stocks.removeAll { $0.symbol.uppercased() == self.symbol.uppercased() }
            etfs.removeAll { $0.symbol.uppercased() == self.symbol.uppercased() }

            // 创建 RelatedSymbol 数组并设置分类
            let stocksRelated = stocks.map { item -> RelatedSymbol in
                let totalWeight = item.matchedTags.reduce(0.0) { $0 + $1.weight }
                let compareValue = dataService.compareData1[item.symbol] ?? ""
                let allTags = item.allTags
                return RelatedSymbol(symbol: item.symbol, totalWeight: totalWeight, compareValue: compareValue, allTags: allTags)
            }

            let etfsRelated = etfs.map { item -> RelatedSymbol in
                let totalWeight = item.matchedTags.reduce(0.0) { $0 + $1.weight }
                let compareValue = dataService.compareData1[item.symbol] ?? ""
                let allTags = item.allTags
                return RelatedSymbol(symbol: item.symbol, totalWeight: totalWeight, compareValue: compareValue, allTags: allTags)
            }

            let allSymbols = stocksRelated + etfsRelated

            // 按 totalWeight 降序排序
            let sortedSymbols = allSymbols.sorted { $0.totalWeight > $1.totalWeight }.prefix(50)

            DispatchQueue.main.async {
                self.relatedSymbols = Array(sortedSymbols)
                self.isLoading = false
            }
        }
    }

    // MARK: - Helper Functions

    private func findTagsBySymbol(symbol: String, data: DescriptionData1?) -> [(tag: String, weight: Double)] {
        guard let data = data else { return [] }
        var tagsWithWeight: [(String, Double)] = []

        for category in ["stocks", "etfs"] {
            let items: [SymbolItem]
            if category == "stocks" {
                items = data.stocks
            } else {
                items = data.etfs
            }

            for item in items {
                if item.symbol.uppercased() == symbol.uppercased() {
                    for tag in item.tag {
                        if let weightKey = DataService1.shared.tagsWeightConfig.first(where: { $0.value.contains(tag) })?.key {
                            tagsWithWeight.append((tag, weightKey))
                        } else {
                            tagsWithWeight.append((tag, 1.0)) // 默认权重
                        }
                    }
                    return tagsWithWeight
                }
            }
        }
        return tagsWithWeight
    }

    private func findSymbolsByTags(targetTagsWithWeight: [(tag: String, weight: Double)], weightGroups: [Double: [String]], data: DescriptionData1?) -> [String: [MatchedSymbol]] {
        var relatedSymbols: [String: [MatchedSymbol]] = ["stocks": [], "etfs": []]

        // 创建目标标签字典，键为小写标签，值为权重
        var targetTagsDict: [String: Double] = [:]
        for (tag, weight) in targetTagsWithWeight {
            targetTagsDict[tag.lowercased()] = weight
        }

        guard let data = data else { return relatedSymbols }

        for category in ["stocks", "etfs"] {
            let items: [SymbolItem]
            if category == "stocks" {
                items = data.stocks
            } else {
                items = data.etfs
            }

            for item in items {
                var matchedTags: [(tag: String, weight: Double)] = []
                var usedTags = Set<String>()

                // 第一阶段：完全匹配
                for tag in item.tag {
                    let tagLower = tag.lowercased()
                    if let weight = targetTagsDict[tagLower], !usedTags.contains(tagLower) {
                        matchedTags.append((tag, weight))
                        usedTags.insert(tagLower)
                    }
                }

                // 第二阶段：部分匹配
                for tag in item.tag {
                    let tagLower = tag.lowercased()
                    if usedTags.contains(tagLower) { continue }
                    for (targetTag, weight) in targetTagsDict {
                        if (tagLower.contains(targetTag) || targetTag.contains(tagLower)) && tagLower != targetTag && !usedTags.contains(targetTag) {
                            // 如果原始权重大于1，给1分；否则给原始权重分数
                            let matchWeight = weight > 1.0 ? 1.0 : weight
                            matchedTags.append((tag, matchWeight))
                            usedTags.insert(targetTag)
                            break
                        }
                    }
                }

                if !matchedTags.isEmpty {
                    relatedSymbols[category]?.append(MatchedSymbol(symbol: item.symbol, matchedTags: matchedTags, allTags: item.tag))
                }
            }
        }

        // 按总权重降序排序
        for category in relatedSymbols.keys {
            relatedSymbols[category]?.sort { (a, b) -> Bool in
                let totalA = a.matchedTags.reduce(0.0) { $0 + $1.weight }
                let totalB = b.matchedTags.reduce(0.0) { $0 + $1.weight }
                return totalA > totalB
            }
        }

        return relatedSymbols
    }
}

struct MatchedSymbol {
    let symbol: String
    let matchedTags: [(tag: String, weight: Double)]
    let allTags: [String]
}

struct RelatedSymbol: Identifiable {
    let id = UUID()
    let symbol: String
    let totalWeight: Double
    let compareValue: String
    let allTags: [String]
}

import Foundation

protocol SymbolItem {
    var symbol: String { get }
    var tag: [String] { get }
}

struct DescriptionData1: Codable {
    let stocks: [Stock1]
    let etfs: [ETF1]
}

struct Stock1: Codable, SymbolItem {
    let symbol: String
    let name: String
    let tag: [String]
    let description1: String
    let description2: String
    let value: String
}

struct ETF1: Codable, SymbolItem {
    let symbol: String
    let name: String
    let tag: [String]
    let description1: String
    let description2: String
    let value: String
}

class DataService1 {
    static let shared = DataService1()

    var descriptionData1: DescriptionData1?
    var tagsWeightConfig: [Double: [String]] = [:]
    var compareData1: [String: String] = [:]

    private init() {
        loadDescriptionData1()
        loadWeightGroups()
        loadCompareData1()
    }

    private func loadDescriptionData1() {
        guard let path = Bundle.main.path(forResource: "description", ofType: "json") else {
            print("description.json 文件未找到")
            return
        }
        let url = URL(fileURLWithPath: path)
        do {
            let data = try Data(contentsOf: url)
            let decoder = JSONDecoder()
            self.descriptionData1 = try decoder.decode(DescriptionData1.self, from: data)
        } catch {
            print("解析 description.json 时出错: \(error)")
        }
    }

    func loadWeightGroups() {
        guard let path = Bundle.main.path(forResource: "tags_weight", ofType: "json") else {
            print("tags_weight.json 文件未找到")
            return
        }
        let url = URL(fileURLWithPath: path)
        do {
            let data = try Data(contentsOf: url)
            let rawData = try JSONSerialization.jsonObject(with: data, options: []) as? [String: [String]]
            var weightGroups: [Double: [String]] = [:]
            if let rawData = rawData {
                for (k, v) in rawData {
                    if let key = Double(k) {
                        weightGroups[key] = v
                    }
                }
            }
            self.tagsWeightConfig = weightGroups
        } catch {
            print("解析 tags_weight.json 时出错: \(error)")
        }
    }

    private func loadCompareData1() {
        guard let path = Bundle.main.path(forResource: "Compare_All", ofType: "txt") else {
            print("Compare_All.txt 文件未找到")
            return
        }
        let url = URL(fileURLWithPath: path)
        do {
            let content = try String(contentsOf: url, encoding: .utf8)
            let lines = content.split(separator: "\n")
            for line in lines {
                let components = line.split(separator: ":", maxSplits: 1).map { String($0).trimmingCharacters(in: .whitespaces) }
                if components.count == 2 {
                    compareData1[components[0]] = components[1]
                }
            }
        } catch {
            print("解析 Compare_All.txt 时出错: \(error)")
        }
    }
}

import SwiftUI

struct ArticleContainerView: View {
    let initialArticle: Article
    let navigationContext: NavigationContext

    @ObservedObject var viewModel: NewsViewModel

    @State private var currentArticle: Article
    @State private var currentSourceName: String

    // 1. 用于在当前页面生命周期内，实时更新未读计数的局部状态变量
    @State private var liveUnreadCount: Int

    // 2. 用于累积在本次查看会话中所有被读过的文章ID
    @State private var readArticleIDsInThisSession: Set<UUID> = []

    @State private var showNoNextToast = false
    @State private var showNoPreviousToast = false

    enum NavigationContext {
        case fromSource(String)
        case fromAllArticles
    }

    // 这个计算属性现在只用于初始化
    private var initialUnreadCount: Int {
        switch navigationContext {
        case .fromAllArticles:
            return viewModel.totalUnreadCount
        case .fromSource(let sourceName):
            return viewModel.sources.first { $0.name == sourceName }?.unreadCount ?? 0
        }
    }

    // 我们需要自定义 init 来正确初始化新的 @State 变量 liveUnreadCount
    init(article: Article, sourceName: String, context: NavigationContext, viewModel: NewsViewModel) {
        self.initialArticle = article
        self.navigationContext = context
        self.viewModel = viewModel

        // 初始化内部状态
        self._currentArticle = State(initialValue: article)
        self._currentSourceName = State(initialValue: sourceName)

        // 根据上下文计算初始的未读数，并用它来初始化 liveUnreadCount
        let baseCount: Int
        switch context {
        case .fromAllArticles:
            baseCount = viewModel.totalUnreadCount
        case .fromSource(let name):
            baseCount = viewModel.sources.first { $0.name == name }?.unreadCount ?? 0
        }
        self._liveUnreadCount = State(initialValue: baseCount)
    }

    var body: some View {
        ZStack(alignment: .bottom) {
            // 将我们实时的、局部的未读数传递给详情页
            ArticleDetailView(
                article: currentArticle,
                sourceName: currentSourceName,
                unreadCount: liveUnreadCount, // <- 使用局部状态
                viewModel: viewModel,
                requestNextArticle: {
                    self.switchToNextArticle()
                },
                requestPreviousArticle: {
                    self.switchToPreviousArticle()
                }
            )
            .id(currentArticle.id)
            .transition(.asymmetric(
                insertion: .move(edge: .bottom).combined(with: .opacity),
                removal: .move(edge: .top).combined(with: .opacity))
            )

            if showNoNextToast {
                ToastView(message: "该分组内已无更多文章")
            }

            if showNoPreviousToast {
                ToastView(message: "这已经是第一篇文章了")
            }
        }
        // --- 已移除: .onAppear ---
        // .onAppear 修饰符已完全删除，不再更新 lastViewedArticleID

        // --- .onDisappear 逻辑保持不变 ---
        .onDisappear {
            // 当视图最终消失时，将当前正在看的文章也加入待处理集合
            // 我们需要检查这篇文章是否本身就是未读的
            if !currentArticle.isRead {
                readArticleIDsInThisSession.insert(currentArticle.id)
            }

            // 一次性将所有在本次会话中读过的文章ID提交给ViewModel
            for articleID in readArticleIDsInThisSession {
                viewModel.markAsRead(articleID: articleID)
            }
        }
        // --- 修改: .onChange ---
        .onChange(of: currentArticle.id) { oldValue, newValue in
            // --- 已移除 ---
            // 更新 lastViewedArticleID 的代码行已被删除
            // viewModel.lastViewedArticleID = newValue

            // 当文章切换时，我们处理刚刚离开的文章 (oldValue)

            // 检查这篇文章是否本身是未读的，并且我们还没有处理过它
            let wasArticleUnread = !viewModel.sources.flatMap { $0.articles }.first { $0.id == oldValue }!.isRead
            let isNewToSession = !readArticleIDsInThisSession.contains(oldValue)

            if wasArticleUnread && isNewToSession {
                // 如果它确实是篇新的未读文章，那么：
                // 1. 将局部未读数减 1，立即更新UI
                liveUnreadCount -= 1
                // 2. 将它的ID加入待处理集合，以便在最后统一提交
                readArticleIDsInThisSession.insert(oldValue)
            }
        }
    }

    /// 切换到下一篇文章的逻辑
    private func switchToNextArticle() {
        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        if let next = viewModel.findNextUnread(after: currentArticle.id,
                                               inSource: sourceNameToSearch) {
            withAnimation(.easeInOut(duration: 0.4)) {
                self.currentArticle = next.article
                self.currentSourceName = next.sourceName
            }
        } else {
            showToast { shouldShow in self.showNoNextToast = shouldShow }
        }
    }

    /// 切换到上一篇文章的逻辑
    private func switchToPreviousArticle() {
        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        if let prev = viewModel.findPreviousUnread(before: currentArticle.id, inSource: sourceNameToSearch) {
            withAnimation(.interactiveSpring(response: 0.4, dampingFraction: 0.8)) {
                self.currentArticle = prev.article
                self.currentSourceName = prev.sourceName
            }
        } else {
            showToast { shouldShow in self.showNoPreviousToast = shouldShow }
        }
    }

    /// 辅助函数，接收一个“设置器”闭包来显示和隐藏提示
    private func showToast(setter: @escaping (Bool) -> Void) {
        setter(true)
        DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
            withAnimation {
                setter(false)
            }
        }
    }
}

