    // 使用 @State 来管理是否已认证的状态
    @State private var isAuthenticated = false

    var body: some View {
        if isAuthenticated {
            // 如果已认证，显示主新闻阅读器界面
            // fullScreenCover 会全屏展示，并允许用户通过下拉手势返回（如果需要）
            SourceListView(isAuthenticated: $isAuthenticated)
        } else {
            // 否则，显示一个简单的登录界面
//            LoginView(isAuthenticated: $isAuthenticated)
            SourceListView(isAuthenticated: $isAuthenticated)
        }
    }
}

// 登录界面
