    @StateObject private var resourceManager = ResourceManager()

    @Binding var isAuthenticated: Bool

    // --- 新增状态用于Alert弹窗 ---
    @State private var showErrorAlert = false
    @State private var errorMessage = ""

    var body: some View {
        ZStack {
            NavigationView {
                List {
                    // "Unread" 行
                    ZStack {
                        HStack {
                            Text("Unread")
                                .font(.system(size: 28, weight: .bold))
                                .foregroundColor(.primary)
                            Spacer()
                            Text("\(viewModel.totalUnreadCount)")
                                .font(.system(size: 28, weight: .bold))
                                .foregroundColor(.gray)
                        }
                        .padding()
                        NavigationLink(destination: AllArticlesListView(viewModel: viewModel)) {
                            EmptyView()
                        }.opacity(0)
                    }
                    .listRowSeparator(.hidden)

                    // 新闻来源列表
                    ForEach(viewModel.sources) { source in
                        ZStack {
                            HStack {
                                Text(source.name)
                                    .fontWeight(.semibold)
                                Spacer()
                                Text("\(source.unreadCount)")
                                    .foregroundColor(.gray)
                            }
                            .padding(.vertical, 8)

                            NavigationLink(destination: ArticleListView(source: source, viewModel: viewModel)) {
                                EmptyView()
                            }.opacity(0)
                        }
                        .listRowSeparator(.hidden)
                    }
                }
                .listStyle(.plain)
                .navigationTitle("Inoreader")
                .navigationBarTitleDisplayMode(.inline)
                .toolbar {
                    ToolbarItem(placement: .navigationBarLeading) {
                        Button(action: {
                            isAuthenticated = false
                        }) {
                            Image(systemName: "chevron.backward")
                            Text("登出")
                        }
                    }
                    ToolbarItem(placement: .navigationBarTrailing) {
                        Button(action: {
                            Task {
                                await syncResources()
                            }
                        }) {
                            Image(systemName: "arrow.clockwise")
                        }
                        // 在同步时禁用按钮，防止重复点击
                        .disabled(resourceManager.isSyncing)
                    }
                }
            }
            .accentColor(.gray)
            .preferredColorScheme(.dark)
            // 当本地数据加载后，即使同步失败，用户依然可以操作此NavigationView
            .onAppear {
                // 视图出现时先加载本地数据，然后再检查更新
                viewModel.loadNews()
                Task {
                    await syncResources()
                }
            }

            // --- 改进后的加载/进度覆盖层 ---
            if resourceManager.isSyncing {
                VStack(spacing: 15) {
                    // 根据是否处于下载阶段，显示不同UI
                    if resourceManager.isDownloading {
                        // 下载阶段：显示进度条
                        Text(resourceManager.syncMessage)
                            .font(.headline)
                            .foregroundColor(.white)

                        ProgressView(value: resourceManager.downloadProgress)
                            .progressViewStyle(LinearProgressViewStyle(tint: .white))
                            .padding(.horizontal, 50)

                        Text(resourceManager.progressText)
                            .font(.caption)
                            .foregroundColor(.secondary)

                    } else {
                        // 检查阶段：显示转圈
                        ProgressView()
                            .progressViewStyle(CircularProgressViewStyle(tint: .white))
                            .scaleEffect(1.5)

                        Text(resourceManager.syncMessage)
                            .padding(.top, 10)
                            .foregroundColor(.secondary)
                    }
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .background(Color.black.opacity(0.6))
                .edgesIgnoringSafeArea(.all)
                // 点击背景不会穿透
                .contentShape(Rectangle())
            }
        }
        // --- 非阻塞的错误提示 ---
        .alert("", isPresented: $showErrorAlert, actions: {
            Button("好的", role: .cancel) { }
        }, message: {
            Text(errorMessage)
        })
    }

    // ==================== 核心修改点在这里 ====================
    private func syncResources() async {
        do {
            try await resourceManager.checkAndDownloadUpdates()
            // 同步成功后，重新加载新闻数据以反映更新
            viewModel.loadNews()
        } catch {
            // 根据错误类型，决定是否打扰用户
            switch error {

            // --- 情况1: 服务器端问题，静默处理 ---
            case is DecodingError:
                // 服务器返回了非JSON数据（很可能是HTML错误页），这是服务器问题。
                print("同步失败 (服务器返回数据格式错误，已静默处理): \(error)")
                // 不做任何事，不弹窗。UI会自动解锁，用户可以继续使用本地数据。

            case let urlError as URLError where urlError.code == .cannotConnectToHost:
                // 明确是“无法连接到主机”，通常意味着服务器进程未启动。
                print("同步失败 (无法连接到主机，已静默处理): \(error.localizedDescription)")
                // 同样不弹窗。

            // --- 情况2: 客户端问题或其他未知错误，弹窗提示 ---
            default:
                // 对于其他所有错误（如手机没网、超时等），我们认为用户需要被告知。
                print("同步失败 (客户端或其他问题): \(error)")
                // 更新一下提示语，引导用户检查网络
                self.errorMessage = "网络异常\n\n请点击右上角刷新↻按钮重试"
                self.showErrorAlert = true
            }
        }
    }
    // ==========================================================
}

import Foundation

// 数据模型保持不变
struct FileInfo: Codable {
    let name: String
    let type: String
}

struct ServerVersion: Codable {
    let version: String
    let files: [FileInfo]
}

@MainActor
class ResourceManager: ObservableObject {

    // --- 状态管理 ---
    @Published var isSyncing = false          // 控制整个同步覆盖层的显示与隐藏
    @Published var syncMessage = "启动中..." // 显示当前操作的文本信息

    // --- 新增的状态，用于精确控制进度条 ---
    @Published var isDownloading = false      // 区分是“检查中”还是“下载中”
    @Published var downloadProgress: Double = 0.0 // 进度条的进度 (0.0 to 1.0)
    @Published var progressText = ""          // 进度文本，如 "1/6"

    private let serverBaseURL = "http://192.168.50.147:5000/api/ONews"
    private let fileManager = FileManager.default
    private var documentsDirectory: URL {
        fileManager.urls(for: .documentDirectory, in: .userDomainMask)[0]
    }

    // MARK: - Main Sync Logic
    func checkAndDownloadUpdates() async throws {
        // 1. 初始化状态
        self.isSyncing = true
        self.isDownloading = false // 开始时不是下载状态，而是检查状态
        self.syncMessage = "正在检查更新..."
        self.progressText = ""
        self.downloadProgress = 0.0

        do {
            let serverVersion = try await getServerVersion()
            let localFiles = try getLocalFiles()

            let filesToDownload = serverVersion.files.filter { fileInfo in
                !localFiles.contains(fileInfo.name)
            }

            // 2. 检查是否需要下载
            if filesToDownload.isEmpty {
                syncMessage = "当前资源已经是最新的了。"
                // 等待短暂时间让用户看到消息，然后结束
                try await Task.sleep(nanoseconds: 1_500_000_000) // 1.5秒
                self.isSyncing = false
                return
            }

            print("需要下载的文件或目录: \(filesToDownload.map { $0.name })")

            // 3. 进入下载阶段
            self.isDownloading = true // 切换到下载模式，UI会显示进度条
            let totalFiles = filesToDownload.count

            for (index, fileInfo) in filesToDownload.enumerated() {
                // 更新进度
                self.progressText = "\(index + 1)/\(totalFiles)"
                self.downloadProgress = Double(index + 1) / Double(totalFiles)

                if fileInfo.type == "images" {
                    self.syncMessage = "正在处理目录..."
                    try await downloadDirectory(named: fileInfo.name, totalFiles: totalFiles, currentIndex: index)
                } else {
                    self.syncMessage = "正在下载文件..."
                    try await downloadSingleFile(named: fileInfo.name)
                }
            }

            // 4. 同步完成
            self.isDownloading = false
            self.syncMessage = "更新完成！"
            self.progressText = ""
            try await Task.sleep(nanoseconds: 1_000_000_000) // 1秒
            self.isSyncing = false

        } catch {
            // 5. 错误处理：直接向上抛出异常
            // 让调用方 (View) 来决定如何处理UI
            self.isSyncing = false
            self.isDownloading = false
            throw error // 将错误传递给 SourceListView 中的 catch 块
        }
    }

    // MARK: - Helper Functions

    private func getServerVersion() async throws -> ServerVersion {
        guard let url = URL(string: "\(serverBaseURL)/check_version") else { throw URLError(.badURL) }
        let (data, _) = try await URLSession.shared.data(from: url)
        return try JSONDecoder().decode(ServerVersion.self, from: data)
    }

    private func getLocalFiles() throws -> Set<String> {
        let contents = try fileManager.contentsOfDirectory(atPath: documentsDirectory.path)
        return Set(contents)
    }

    private func getFileList(for directoryName: String) async throws -> [String] {
        guard var components = URLComponents(string: "\(serverBaseURL)/list_files") else {
            throw URLError(.badURL)
        }
        components.queryItems = [URLQueryItem(name: "dirname", value: directoryName)]
        guard let url = components.url else {
            throw URLError(.badURL)
        }

        print("准备获取目录清单: \(url.absoluteString)")
        let (data, _) = try await URLSession.shared.data(from: url)
        return try JSONDecoder().decode([String].self, from: data)
    }

    // downloadDirectory 和 downloadSingleFile 保持不变，因为它们只负责下载逻辑
    // 进度更新的责任已经移交给了主函数 checkAndDownloadUpdates

    private func downloadDirectory(named directoryName: String, totalFiles: Int, currentIndex: Int) async throws {
        let fileList = try await getFileList(for: directoryName)
        if fileList.isEmpty {
            print("目录 \(directoryName) 在服务器上为空，跳过。")
            return
        }
        print("目录 \(directoryName) 包含 \(fileList.count) 个文件，准备逐个下载。")

        let localDirectoryURL = documentsDirectory.appendingPathComponent(directoryName)
        try fileManager.createDirectory(at: localDirectoryURL, withIntermediateDirectories: true, attributes: nil)

        for (fileIndex, remoteFilename) in fileList.enumerated() {
            // 更新更详细的消息
            self.syncMessage = "正在下载新闻图片... (\(fileIndex + 1)/\(fileList.count))"

            let downloadPath = "\(directoryName)/\(remoteFilename)"

            guard var components = URLComponents(string: "\(serverBaseURL)/download") else {
                print("❌ Invalid base URL for components")
                continue
            }
            components.queryItems = [URLQueryItem(name: "filename", value: downloadPath)]
            guard let url = components.url else {
                print("❌ Could not create final URL from components for path: \(downloadPath)")
                continue
            }

            let (tempURL, response) = try await URLSession.shared.download(from: url)
            guard let httpResponse = response as? HTTPURLResponse, httpResponse.statusCode == 200 else {
                print("❌ 服务器响应错误 for \(url.absoluteString)")
                throw URLError(.badServerResponse)
            }

            let destinationURL = localDirectoryURL.appendingPathComponent(remoteFilename)
            if fileManager.fileExists(atPath: destinationURL.path) {
                try fileManager.removeItem(at: destinationURL)
            }
            try fileManager.moveItem(at: tempURL, to: destinationURL)
        }
        print("✅ 目录 \(directoryName) 内所有文件下载完成。")
    }

    private func downloadSingleFile(named filename: String) async throws {
        guard var components = URLComponents(string: "\(serverBaseURL)/download") else {
            throw URLError(.badURL)
        }
        components.queryItems = [URLQueryItem(name: "filename", value: filename)]
        guard let url = components.url else {
            throw URLError(.badURL)
        }

        print("✅ [1/3] 开始下载单个文件: \(url.absoluteString)")
        let (tempURL, response) = try await URLSession.shared.download(from: url)

        guard let httpResponse = response as? HTTPURLResponse, httpResponse.statusCode == 200 else {
            throw URLError(.badServerResponse)
        }
        print("✅ [2/3] 下载成功，临时文件位于: \(tempURL.path)")

        let destinationURL = documentsDirectory.appendingPathComponent(filename)
        if fileManager.fileExists(atPath: destinationURL.path) {
            try fileManager.removeItem(at: destinationURL)
        }
        try fileManager.moveItem(at: tempURL, to: destinationURL)
        print("✅ [3/3] 文件 \(filename) 已成功保存。")
    }
}

import SwiftUI

struct ArticleContainerView: View {
    let initialArticle: Article
    let navigationContext: NavigationContext

    @ObservedObject var viewModel: NewsViewModel

    @State private var currentArticle: Article
    @State private var currentSourceName: String

    // 1. 用于在当前页面生命周期内，实时更新未读计数的局部状态变量
    @State private var liveUnreadCount: Int

    // 2. 用于累积在本次查看会话中所有被读过的文章ID
    @State private var readArticleIDsInThisSession: Set<UUID> = []

    @State private var showNoNextToast = false
    @State private var showNoPreviousToast = false

    enum NavigationContext {
        case fromSource(String)
        case fromAllArticles
    }

    // 这个计算属性现在只用于初始化
    private var initialUnreadCount: Int {
        switch navigationContext {
        case .fromAllArticles:
            return viewModel.totalUnreadCount
        case .fromSource(let sourceName):
            return viewModel.sources.first { $0.name == sourceName }?.unreadCount ?? 0
        }
    }

    // 我们需要自定义 init 来正确初始化新的 @State 变量 liveUnreadCount
    init(article: Article, sourceName: String, context: NavigationContext, viewModel: NewsViewModel) {
        self.initialArticle = article
        self.navigationContext = context
        self.viewModel = viewModel

        // 初始化内部状态
        self._currentArticle = State(initialValue: article)
        self._currentSourceName = State(initialValue: sourceName)

        // 根据上下文计算初始的未读数，并用它来初始化 liveUnreadCount
        let baseCount: Int
        switch context {
        case .fromAllArticles:
            baseCount = viewModel.totalUnreadCount
        case .fromSource(let name):
            baseCount = viewModel.sources.first { $0.name == name }?.unreadCount ?? 0
        }
        self._liveUnreadCount = State(initialValue: baseCount)
    }

    var body: some View {
        ZStack(alignment: .bottom) {
            // 将我们实时的、局部的未读数传递给详情页
            ArticleDetailView(
                article: currentArticle,
                sourceName: currentSourceName,
                unreadCount: liveUnreadCount, // <- 使用局部状态
                viewModel: viewModel,
                requestNextArticle: {
                    self.switchToNextArticle()
                },
                requestPreviousArticle: {
                    self.switchToPreviousArticle()
                }
            )
            .id(currentArticle.id)
            .transition(.asymmetric(
                insertion: .move(edge: .bottom).combined(with: .opacity),
                removal: .move(edge: .top).combined(with: .opacity))
            )

            if showNoNextToast {
                ToastView(message: "该分组内已无更多文章")
            }

            if showNoPreviousToast {
                ToastView(message: "这已经是第一篇文章了")
            }
        }
        // --- 已移除: .onAppear ---
        // .onAppear 修饰符已完全删除，不再更新 lastViewedArticleID

        // --- .onDisappear 逻辑保持不变 ---
        .onDisappear {
            // 当视图最终消失时，将当前正在看的文章也加入待处理集合
            // 我们需要检查这篇文章是否本身就是未读的
            if !currentArticle.isRead {
                readArticleIDsInThisSession.insert(currentArticle.id)
            }

            // 一次性将所有在本次会话中读过的文章ID提交给ViewModel
            for articleID in readArticleIDsInThisSession {
                viewModel.markAsRead(articleID: articleID)
            }
        }
        // --- 修改: .onChange ---
        .onChange(of: currentArticle.id) { oldValue, newValue in
            // --- 已移除 ---
            // 更新 lastViewedArticleID 的代码行已被删除
            // viewModel.lastViewedArticleID = newValue

            // 当文章切换时，我们处理刚刚离开的文章 (oldValue)

            // 检查这篇文章是否本身是未读的，并且我们还没有处理过它
            let wasArticleUnread = !viewModel.sources.flatMap { $0.articles }.first { $0.id == oldValue }!.isRead
            let isNewToSession = !readArticleIDsInThisSession.contains(oldValue)

            if wasArticleUnread && isNewToSession {
                // 如果它确实是篇新的未读文章，那么：
                // 1. 将局部未读数减 1，立即更新UI
                liveUnreadCount -= 1
                // 2. 将它的ID加入待处理集合，以便在最后统一提交
                readArticleIDsInThisSession.insert(oldValue)
            }
        }
    }

    /// 切换到下一篇文章的逻辑
    private func switchToNextArticle() {
        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        if let next = viewModel.findNextUnread(after: currentArticle.id,
                                               inSource: sourceNameToSearch) {
            withAnimation(.easeInOut(duration: 0.4)) {
                self.currentArticle = next.article
                self.currentSourceName = next.sourceName
            }
        } else {
            showToast { shouldShow in self.showNoNextToast = shouldShow }
        }
    }

    /// 切换到上一篇文章的逻辑
    private func switchToPreviousArticle() {
        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        if let prev = viewModel.findPreviousUnread(before: currentArticle.id, inSource: sourceNameToSearch) {
            withAnimation(.interactiveSpring(response: 0.4, dampingFraction: 0.8)) {
                self.currentArticle = prev.article
                self.currentSourceName = prev.sourceName
            }
        } else {
            showToast { shouldShow in self.showNoPreviousToast = shouldShow }
        }
    }

    /// 辅助函数，接收一个“设置器”闭包来显示和隐藏提示
    private func showToast(setter: @escaping (Bool) -> Void) {
        setter(true)
        DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
            withAnimation {
                setter(false)
            }
        }
    }
}

