                                    linePath.addLine(to: CGPoint(x: x, y: verticalPadding))
                                    linePath.addLine(to: CGPoint(x: x, y: size.height - verticalPadding))
                                    context.stroke(linePath, with: .color(Color.gray), style: StrokeStyle(lineWidth: 1, dash: [4]))

                                    // 第二个点的高亮显示
