import Foundation
import SwiftUI

// MARK: - 数据模型
struct VersionResponse: Codable {
let version: String
let files: [FileInfo]
}

struct FileInfo: Codable, Hashable {
let name: String
let type: String
}

// MARK: - 更新状态
enum UpdateState {
case idle
case checking
case downloading(progress: Double, total: Int)
case finished
case error(message: String)
}

// MARK: - UpdateManager
@MainActor
class UpdateManager: ObservableObject {
    static let shared = UpdateManager()

    @Published var updateState: UpdateState = .idle

    private let serverBaseURL = "http://192.168.50.148:5000/api/Finance"
    private let localVersionKey = "FinanceAppLocalDataVersion"

    private init() {}

    func checkForUpdates() async -> Bool {
        self.updateState = .checking
        print("开始检查更新...")

        // 1. 获取服务器版本信息
        guard let serverVersionResponse = await fetchServerVersion() else {
            let errorMessage = "无法获取服务器版本信息。"
            print(errorMessage)
            self.updateState = .error(message: errorMessage)
            return false
        }

        // 2. 获取本地版本信息
        let localVersion = UserDefaults.standard.string(forKey: localVersionKey) ?? "0.0"
        print("服务器版本: \(serverVersionResponse.version), 本地版本: \(localVersion)")

        // 3. 比较版本
        if serverVersionResponse.version.compare(localVersion, options: .numeric) == .orderedDescending {
            print("发现新版本，开始下载文件...")
            // 发现新版本，下载文件
            let downloadSuccess = await downloadFiles(from: serverVersionResponse)
            if downloadSuccess {
                print("所有文件下载成功。")
                // 清理旧文件
                cleanupOldFiles(keeping: serverVersionResponse.files)
                // 更新本地版本号
                UserDefaults.standard.set(serverVersionResponse.version, forKey: localVersionKey)
                print("本地版本已更新至: \(serverVersionResponse.version)")
                self.updateState = .finished
                return true // 有更新
            } else {
                let errorMessage = "文件下载失败。"
                print(errorMessage)
                self.updateState = .error(message: errorMessage)
                return false
            }
        } else {
            print("当前已是最新版本。")
            self.updateState = .finished
            return false // 无更新
        }
    }

    private func fetchServerVersion() async -> VersionResponse? {
        guard let url = URL(string: "\(serverBaseURL)/check_version") else { return nil }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let decodedResponse = try JSONDecoder().decode(VersionResponse.self, from: data)
            return decodedResponse
        } catch {
            print("获取或解析版本文件失败: \(error)")
            return nil
        }
    }

    private func downloadFiles(from versionResponse: VersionResponse) async -> Bool {
        let filesToDownload = versionResponse.files
        let totalFiles = filesToDownload.count
        var downloadedCount = 0

        self.updateState = .downloading(progress: 0, total: totalFiles)

        // 使用 TaskGroup 并行下载
        return await withTaskGroup(of: Bool.self, body: { group in
            for fileInfo in filesToDownload {
                group.addTask {
                    return await self.downloadFile(named: fileInfo.name)
                }
            }

            var allSuccess = true
            for await success in group {
                if success {
                    downloadedCount += 1
                    let progress = Double(downloadedCount) / Double(totalFiles)
                    // 在主线程更新UI状态
                    await MainActor.run {
                        self.updateState = .downloading(progress: progress, total: totalFiles)
                    }
                } else {
                    allSuccess = false
                }
            }
            return allSuccess
        })
    }

    private func downloadFile(named filename: String) async -> Bool {
        guard let url = URL(string: "\(serverBaseURL)/download?filename=\(filename)") else {
            print("无效的下载URL for \(filename)")
            return false
        }

        do {
            print("正在下载: \(filename)")
            let (data, _) = try await URLSession.shared.data(from: url)

            let destinationURL = FileManagerHelper.documentsDirectory.appendingPathComponent(filename)
            try data.write(to: destinationURL)
            print("成功保存: \(filename) 到 Documents")
            return true
        } catch {
            print("下载或保存文件 \(filename) 失败: \(error)")
            return false
        }
    }

    private func cleanupOldFiles(keeping newFiles: [FileInfo]) {
        print("开始清理旧文件...")
        let newFileNames = Set(newFiles.map { $0.name })
        let fileManager = FileManager.default
        let documentsURL = FileManagerHelper.documentsDirectory

        // 定义文件基础名，用于识别哪些是需要版本管理的文件
        let baseFileNames = Set(newFiles.map { fileInfo -> String in
            if let range = fileInfo.name.range(of: "_\\d{6}\\.", options: .regularExpression) {
                return String(fileInfo.name[..<range.lowerBound])
            }
            return fileInfo.name
        })

        do {
            let fileURLs = try fileManager.contentsOfDirectory(at: documentsURL, includingPropertiesForKeys: nil)

            for url in fileURLs {
                let filename = url.lastPathComponent

                // 检查文件是否属于我们管理的基础文件名之一
                var shouldCleanup = false
                for baseName in baseFileNames {
                    if filename.hasPrefix("\(baseName)_") {
                        shouldCleanup = true
                        break
                    }
                }

                // 如果是受管理的文件，并且不在新文件列表中，则删除
                if shouldCleanup && !newFileNames.contains(filename) {
                    try fileManager.removeItem(at: url)
                    print("已删除旧文件: \(filename)")
                }
            }
        } catch {
            print("清理旧文件时出错: \(error)")
        }
    }
}

class FileManagerHelper {

    // 获取应用的 Documents 目录 URL
    static var documentsDirectory: URL {
        let paths = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)
        return paths[0]
    }

    /**
     在 Documents 目录中查找具有最新时间戳的文件。
     例如，对于 baseName="HighLow"，它会查找 "HighLow_250710.txt", "HighLow_250709.txt" 等，并返回最新的一个。

     - Parameters:
       - baseName: 文件名的基础部分 (例如, "HighLow")
     - Returns: 最新文件的 URL，如果找不到则返回 nil。
     */
    static func getLatestFileUrl(for baseName: String) -> URL? {
        let fileManager = FileManager.default
        let documentsURL = self.documentsDirectory

        do {
            // 获取 Documents 目录下的所有文件
            let fileURLs = try fileManager.contentsOfDirectory(at: documentsURL, includingPropertiesForKeys: nil)

            var latestFile: (url: URL, timestamp: String)? = nil

            // 正则表达式，用于匹配 "baseName_YYMMDD.extension" 格式
            // 例如: "HighLow_250710.json" -> 匹配 "HighLow", "250710", ".json"
            let regex = try NSRegularExpression(pattern: "^\(baseName)_(\\d{6})\\..+$")

            for url in fileURLs {
                let filename = url.lastPathComponent
                let range = NSRange(location: 0, length: filename.utf16.count)

                if let match = regex.firstMatch(in: filename, options: [], range: range) {
                    // 提取时间戳 (YYMMDD)
                    if let timestampRange = Range(match.range(at: 1), in: filename) {
                        let timestamp = String(filename[timestampRange])

                        // 如果是第一个匹配的文件，或者当前文件的时间戳更新
                        if latestFile == nil || timestamp > latestFile!.timestamp {
                            latestFile = (url, timestamp)
                        }
                    }
                }
            }

            // 如果找到了文件，返回其 URL
            if let file = latestFile {
                print("找到最新文件 for '\(baseName)': \(file.url.lastPathComponent)")
                return file.url
            } else {
                print("警告: 未能在 Documents 中找到 for '\(baseName)' 的任何版本文件。")
                return nil
            }

        } catch {
            print("错误: 无法列出 Documents 目录中的文件: \(error)")
            return nil
        }
    }
}

import SwiftUI
import Foundation

@main
struct Finance: App {
    var body: some Scene {
        WindowGroup {
            MainContentView()
        }
    }
}

// MARK: - 新增：更新状态视图
struct UpdateOverlayView: View {
    @ObservedObject var updateManager: UpdateManager

    var body: some View {
        Group {
            switch updateManager.updateState {
            case .idle, .finished:
                EmptyView()
            case .checking:
                VStack {
                    ProgressView()
                    Text("正在检查更新...")
                }
                .padding()
                .background(Color(.systemBackground).opacity(0.8))
                .cornerRadius(10)
                .shadow(radius: 10)
            case .downloading(let progress, let total):
                VStack {
                    ProgressView(value: progress)
                    Text("正在下载 \(Int(progress * Double(total)))/\(total)...")
                }
                .padding()
                .background(Color(.systemBackground).opacity(0.8))
                .cornerRadius(10)
                .shadow(radius: 10)
            case .error(let message):
                VStack {
                    Image(systemName: "xmark.octagon.fill").foregroundColor(.red)
                    Text("更新失败")
                    Text(message).font(.caption).foregroundColor(.secondary)
                }
                .padding()
                .background(Color(.systemBackground).opacity(0.8))
                .cornerRadius(10)
                .shadow(radius: 10)
            }
        }
    }
}


struct MainContentView: View {
    // MARK: - 修改
    @StateObject private var dataService = DataService.shared
    @StateObject private var updateManager = UpdateManager.shared
    @State private var isDataReady = false

    var body: some View {
        ZStack {
            NavigationStack {
                VStack(spacing: 0) {
                    if isDataReady {
                        // 1. 上部：Sectors 展示
                        IndicesContentView()
                            .frame(maxHeight: .infinity, alignment: .top)

                        Divider()

                        // 2. 中部：搜索框
                        SearchContentView()
                            .frame(height: 60)
                            .padding(.vertical, 10)

                        Divider()

                        // 3. 下部：自定义标签栏
                        TopContentView()
                            .frame(height: 60)
                            .background(Color(.systemBackground))
                    } else {
                        // 在数据加载完成前显示一个加载指示器
                        VStack {
                            Spacer()
                            ProgressView("正在准备数据...")
                            Spacer()
                        }
                    }
                }
                .navigationBarTitle("经济数据与搜索", displayMode: .inline)
            }
            .environmentObject(dataService)
            .onAppear {
                // 仅在首次出现时执行更新和加载
                if !isDataReady {
                    Task {
                        // 1. 检查并执行更新
                        _ = await updateManager.checkForUpdates()

                        // 2. 更新完成后，加载所有数据到内存
                        dataService.loadData()

                        // 3. 更新UI，显示主内容
                        withAnimation {
                            isDataReady = true
                        }
                    }
                }
            }

            // 更新状态的浮层
            UpdateOverlayView(updateManager: updateManager)
        }
    }
}

import Foundation
import SQLite3

class DatabaseManager {
    static let shared = DatabaseManager()
    private var db: OpaquePointer?

    struct MarketCapInfo {
        let symbol: String
        let marketCap: Double
        let peRatio: Double?
        let pb: Double?
    }

    private init() {
        print("=== DatabaseManager Initializing ===")
        // 初始化时，执行一次数据库打开操作
        openLatestDatabase()
    }

    // MARK: - 新增：重新连接到最新的数据库
    /// 当数据库文件更新后，调用此方法来关闭旧连接并打开新连接。
    func reconnectToLatestDatabase() {
        print("=== DatabaseManager Reconnecting ===")
        // 1. 先关闭现有的数据库连接（如果存在）
        if db != nil {
            sqlite3_close(db)
            db = nil // 将指针设为 nil
            print("已关闭旧的数据库连接。")
        }

        // 2. 重新执行打开最新数据库的逻辑
        openLatestDatabase()
    }

    // MARK: - 新增：将打开数据库的逻辑提取到私有方法
    /// 查找最新的数据库文件并打开连接。
    private func openLatestDatabase() {
        guard let dbUrl = FileManagerHelper.getLatestFileUrl(for: "Finance") else {
            print("错误：在 Documents 目录中未找到任何 Finance 数据库文件。")
            // 确保 db 为 nil
            self.db = nil
            return
        }

        // 尝试打开新的数据库文件
        if sqlite3_open(dbUrl.path, &db) == SQLITE_OK {
            print("成功从 Documents 目录打开数据库: \(dbUrl.lastPathComponent)")
        } else {
            let errorMessage = String(cString: sqlite3_errmsg(db))
            print("无法从 Documents 目录打开数据库: \(dbUrl.lastPathComponent)。错误: \(errorMessage)")
            // 确保打开失败时 db 为 nil
            self.db = nil
        }
    }

    deinit {
        if db != nil {
            sqlite3_close(db)
        }
    }

    struct PriceData: Identifiable {
        let id: Int
        let date: Date
        let price: Double
        let volume: Int64?
    }

    func fetchAllMarketCapData(from tableName: String) -> [MarketCapInfo] {
        guard db != nil else {
            print("数据库连接无效，无法执行 fetchAllMarketCapData。")
            return []
        }

        var results: [MarketCapInfo] = []
        let query = "SELECT symbol, marketcap, pe_ratio, pb FROM \"\(tableName)\""
        var statement: OpaquePointer?

        if sqlite3_prepare_v2(db, query, -1, &statement, nil) == SQLITE_OK {
            while sqlite3_step(statement) == SQLITE_ROW {
                let symbol = String(cString: sqlite3_column_text(statement, 0))
                let marketCap = sqlite3_column_double(statement, 1)

                let peRatio: Double? = sqlite3_column_type(statement, 2) != SQLITE_NULL ? sqlite3_column_double(statement, 2) : nil
                let pb: Double? = sqlite3_column_type(statement, 3) != SQLITE_NULL ? sqlite3_column_double(statement, 3) : nil

                results.append(MarketCapInfo(symbol: symbol, marketCap: marketCap, peRatio: peRatio, pb: pb))
            }
        } else {
            print("Failed to prepare statement for market cap data: \(String(cString: sqlite3_errmsg(db)))")
        }

        sqlite3_finalize(statement)
        return results
    }

    // ... 其他 fetch 方法保持不变 ...
    // fetchLatestVolume, fetchHistoricalData, fetchEarningData, checkIfTableHasVolume
    // 这些方法都不需要修改，因为它们依赖于 db 连接，只要 db 连接是正确的，它们就能正常工作。

    // 新增的方法：获取特定 ETF 的最新 volume
    func fetchLatestVolume(forSymbol symbol: String, tableName: String) -> Int64? {
        guard db != nil else { return nil }
        let query = "SELECT volume FROM \(tableName) WHERE name = ? ORDER BY date DESC LIMIT 1"
        var statement: OpaquePointer?
        var latestVolume: Int64? = nil

        if sqlite3_prepare_v2(db, query, -1, &statement, nil) == SQLITE_OK {
            sqlite3_bind_text(statement, 1, (symbol as NSString).utf8String, -1, nil)
            if sqlite3_step(statement) == SQLITE_ROW {
                latestVolume = sqlite3_column_int64(statement, 0)
            }
        } else {
            print("Failed to prepare statement: \(String(cString: sqlite3_errmsg(db)))")
        }
        sqlite3_finalize(statement)
        return latestVolume
    }

    enum DateRangeInput {
        case timeRange(TimeRange)
        case customRange(start: Date, end: Date)
    }

    func fetchHistoricalData(
        symbol: String,
        tableName: String,
        dateRange: DateRangeInput
    ) -> [PriceData] {
        guard db != nil else { return [] }
        var result: [PriceData] = []
        let dateFormat = "yyyy-MM-dd"

