    private func loadSectorsPanel() {
        // MARK: - 修改
        guard let url = FileManagerHelper.getLatestFileUrl(for: "Sectors_panel") else {
            DispatchQueue.main.async { self.errorMessage = "Sectors_panel 文件未在 Documents 中找到" }
