                        // MARK: - 最后渲染底部特定行 (Qualified_Symbol, Earning_Filter)
                        if !bottomSectors.isEmpty {
                            HStack(spacing: 12) {
                                ForEach(bottomSectors) { sector in
                                    NavigationLink {
