    @State private var isDataReady = false

    // MARK: - 此处为核心修改
    private var isUpdateInProgress: Bool {
        // 只要更新管理器的状态不是“空闲”，就认为更新流程正在进行中。
        // 这会确保按钮在检查、下载、显示结果（成功/失败）的整个过程中都保持禁用，
        // 直到状态被重置回 .idle 为止。
        return updateManager.updateState != .idle
    }

    var body: some View {
        ZStack {
            NavigationStack {
                VStack(spacing: 0) {
                    if isDataReady {
                        IndicesContentView()
                            .frame(maxHeight: .infinity, alignment: .top)

                        Divider()

                        SearchContentView()
                            .frame(height: 60)
                            .padding(.vertical, 10)

                        Divider()

                        TopContentView()
                            .frame(height: 60)
