            ?? fallbackGroupName
    }

    var body: some View {
        NavigationLink(destination: ChartView(symbol: symbol.symbol, groupName: groupName)) {
            VStack(alignment: .leading, spacing: 8) {
                // 只显示 symbol
                HStack {
                    Text(symbol.symbol)
                        .font(.headline)
                        .foregroundColor(.primary)

                    Spacer()

                    Text(symbol.value)
                        .foregroundColor(getValueColor(value: symbol.value))
                        .fontWeight(.semibold)
                }

                // 保持 tags 显示
                if let tags = symbol.tags, !tags.isEmpty {
                    Text(tags.joined(separator: ", "))
                        .font(.footnote)
                        .foregroundColor(.secondary)
                        .lineLimit(2)
                        .multilineTextAlignment(.leading)
                        .fixedSize(horizontal: false, vertical: true)
                }
            }
            .padding()
            .background(
                RoundedRectangle(cornerRadius: 12)
                    .fill(Color(.systemGray6))
                    .shadow(color: Color.black.opacity(0.05), radius: 2, x: 2, y: 2)
            )
            .padding(.vertical, 4)
        }
    }

    private func getValueColor(value: String) -> Color {
        if value.contains("+") {
            return .green
        } else if value.contains("-") {
            return .red
        } else if value == "N/A" {
            return .gray
        } else {
            return .blue
        }
    }
}

