struct MainContentView: View {
    @StateObject private var dataService = DataService.shared
    @StateObject private var updateManager = UpdateManager.shared
    @State private var isDataReady = false

    // 判断更新流程是否在进行中，用来 disable 刷新按钮
    private var isUpdateInProgress: Bool {
        updateManager.updateState != .idle
    }

    var body: some View {
        ZStack {
            NavigationStack {
                VStack(spacing: 0) {
                    if isDataReady {
                        IndicesContentView()
                            .frame(maxHeight: .infinity, alignment: .top)
                        Divider()
                        SearchContentView()
                            .frame(height: 60)
                            .padding(.vertical, 10)
                        Divider()
                        TopContentView()
                            .frame(height: 60)
                            .background(Color(.systemBackground))
                    } else {
                        VStack {
                            Spacer()
                            ProgressView("正在准备数据…")
                            Spacer()
                        }
                    }
                }
                .navigationBarTitle("经济数据与搜索", displayMode: .inline)
                .toolbar {
                    ToolbarItem(placement: .navigationBarTrailing) {
                        Button {
                            Task {
                                // 手动检查更新时，要等整个流程完成才重新 loadData
                                if await updateManager.checkForUpdates(isManual: true) {
                                    DatabaseManager.shared.reconnectToLatestDatabase()
                                    // MARK: - 修改：调用新的强制刷新方法
                                    dataService.forceReloadData()
                                }
                            }
                        } label: {
                            Image(systemName: "arrow.clockwise")
                        }
                        .disabled(isUpdateInProgress)
                    }
                }
            }
            .environmentObject(dataService)
            .onAppear {
                // 先检查本地是否已有 description.json
                let hasLocalDescription = FileManagerHelper.getLatestFileUrl(for: "description") != nil

                if !hasLocalDescription {
                    // 首次启动，Documents 里没有任何数据文件
                    // 先执行一次「同步」更新
                    Task {
                        let updated = await updateManager.checkForUpdates(isManual: false)
                        if updated {
                            DatabaseManager.shared.reconnectToLatestDatabase()
                            // MARK: - 修改：首次启动后也调用强制刷新
                            dataService.forceReloadData()
                        }
                        // 不管更新是否成功，都尝试加载（如果更新失败，则可能依然无本地数据，界面会报错）
                        dataService.loadData()
                        isDataReady = true
                    }
                } else {
                    // 已经有本地数据，立即加载并展示
                    dataService.loadData()
                    isDataReady = true

                    // 后台异步发起一次更新
                    Task {
                        if await updateManager.checkForUpdates(isManual: false) {
                            // 如果更新成功，重新打开 DB，reload 本地数据
                            DatabaseManager.shared.reconnectToLatestDatabase()
                            // MARK: - 修改：后台更新成功后，调用强制刷新
                            dataService.forceReloadData()
                        }
                    }
                }
            }

            // 更新状态浮层
            UpdateOverlayView(updateManager: updateManager)
        }
    }
}

import Foundation
import SQLite3

class DatabaseManager {
    static let shared = DatabaseManager()
    private var db: OpaquePointer?

    struct MarketCapInfo {
        let symbol: String
        let marketCap: Double
        let peRatio: Double?
        let pb: Double?
    }

    private init() {
        print("=== DatabaseManager Initializing ===")
        // 初始化时，执行一次数据库打开操作
        openDatabase()
    }

    deinit {
        if db != nil {
            sqlite3_close(db)
        }
    }

    // MARK: - 修改：重命名并简化打开逻辑
    /// 当数据库文件更新后，调用此方法来关闭旧连接并打开新连接。
    func reconnectToLatestDatabase() {
        print("=== DatabaseManager Reconnecting ===")
        // 1. 先关闭现有的数据库连接（如果存在）
        if db != nil {
            sqlite3_close(db)
            db = nil // 将指针设为 nil
            print("已关闭旧的数据库连接。")
        }
        openDatabase()
    }

    // MARK: - 修改：直接打开固定名称的数据库
    /// 查找名为 "Finance.db" 的数据库文件并打开连接。
    private func openDatabase() {
        let dbName = "Finance.db"
        let dbUrl = FileManagerHelper.documentsDirectory.appendingPathComponent(dbName)

        // 先检查文件是否存在
        guard FileManager.default.fileExists(atPath: dbUrl.path) else {
            print("错误：数据库文件 \(dbName) 在 Documents 目录中未找到。")
            self.db = nil
            return
        }

        // 尝试打开新的数据库文件
        if sqlite3_open(dbUrl.path, &db) == SQLITE_OK {
            print("成功从 Documents 目录打开数据库: \(dbName)")
        } else {
            let errorMessage = String(cString: sqlite3_errmsg(db))
            print("无法从 Documents 目录打开数据库: \(dbName)。错误: \(errorMessage)")
            self.db = nil
        }
    }

    // MARK: - 新增：应用从服务器同步的变更
    func applySyncChanges(_ changes: [Change]) async -> Bool {
        guard db != nil else {
            print("数据库连接无效，无法应用变更。")
            return false
        }

        // 在后台线程执行数据库操作
        return await Task.detached {
            // 1. 开始事务
            guard sqlite3_exec(self.db, "BEGIN TRANSACTION", nil, nil, nil) == SQLITE_OK else {
                print("开启事务失败: \(String(cString: sqlite3_errmsg(self.db)))")
                return false
            }

            for change in changes {
                var success = false
                switch change.op {
                case "I", "U":
                    success = self.applyReplace(for: change)
                case "D":
                    success = self.applyDelete(for: change)
                default:
                    print("未知的操作类型: \(change.op)")
                    success = true // 或者 false，取决于严格程度
                }

                // 如果任何一步失败，则回滚并退出
                if !success {
                    print("应用变更失败，正在回滚...")
                    sqlite3_exec(self.db, "ROLLBACK TRANSACTION", nil, nil, nil)
                    return false
                }
            }

            // 3. 提交事务
            guard sqlite3_exec(self.db, "COMMIT TRANSACTION", nil, nil, nil) == SQLITE_OK else {
                print("提交事务失败: \(String(cString: sqlite3_errmsg(self.db)))")
                // 尝试回滚
                sqlite3_exec(self.db, "ROLLBACK TRANSACTION", nil, nil, nil)
                return false
            }

            print("成功应用 \(changes.count) 条变更。")
            return true
        }.value
    }

    private func applyDelete(for change: Change) -> Bool {
        var sql: String
        var statement: OpaquePointer?

        // --- 核心修改：使用 switch 来处理不同表的删除逻辑 ---
        switch change.table {
        case "Earning":
            guard case let .string(name) = change.key["name"],
                  case let .string(date) = change.key["date"] else {
                print("Earning 删除失败：无法从 key 解析 name 和 date。Key: \(change.key)")
                return false
            }
            sql = "DELETE FROM \"Earning\" WHERE name = ? AND date = ?;"

            guard sqlite3_prepare_v2(db, sql, -1, &statement, nil) == SQLITE_OK else {
                print("为 Earning DELETE 准备语句失败: \(String(cString: sqlite3_errmsg(db)))")
                return false
            }
            sqlite3_bind_text(statement, 1, (name as NSString).utf8String, -1, nil)
            sqlite3_bind_text(statement, 2, (date as NSString).utf8String, -1, nil)

        case "MNSPP":
            guard case let .string(symbol) = change.key["symbol"] else {
                print("MNSPP 删除失败：无法从 key 解析 symbol。Key: \(change.key)")
                return false
            }
            sql = "DELETE FROM \"MNSPP\" WHERE symbol = ?;"

            guard sqlite3_prepare_v2(db, sql, -1, &statement, nil) == SQLITE_OK else {
                print("为 MNSPP DELETE 准备语句失败: \(String(cString: sqlite3_errmsg(db)))")
                return false
            }
            sqlite3_bind_text(statement, 1, (symbol as NSString).utf8String, -1, nil)

        default:
            print("未知的表类型 \(change.table)，无法执行删除。")
            return false // 或者 true，取决于您想不想让未知表中断整个同步
        }

        let result = sqlite3_step(statement)
        sqlite3_finalize(statement)

        guard result == SQLITE_DONE else {
            print("执行 DELETE 失败 (table: \(change.table), key: \(change.key)): \(String(cString: sqlite3_errmsg(db)))")
            return false
        }

        return true
    }

    private func applyReplace(for change: Change) -> Bool {
                guard let data = change.data, !data.isEmpty else { return false }

                // 1. 关键修复：先对键进行字母排序，得到一个唯一的、固定的顺序
                let sortedKeys = data.keys.sorted()

                // 2. 使用这个固定的顺序来构建列名部分
                let columns = sortedKeys.map { "\"\($0)\"" }.joined(separator: ", ")
                let placeholders = Array(repeating: "?", count: data.count).joined(separator: ", ")
                let sql = "REPLACE INTO \"\(change.table)\" (\(columns)) VALUES (\(placeholders));"

                var statement: OpaquePointer?

                guard sqlite3_prepare_v2(db, sql, -1, &statement, nil) == SQLITE_OK else {
                    print("为 REPLACE 操作准备语句失败: \(String(cString: sqlite3_errmsg(db)))")
                    // 如果准备失败，也打印出 change 方便调试
                    print("导致准备失败的变更是: \(change)")
                    return false
                }

                // 3. 使用完全相同的 sortedKeys 顺序来绑定值
                var index: Int32 = 1
                for key in sortedKeys {
                    let value = data[key]!

                    switch value {
                    case .int(let intValue):
                        sqlite3_bind_int64(statement, index, Int64(intValue))

                    case .double(let doubleValue):
                        if doubleValue.truncatingRemainder(dividingBy: 1) == 0 {
                            sqlite3_bind_int64(statement, index, Int64(doubleValue))
                        } else {
                            sqlite3_bind_double(statement, index, doubleValue)
                        }

                    case .string(let stringValue):
                        sqlite3_bind_text(statement, index, (stringValue as NSString).utf8String, -1, nil)

                    case .null:
                        sqlite3_bind_null(statement, index)
                    }

                    index += 1
                }

                let result = sqlite3_step(statement)
                sqlite3_finalize(statement)

                guard result == SQLITE_DONE else {
            // --- 优化日志 ---
            print("执行 REPLACE 失败 (table: \(change.table), key: \(change.key)): \(String(cString: sqlite3_errmsg(db)))")
                    return false
                }

                return true
            }

    struct PriceData: Identifiable {
        let id: Int
        let date: Date
        let price: Double
        let volume: Int64?
    }

    func fetchAllMarketCapData(from tableName: String) -> [MarketCapInfo] {
        guard db != nil else {
            print("数据库连接无效，无法执行 fetchAllMarketCapData。")
            return []
        }

        var results: [MarketCapInfo] = []
        let query = "SELECT symbol, marketcap, pe_ratio, pb FROM \"\(tableName)\""
        var statement: OpaquePointer?

        if sqlite3_prepare_v2(db, query, -1, &statement, nil) == SQLITE_OK {
            while sqlite3_step(statement) == SQLITE_ROW {
                let symbol = String(cString: sqlite3_column_text(statement, 0))
                let marketCap = sqlite3_column_double(statement, 1)

                let peRatio: Double? = sqlite3_column_type(statement, 2) != SQLITE_NULL ? sqlite3_column_double(statement, 2) : nil
                let pb: Double? = sqlite3_column_type(statement, 3) != SQLITE_NULL ? sqlite3_column_double(statement, 3) : nil

                results.append(MarketCapInfo(symbol: symbol, marketCap: marketCap, peRatio: peRatio, pb: pb))
            }
        } else {
            print("Failed to prepare statement for market cap data: \(String(cString: sqlite3_errmsg(db)))")
        }

        sqlite3_finalize(statement)
        return results
    }

    // ... 其他 fetch 方法保持不变 ...
    // fetchLatestVolume, fetchHistoricalData, fetchEarningData, checkIfTableHasVolume
    // 这些方法都不需要修改，因为它们依赖于 db 连接，只要 db 连接是正确的，它们就能正常工作。

    // 新增的方法：获取特定 ETF 的最新 volume
    func fetchLatestVolume(forSymbol symbol: String, tableName: String) -> Int64? {
        guard db != nil else { return nil }
        let query = "SELECT volume FROM \(tableName) WHERE name = ? ORDER BY date DESC LIMIT 1"
        var statement: OpaquePointer?
        var latestVolume: Int64? = nil

        if sqlite3_prepare_v2(db, query, -1, &statement, nil) == SQLITE_OK {
            sqlite3_bind_text(statement, 1, (symbol as NSString).utf8String, -1, nil)
            if sqlite3_step(statement) == SQLITE_ROW {
                latestVolume = sqlite3_column_int64(statement, 0)
            }
        } else {
            print("Failed to prepare statement: \(String(cString: sqlite3_errmsg(db)))")
        }
        sqlite3_finalize(statement)
        return latestVolume
    }

    enum DateRangeInput {
        case timeRange(TimeRange)
        case customRange(start: Date, end: Date)
    }

    func fetchHistoricalData(
        symbol: String,
        tableName: String,
        dateRange: DateRangeInput
    ) -> [PriceData] {
        guard db != nil else { return [] }
        var result: [PriceData] = []
        let dateFormat = "yyyy-MM-dd"

        // 确定日期范围
        let (startDate, endDate): (Date, Date) = {
            switch dateRange {
            case .timeRange(let timeRange):
                return (timeRange.startDate, Date())
            case .customRange(let start, let end):
                return (start, end)
            }
        }()

        // 检查表结构
        let hasVolumeColumn = checkIfTableHasVolume(tableName: tableName)

        // 构建查询语句
        let query = """
            SELECT id, date, price\(hasVolumeColumn ? ", volume" : "")
            FROM \(tableName)
            WHERE name = ? AND date BETWEEN ? AND ?
            ORDER BY date ASC
        """

        var statement: OpaquePointer?

        if sqlite3_prepare_v2(db, query, -1, &statement, nil) == SQLITE_OK {
            let formatter = DateFormatter()
            formatter.dateFormat = dateFormat

            // 绑定参数
            sqlite3_bind_text(statement, 1, (symbol as NSString).utf8String, -1, nil)
            sqlite3_bind_text(statement, 2, (formatter.string(from: startDate) as NSString).utf8String, -1, nil)
            sqlite3_bind_text(statement, 3, (formatter.string(from: endDate) as NSString).utf8String, -1, nil)

            // 处理结果
            while sqlite3_step(statement) == SQLITE_ROW {
                let id = Int(sqlite3_column_int(statement, 0))
                let dateString = String(cString: sqlite3_column_text(statement, 1))
                let price = sqlite3_column_double(statement, 2)

                if let date = formatter.date(from: dateString) {
                    let volume = hasVolumeColumn ? sqlite3_column_int64(statement, 3) : nil
                    result.append(PriceData(id: id, date: date, price: price, volume: volume))
                }
            }
        }

        sqlite3_finalize(statement)
        return result
    }

    struct EarningData {
        let date: Date
        let price: Double
    }

    func fetchEarningData(forSymbol symbol: String) -> [EarningData] {
        guard db != nil else { return [] }
        var result: [EarningData] = []
        let dateFormat = "yyyy-MM-dd"
        let formatter = DateFormatter()
        formatter.dateFormat = dateFormat

        let query = "SELECT date, price FROM Earning WHERE name = ?"
        var statement: OpaquePointer?

        if sqlite3_prepare_v2(db, query, -1, &statement, nil) == SQLITE_OK {
            sqlite3_bind_text(statement, 1, (symbol as NSString).utf8String, -1, nil)

            while sqlite3_step(statement) == SQLITE_ROW {
                if let dateString = sqlite3_column_text(statement, 0) {
                    let dateStr = String(cString: dateString)
                    let price = sqlite3_column_double(statement, 1)

                    if let date = formatter.date(from: dateStr) {
                        result.append(EarningData(date: date, price: price))
                    }
                }
            }
        } else {
            print("Failed to prepare statement: \(String(cString: sqlite3_errmsg(db)))")
        }

        sqlite3_finalize(statement)
        return result
    }

    // 添加辅助方法来检查表是否包含 volume 列
    private func checkIfTableHasVolume(tableName: String) -> Bool {
        guard db != nil else { return false }
        var hasVolume = false
        var statement: OpaquePointer?

        // 查询表结构
        let query = "PRAGMA table_info(\(tableName))"

        if sqlite3_prepare_v2(db, query, -1, &statement, nil) == SQLITE_OK {
            while sqlite3_step(statement) == SQLITE_ROW {
                if let name = sqlite3_column_text(statement, 1) {
                    let columnName = String(cString: name)
                    if columnName.lowercased() == "volume" {
                        hasVolume = true
                        break
                    }
                }
            }
        }

        sqlite3_finalize(statement)
        return hasVolume
    }
}

import SwiftUI
import Foundation

// MARK: - Models

struct IndicesSector: Identifiable, Codable {
    var id: String { name }
    let name: String
    let symbols: [IndicesSymbol]
    var subSectors: [IndicesSector]? // 添加子分组

    private enum CodingKeys: String, CodingKey {
        case name, symbols
    }

    init(name: String, symbols: [IndicesSymbol], subSectors: [IndicesSector]? = nil) {
        self.name = name
        self.symbols = symbols
        self.subSectors = subSectors
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.name = try container.decode(String.self, forKey: .name)
        self.symbols = try container.decode([IndicesSymbol].self, forKey: .symbols)
        self.subSectors = nil
    }
}


struct IndicesSymbol: Identifiable, Codable {
    var id: String { symbol }  // 使用symbol作为唯一标识符
    let symbol: String
    let name: String
    var value: String
    var tags: [String]?

    private enum CodingKeys: String, CodingKey {
        case symbol, name, value, tags
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.symbol = try container.decode(String.self, forKey: .symbol)
        self.name = try container.decode(String.self, forKey: .name)
        self.value = try container.decode(String.self, forKey: .value)
        self.tags = try container.decodeIfPresent([String].self, forKey: .tags)
    }

    init(symbol: String, name: String, value: String, tags: [String]?) {
        self.symbol = symbol
        self.name = name
        self.value = value
        self.tags = tags
    }
}

struct DynamicCodingKeys: CodingKey {
    var stringValue: String
    var intValue: Int? { return nil }

    init?(stringValue: String) { self.stringValue = stringValue }
    init?(intValue: Int) { return nil }
}

struct SectorsPanel: Decodable {
    let sectors: [IndicesSector]

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: DynamicCodingKeys.self)
        var sectors: [IndicesSector] = []

        let orderedKeys = container.allKeys
            .map { $0.stringValue }
            .sorted()

        for key in orderedKeys {
            let codingKey = DynamicCodingKeys(stringValue: key)!
            let symbolsContainer = try container.nestedContainer(keyedBy: DynamicCodingKeys.self, forKey: codingKey)
            let orderedSymbolKeys = symbolsContainer.allKeys
                .map { $0.stringValue }
                .sorted()

            if key == "Economics" {
                // 原 Economics 分组特殊处理
                var groupedSymbols: [String: [IndicesSymbol]] = [:]

                for symbolKey in orderedSymbolKeys {
                    let symbolCodingKey = DynamicCodingKeys(stringValue: symbolKey)!
                    let symbolValue = try symbolsContainer.decode(String.self, forKey: symbolCodingKey)

                    // 按前缀数字分组
                    if let prefixNumber = symbolValue.split(separator: " ").first,
                       let _ = Int(prefixNumber) {
                        let group = String(prefixNumber)
                        let symbolName = symbolValue.split(separator: " ")[1]
                        let symbol = IndicesSymbol(
                            symbol: symbolKey,
                            name: String(symbolName),
                            value: "",
                            tags: nil
                        )

                        if groupedSymbols[group] == nil {
                            groupedSymbols[group] = []
                        }
                        groupedSymbols[group]?.append(symbol)
                    }
                }

                let subSectors = groupedSymbols.sorted(by: { $0.key < $1.key }).map { group, groupSymbols in
                    IndicesSector(name: group, symbols: groupSymbols)
                }

                let economicsSector = IndicesSector(
                    name: key,
                    symbols: [],
                    subSectors: subSectors
                )
                sectors.append(economicsSector)
            } else if key == "Commodities" {
                // Commodities 分组特殊处理：添加“重要”子分组，把 CrudeOil 和 Huangjin 放到其中
                var importantSymbols: [IndicesSymbol] = []
                var normalSymbols: [IndicesSymbol] = []

                for symbolKey in orderedSymbolKeys {
                    let symbolCodingKey = DynamicCodingKeys(stringValue: symbolKey)!
                    let symbolName = try symbolsContainer.decode(String.self, forKey: symbolCodingKey)
                    let symbol = IndicesSymbol(symbol: symbolKey, name: symbolName, value: "", tags: nil)

                    if symbolKey == "CrudeOil" || symbolKey == "Huangjin" {
                        importantSymbols.append(symbol)
                    } else {
                        normalSymbols.append(symbol)
                    }
                }

                if !importantSymbols.isEmpty {
                    var subSectors: [IndicesSector] = []
                    // “重要”子分组
                    subSectors.append(IndicesSector(name: "重要", symbols: importantSymbols))
                    // 若还有其他 symbol，则增加“其他”子分组
                    if !normalSymbols.isEmpty {
                        subSectors.append(IndicesSector(name: "其他", symbols: normalSymbols))
                    }
                    let commoditiesSector = IndicesSector(name: key, symbols: [], subSectors: subSectors)
                    sectors.append(commoditiesSector)
                } else if !normalSymbols.isEmpty {
                    // 如果没有重要 symbol，则常规处理
                    let commoditiesSector = IndicesSector(name: key, symbols: normalSymbols)
                    sectors.append(commoditiesSector)
                }
            } else if key == "Currencies" {
                // Currencies 分组特殊处理：添加“重要”子分组，把 USDJPY 和 USDCNY 和 DXY 和 CNYI 放到其中
                var importantSymbols: [IndicesSymbol] = []
                var normalSymbols: [IndicesSymbol] = []

                for symbolKey in orderedSymbolKeys {
                    let symbolCodingKey = DynamicCodingKeys(stringValue: symbolKey)!
                    let symbolName = try symbolsContainer.decode(String.self, forKey: symbolCodingKey)
                    let symbol = IndicesSymbol(symbol: symbolKey, name: symbolName, value: "", tags: nil)

                    if symbolKey == "USDJPY" || symbolKey == "USDCNY" || symbolKey == "DXY" || symbolKey == "CNYI" || symbolKey == "JPYI" || symbolKey == "CHFI" || symbolKey == "EURI" || symbolKey == "CNYUSD" {
                        importantSymbols.append(symbol)
                    } else {
                        normalSymbols.append(symbol)
                    }
                }

                if !importantSymbols.isEmpty {
                    var subSectors: [IndicesSector] = []
                    // “重要”子分组
                    subSectors.append(IndicesSector(name: "重要", symbols: importantSymbols))
                    // 如果还有其他 symbol，则增加“其他”子分组
                    if !normalSymbols.isEmpty {
                        subSectors.append(IndicesSector(name: "其他", symbols: normalSymbols))
                    }
                    let currenciesSector = IndicesSector(name: key, symbols: [], subSectors: subSectors)
                    sectors.append(currenciesSector)
                } else if !normalSymbols.isEmpty {
                    // 如果没有特别的 symbol，则常规处理
                    let currenciesSector = IndicesSector(name: key, symbols: normalSymbols)
                    sectors.append(currenciesSector)
                }
            } else {
                // 其他分组常规处理
                var symbols: [IndicesSymbol] = []
                for symbolKey in orderedSymbolKeys {
                    let symbolCodingKey = DynamicCodingKeys(stringValue: symbolKey)!
                    let symbolName = try symbolsContainer.decode(String.self, forKey: symbolCodingKey)
                    symbols.append(IndicesSymbol(
                        symbol: symbolKey,
                        name: symbolName,
                        value: "",
                        tags: nil
                    ))
                }

                if !symbols.isEmpty {
                    let sector = IndicesSector(name: key, symbols: symbols)
                    sectors.append(sector)
                }
            }
        }

        self.sectors = sectors
    }
}

