import Foundation
import SQLite3

class DatabaseManager {
    static let shared = DatabaseManager()
    private var db: OpaquePointer?

    struct MarketCapInfo {
        let symbol: String
        let marketCap: Double
        let peRatio: Double?
        let pb: Double?
    }

    private init() {
        print("=== DatabaseManager Initializing ===")
        // 初始化时，执行一次数据库打开操作
        openDatabase()
    }

    deinit {
        if db != nil {
            sqlite3_close(db)
        }
    }

    // MARK: - 修改：重命名并简化打开逻辑
    /// 当数据库文件更新后，调用此方法来关闭旧连接并打开新连接。
    func reconnectToLatestDatabase() {
        print("=== DatabaseManager Reconnecting ===")
        // 1. 先关闭现有的数据库连接（如果存在）
        if db != nil {
            sqlite3_close(db)
            db = nil // 将指针设为 nil
            print("已关闭旧的数据库连接。")
        }
        openDatabase()
    }

    // MARK: - 修改：直接打开固定名称的数据库
    /// 查找名为 "Finance.db" 的数据库文件并打开连接。
    private func openDatabase() {
        let dbName = "Finance.db"
        let dbUrl = FileManagerHelper.documentsDirectory.appendingPathComponent(dbName)

        // 先检查文件是否存在
        guard FileManager.default.fileExists(atPath: dbUrl.path) else {
            print("错误：数据库文件 \(dbName) 在 Documents 目录中未找到。")
            self.db = nil
            return
        }

        // 尝试打开新的数据库文件
        if sqlite3_open(dbUrl.path, &db) == SQLITE_OK {
            print("成功从 Documents 目录打开数据库: \(dbName)")
        } else {
            let errorMessage = String(cString: sqlite3_errmsg(db))
            print("无法从 Documents 目录打开数据库: \(dbName)。错误: \(errorMessage)")
            self.db = nil
        }
    }

    // MARK: - 新增：应用从服务器同步的变更
    func applySyncChanges(_ changes: [Change]) async -> Bool {
        guard db != nil else {
            print("数据库连接无效，无法应用变更。")
            return false
        }

        // 在后台线程执行数据库操作
        return await Task.detached {
            // 1. 开始事务
            guard sqlite3_exec(self.db, "BEGIN TRANSACTION", nil, nil, nil) == SQLITE_OK else {
                print("开启事务失败: \(String(cString: sqlite3_errmsg(self.db)))")
                return false
            }

            for change in changes {
                var success = false
                switch change.op {
                case "I", "U":
                    success = self.applyReplace(for: change)
                case "D":
                    success = self.applyDelete(for: change)
                default:
                    print("未知的操作类型: \(change.op)")
                    success = true // 或者 false，取决于严格程度
                }

                // 如果任何一步失败，则回滚并退出
                if !success {
                    print("应用变更失败，正在回滚...")
                    sqlite3_exec(self.db, "ROLLBACK TRANSACTION", nil, nil, nil)
                    return false
                }
            }

            // 3. 提交事务
            guard sqlite3_exec(self.db, "COMMIT TRANSACTION", nil, nil, nil) == SQLITE_OK else {
                print("提交事务失败: \(String(cString: sqlite3_errmsg(self.db)))")
                // 尝试回滚
                sqlite3_exec(self.db, "ROLLBACK TRANSACTION", nil, nil, nil)
                return false
            }

            print("成功应用 \(changes.count) 条变更。")
            return true
        }.value
    }

    private func applyDelete(for change: Change) -> Bool {
        var sql: String
        var statement: OpaquePointer?

        // --- 核心修改：使用 switch 来处理不同表的删除逻辑 ---
        switch change.table {
        case "Earning":
            guard case let .string(name) = change.key["name"],
                  case let .string(date) = change.key["date"] else {
                print("Earning 删除失败：无法从 key 解析 name 和 date。Key: \(change.key)")
                return false
            }
            sql = "DELETE FROM \"Earning\" WHERE name = ? AND date = ?;"

            guard sqlite3_prepare_v2(db, sql, -1, &statement, nil) == SQLITE_OK else {
                print("为 Earning DELETE 准备语句失败: \(String(cString: sqlite3_errmsg(db)))")
                return false
            }
            sqlite3_bind_text(statement, 1, (name as NSString).utf8String, -1, nil)
            sqlite3_bind_text(statement, 2, (date as NSString).utf8String, -1, nil)

        case "MNSPP":
            guard case let .string(symbol) = change.key["symbol"] else {
                print("MNSPP 删除失败：无法从 key 解析 symbol。Key: \(change.key)")
                return false
            }
            sql = "DELETE FROM \"MNSPP\" WHERE symbol = ?;"

            guard sqlite3_prepare_v2(db, sql, -1, &statement, nil) == SQLITE_OK else {
                print("为 MNSPP DELETE 准备语句失败: \(String(cString: sqlite3_errmsg(db)))")
                return false
            }
            sqlite3_bind_text(statement, 1, (symbol as NSString).utf8String, -1, nil)

        default:
            print("未知的表类型 \(change.table)，无法执行删除。")
            return false // 或者 true，取决于您想不想让未知表中断整个同步
        }

        let result = sqlite3_step(statement)
        sqlite3_finalize(statement)

        guard result == SQLITE_DONE else {
            print("执行 DELETE 失败 (table: \(change.table), key: \(change.key)): \(String(cString: sqlite3_errmsg(db)))")
            return false
        }

        return true
    }

    private func applyReplace(for change: Change) -> Bool {
                guard let data = change.data, !data.isEmpty else { return false }

                // 1. 关键修复：先对键进行字母排序，得到一个唯一的、固定的顺序
                let sortedKeys = data.keys.sorted()

                // 2. 使用这个固定的顺序来构建列名部分
                let columns = sortedKeys.map { "\"\($0)\"" }.joined(separator: ", ")
                let placeholders = Array(repeating: "?", count: data.count).joined(separator: ", ")
                let sql = "REPLACE INTO \"\(change.table)\" (\(columns)) VALUES (\(placeholders));"

                var statement: OpaquePointer?

                guard sqlite3_prepare_v2(db, sql, -1, &statement, nil) == SQLITE_OK else {
                    print("为 REPLACE 操作准备语句失败: \(String(cString: sqlite3_errmsg(db)))")
                    // 如果准备失败，也打印出 change 方便调试
                    print("导致准备失败的变更是: \(change)")
                    return false
                }

                // 3. 使用完全相同的 sortedKeys 顺序来绑定值
                var index: Int32 = 1
                for key in sortedKeys {
                    let value = data[key]!

                    switch value {
                    case .int(let intValue):
                        sqlite3_bind_int64(statement, index, Int64(intValue))

                    case .double(let doubleValue):
                        if doubleValue.truncatingRemainder(dividingBy: 1) == 0 {
                            sqlite3_bind_int64(statement, index, Int64(doubleValue))
                        } else {
                            sqlite3_bind_double(statement, index, doubleValue)
                        }

                    case .string(let stringValue):
                        sqlite3_bind_text(statement, index, (stringValue as NSString).utf8String, -1, nil)

                    case .null:
                        sqlite3_bind_null(statement, index)
                    }

                    index += 1
                }

                let result = sqlite3_step(statement)
                sqlite3_finalize(statement)

                guard result == SQLITE_DONE else {
            // --- 优化日志 ---
            print("执行 REPLACE 失败 (table: \(change.table), key: \(change.key)): \(String(cString: sqlite3_errmsg(db)))")
                    return false
                }

                return true
            }

    struct PriceData: Identifiable {
        let id: Int
        let date: Date
        let price: Double
        let volume: Int64?
    }

    func fetchAllMarketCapData(from tableName: String) -> [MarketCapInfo] {
        guard db != nil else {
            print("数据库连接无效，无法执行 fetchAllMarketCapData。")
            return []
        }

        var results: [MarketCapInfo] = []
        let query = "SELECT symbol, marketcap, pe_ratio, pb FROM \"\(tableName)\""
        var statement: OpaquePointer?

        if sqlite3_prepare_v2(db, query, -1, &statement, nil) == SQLITE_OK {
            while sqlite3_step(statement) == SQLITE_ROW {
                let symbol = String(cString: sqlite3_column_text(statement, 0))
                let marketCap = sqlite3_column_double(statement, 1)

                let peRatio: Double? = sqlite3_column_type(statement, 2) != SQLITE_NULL ? sqlite3_column_double(statement, 2) : nil
                let pb: Double? = sqlite3_column_type(statement, 3) != SQLITE_NULL ? sqlite3_column_double(statement, 3) : nil

                results.append(MarketCapInfo(symbol: symbol, marketCap: marketCap, peRatio: peRatio, pb: pb))
            }
        } else {
            print("Failed to prepare statement for market cap data: \(String(cString: sqlite3_errmsg(db)))")
        }

        sqlite3_finalize(statement)
        return results
    }

    // ... 其他 fetch 方法保持不变 ...
    // fetchLatestVolume, fetchHistoricalData, fetchEarningData, checkIfTableHasVolume
    // 这些方法都不需要修改，因为它们依赖于 db 连接，只要 db 连接是正确的，它们就能正常工作。

    // 新增的方法：获取特定 ETF 的最新 volume
    func fetchLatestVolume(forSymbol symbol: String, tableName: String) -> Int64? {
        guard db != nil else { return nil }
        let query = "SELECT volume FROM \(tableName) WHERE name = ? ORDER BY date DESC LIMIT 1"
        var statement: OpaquePointer?
        var latestVolume: Int64? = nil

        if sqlite3_prepare_v2(db, query, -1, &statement, nil) == SQLITE_OK {
            sqlite3_bind_text(statement, 1, (symbol as NSString).utf8String, -1, nil)
            if sqlite3_step(statement) == SQLITE_ROW {
                latestVolume = sqlite3_column_int64(statement, 0)
            }
        } else {
            print("Failed to prepare statement: \(String(cString: sqlite3_errmsg(db)))")
        }
        sqlite3_finalize(statement)
        return latestVolume
    }

    enum DateRangeInput {
        case timeRange(TimeRange)
        case customRange(start: Date, end: Date)
    }

    func fetchHistoricalData(
        symbol: String,
        tableName: String,
        dateRange: DateRangeInput
    ) -> [PriceData] {
        guard db != nil else { return [] }
        var result: [PriceData] = []
        let dateFormat = "yyyy-MM-dd"

        // 确定日期范围
        let (startDate, endDate): (Date, Date) = {
            switch dateRange {
            case .timeRange(let timeRange):
                return (timeRange.startDate, Date())
            case .customRange(let start, let end):
                return (start, end)
            }
        }()

        // 检查表结构
        let hasVolumeColumn = checkIfTableHasVolume(tableName: tableName)

        // 构建查询语句
        let query = """
            SELECT id, date, price\(hasVolumeColumn ? ", volume" : "")
            FROM \(tableName)
            WHERE name = ? AND date BETWEEN ? AND ?
            ORDER BY date ASC
        """

        var statement: OpaquePointer?

        if sqlite3_prepare_v2(db, query, -1, &statement, nil) == SQLITE_OK {
            let formatter = DateFormatter()
            formatter.dateFormat = dateFormat

            // 绑定参数
            sqlite3_bind_text(statement, 1, (symbol as NSString).utf8String, -1, nil)
            sqlite3_bind_text(statement, 2, (formatter.string(from: startDate) as NSString).utf8String, -1, nil)
            sqlite3_bind_text(statement, 3, (formatter.string(from: endDate) as NSString).utf8String, -1, nil)

            // 处理结果
            while sqlite3_step(statement) == SQLITE_ROW {
                let id = Int(sqlite3_column_int(statement, 0))
                let dateString = String(cString: sqlite3_column_text(statement, 1))
                let price = sqlite3_column_double(statement, 2)

                if let date = formatter.date(from: dateString) {
                    let volume = hasVolumeColumn ? sqlite3_column_int64(statement, 3) : nil
                    result.append(PriceData(id: id, date: date, price: price, volume: volume))
                }
            }
        }

        sqlite3_finalize(statement)
        return result
    }

    struct EarningData {
        let date: Date
        let price: Double
    }

    func fetchEarningData(forSymbol symbol: String) -> [EarningData] {
        guard db != nil else { return [] }
        var result: [EarningData] = []
        let dateFormat = "yyyy-MM-dd"
        let formatter = DateFormatter()
        formatter.dateFormat = dateFormat

        let query = "SELECT date, price FROM Earning WHERE name = ?"
        var statement: OpaquePointer?

        if sqlite3_prepare_v2(db, query, -1, &statement, nil) == SQLITE_OK {
            sqlite3_bind_text(statement, 1, (symbol as NSString).utf8String, -1, nil)

            while sqlite3_step(statement) == SQLITE_ROW {
                if let dateString = sqlite3_column_text(statement, 0) {
                    let dateStr = String(cString: dateString)
                    let price = sqlite3_column_double(statement, 1)

                    if let date = formatter.date(from: dateStr) {
                        result.append(EarningData(date: date, price: price))
                    }
                }
            }
        } else {
            print("Failed to prepare statement: \(String(cString: sqlite3_errmsg(db)))")
        }

        sqlite3_finalize(statement)
        return result
    }

    // 添加辅助方法来检查表是否包含 volume 列
    private func checkIfTableHasVolume(tableName: String) -> Bool {
        guard db != nil else { return false }
        var hasVolume = false
        var statement: OpaquePointer?

        // 查询表结构
        let query = "PRAGMA table_info(\(tableName))"

        if sqlite3_prepare_v2(db, query, -1, &statement, nil) == SQLITE_OK {
            while sqlite3_step(statement) == SQLITE_ROW {
                if let name = sqlite3_column_text(statement, 1) {
                    let columnName = String(cString: name)
                    if columnName.lowercased() == "volume" {
                        hasVolume = true
                        break
                    }
                }
            }
        }

        sqlite3_finalize(statement)
        return hasVolume
    }
}

import Foundation
import SwiftUI

// MARK: - 数据模型 (无修改)
struct VersionResponse: Codable {
    let version: String
    let files: [FileInfo]
}

struct FileInfo: Codable, Hashable {
    let name: String
    let type: String
    let updateType: String?

    // --- 新增此部分 ---
    enum CodingKeys: String, CodingKey {
        case name
        case type
        case updateType = "update_type" // 将 JSON 中的 "update_type" 映射到 Swift 的 updateType 属性
    }
    // --------------------
}

// MARK: - 新增：同步响应模型
struct SyncResponse: Codable {
    let lastId: Int
    let changes: [Change]

    enum CodingKeys: String, CodingKey {
        case lastId = "last_id"
        case changes
    }
}

struct Change: Codable {
    let logId: Int
    let table: String
    let op: String // "I", "U", "D"

    // 新增：用于定位记录的键，例如 ["name": "AAPL", "date": "2025-01-01"]
    let key: [String: JSONValue]

    // data 字段保持不变，用于 I 和 U 操作
    let data: [String: JSONValue]?

    enum CodingKeys: String, CodingKey {
        case logId = "log_id"
        case table, op, key, data
    }
}
// 用于解码 [String: Any] 的辅助类型
enum JSONValue: Codable {
    case int(Int)
    case double(Double)
    case string(String)
    case null

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let intValue = try? container.decode(Int.self) {
            self = .int(intValue)
        } else if let doubleValue = try? container.decode(Double.self) {
            self = .double(doubleValue)
        } else if let stringValue = try? container.decode(String.self) {
            self = .string(stringValue)
        } else if container.decodeNil() {
            self = .null
        } else {
            throw DecodingError.typeMismatch(JSONValue.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Unsupported JSON value"))
        }
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .int(let value): try container.encode(value)
        case .double(let value): try container.encode(value)
        case .string(let value): try container.encode(value)
        case .null: try container.encodeNil()
        }
    }
}


// MARK: - 更新状态 (无修改)
enum UpdateState: Equatable {
    case idle
    case checking
    // --- 修改此行：移除了 speed 参数 ---
    case downloadingFile(name: String, progress: Double, downloadedBytes: Int64, totalBytes: Int64)
    case downloading(progress: Double, total: Int)
    case updateCompleted
    case alreadyUpToDate
    case error(message: String)

    // Equatable 的实现需要更新
    static func == (lhs: UpdateState, rhs: UpdateState) -> Bool {
        switch (lhs, rhs) {
        case (.idle, .idle): return true
        case (.checking, .checking): return true
        // --- 修改此行：匹配新的 case 定义 ---
        case (let .downloadingFile(n1, p1, db1, tb1), let .downloadingFile(n2, p2, db2, tb2)):
            return n1 == n2 && p1 == p2 && db1 == db2 && tb1 == tb2
        case (let .downloading(p1, t1), let .downloading(p2, t2)):
            return p1 == p2 && t1 == t2
        case (.updateCompleted, .updateCompleted): return true
        case (.alreadyUpToDate, .alreadyUpToDate): return true
        case (let .error(m1), let .error(m2)):
            return m1 == m2
        default:
            return false
        }
    }
}


// MARK: - 网络错误类型枚举 (无修改)
enum NetworkErrorType {
    /// 客户端网络问题 (例如，未连接到互联网)
    case clientOffline
    /// 服务器无法访问 (例如，IP错误、服务器关闭、超时)
    case serverUnreachable(String)
    /// 数据解析失败 (例如，服务器返回了无效的JSON)
    case decodingFailed(String)
}

// MARK: - fetchServerVersion 的返回结果枚举 (无修改)
enum ServerVersionResult {
    case success(VersionResponse)
    case failure(NetworkErrorType)
}


// MARK: - UpdateManager
@MainActor
class UpdateManager: ObservableObject {
    static let shared = UpdateManager()

    @Published var updateState: UpdateState = .idle

    private let serverBaseURL = "http://192.168.50.148:5000/api/Finance"
    private let localVersionKey = "FinanceAppLocalDataVersion"
    private let lastSyncIdKey = "FinanceLastSyncID" // 新增: 用于数据库同步

    private init() {}

    private var isInitialLoad: Bool {
        let localVersion = UserDefaults.standard.string(forKey: localVersionKey)
        return localVersion == nil || localVersion == "0.0"
    }

    func checkForUpdates(isManual: Bool = false) async -> Bool {
        if case .checking = updateState, !isManual { return false }
        if case .downloading = updateState, case .downloadingFile = updateState { return false }

        // 一开始就把状态置为 checking，无论手动还是自动
            await MainActor.run { self.updateState = .checking }

        if isManual { // 仅在手动检查时立即显示 "checking"
//            self.updateState = .checking
            try? await Task.sleep(for: .milliseconds(1))
        }

        print("开始检查更新... (手动触发: \(isManual))")

        let result = await fetchServerVersion()

        switch result {
        case .success(let serverVersionResponse):
            let localVersion = UserDefaults.standard.string(forKey: localVersionKey) ?? "0.0"
            print("服务器版本: \(serverVersionResponse.version), 本地版本: \(localVersion)")

            // 首次安装时，即使版本号相同，也需要下载/同步一次
            let isFirstTimeSetup = (UserDefaults.standard.string(forKey: localVersionKey) == nil)

            if isFirstTimeSetup || serverVersionResponse.version.compare(localVersion, options: .numeric) == .orderedDescending {
                print(isFirstTimeSetup ? "首次启动，开始同步所有资源..." : "发现新版本，开始下载/同步文件...")

                // MARK: - 核心修改点
                // 现在 downloadAndSyncFiles 会处理下载和同步两种情况
                let success = await downloadAndSyncFiles(from: serverVersionResponse)

                if success {
                    print("所有文件更新成功。")
                    // 清理时要传入所有新文件的信息
                    cleanupOldFiles(keeping: serverVersionResponse.files)
                    UserDefaults.standard.set(serverVersionResponse.version, forKey: localVersionKey)
                    print("本地版本已更新至: \(serverVersionResponse.version)")
                    self.updateState = .updateCompleted
                    resetStateAfterDelay()
                    return true
                } else {
                    self.updateState = .error(message: "文件更新失败。")
                    resetStateAfterDelay()
                    return false
                }
            } else {
                print("当前已是最新版本。")
                if isManual {
                    self.updateState = .alreadyUpToDate
                    resetStateAfterDelay()
                } else {
                    self.updateState = .idle
                }
                return false
            }

        // MARK: - 核心修改部分
        // 这里是实现您需求的关键
        case .failure(let errorType):
            // 只有在用户“手动”刷新时，才显示网络相关的错误提示
            if isManual {
                let errorMessage: String
                switch errorType {
                case .clientOffline:
                    errorMessage = "网络未连接，请检查设置。"
                case .serverUnreachable:
                    errorMessage = "无法连接到服务器。"
                case .decodingFailed:
                    errorMessage = "服务器响应异常，请稍后重试。"
                }
                print("手动检查更新失败: \(errorMessage)")
                self.updateState = .error(message: errorMessage)
                resetStateAfterDelay()
            } else {
                // 如果是应用启动时的“自动”检查，则静默失败，不打扰用户
                print("后台自动检查更新失败，已静默处理。错误: \(errorType)")
                self.updateState = .idle // 直接重置状态，UI上不会有任何提示
            }
            return false
        }
    }

    private func resetStateAfterDelay(seconds: TimeInterval = 2) {
        Task {
            try? await Task.sleep(for: .seconds(seconds))
            await MainActor.run {
                self.updateState = .idle
            }
        }
    }

    private func fetchServerVersion() async -> ServerVersionResult {
        guard let url = URL(string: "\(serverBaseURL)/check_version") else {
            return .failure(.decodingFailed("无效的URL"))
        }

        do {
            var request = URLRequest(url: url)
            request.timeoutInterval = 5

            let (data, response) = try await URLSession.shared.data(for: request)

            // --- 新增：检查 HTTP 状态码 ---
            guard let httpResponse = response as? HTTPURLResponse, httpResponse.statusCode == 200 else {
                let statusCode = (response as? HTTPURLResponse)?.statusCode ?? -1
                print("服务器返回了非预期的状态码: \(statusCode)")
                // 你可以认为这也是一种服务器无法访问的错误
                return .failure(.serverUnreachable("服务器返回状态码 \(statusCode)"))
            }
            // ---------------------------------

            // 只有在状态码是 200 的情况下，才尝试解码
            let decodedResponse = try JSONDecoder().decode(VersionResponse.self, from: data)
            return .success(decodedResponse)

        } catch {
            // ... catch 块的逻辑保持不变
            if let urlError = error as? URLError {
                switch urlError.code {
                case .notConnectedToInternet, .networkConnectionLost:
                    print("网络错误：设备未连接到互联网。")
                    return .failure(.clientOffline)
                case .cannotFindHost, .cannotConnectToHost, .timedOut:
                    print("网络错误：无法连接到主机或请求超时。 \(urlError.localizedDescription)")
                    return .failure(.serverUnreachable(urlError.localizedDescription))
                default:
                    print("未分类的URL错误: \(urlError.localizedDescription)")
                    return .failure(.serverUnreachable(urlError.localizedDescription))
                }
            } else if error is DecodingError {
                print("数据解析错误: \(error.localizedDescription)")
                // 加上这一句，可以帮助调试
                // if let responseString = String(data: data, encoding: .utf8) { print(responseString) }
                return .failure(.decodingFailed(error.localizedDescription))
            } else {
                print("未知网络错误: \(error.localizedDescription)")
                return .failure(.serverUnreachable(error.localizedDescription))
            }
        }
    }

    // MARK: - 重构的核心方法：downloadAndSyncFiles
    private func downloadAndSyncFiles(from versionResponse: VersionResponse) async -> Bool {
        let allFiles = versionResponse.files
        // ==================【请在这里加入调试代码】==================
            print("--- 开始调试 downloadAndSyncFiles ---")
            print("从 version.json 解析到的所有文件信息:")
            for file in allFiles {
                // 我们想知道 updateType 是否被正确解析
                print("- 文件名: \(file.name), 类型: \(file.type), 更新方式(updateType): \(file.updateType ?? "nil")")
            }
            print("-----------------------------------------")
            // ========================================================
        let totalTasks = allFiles.count
        var completedTasks = 0

        // 区分需要同步和需要下载的文件
        let syncableFiles = allFiles.filter { $0.updateType == "sync" }
        let downloadableFiles = allFiles.filter { $0.updateType != "sync" }

        // ==================【再在这里加入调试代码】==================
            print("--- 逻辑判断 ---")
            print("被识别为需要【同步】的文件数量: \(syncableFiles.count)")
            print("被识别为需要【下载】的文件数量: \(downloadableFiles.count)")

        if syncableFiles.first(where: { $0.name == "Finance.db" }) != nil {
                let dbExists = FileManagerHelper.fileExists(named: "Finance.db")
                print("Finance.db 被识别为同步文件。")
                print("检查本地文件是否存在 (fileExists): \(dbExists)")
                if !dbExists {
                    print("结论：本地数据库不存在，将执行全量下载。")
                } else {
                    print("结论：本地数据库已存在，将执行增量同步。")
                }
            } else {
                print("警告：Finance.db 未被识别为同步文件！")
            }
            print("------------------")
            // ========================================================

        self.updateState = .downloading(progress: 0, total: totalTasks)

        // 1. 先处理同步任务 (通常只有一个数据库文件)
        for fileInfo in syncableFiles {
            let success: Bool
            // 如果是首次安装，数据库文件不存在，需要全量下载一次
            if !FileManagerHelper.fileExists(named: "Finance.db") {
                print("本地数据库不存在，执行首次全量下载...")
                // --- 核心修改点：调用新的带进度的下载方法 ---
                success = await downloadFileWithProgress(named: fileInfo.name)

                if success {
                     await resetSyncIDToLatest()
                }
            } else {
                // 否则，执行增量同步
                print("执行数据库增量同步...")
                // 在开始同步前，设置一个状态，让用户知道正在处理
                self.updateState = .downloading(progress: 0, total: totalTasks)
                success = await syncDatabase()
            }

            if !success {
                print("数据库同步或下载失败: \(fileInfo.name)")
                return false // 一个失败则整个流程失败
            }

            completedTasks += 1
            let progress = Double(completedTasks) / Double(totalTasks)
            // 更新整体进度
            self.updateState = .downloading(progress: progress, total: totalTasks)
        }

        // 2. 并行处理所有下载任务
        if downloadableFiles.isEmpty {
             return true // 如果没有其他文件要下载，到此成功结束
        }

        return await withTaskGroup(of: Bool.self, body: { group in
            for fileInfo in downloadableFiles {
                group.addTask {
                    // 小文件继续使用旧的下载方法
                    return await self.downloadFile(named: fileInfo.name)
                }
            }

            var allSuccess = true
            for await success in group {
                if success {
                    completedTasks += 1
                    let progress = Double(completedTasks) / Double(totalTasks)
                    await MainActor.run {
                        self.updateState = .downloading(progress: progress, total: totalTasks)
                    }
                } else {
                    allSuccess = false
                }
            }
            return allSuccess
        })
    }

    // MARK: - 新增：数据库同步逻辑
    private func syncDatabase() async -> Bool {
        let lastID = UserDefaults.standard.integer(forKey: lastSyncIdKey)
        guard let url = URL(string: "\(serverBaseURL)/sync?last_id=\(lastID)") else {
            print("无效的同步URL")
            return false
        }

        do {
            print("正在从 last_id: \(lastID) 开始同步...")
            let (data, _) = try await URLSession.shared.data(from: url)

            let syncResponse = try JSONDecoder().decode(SyncResponse.self, from: data)

            if syncResponse.changes.isEmpty {
                print("没有需要同步的变更。")
                return true
            }

            print("获取到 \(syncResponse.changes.count) 条变更，准备应用...")

            // 调用 DBManager 应用变更
            let applySuccess = await DatabaseManager.shared.applySyncChanges(syncResponse.changes)

            if applySuccess {
                UserDefaults.standard.set(syncResponse.lastId, forKey: lastSyncIdKey)
                print("同步成功，新的 last_id 已更新为: \(syncResponse.lastId)")
                return true
            } else {
                print("应用数据库变更失败。")
                return false
            }

        } catch {
            print("同步失败: \(error.localizedDescription)")
            return false
        }
    }

    // 新增辅助函数：当首次下载DB后，获取服务器最新log_id
    private func resetSyncIDToLatest() async {
        // 调用 sync 接口，但 last_id 给一个超大值，这样服务器不会返回任何 changes，
        // 只会返回当前最新的 log_id
        let veryLargeLastID = 999999999
        guard let url = URL(string: "\(serverBaseURL)/sync?last_id=\(veryLargeLastID)") else { return }

        do {
            let (data, _) = try await URLSession.shared.data(from: url)
            let syncResponse = try JSONDecoder().decode(SyncResponse.self, from: data)
            UserDefaults.standard.set(syncResponse.lastId, forKey: lastSyncIdKey)
            print("已重置数据库同步点，最新 last_id 为: \(syncResponse.lastId)")
        } catch {
            print("获取最新 log_id 失败: \(error)")
            // 如果失败，下次同步会从 0 开始，可能会导致一些重复操作，但 REPLACE INTO 可以处理
            UserDefaults.standard.set(0, forKey: lastSyncIdKey)
        }
    }

    // --- 新增：带进度的文件下载方法 ---
    private func downloadFileWithProgress(named filename: String) async -> Bool {
        guard let url = URL(string: "\(serverBaseURL)/download?filename=\(filename)") else {
            print("无效的下载URL for \(filename)")
            return false
        }

        // --- 修改：初始状态不包含 speed ---
        await MainActor.run {
            self.updateState = .downloadingFile(name: filename, progress: 0, downloadedBytes: 0, totalBytes: 1)
        }

        do {
            // 使用 FileDownloader 执行下载
            let downloader = FileDownloader()
            // --- 修改：回调闭包不再接收 speed ---
            let fileData = try await downloader.download(from: url) { progress, downloaded, total in
                Task { @MainActor in
                    // --- 修改：设置状态时不再传递 speed ---
                    self.updateState = .downloadingFile(
                        name: filename,
                        progress: progress,
                        downloadedBytes: downloaded,
                        totalBytes: total
                    )
                }
            }

            // 下载成功后，保存文件
            let destinationURL = FileManagerHelper.documentsDirectory.appendingPathComponent(filename)
            try fileData.write(to: destinationURL)
            print("成功保存 (带进度): \(filename) 到 Documents")
            return true

        } catch {
            print("下载或保存文件 \(filename) 失败: \(error)")
            return false
        }
    }

    // 旧的下载方法保持不变，用于下载无需显示进度的小文件
    private func downloadFile(named filename: String) async -> Bool {
        guard let url = URL(string: "\(serverBaseURL)/download?filename=\(filename)") else {
            print("无效的下载URL for \(filename)")
            return false
        }

        do {
            print("正在下载最新数据: \(filename)")
            var request = URLRequest(url: url)
            request.timeoutInterval = 60

            let (data, _) = try await URLSession.shared.data(for: request)

            // 如果是目录类型，先创建目录
            if filename.hasSuffix("/") || filename.contains("/") {
                 let dirURL = FileManagerHelper.documentsDirectory.appendingPathComponent(filename).deletingLastPathComponent()
                 try FileManager.default.createDirectory(at: dirURL, withIntermediateDirectories: true, attributes: nil)
            }

            let destinationURL = FileManagerHelper.documentsDirectory.appendingPathComponent(filename)
            try data.write(to: destinationURL)
            print("成功保存: \(filename) 到 Documents")
            return true
        } catch {
            print("下载或保存文件 \(filename) 失败: \(error)")
            return false
        }
    }

    // MARK: - 修改后的清理逻辑
    private func cleanupOldFiles(keeping newFiles: [FileInfo]) {
        print("开始清理旧文件...")
        // 包含所有新版本文件的文件名集合，包括像 Finance.db 这样的固定名称文件
        let newFileNames = Set(newFiles.map { $0.name })
        let fileManager = FileManager.default
        let documentsURL = FileManagerHelper.documentsDirectory

        // 需要清理的文件的基本名称（不含时间戳的部分）
        // 我们只对那些文件名里包含时间戳模式的文件进行“按前缀清理”
        let baseFileNamesToClean = Set(newFiles.compactMap { fileInfo -> String? in
            // 如果文件是按时间戳管理的，才把它加入清理列表
            if fileInfo.name.range(of: "_\\d{6}\\.", options: .regularExpression) != nil {
                return String(fileInfo.name.split(separator: "_").first ?? "")
            }
            return nil
        })

        do {
            let fileURLs = try fileManager.contentsOfDirectory(at: documentsURL, includingPropertiesForKeys: nil)

            for url in fileURLs {
                let filename = url.lastPathComponent

                // 跳过不应该被自动清理的固定文件，比如 Finance.db
                if !baseFileNamesToClean.contains(where: { filename.hasPrefix($0) }) {
                    continue
                }

                // 如果一个带时间戳的文件，其完整文件名不在新版本文件列表中，则删除
                if !newFileNames.contains(filename) {
                    try fileManager.removeItem(at: url)
                    print("已删除旧文件: \(filename)")
                }
            }
        } catch {
            print("清理旧文件时出错: \(error)")
        }
    }
}

// MARK: - 新增：FileDownloader 辅助类
private class FileDownloader: NSObject {
    // --- 修改：ProgressHandler 的定义不再包含 speed ---
    typealias ProgressHandler = @MainActor (Double, Int64, Int64) -> Void

    private var progressHandler: ProgressHandler?
    private var continuation: CheckedContinuation<Data, Error>?

    private var receivedData = Data()
    private var expectedContentLength: Int64 = 0

    // --- 已移除：所有与速度计算相关的属性 ---

    func download(from url: URL, onProgress: @escaping ProgressHandler) async throws -> Data {
        return try await withCheckedThrowingContinuation { continuation in
            self.continuation = continuation
            self.progressHandler = onProgress

            let session = URLSession(configuration: .default, delegate: self, delegateQueue: nil)
            session.dataTask(with: url).resume()
        }
    }
}

extension FileDownloader: URLSessionDataDelegate {
    // 1. 收到服务器响应
    func urlSession(_ session: URLSession, dataTask: URLSessionDataTask, didReceive response: URLResponse, completionHandler: @escaping (URLSession.ResponseDisposition) -> Void) {
        guard let httpResponse = response as? HTTPURLResponse,
              (200...299).contains(httpResponse.statusCode),
              let contentLength = httpResponse.value(forHTTPHeaderField: "Content-Length"),
              let totalBytes = Int64(contentLength) else {
            continuation?.resume(throwing: URLError(.badServerResponse))
            completionHandler(.cancel)
            return
        }
        self.expectedContentLength = totalBytes
        completionHandler(.allow)
    }

    // 2. 收到数据块 (此方法会被多次调用)
    func urlSession(_ session: URLSession, dataTask: URLSessionDataTask, didReceive data: Data) {
        receivedData.append(data)
        let progress = Double(receivedData.count) / Double(expectedContentLength)

        // --- 已移除：速度计算的逻辑 ---

        // --- 修改：调用进度回调，不再传递 speed ---
        Task { @MainActor in
            self.progressHandler?(progress, Int64(receivedData.count), expectedContentLength)
        }
    }

    // 3. 任务完成
    func urlSession(_ session: URLSession, task: URLSessionTask, didCompleteWithError error: Error?) {
        if let error = error {
            continuation?.resume(throwing: error)
        } else {
            // 成功完成，返回所有数据
            continuation?.resume(returning: receivedData)
        }
    }
}


// MARK: - FileManagerHelper (无修改)
class FileManagerHelper {

    static var documentsDirectory: URL {
        let paths = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)
        return paths[0]
    }

    // 新增：检查文件是否存在
    static func fileExists(named filename: String) -> Bool {
        let url = documentsDirectory.appendingPathComponent(filename)
        return FileManager.default.fileExists(atPath: url.path)
    }

    static func getLatestFileUrl(for baseName: String) -> URL? {
        let fileManager = FileManager.default
        let documentsURL = self.documentsDirectory

        do {
            let fileURLs = try fileManager.contentsOfDirectory(at: documentsURL, includingPropertiesForKeys: nil)

            var latestFile: (url: URL, timestamp: String)? = nil

            let regex = try NSRegularExpression(pattern: "^\(baseName)_(\\d{6})\\..+$")

            for url in fileURLs {
                let filename = url.lastPathComponent
                let range = NSRange(location: 0, length: filename.utf16.count)

                if let match = regex.firstMatch(in: filename, options: [], range: range) {
                    if let timestampRange = Range(match.range(at: 1), in: filename) {
                        let timestamp = String(filename[timestampRange])

                        if latestFile == nil || timestamp > latestFile!.timestamp {
                            latestFile = (url, timestamp)
                        }
                    }
                }
            }

            if let file = latestFile {
                print("找到最新文件 for '\(baseName)': \(file.url.lastPathComponent)")
                return file.url
            } else {
                print("警告: 未能在 Documents 中找到 for '\(baseName)' 的任何版本文件。")
                return nil
            }

        } catch {
            print("错误: 无法列出 Documents 目录中的文件: \(error)")
            return nil
        }
    }
}

import SwiftUI

struct ArticleContainerView: View {
    let initialArticle: Article
    let navigationContext: NavigationContext

    @ObservedObject var viewModel: NewsViewModel

    @State private var currentArticle: Article
    @State private var currentSourceName: String

    @State private var liveUnreadCount: Int

    @State private var readArticleIDsInThisSession: Set<UUID> = []

    @State private var showNoNextToast = false
    @State private var showNoPreviousToast = false

    enum NavigationContext {
        case fromSource(String)
        case fromAllArticles
    }

    private var initialUnreadCount: Int {
        switch navigationContext {
        case .fromAllArticles:
            return viewModel.totalUnreadCount
        case .fromSource(let sourceName):
            return viewModel.sources.first { $0.name == sourceName }?.unreadCount ?? 0
        }
    }

    init(article: Article, sourceName: String, context: NavigationContext, viewModel: NewsViewModel) {
        self.initialArticle = article
        self.navigationContext = context
        self.viewModel = viewModel

        self._currentArticle = State(initialValue: article)
        self._currentSourceName = State(initialValue: sourceName)

        let baseCount: Int
        switch context {
        case .fromAllArticles:
            baseCount = viewModel.totalUnreadCount
        case .fromSource(let name):
            baseCount = viewModel.sources.first { $0.name == name }?.unreadCount ?? 0
        }
        self._liveUnreadCount = State(initialValue: baseCount)
    }

    var body: some View {
        ZStack(alignment: .bottom) {
            // ==================== 修改点: 更新 ArticleDetailView 的调用 ====================
            // 重新传入 requestNextArticle 参数，并将我们的切换函数传递给它
            ArticleDetailView(
                article: currentArticle,
                sourceName: currentSourceName,
                unreadCount: liveUnreadCount,
                viewModel: viewModel,
                requestNextArticle: {
                    self.switchToNextArticle()
                }
            )
            // ==========================================================================
            .id(currentArticle.id)
            .transition(.asymmetric(
                insertion: .move(edge: .bottom).combined(with: .opacity),
                removal: .move(edge: .top).combined(with: .opacity))
            )

            if showNoNextToast {
                ToastView(message: "该分组内已无更多文章")
            }

            if showNoPreviousToast {
                ToastView(message: "这已经是第一篇文章了")
            }
        }
        .onDisappear {
            if !currentArticle.isRead {
                readArticleIDsInThisSession.insert(currentArticle.id)
            }

            for articleID in readArticleIDsInThisSession {
                viewModel.markAsRead(articleID: articleID)
            }
        }
        .onChange(of: currentArticle.id) { oldValue, newValue in
            let wasArticleUnread = !viewModel.sources.flatMap { $0.articles }.first { $0.id == oldValue }!.isRead
            let isNewToSession = !readArticleIDsInThisSession.contains(oldValue)

            if wasArticleUnread && isNewToSession {
                liveUnreadCount -= 1
                readArticleIDsInThisSession.insert(oldValue)
            }
        }
        .background(Color.viewBackground.ignoresSafeArea())
    }

    /// 切换到下一篇文章的逻辑
    private func switchToNextArticle() {
        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        if let next = viewModel.findNextUnread(after: currentArticle.id,
                                               inSource: sourceNameToSearch) {
            withAnimation(.easeInOut(duration: 0.4)) {
                self.currentArticle = next.article
                self.currentSourceName = next.sourceName
            }
        } else {
            showToast { shouldShow in self.showNoNextToast = shouldShow }
        }
    }

    /// 切换到上一篇文章的逻辑 (此方法当前未被UI调用)
    private func switchToPreviousArticle() {
        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        if let prev = viewModel.findPreviousUnread(before: currentArticle.id, inSource: sourceNameToSearch) {
            withAnimation(.interactiveSpring(response: 0.4, dampingFraction: 0.8)) {
                self.currentArticle = prev.article
                self.currentSourceName = prev.sourceName
            }
        } else {
            showToast { shouldShow in self.showNoPreviousToast = shouldShow }
        }
    }

    private func showToast(setter: @escaping (Bool) -> Void) {
        setter(true)
        DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
            withAnimation {
                setter(false)
            }
        }
    }
}

