    @State private var errorMessage = ""

    // ==================== 修改 2: 引入 scenePhase 环璄变量 ====================
    @Environment(\.scenePhase) private var scenePhase
    // ========================================================================

    var body: some View {
        ZStack {
            NavigationView {
                List {
                    // ... List 内部代码保持不变 ...
                    // "Unread" 行
                    ZStack {
                        HStack {
