                            EmptyView()
                        }.opacity(0)
                    }
                    .listRowSeparator(.hidden)

                    // 新闻来源列表
                    ForEach(viewModel.sources) { source in
                        ZStack {
                            HStack {
                                Text(source.name)
                                    .fontWeight(.semibold)
