                            let effectiveHeight = size.height - (verticalPadding * 2)

                            // 修改所有 y 坐标计算，加入边距因素
                            let priceToY: (Double) -> CGFloat = { price in
                                let normalizedY = CGFloat((price - minPrice) / priceRange)
