// MARK: - ViewModel
class SearchViewModel: ObservableObject {
    @Published var searchHistory: [String] = []
    @Published var errorMessage: String? = nil
    @Published var isChartLoading: Bool = false
    @Published var groupedSearchResults: [GroupedSearchResults] = []

    var dataService: DataService
    private var cancellables = Set<AnyCancellable>()

    // 使用 DataService.shared 作为默认值
    init(dataService: DataService = DataService.shared) {
        self.dataService = dataService
        dataService.$errorMessage
            .receive(on: DispatchQueue.main)
            .assign(to: \.errorMessage, on: self)
            .store(in: &cancellables)
        loadSearchHistory()
    }

    func performSearch(query: String, completion: @escaping ([GroupedSearchResults]) -> Void) {
        let keywords = query.lowercased().split(separator: " ").map { String($0) }

        DispatchQueue.global(qos: .userInitiated).async { [weak self] in
            guard let self = self, let descriptionData = self.dataService.descriptionData else {
                DispatchQueue.main.async { completion([]) }
                return
            }

            var groupedResults: [(
                group: GroupedSearchResults,
                matchScore: Int,
                priority: Int
            )] = []

            let categories: [MatchCategory] = [
                .stockSymbol, .etfSymbol,
                .stockName, .etfName,
                .stockTag, .etfTag,
                .stockDescription, .etfDescription
            ]

            for category in categories {
                var matches: [(result: SearchResult, score: Int)] = []

                switch category {
                case .stockSymbol, .stockName, .stockDescription, .stockTag:
                    matches = self.searchCategory(items: descriptionData.stocks, keywords: keywords, category: category)

                case .etfSymbol, .etfName, .etfDescription, .etfTag:
                    matches = self.searchCategory(items: descriptionData.etfs, keywords: keywords, category: category)
                }

                if !matches.isEmpty {
                    let highestScore = matches.max(by: { $0.score < $1.score })?.score ?? 0
                    let group = GroupedSearchResults(category: category, results: matches, highestScore: highestScore)
                    groupedResults.append((group, highestScore, category.priority))
                }
            }

            let sortedGroups = groupedResults.sorted {
                if $0.matchScore != $1.matchScore {
                    return $0.matchScore > $1.matchScore
                }
                return $0.priority > $1.priority
            }.map { $0.group }

            DispatchQueue.main.async {
                if !keywords.isEmpty {
                    self.addSearchHistory(term: query)
                }
                self.groupedSearchResults = sortedGroups

                // 【修改】: 将数据获取流程串联起来
                self.fetchLatestVolumes(for: sortedGroups) {
                    // 在获取 volume 之后，接着获取财报趋势
                    self.fetchEarningTrends(for: sortedGroups) {
                        // 所有数据都获取完毕后，才最终回调
                        completion(sortedGroups)
                    }
                }
            }
        }
    }

    // 【新增】: 为所有搜索结果异步获取财报趋势
    private func fetchEarningTrends(for groupedResults: [GroupedSearchResults], completion: @escaping () -> Void) {
        let dispatchGroup = DispatchGroup()

        for group in groupedResults {
            for entry in group.results {
                dispatchGroup.enter()

                // 确保在后台线程执行数据库查询
                DispatchQueue.global(qos: .userInitiated).async {
                    let symbol = entry.result.symbol
                    var trend: EarningTrend = .insufficientData

                    // 获取所有财报数据并排序
                    let sortedEarnings = DatabaseManager.shared.fetchEarningData(forSymbol: symbol).sorted { $0.date > $1.date }

                    if sortedEarnings.count >= 2 {
                        let latestEarning = sortedEarnings[0]
                        let previousEarning = sortedEarnings[1]

                        // 使用 dataService 获取正确的表名
                        if let tableName = self.dataService.getCategory(for: symbol) {
                            let latestClose = DatabaseManager.shared.fetchClosingPrice(forSymbol: symbol, onDate: latestEarning.date, tableName: tableName)
                            let previousClose = DatabaseManager.shared.fetchClosingPrice(forSymbol: symbol, onDate: previousEarning.date, tableName: tableName)

                            if let latest = latestClose, let previous = previousClose {
                                if latestEarning.price > 0 {
                                    trend = (latest > previous) ? .positiveAndUp : .positiveAndDown
                                } else {
                                    trend = (latest > previous) ? .negativeAndUp : .negativeAndDown
                                }
                            }
                        }
                    }

                    // 回到主线程更新 UI 相关的属性
                    DispatchQueue.main.async {
                        entry.result.earningTrend = trend
                        dispatchGroup.leave()
                    }
                }
            }
        }

        // 当所有异步任务都完成后，调用最终的 completion
        dispatchGroup.notify(queue: .main) {
            completion()
        }
    }

    private func fetchLatestVolumes(for groupedResults: [GroupedSearchResults], completion: @escaping () -> Void) {
        let etfCategories: Set<MatchCategory> = [.etfSymbol, .etfName, .etfDescription, .etfTag]

        for groupedResult in groupedResults {
            if etfCategories.contains(groupedResult.category) {
                for (_, entry) in groupedResult.results.enumerated() {
                    let symbol = entry.result.symbol
                    if let latestVolume = DatabaseManager.shared.fetchLatestVolume(forSymbol: symbol, tableName: "ETFs") {
                        DispatchQueue.main.async {
                            entry.result.volume = self.formatVolume(latestVolume)
                        }
                    } else {
                        DispatchQueue.main.async {
                            entry.result.volume = "--K"
                        }
                    }
                }
            }
        }
        completion()
    }

    private func formatVolume(_ volume: Int64) -> String {
        let kVolume = Double(volume) / 1000.0
        return String(format: "%.0fK", kVolume)
    }

    // 搜索类别，并根据结果进行匹配和排序
    func searchCategory<T: SearchDescribableItem>(items: [T],
                                                  keywords: [String],
                                                  category: MatchCategory)
    -> [(result: SearchResult, score: Int)] {
        var scoredResults: [(SearchResult, Int)] = []

        for item in items {
            if let totalScore = matchScoreForItem(item, category: category, keywords: keywords) {
                let upperSymbol = item.symbol.uppercased()
                let data = dataService.marketCapData[upperSymbol]
                let marketCap = data?.marketCap
                let peRatioStr = data?.peRatio != nil ? String(format: "%.2f", data!.peRatio!) : "--"
                let pbStr = data?.pb != nil ? String(format: "%.2f", data!.pb!) : "--"  // 添加 PB 格式化

                let result = SearchResult(
                    symbol: item.symbol,
                    name: item.name,
                    tag: item.tag,
                    marketCap: marketCap,
                    peRatio: peRatioStr,
                    pb: pbStr,  // 添加 PB 数据
                    compare: dataService.compareData[upperSymbol]
                )

                scoredResults.append((result, totalScore))
            }
        }

        return scoredResults.sorted { $0.1 > $1.1 }
    }

    // 计算某个 item 与一组关键词在指定分类下的匹配分数
    private func matchScoreForItem<T: SearchDescribableItem>(
        _ item: T,
        category: MatchCategory,
        keywords: [String]) -> Int? {

        var totalScore = 0

        for keyword in keywords {
            let lowerKeyword = keyword.lowercased()
            let singleScore = scoreOfSingleMatch(item: item, keyword: lowerKeyword, category: category)
            if singleScore <= 0 {
                return nil
            } else {
                totalScore += singleScore
            }
        }
        return totalScore
    }

    // 计算单个关键词在指定分类下的匹配分数
    private func scoreOfSingleMatch<T: SearchDescribableItem>(
        item: T,
        keyword: String,
        category: MatchCategory) -> Int {

        switch category {
        case .stockSymbol, .etfSymbol:
            return matchSymbol(item.symbol.lowercased(), keyword: keyword)
        case .stockName, .etfName:
            return matchName(item.name, keyword: keyword)
        case .stockTag, .etfTag:
            return matchTags(item.tag, keyword: keyword)
        case .stockDescription, .etfDescription:
            return matchDescriptions(item.description1, item.description2, keyword: keyword)
        }
    }

    private func matchSymbol(_ symbol: String, keyword: String) -> Int {
        if symbol == keyword {
            return 3
        } else if symbol.contains(keyword) {
            return 2
        } else if isFuzzyMatch(text: symbol, keyword: keyword, maxDistance: 1) {
            return 1
        }
        return 0
    }

    private func matchName(_ name: String, keyword: String) -> Int {
        let lowercasedName = name.lowercased()
        let nameComponents = lowercasedName.components(separatedBy: ",")
        let mainName = nameComponents.first ?? lowercasedName
        let nameWords = mainName.split(separator: " ").map { String($0) }

        if lowercasedName == keyword {
            return 4
        } else if nameWords.contains(keyword) || mainName == keyword {
            return 3
        } else if mainName.contains(keyword) {
            return 2
        } else if lowercasedName.contains(keyword) {
            return 1
        } else if isFuzzyMatch(text: lowercasedName, keyword: keyword, maxDistance: 1) {
            return 1
        }
        return 0
    }

    private func matchTags(_ tags: [String], keyword: String) -> Int {
        var maxScore = 0
        for t in tags {
            let lowerTag = t.lowercased()
            var score = 0
            if lowerTag == keyword {
                score = 3
            } else if lowerTag.contains(keyword) {
                score = 2
            } else if isFuzzyMatch(text: lowerTag, keyword: keyword, maxDistance: 1) {
                score = 1
            }
            maxScore = max(maxScore, score)
        }
        return maxScore
    }

    private func matchDescriptions(_ desc1: String, _ desc2: String, keyword: String) -> Int {
        let d1 = desc1.lowercased()
        let d2 = desc2.lowercased()
        let words = d1.split(separator: " ") + d2.split(separator: " ")

        if words.contains(where: { String($0) == keyword }) {
            return 2
        } else if d1.contains(keyword) || d2.contains(keyword) {
            return 1
        }
        return 0
    }

    private func isFuzzyMatch(text: String, keyword: String, maxDistance: Int) -> Bool {
        if keyword.count <= 1 {
            return text.contains(keyword)
        }
        let words = text.split(separator: " ").map { String($0) }
        return words.contains { levenshteinDistance($0, keyword) <= maxDistance }
    }

    private func levenshteinDistance(_ s1: String, _ s2: String) -> Int {
        let a = Array(s1)
        let b = Array(s2)
        let n = a.count
        let m = b.count

        if n == 0 { return m }
        if m == 0 { return n }

        var matrix = Array(repeating: Array(repeating: 0, count: m + 1), count: n + 1)
        for i in 0...n { matrix[i][0] = i }
        for j in 0...m { matrix[0][j] = j }

        for i in 1...n {
            for j in 1...m {
                if a[i - 1] == b[j - 1] {
                    matrix[i][j] = matrix[i - 1][j - 1]
                } else {
                    matrix[i][j] = min(
                        matrix[i - 1][j] + 1,
                        matrix[i][j - 1] + 1,
                        matrix[i - 1][j - 1] + 1
                    )
                }
            }
        }
        return matrix[n][m]
    }

    // MARK: - 搜索历史
    func loadSearchHistory() {
        if let history = UserDefaults.standard.array(forKey: "stockSearchHistory") as? [String] {
            self.searchHistory = history
        }
    }

    func addSearchHistory(term: String) {
        let trimmedTerm = term.trimmingCharacters(in: .whitespaces)
        guard !trimmedTerm.isEmpty else { return }

        if let index = self.searchHistory.firstIndex(where: { $0.lowercased() == trimmedTerm.lowercased() }) {
            self.searchHistory.remove(at: index)
        }
        self.searchHistory.insert(trimmedTerm, at: 0)

        // 增加搜索历史记录保存条目的数量
        if self.searchHistory.count > 20 {
            self.searchHistory = Array(self.searchHistory.prefix(20))
        }
        UserDefaults.standard.set(searchHistory, forKey: "stockSearchHistory")
    }

    func removeSearchHistory(term: String) {
        if let index = searchHistory.firstIndex(where: { $0.lowercased() == term.lowercased() }) {
            searchHistory.remove(at: index)
            UserDefaults.standard.set(searchHistory, forKey: "stockSearchHistory")
        }
    }
}

import Foundation
import SQLite3

extension DatabaseManager: @unchecked Sendable {}

class DatabaseManager {
    static let shared = DatabaseManager()
    private var db: OpaquePointer?
    private let dbQueue = DispatchQueue(label: "com.finance.db.queue") // 新增：串行队列

    // MARK: - 表分组定义
    // 定义使用 (name, date) 作为复合主键的表集合
    private let tablesWithCompositeKey: Set<String> = [
        "Earning", "Energy", "Indices", "Crypto", "Currencies", "Bonds",
        "Basic_Materials", "Communication_Services", "Consumer_Cyclical",
        "Consumer_Defensive", "Financial_Services", "Utilities", "Real_Estate",
        "Industrials", "Healthcare", "Technology", "Economics", "ETFs",
        "Commodities"
    ]

    // 定义使用 (symbol) 作为主键的表集合
    private let tablesWithSymbolKey: Set<String> = ["MNSPP"]

    struct MarketCapInfo {
        let symbol: String
        let marketCap: Double
        let peRatio: Double?
        let pb: Double?
    }

    private init() {
        print("=== DatabaseManager Initializing ===")
        openDatabase()
    }

    deinit {
        if db != nil {
            sqlite3_close(db)
        }
    }

    func reconnectToLatestDatabase() {
        print("=== DatabaseManager Reconnecting ===")
        if db != nil {
            sqlite3_close(db)
            db = nil
            print("已关闭旧的数据库连接。")
        }
        openDatabase()
    }

    private func openDatabase() {
        let dbName = "Finance.db"
        let dbUrl = FileManagerHelper.documentsDirectory.appendingPathComponent(dbName)

        guard FileManager.default.fileExists(atPath: dbUrl.path) else {
            print("错误：数据库文件 \(dbName) 在 Documents 目录中未找到。")
            self.db = nil
            return
        }

        if sqlite3_open(dbUrl.path, &db) == SQLITE_OK {
            print("成功从 Documents 目录打开数据库: \(dbName)")
        } else {
            let errorMessage = String(cString: sqlite3_errmsg(db))
            print("无法从 Documents 目录打开数据库: \(dbName)。错误: \(errorMessage)")
            self.db = nil
        }
    }

    func applySyncChanges(_ changes: [Change]) async -> Bool {
        return await withCheckedContinuation { continuation in
            dbQueue.async {
                guard self.db != nil else {
                    print("数据库连接无效，无法应用变更。")
                    continuation.resume(returning: false)
                    return
                }

                guard sqlite3_exec(self.db, "BEGIN TRANSACTION", nil, nil, nil) == SQLITE_OK else {
                    print("开启事务失败: \(String(cString: sqlite3_errmsg(self.db)))")
                    continuation.resume(returning: false)
                    return
                }

                for change in changes {
                    var success = false
                    switch change.op {
                    case "I", "U":
                        success = self.applyReplace(for: change)
                    case "D":
                        success = self.applyDelete(for: change)
                    default:
                        print("未知的操作类型: \(change.op)")
                        success = true
                    }

                    if !success {
                        print("应用变更失败，正在回滚...")
                        sqlite3_exec(self.db, "ROLLBACK TRANSACTION", nil, nil, nil)
                        continuation.resume(returning: false)
                        return
                    }
                }

                guard sqlite3_exec(self.db, "COMMIT TRANSACTION", nil, nil, nil) == SQLITE_OK else {
                    print("提交事务失败: \(String(cString: sqlite3_errmsg(self.db)))")
                    sqlite3_exec(self.db, "ROLLBACK TRANSACTION", nil, nil, nil)
                    continuation.resume(returning: false)
                    return
                }

                print("成功应用 \(changes.count) 条变更。")
                continuation.resume(returning: true)
            }
        }
    }

    // ==================== 【最终版修复代码】 ====================
    private func applyDelete(for change: Change) -> Bool {
        var sql: String
        var statement: OpaquePointer?

        // 使用 Set 来判断表的类型，实现动态处理
        if tablesWithCompositeKey.contains(change.table) {
            // 处理所有使用 (name, date) 作为主键的表
            guard case let .string(name) = change.key["name"],
                  case let .string(date) = change.key["date"] else {
                print("\(change.table) 删除失败：无法从 key 解析 name 和 date。Key: \(change.key)")
                return false
            }

            sql = "DELETE FROM \"\(change.table)\" WHERE name = ? AND date = ?;"

            guard sqlite3_prepare_v2(db, sql, -1, &statement, nil) == SQLITE_OK else {
                print("为 \(change.table) DELETE 准备语句失败: \(String(cString: sqlite3_errmsg(db)))")
                return false
            }
            sqlite3_bind_text(statement, 1, (name as NSString).utf8String, -1, nil)
            sqlite3_bind_text(statement, 2, (date as NSString).utf8String, -1, nil)

        } else if tablesWithSymbolKey.contains(change.table) {
            // 处理所有使用 (symbol) 作为主键的表
            guard case let .string(symbol) = change.key["symbol"] else {
                print("\(change.table) 删除失败：无法从 key 解析 symbol。Key: \(change.key)")
                return false
            }

            sql = "DELETE FROM \"\(change.table)\" WHERE symbol = ?;"

            guard sqlite3_prepare_v2(db, sql, -1, &statement, nil) == SQLITE_OK else {
                print("为 \(change.table) DELETE 准备语句失败: \(String(cString: sqlite3_errmsg(db)))")
                return false
            }
            sqlite3_bind_text(statement, 1, (symbol as NSString).utf8String, -1, nil)

        } else {
            // 如果有未知的表类型，打印错误
            print("未知的表类型 \(change.table)，无法执行删除。请检查 DBManager.swift 中的分组定义。")
            return false
        }

        let result = sqlite3_step(statement)
        sqlite3_finalize(statement)

        guard result == SQLITE_DONE else {
            print("执行 DELETE 失败 (table: \(change.table), key: \(change.key)): \(String(cString: sqlite3_errmsg(db)))")
            return false
        }

        return true
    }
    // ==========================================================

    private func applyReplace(for change: Change) -> Bool {
        guard let data = change.data, !data.isEmpty else { return false }

        let sortedKeys = data.keys.sorted()

        let columns = sortedKeys.map { "\"\($0)\"" }.joined(separator: ", ")
        let placeholders = Array(repeating: "?", count: data.count).joined(separator: ", ")
        let sql = "REPLACE INTO \"\(change.table)\" (\(columns)) VALUES (\(placeholders));"

        var statement: OpaquePointer?

        guard sqlite3_prepare_v2(db, sql, -1, &statement, nil) == SQLITE_OK else {
            print("为 REPLACE 操作准备语句失败: \(String(cString: sqlite3_errmsg(db)))")
            print("导致准备失败的变更是: \(change)")
            return false
        }

        var index: Int32 = 1
        for key in sortedKeys {
            let value = data[key]!

            switch value {
            case .int(let intValue):
                sqlite3_bind_int64(statement, index, Int64(intValue))
            case .double(let doubleValue):
                if doubleValue.truncatingRemainder(dividingBy: 1) == 0 {
                    sqlite3_bind_int64(statement, index, Int64(doubleValue))
                } else {
                    sqlite3_bind_double(statement, index, doubleValue)
                }
            case .string(let stringValue):
                sqlite3_bind_text(statement, index, (stringValue as NSString).utf8String, -1, nil)
            case .null:
                sqlite3_bind_null(statement, index)
            }
            index += 1
        }

        let result = sqlite3_step(statement)
        sqlite3_finalize(statement)

        guard result == SQLITE_DONE else {
            print("执行 REPLACE 失败 (table: \(change.table), key: \(change.key)): \(String(cString: sqlite3_errmsg(db)))")
            return false
        }

        return true
    }

    struct PriceData: Identifiable {
        let id: Int
        let date: Date
        let price: Double
        let volume: Int64?
    }

    func fetchAllMarketCapData(from tableName: String) -> [MarketCapInfo] {
            var results: [MarketCapInfo] = []

            // 在串行队列中同步执行数据库操作
            dbQueue.sync {
                guard db != nil else { return }
                let query = "SELECT symbol, marketcap, pe_ratio, pb FROM \"\(tableName)\""
                var statement: OpaquePointer?

                if sqlite3_prepare_v2(db, query, -1, &statement, nil) == SQLITE_OK {
                    while sqlite3_step(statement) == SQLITE_ROW {
                        let symbol = String(cString: sqlite3_column_text(statement, 0))
                        let marketCap = sqlite3_column_double(statement, 1)
                        let peRatio: Double? = sqlite3_column_type(statement, 2) != SQLITE_NULL ? sqlite3_column_double(statement, 2) : nil
                        let pb: Double? = sqlite3_column_type(statement, 3) != SQLITE_NULL ? sqlite3_column_double(statement, 3) : nil
                        results.append(MarketCapInfo(symbol: symbol, marketCap: marketCap, peRatio: peRatio, pb: pb))
                    }
                } else {
                    print("Failed to prepare statement for market cap data: \(String(cString: sqlite3_errmsg(db)))")
                }
                sqlite3_finalize(statement)
            }

            return results
        }

    func fetchLatestVolume(forSymbol symbol: String, tableName: String) -> Int64? {
            var latestVolume: Int64? = nil

            dbQueue.sync {
                guard db != nil else { return }
                let query = "SELECT volume FROM \(tableName) WHERE name = ? ORDER BY date DESC LIMIT 1"
                var statement: OpaquePointer?

                if sqlite3_prepare_v2(db, query, -1, &statement, nil) == SQLITE_OK {
                    sqlite3_bind_text(statement, 1, (symbol as NSString).utf8String, -1, nil)
                    if sqlite3_step(statement) == SQLITE_ROW {
                        latestVolume = sqlite3_column_int64(statement, 0)
                    }
                } else {
                    print("Failed to prepare statement: \(String(cString: sqlite3_errmsg(db)))")
                }
                sqlite3_finalize(statement)
            }

            return latestVolume
        }

    enum DateRangeInput {
        case timeRange(TimeRange)
        case customRange(start: Date, end: Date)
    }

    func fetchHistoricalData(
        symbol: String,
        tableName: String,
        dateRange: DateRangeInput
    ) -> [PriceData] {
        var result: [PriceData] = []

        dbQueue.sync {
            guard db != nil else { return }
            let dateFormat = "yyyy-MM-dd"

            let (startDate, endDate): (Date, Date) = {
                switch dateRange {
                case .timeRange(let timeRange):
                    return (timeRange.startDate, Date())
                case .customRange(let start, let end):
                    return (start, end)
                }
            }()

            let hasVolumeColumn = self.checkIfTableHasVolumeInternal(tableName: tableName)

            let query = """
                SELECT id, date, price\(hasVolumeColumn ? ", volume" : "")
                FROM "\(tableName)"
                WHERE name = ? AND date BETWEEN ? AND ?
                ORDER BY date ASC
            """

            var statement: OpaquePointer?

            if sqlite3_prepare_v2(db, query, -1, &statement, nil) == SQLITE_OK {
                let formatter = DateFormatter()
                formatter.dateFormat = dateFormat

                sqlite3_bind_text(statement, 1, (symbol as NSString).utf8String, -1, nil)
                sqlite3_bind_text(statement, 2, (formatter.string(from: startDate) as NSString).utf8String, -1, nil)
                sqlite3_bind_text(statement, 3, (formatter.string(from: endDate) as NSString).utf8String, -1, nil)

                while sqlite3_step(statement) == SQLITE_ROW {
                    let id = Int(sqlite3_column_int(statement, 0))
                    let dateString = String(cString: sqlite3_column_text(statement, 1))
                    let price = sqlite3_column_double(statement, 2)

                    if let date = formatter.date(from: dateString) {
                        let volume = hasVolumeColumn ? sqlite3_column_int64(statement, 3) : nil
                        result.append(PriceData(id: id, date: date, price: price, volume: volume))
                    }
                }
            }

            sqlite3_finalize(statement)
        }

        return result
    }

    struct EarningData {
        let date: Date
        let price: Double
    }

    func fetchEarningData(forSymbol symbol: String) -> [EarningData] {
            var result: [EarningData] = []

            // 在串行队列中同步执行数据库操作
            dbQueue.sync {
                guard db != nil else { return }
                let dateFormat = "yyyy-MM-dd"
                let formatter = DateFormatter()
                formatter.dateFormat = dateFormat

                let query = "SELECT date, price FROM Earning WHERE name = ?"
                var statement: OpaquePointer?

                if sqlite3_prepare_v2(db, query, -1, &statement, nil) == SQLITE_OK {
                    sqlite3_bind_text(statement, 1, (symbol as NSString).utf8String, -1, nil)

                    while sqlite3_step(statement) == SQLITE_ROW {
                        if let dateString = sqlite3_column_text(statement, 0) {
                            let dateStr = String(cString: dateString)
                            let price = sqlite3_column_double(statement, 1)

                            if let date = formatter.date(from: dateStr) {
                                result.append(EarningData(date: date, price: price))
                            }
                        }
                    }
                } else {
                    print("Failed to prepare statement: \(String(cString: sqlite3_errmsg(db)))")
                }

                sqlite3_finalize(statement)
            }

            return result
        }

        /// 根据 symbol, date 和 table name 获取单日的收盘价
        func fetchClosingPrice(forSymbol symbol: String, onDate date: Date, tableName: String) -> Double? {
            var price: Double?

            dbQueue.sync {
                guard db != nil else { return }

                let formatter = DateFormatter()
                formatter.dateFormat = "yyyy-MM-dd"
                let dateString = formatter.string(from: date)

                let query = "SELECT price FROM \"\(tableName)\" WHERE name = ? AND date = ? LIMIT 1"
                var statement: OpaquePointer?

                if sqlite3_prepare_v2(db, query, -1, &statement, nil) == SQLITE_OK {
                    sqlite3_bind_text(statement, 1, (symbol as NSString).utf8String, -1, nil)
                    sqlite3_bind_text(statement, 2, (dateString as NSString).utf8String, -1, nil)

                    if sqlite3_step(statement) == SQLITE_ROW {
                        price = sqlite3_column_double(statement, 0)
                    }
                } else {
                    print("Failed to prepare statement for closing price: \(String(cString: sqlite3_errmsg(db)))")
                }

                sqlite3_finalize(statement)
            }

            return price
        }

    // 将原来的 checkIfTableHasVolume 拆分为两个方法
    private func checkIfTableHasVolumeInternal(tableName: String) -> Bool {
        guard db != nil else { return false }
        var hasVolume = false
        var statement: OpaquePointer?

        let query = "PRAGMA table_info(\"\(tableName)\")"

        if sqlite3_prepare_v2(db, query, -1, &statement, nil) == SQLITE_OK {
            while sqlite3_step(statement) == SQLITE_ROW {
                if let name = sqlite3_column_text(statement, 1) {
                    let columnName = String(cString: name)
                    if columnName.lowercased() == "volume" {
                        hasVolume = true
                        break
                    }
                }
            }
        }

        sqlite3_finalize(statement)
        return hasVolume
    }

    func checkIfTableHasVolume(tableName: String) -> Bool {
        var result = false
        dbQueue.sync {
            result = checkIfTableHasVolumeInternal(tableName: tableName)
        }
        return result
    }
}

