    // -------------------- MODIFICATION 1: REMOVED --------------------
    // @State private var shouldUppercase = true (已移除)
    // -----------------------------------------------------------------

    var body: some View {
        VStack {
            ScrollView {
                VStack(alignment: .leading, spacing: 16) {

