        }
        .onAppear {
            if symbols.isEmpty {
                if initialSymbol.isEmpty {
                    symbols.append("")
                } else {
                    symbols.append(initialSymbol)
                }
                symbols.append("")

                DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                    focusedField = initialSymbol.isEmpty ? 0 : 1
                }
            }
        }
        .navigationDestination(isPresented: $navigateToComparison) {
            // 导航目标变为新的 ComparisonChartView
            ComparisonChartView(symbols: symbols, startDate: startDate, endDate: endDate)
        }
        .alert(isPresented: $showAlert) {
            Alert(title: Text("错误"),
                  message: Text(errorMessage ?? "未知错误"),
                  dismissButton: .default(Text("确定")))
        }
    }

    // -------------------- MODIFICATION 2: UPDATED `formatSymbol` LOGIC --------------------
    /// 尝试以两种方式匹配股票代码：首先是全大写，然后是首字母大写。
    /// - Parameter symbol: 用户输入的原始股票代码。
    /// - Returns: 如果找到匹配项，则返回数据库中原始大小写的代码；否则返回 `nil`。
    func formatSymbol(_ symbol: String) -> String? {
        guard let url = Bundle.main.url(forResource: "Sectors_All", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let sectorData = try? JSONSerialization.jsonObject(with: data, options: []) as? [String: [String]] else {
            return nil // 如果JSON加载失败，直接返回nil
        }

        let uppercasedInput = symbol.uppercased()
        let capitalizedInput = symbol.capitalized

        // 第一次尝试：全大写匹配
        // 遍历JSON数据，将JSON中的代码和用户输入的代码都转为大写进行比较
        for (_, symbolList) in sectorData {
            for originalJsonSymbol in symbolList {
                if originalJsonSymbol.uppercased() == uppercasedInput {
                    return originalJsonSymbol // 找到匹配，返回数据库中的原始代码
                }
            }
        }

        // 第二次尝试：首字母大写匹配
        // 遍历JSON数据，将用户输入转为首字母大写后，与JSON中的原始代码直接比较
        for (_, symbolList) in sectorData {
            for originalJsonSymbol in symbolList {
                if originalJsonSymbol == capitalizedInput {
                    return originalJsonSymbol // 找到匹配，返回数据库中的原始代码
                }
            }
        }

        // 如果两种方式都找不到，则返回 nil
        return nil
    }
    // ------------------------------------------------------------------------------------

    // -------------------- MODIFICATION 3: UPDATED `startComparison` LOGIC --------------------
    private func startComparison() {
        errorMessage = nil
        let trimmedSymbols = symbols
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }

        guard !trimmedSymbols.isEmpty else {
            errorMessage = "请至少输入一个股票代码"
            showAlert = true
            return
        }

        if trimmedSymbols.count > maxSymbols {
            errorMessage = "最多只能比较 \(maxSymbols) 个股票代码"
            showAlert = true
            return
        }

        guard startDate <= endDate else {
            errorMessage = "开始日期必须早于或等于结束日期"
            showAlert = true
            return
        }

        var formattedSymbols: [String] = []
        // 遍历用户输入的每个代码，并使用新的匹配逻辑进行格式化
        for symbol in trimmedSymbols {
            if let formattedSymbol = formatSymbol(symbol) {
                // 如果匹配成功，将其添加到新数组中
                formattedSymbols.append(formattedSymbol)
            } else {
                // 如果匹配失败 (formatSymbol返回nil)，则设置错误消息并中断流程
                errorMessage = "无法找到股票代码 \"\(symbol)\" 的有效匹配。请检查拼写。"
                showAlert = true
                return // 立即退出函数
            }
        }

        // 只有当所有代码都成功匹配后，才继续导航
        self.symbols = formattedSymbols
        navigateToComparison = true
    }
}


