                    .background(Color.white.opacity(0.8))
                    .clipShape(Circle())
            }
            .padding(8),
            alignment: .topTrailing
        )
        .offset(y: -50) // 向下偏移100点，你可以根据需要调整这个值
        .padding(.horizontal) // 添加水平内边距确保不会太靠近屏幕边缘
        .onChange(of: playerManager.progress) { _, newValue in
