            }
            .padding(.top, 5)
            .transition(.move(edge: .top).combined(with: .opacity))
            .zIndex(1)
        }
    }
    .toolbar {
        ToolbarItem(placement: .principal) {
            VStack(spacing: 2) {
                Text(sourceName.replacingOccurrences(of: "_", with: " "))
                    .font(.headline)
                HStack(spacing: 8) {
