    .sheet(isPresented: $isSharePresented) {
        let shareText = article.topic + "\n\n" + paragraphs.joined(separator: "\n\n")
        ActivityView(activityItems: [shareText])
            .presentationDetents([.medium, .large]).presentationDragIndicator(.visible)
    }
