    // 保留但当前不依赖通知去启动自动播放
    @State private var pendingAutoPlayRequestID: UUID?

    enum NavigationContext {
        case fromSource(String)
        case fromAllArticles
    }

    private var initialUnreadCount: Int {
        switch navigationContext {
        case .fromAllArticles:
