struct ArticleListView: View {
    let source: NewsSource
    @ObservedObject var viewModel: NewsViewModel

    @State private var filterMode: ArticleFilterMode = .unread

    // 编程式导航用状态（新写法）
    @State private var showFirstTarget = false
    @State private var firstTargetArticle: Article?

    private var filteredArticles: [Article] {
        source.articles.filter { filterMode == .unread ? !$0.isRead : $0.isRead }
    }
    private var groupedArticles: [String: [Article]] {
        Dictionary(grouping: filteredArticles, by: { $0.timestamp })
    }
    private var sortedTimestamps: [String] {
        groupedArticles.keys.sorted()
    }
    private var unreadCount: Int { source.articles.filter { !$0.isRead }.count }
    private var readCount: Int { source.articles.filter { $0.isRead }.count }

    var body: some View {
        VStack {
            List {
                ForEach(sortedTimestamps, id: \.self) { timestamp in
                    Section(header: Text(formatTimestamp(timestamp))
                                .font(.headline)
                                .foregroundColor(.blue.opacity(0.7))
                                .padding(.vertical, 4)
                    ) {
                        ForEach(groupedArticles[timestamp] ?? []) { article in
                            NavigationLink(destination: ArticleContainerView(
                                article: article,
                                sourceName: source.name,
                                context: .fromSource(source.name),
                                viewModel: viewModel
                            )) {
                                ArticleRowCardView(article: article, sourceName: nil)
                            }
                            .listRowInsets(EdgeInsets(top: 4, leading: 6, bottom: 4, trailing: 6))
                            .listRowSeparator(.hidden)
                            .listRowBackground(Color.clear)
                            .contextMenu {
                                if article.isRead {
                                    Button { viewModel.markAsUnread(articleID: article.id) }
                                    label: { Label("标记为未读", systemImage: "circle") }
                                } else {
                                    Button { viewModel.markAsRead(articleID: article.id) }
                                    label: { Label("标记为已读", systemImage: "checkmark.circle") }
                                    if filterMode == .unread {
                                        Divider()
                                        Button {
                                            viewModel.markAllAboveAsRead(articleID: article.id, inVisibleList: self.filteredArticles)
                                        }
                                        label: { Label("以上全部已读", systemImage: "arrow.up.to.line.compact") }

                                        Button {
                                            viewModel.markAllBelowAsRead(articleID: article.id, inVisibleList: self.filteredArticles)
                                        }
                                        label: { Label("以下全部已读", systemImage: "arrow.down.to.line.compact") }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            .listStyle(PlainListStyle())
            .navigationTitle(source.name.replacingOccurrences(of: "_", with: " "))
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .navigationBarTrailing) {
                    Button {
                        navigateToFirstAndAutoplay(in: filteredArticles, sourceName: source.name)
                    } label: {
                        Image(systemName: "speaker.wave.2.fill")
                    }
                    .accessibilityLabel("朗读此列表")
                }
            }

            Picker("Filter", selection: $filterMode) {
                ForEach(ArticleFilterMode.allCases, id: \.self) { mode in
                    let count = (mode == .unread) ? unreadCount : readCount
                    Text("\(mode.rawValue) (\(count))").tag(mode)
                }
            }
            .pickerStyle(.segmented)
            .padding([.horizontal, .bottom])
        }
        .background(Color.viewBackground.ignoresSafeArea())
        // 新导航目的地（替代废弃 API）
        .navigationDestination(isPresented: $showFirstTarget) {
            if let target = firstTargetArticle {
                ArticleContainerView(
                    article: target,
                    sourceName: source.name,
                    context: .fromSource(source.name),
                    viewModel: viewModel
                )
            } else {
                EmptyView()
            }
        }
    }

    private func formatTimestamp(_ timestamp: String) -> String {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyMMdd"
        guard let date = formatter.date(from: timestamp) else { return timestamp }
        formatter.locale = Locale(identifier: "zh_CN")
        formatter.dateFormat = "yyyy年M月d日, EEEE"
        return formatter.string(from: date)
    }

    // 跳转到列表首篇（优先未读），并请求自动播放
    private func navigateToFirstAndAutoplay(in visibleList: [Article], sourceName: String) {
        guard !visibleList.isEmpty else { return }
        // 优先第一篇未读，否则就第一篇
        let target = visibleList.first(where: { !$0.isRead }) ?? visibleList.first!
        self.firstTargetArticle = target
        self.showFirstTarget = true
        // 等待导航入栈后，发送自动播放请求
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
            NotificationCenter.default.post(name: .onewsAutoPlayRequest, object: nil, userInfo: ["articleID": target.id])
        }
    }
}

// ==================== 所有文章列表 ====================
struct AllArticlesListView: View {
    @ObservedObject var viewModel: NewsViewModel
    @State private var filterMode: ArticleFilterMode = .unread

    // 编程式导航用状态（新写法）
    @State private var showFirstTarget = false
    @State private var firstTarget: (article: Article, sourceName: String)?

    private var filteredArticles: [(article: Article, sourceName: String)] {
        viewModel.allArticlesSortedForDisplay.filter { item in
            filterMode == .unread ? !item.article.isRead : item.article.isRead
        }
    }

    private var groupedArticles: [String: [(article: Article, sourceName: String)]] {
        Dictionary(grouping: filteredArticles, by: { $0.article.timestamp })
    }

    private var sortedTimestamps: [String] {
        groupedArticles.keys.sorted()
    }

    private var totalUnreadCount: Int { viewModel.totalUnreadCount }
    private var totalReadCount: Int { viewModel.sources.flatMap { $0.articles }.filter { $0.isRead }.count }

    var body: some View {
        VStack {
            List {
                ForEach(sortedTimestamps, id: \.self) { timestamp in
                    Section(header: Text(formatTimestamp(timestamp))
                                .font(.headline)
                                .foregroundColor(.blue.opacity(0.7))
                                .padding(.vertical, 4)
                    ) {
                        ForEach(groupedArticles[timestamp] ?? [], id: \.article.id) { item in
                            NavigationLink(destination: ArticleContainerView(
                                article: item.article,
                                sourceName: item.sourceName,
                                context: .fromAllArticles,
                                viewModel: viewModel
                            )) {
                                ArticleRowCardView(article: item.article, sourceName: item.sourceName)
                            }
                            .listRowInsets(EdgeInsets(top: 4, leading: 6, bottom: 4, trailing: 6))
                            .listRowSeparator(.hidden)
                            .listRowBackground(Color.clear)
                            .contextMenu {
                                if item.article.isRead {
                                    Button { viewModel.markAsUnread(articleID: item.article.id) }
                                    label: { Label("标记为未读", systemImage: "circle") }
                                } else {
                                    Button { viewModel.markAsRead(articleID: item.article.id) }
                                    label: { Label("标记为已读", systemImage: "checkmark.circle") }
                                    if filterMode == .unread {
                                        Divider()
                                        Button {
                                            let visibleArticleList = self.filteredArticles.map { $0.article }
                                            viewModel.markAllAboveAsRead(articleID: item.article.id, inVisibleList: visibleArticleList)
                                        }
                                        label: { Label("以上全部已读", systemImage: "arrow.up.to.line.compact") }

                                        Button {
                                            let visibleArticleList = self.filteredArticles.map { $0.article }
                                            viewModel.markAllBelowAsRead(articleID: item.article.id, inVisibleList: visibleArticleList)
                                        }
                                        label: { Label("以下全部已读", systemImage: "arrow.down.to.line.compact") }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            .listStyle(PlainListStyle())
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .navigationBarTrailing) {
                    Button {
                        navigateToFirstAndAutoplayInAll()
                    } label: {
                        Image(systemName: "speaker.wave.2.fill")
                    }
                    .accessibilityLabel("朗读此列表")
                }
            }

            Picker("Filter", selection: $filterMode) {
                ForEach(ArticleFilterMode.allCases, id: \.self) { mode in
                    let count = (mode == .unread) ? totalUnreadCount : totalReadCount
                    Text("\(mode.rawValue) (\(count))").tag(mode)
                }
            }
            .pickerStyle(.segmented)
            .padding([.horizontal, .bottom])
        }
        .background(Color.viewBackground.ignoresSafeArea())
        // 新导航目的地（替代废弃 API）
        .navigationDestination(isPresented: $showFirstTarget) {
            if let target = firstTarget {
                ArticleContainerView(
                    article: target.article,
                    sourceName: target.sourceName,
                    context: .fromAllArticles,
                    viewModel: viewModel
                )
            } else {
                EmptyView()
            }
        }
    }

    private func formatTimestamp(_ timestamp: String) -> String {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyMMdd"
        guard let date = formatter.date(from: timestamp) else { return timestamp }
        formatter.locale = Locale(identifier: "zh_CN")
        formatter.dateFormat = "yyyy年M月d日, EEEE"
        return formatter.string(from: date)
    }

    // 跳转到首篇（优先未读），并请求自动播放（All 视图）
    private func navigateToFirstAndAutoplayInAll() {
        guard !filteredArticles.isEmpty else { return }
        let target = filteredArticles.first(where: { !$0.article.isRead }) ?? filteredArticles.first!
        self.firstTarget = target
        self.showFirstTarget = true
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
            NotificationCenter.default.post(name: .onewsAutoPlayRequest, object: nil, userInfo: ["articleID": target.article.id])
        }
    }
}

import Foundation
import AVFoundation
import Combine
import SwiftUI
import MediaPlayer
import NaturalLanguage

@MainActor
class AudioPlayerManager: NSObject, ObservableObject, AVSpeechSynthesizerDelegate, @preconcurrency AVAudioPlayerDelegate {
    // MARK: - Published Properties for UI
    @Published var isPlaybackActive = false
    @Published var isPlaying = false
    @Published var isSynthesizing = false

    @Published var progress: Double = 0.0
    @Published var currentTimeString: String = "00:00"
    @Published var durationString: String = "00:00"

    // 回调
    var onPlaybackFinished: (() -> Void)?
    var onNextRequested: (() -> Void)?
    var onToggleRepeatRequested: (() -> Void)?

    @Published var isAutoPlayEnabled = false {
        didSet {
            UserDefaults.standard.set(isAutoPlayEnabled, forKey: autoPlayEnabledKey)
            updateRepeatStateInNowPlaying()
        }
    }

    @Published var playbackRate: Float = 1.0 {
        didSet {
            if playbackRate < 0.5 { playbackRate = 0.5 }
            else if playbackRate > 2.0 { playbackRate = 2.0 }
            applyPlaybackRate()
            refreshNowPlayingInfo()
        }
    }

    // MARK: - Private Properties
    private var speechSynthesizer = AVSpeechSynthesizer()
    private var audioPlayer: AVAudioPlayer?
    private var displayLink: CADisplayLink?

    private var temporaryAudioFileURL: URL?
    private var audioFile: AVAudioFile?
    private let autoPlayEnabledKey = "audio.autoPlayEnabled"

    // 防重复注册 Remote Commands 的标志
    private var remoteCommandsRegistered = false

    // 当前播放项的标题（用于锁屏展示）
    private var nowPlayingTitle: String = "正在播放的文章"

    // 合成阶段看门狗（防止在锁屏后台卡死）
    private var synthesisWatchdogTimer: Timer?
    private var synthesisLastWriteAt: Date?

    override init() {
        super.init()
        self.speechSynthesizer.delegate = self
        if UserDefaults.standard.object(forKey: autoPlayEnabledKey) != nil {
            self.isAutoPlayEnabled = UserDefaults.standard.bool(forKey: autoPlayEnabledKey)
        } else {
            self.isAutoPlayEnabled = false
        }
        setupRemoteTransportControls()
        setupNotifications()
    }

    deinit {
        audioPlayer?.stop()
        audioPlayer?.delegate = nil
        audioPlayer = nil
        speechSynthesizer.stopSpeaking(at: .immediate)
        speechSynthesizer.delegate = nil
        Task { @MainActor [weak self] in
            self?.invalidateSynthesisWatchdog()
        }
        // 其余完整清理由外部 stop() 负责
    }

    // 仅用于“切到下一篇”时的轻量清理：不反激活 AudioSession，不拆 Remote Commands
    func prepareForNextTransition() {
        speechSynthesizer.stopSpeaking(at: .immediate)
        audioPlayer?.stop()
        isPlaying = false
        isSynthesizing = false
        stopDisplayLink()
        cleanupTemporaryFile()
        invalidateSynthesisWatchdog()
        // 保持 isPlaybackActive = true，让播放器面板维持（如果你想隐藏可自行改）
        // 保持 AudioSession 活跃，避免后台/锁屏时下一篇激活失败
    }

    private func applyPlaybackRate() {
        guard let player = audioPlayer else { return }
        player.enableRate = true
        player.rate = playbackRate
    }

    // MARK: - Remote Command Center
    private func setupRemoteTransportControls() {
        guard !remoteCommandsRegistered else { return }
        let commandCenter = MPRemoteCommandCenter.shared()

        commandCenter.playCommand.isEnabled = true
        commandCenter.pauseCommand.isEnabled = true
        commandCenter.stopCommand.isEnabled = true
        commandCenter.nextTrackCommand.isEnabled = true
        commandCenter.previousTrackCommand.isEnabled = false

        commandCenter.playCommand.addTarget { [weak self] _ in
            guard let self = self else { return .commandFailed }
            if !self.isPlaying {
                self.playPause()
                return .success
            }
            return .commandFailed
        }

        commandCenter.pauseCommand.addTarget { [weak self] _ in
            guard let self = self else { return .commandFailed }
            if self.isPlaying {
                self.playPause()
                return .success
            }
            return .commandFailed
        }

        commandCenter.stopCommand.addTarget { [weak self] _ in
            self?.stop()
            return .success
        }

        commandCenter.nextTrackCommand.addTarget { [weak self] _ in
            guard let self = self else { return .commandFailed }
            self.prepareForNextTransition()
            self.onNextRequested?()
            return .success
        }

        remoteCommandsRegistered = true
    }

    private func teardownRemoteTransportControls() {
        let cc = MPRemoteCommandCenter.shared()
        cc.playCommand.removeTarget(nil)
        cc.pauseCommand.removeTarget(nil)
        cc.stopCommand.removeTarget(nil)
        cc.nextTrackCommand.removeTarget(nil)
        remoteCommandsRegistered = false
    }

    private func updateRepeatStateInNowPlaying() {
        var info = MPNowPlayingInfoCenter.default().nowPlayingInfo ?? [:]
        info[MPMediaItemPropertyTitle] = nowPlayingTitle
        if let player = audioPlayer {
            info[MPNowPlayingInfoPropertyElapsedPlaybackTime] = player.currentTime
            info[MPMediaItemPropertyPlaybackDuration] = player.duration
            info[MPNowPlayingInfoPropertyPlaybackRate] = player.isPlaying ? Double(playbackRate) : 0.0
        }
        info[MPMediaItemPropertyArtist] = isAutoPlayEnabled ? "自动连播" : "单次播放"
        MPNowPlayingInfoCenter.default().nowPlayingInfo = info
    }

    private func refreshNowPlayingInfo(playbackRate explicitRate: Double? = nil) {
        var info = MPNowPlayingInfoCenter.default().nowPlayingInfo ?? [:]

        info[MPMediaItemPropertyTitle] = nowPlayingTitle

        let speedText = String(format: "%.2fx", playbackRate).replacingOccurrences(of: ".00", with: "x")
        info[MPMediaItemPropertyArtist] = isAutoPlayEnabled ? "自动连播 • \(speedText)" : "单次播放 • \(speedText)"
        info[MPMediaItemPropertyAlbumTitle] = "Speed \(speedText)"

        if let player = audioPlayer {
            info[MPNowPlayingInfoPropertyElapsedPlaybackTime] = player.currentTime
            info[MPMediaItemPropertyPlaybackDuration] = player.duration
            let rate: Double
            if let explicitRate = explicitRate {
                rate = explicitRate
            } else {
                rate = player.isPlaying ? Double(self.playbackRate) : 0.0
            }
            info[MPNowPlayingInfoPropertyPlaybackRate] = rate
        } else {
            info[MPNowPlayingInfoPropertyElapsedPlaybackTime] = 0
            info[MPMediaItemPropertyPlaybackDuration] = 0
            info[MPNowPlayingInfoPropertyPlaybackRate] = 0
        }

        MPNowPlayingInfoCenter.default().nowPlayingInfo = info
    }

    // MARK: - Notifications
    private func setupNotifications() {
        NotificationCenter.default.addObserver(self,
            selector: #selector(handleInterruption),
            name: AVAudioSession.interruptionNotification,
            object: nil)
    }

    @objc private func handleInterruption(notification: Notification) {
        guard let userInfo = notification.userInfo,
              let typeValue = userInfo[AVAudioSessionInterruptionTypeKey] as? UInt,
              let type = AVAudioSession.InterruptionType(rawValue: typeValue) else {
            return
        }

        switch type {
        case .began:
            if isPlaying { playPause() }
        case .ended:
            guard let optionsValue = userInfo[AVAudioSessionInterruptionOptionKey] as? UInt else { return }
            let options = AVAudioSession.InterruptionOptions(rawValue: optionsValue)
            if options.contains(.shouldResume) {
                if !isPlaying { playPause() }
            }
        @unknown default:
            break
        }
    }

    func setHasNext(_ hasNext: Bool) {
        MPRemoteCommandCenter.shared().nextTrackCommand.isEnabled = hasNext
    }

    // MARK: - Public Control Methods
    func startPlayback(text: String, title: String? = nil) {
        guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            handleError("文本内容为空，无法播放。")
            return
        }

        // 清理旧状态（轻量）
        speechSynthesizer.stopSpeaking(at: .immediate)
        audioPlayer?.stop()
        audioPlayer?.delegate = nil
        audioPlayer = nil
        stopDisplayLink()
        cleanupTemporaryFile()
        invalidateSynthesisWatchdog()

        // 更新标题
        self.nowPlayingTitle = title?.isEmpty == false ? title! : "正在播放的文章"

        // 重新绑定 delegate
        self.speechSynthesizer.delegate = self

        let processedText = preprocessText(text)

        isSynthesizing = true
        isPlaybackActive = true

        // 确保音频会话处于可用状态：先设置分类，再尝试激活（若已激活则此调用幂等）
        do {
            let session = AVAudioSession.sharedInstance()
            try session.setCategory(.playback, mode: .spokenAudio)
            try session.setActive(true, options: [])
        } catch {
            print("激活音频会话警告: \(error.localizedDescription)")
        }

        // 合成阶段刷新 NowPlaying
        refreshNowPlayingInfo(playbackRate: 0.0)

        let utterance = AVSpeechUtterance(string: processedText)
        utterance.voice = getBestVoice(for: text)
        utterance.rate = AVSpeechUtteranceDefaultSpeechRate
        utterance.pitchMultiplier = 1.0
        utterance.postUtteranceDelay = 0.3
        utterance.preUtteranceDelay = 0.2

        let tempDir = FileManager.default.temporaryDirectory
        let fileName = UUID().uuidString + ".caf"
        temporaryAudioFileURL = tempDir.appendingPathComponent(fileName)

        // 启动合成看门狗
        synthesisLastWriteAt = Date()
        startSynthesisWatchdog()

        // AVSpeechSynthesizer.write 的闭包是 Sendable 语境，切回主 actor 访问/更新状态
        speechSynthesizer.write(utterance) { [weak self] buffer in
            Task { @MainActor [weak self] in
                guard let self else { return }
                guard let pcmBuffer = buffer as? AVAudioPCMBuffer else {
                    self.handleError("无法获取 PCM 缓冲。")
                    return
                }

                // 喂狗
                self.synthesisLastWriteAt = Date()

                if pcmBuffer.frameLength == 0 {
                    self.synthesisToFileCompleted()
                } else {
                    if self.audioFile == nil {
                        do {
                            guard let url = self.temporaryAudioFileURL else {
                                self.handleError("无法创建音频文件：临时 URL 缺失。")
                                return
                            }
                            self.audioFile = try AVAudioFile(forWriting: url, settings: pcmBuffer.format.settings)
                        } catch {
                            self.handleError("根据音频数据格式创建文件失败: \(error)")
                            return
                        }
                    }
                    self.appendBufferToFile(buffer: pcmBuffer)
                }
            }
        }
    }

    private func getBestVoice(for text: String) -> AVSpeechSynthesisVoice? {
        let recognizer = NLLanguageRecognizer()
        recognizer.processString(text)
        guard let languageCode = recognizer.dominantLanguage?.rawValue else {
            return AVSpeechSynthesisVoice(language: Locale.current.language.languageCode?.identifier ?? "en-US")
        }

        let voices = AVSpeechSynthesisVoice.speechVoices()
        let matches = voices.filter { $0.language.starts(with: languageCode) }
        if let v = matches.first(where: { $0.quality == .premium }) { return v }
        if let v = matches.first(where: { $0.quality == .enhanced }) { return v }
        if let v = matches.first { return v }
        return AVSpeechSynthesisVoice(language: languageCode)
    }

    func playPause() {
        guard let player = audioPlayer else { return }
        if player.isPlaying {
            player.pause()
            isPlaying = false
            stopDisplayLink()
            refreshNowPlayingInfo(playbackRate: 0.0)
        } else {
            do {
                try setupAudioSession()
                player.play()
                applyPlaybackRate()
                isPlaying = true
                startDisplayLink()
                setupRemoteTransportControls()
                enableRemoteCommandsForActivePlayback()
                refreshNowPlayingInfo(playbackRate: 1.0)
            } catch {
                handleError("恢复播放时，重新激活音频会话失败: \(error)")
            }
        }
    }

    func stop() {
        // 彻底停止：用于用户显式停止或页面消失
        speechSynthesizer.stopSpeaking(at: .immediate)
        audioPlayer?.stop()

        isPlaying = false
        isPlaybackActive = false
        isSynthesizing = false

        progress = 0.0
        currentTimeString = "00:00"
        durationString = "00:00"

        MPNowPlayingInfoCenter.default().nowPlayingInfo = nil

        // 禁用并移除 Remote Commands
        let commandCenter = MPRemoteCommandCenter.shared()
        commandCenter.playCommand.isEnabled = false
        commandCenter.pauseCommand.isEnabled = false
        commandCenter.stopCommand.isEnabled = false
        teardownRemoteTransportControls()

        stopDisplayLink()
        cleanupTemporaryFile()
        deactivateAudioSession()
        invalidateSynthesisWatchdog()

        // 彻底释放播放器与合成器
        audioPlayer?.delegate = nil
        audioPlayer = nil
        speechSynthesizer.delegate = nil
    }

    // 自然结束时的收尾，不隐藏面板，不反激活会话
    private func finishNaturally() {
        audioPlayer?.stop()
        isPlaying = false
        isSynthesizing = false
        stopDisplayLink()

        if let player = audioPlayer {
            progress = 1.0
            currentTimeString = formatTime(player.duration)
            refreshNowPlayingInfo(playbackRate: 0.0)
            enableRemoteCommandsForActivePlayback()
        }

        onNextRequested?()
        onPlaybackFinished?()
    }

    func seek(to value: Double) {
        guard let player = audioPlayer else { return }
        let newTime = player.duration * value
        player.currentTime = newTime
        updateProgress()
    }

    // MARK: - Synthesis and File Handling
    private func appendBufferToFile(buffer: AVAudioPCMBuffer) {
        do {
            try self.audioFile?.write(from: buffer)
        } catch {
            handleError("写入音频文件失败: \(error)")
        }
    }

    private func synthesisToFileCompleted() {
        self.audioFile = nil
        guard let url = self.temporaryAudioFileURL else {
            handleError("合成结束，但找不到临时文件URL。")
            return
        }
        invalidateSynthesisWatchdog()

        self.isSynthesizing = false
        self.setupAndPlayAudioPlayer(from: url)
    }

    private func cleanupTemporaryFile() {
        audioFile = nil
        if let url = temporaryAudioFileURL {
            try? FileManager.default.removeItem(at: url)
            temporaryAudioFileURL = nil
        }
    }

    // MARK: - Watchdog for synthesis (MainActor)
    private func startSynthesisWatchdog(timeout: TimeInterval = 15) {
        invalidateSynthesisWatchdog()
        synthesisWatchdogTimer = Timer.scheduledTimer(withTimeInterval: 5, repeats: true) { [weak self] _ in
            Task { @MainActor [weak self] in
                guard let self else { return }
                guard self.isSynthesizing else { self.invalidateSynthesisWatchdog(); return }
                guard let last = self.synthesisLastWriteAt else { return }
                let elapsed = Date().timeIntervalSince(last)
                if elapsed > timeout {
                    self.handleError("语音合成阶段长时间无响应（可能在后台被系统限制）。已中止此次合成。")
                }
            }
        }
        RunLoop.main.add(synthesisWatchdogTimer!, forMode: .common)
    }

    private func invalidateSynthesisWatchdog() {
        synthesisWatchdogTimer?.invalidate()
        synthesisWatchdogTimer = nil
        synthesisLastWriteAt = nil
    }

    // MARK: - AVAudioPlayer Setup and Delegate
    private func setupAndPlayAudioPlayer(from url: URL) {
        do {
            try setupAudioSession()
            audioPlayer = try AVAudioPlayer(contentsOf: url)
            audioPlayer?.delegate = self
            audioPlayer?.enableRate = true
            audioPlayer?.prepareToPlay()
            durationString = formatTime(audioPlayer?.duration ?? 0)
            applyPlaybackRate()
            audioPlayer?.play()
            isPlaying = true
            startDisplayLink()

            setupRemoteTransportControls()
            enableRemoteCommandsForActivePlayback()
            refreshNowPlayingInfo(playbackRate: 1.0)
        } catch {
            handleError("创建或播放 AVAudioPlayer 失败: \(error)")
        }
    }

    private func enableRemoteCommandsForActivePlayback() {
        let commandCenter = MPRemoteCommandCenter.shared()
        commandCenter.playCommand.isEnabled = true
        commandCenter.pauseCommand.isEnabled = true
        commandCenter.stopCommand.isEnabled = true
        commandCenter.nextTrackCommand.isEnabled = true
    }

    func audioPlayerDidFinishPlaying(_ player: AVAudioPlayer, successfully flag: Bool) {
        finishNaturally()
    }

    // MARK: - Progress Update (CADisplayLink)
    private func startDisplayLink() {
        stopDisplayLink()
        displayLink = CADisplayLink(target: self, selector: #selector(updateProgress))
        displayLink?.add(to: .current, forMode: .common)
    }

    private func stopDisplayLink() {
        displayLink?.invalidate()
        displayLink = nil
    }

    @objc private func updateProgress() {
        guard let player = audioPlayer, player.duration > 0 else { return }
        progress = player.currentTime / player.duration
        currentTimeString = formatTime(player.currentTime)
        refreshNowPlayingInfo()
    }

    // MARK: - Audio Session and Error Handling
    private func setupAudioSession() throws {
        let session = AVAudioSession.sharedInstance()
        try session.setCategory(.playback, mode: .spokenAudio)
        try session.setActive(true)
    }

    private func deactivateAudioSession() {
        do {
            try AVAudioSession.sharedInstance().setActive(false, options: .notifyOthersOnDeactivation)
        } catch {
            print("释放音频会话失败: \(error)")
        }
    }

    private func handleError(_ message: String) {
        print("错误: \(message)")
        self.stop()
    }

    private func formatTime(_ time: TimeInterval) -> String {
        let minutes = Int(time) / 60
        let seconds = Int(time) % 60
        return String(format: "%02d:%02d", minutes, seconds)
    }

    // --- 新增函数 ---
    // 移除数字中的千位分隔符，例如 "1,500" -> "1500"
    private func removeCommasFromNumbers(_ text: String) -> String {
        // 正则表达式：查找一个数字，后跟一个逗号，再后跟三位数字
        // (\d) 是捕获组1，(\d{3}) 是捕获组2
        // 这个模式会匹配 "1,500" 中的 "1,500"，"1,234,567" 中的 "1,234" 和 "4,567"
        let pattern = #"(\d),(\d{3})"#
        guard let regex = try? NSRegularExpression(pattern: pattern) else {
            return text
        }

        var result = text
        // 循环替换，直到找不到更多匹配项为止
        // 这对于处理多个分隔符（如 "1,234,567"）是必要的
        while regex.firstMatch(in: result, range: NSRange(result.startIndex..., in: result)) != nil {
            result = regex.stringByReplacingMatches(
                in: result,
                range: NSRange(result.startIndex..., in: result),
                withTemplate: "$1$2" // 将 "数字,三位数字" 替换为 "数字三位数字"
            )
        }
        return result
    }

    // 将阿拉伯数字年份转为逐位中文数字：1944 -> 一九四四
    private func formatYearToPinyinDigits(_ year: String) -> String {
        let map: [Character: String] = [
            "0": "零", "1": "一", "2": "二", "3": "三", "4": "四",
            "5": "五", "6": "六", "7": "七", "8": "八", "9": "九"
        ]
        return year.compactMap { map[$0] }.joined()
    }

    // 将“1944-1947年”替换为“一九四四到1947年”
    private func replaceYearRangesForChinese(_ text: String) -> String {
        // 匹配 4位-4位 后紧跟 年（可有空格）
        // 捕获组：1=左年份 2=右年份
        let pattern = #"(?<!\d)(\d{4})\s*-\s*(\d{4})(?=\s*年)"#
        guard let regex = try? NSRegularExpression(pattern: pattern, options: []) else { return text }
        let nsRange = NSRange(text.startIndex..<text.endIndex, in: text)
        var result = text
        var offset = 0

        regex.enumerateMatches(in: text, options: [], range: nsRange) { match, _, _ in
            guard let match = match, match.numberOfRanges >= 3 else { return }
            if let r1 = Range(match.range(at: 1), in: text),
               let r2 = Range(match.range(at: 2), in: text) {
                let leftYear = String(text[r1])
                let rightYear = String(text[r2])
                let leftDigits = formatYearToPinyinDigits(leftYear)
                // 直接以 match.range 替换，不创建未使用变量
                let replacement = "\(leftDigits)到\(rightYear)"
                let start = result.index(result.startIndex, offsetBy: match.range.location + offset)
                let end = result.index(start, offsetBy: match.range.length)
                result.replaceSubrange(start..<end, with: replacement)
                offset += replacement.count - match.range.length
            }
        }
        return result
    }

    // 将所有以 "20" 开头的四位数字（如 2024）转为逐位朗读
    private func replaceModernYearsForChinese(_ text: String) -> String {
        // 正则表达式：\b 匹配单词边界，确保匹配的是独立的数字
        // (20\d{2}) 捕获以 "20" 开头，后跟两位数字的四位数
        let pattern = #"\b(20\d{2})\b"#
        guard let regex = try? NSRegularExpression(pattern: pattern, options: []) else { return text }

        var result = text
        // 从后往前替换，避免 range 变化导致错误
        let matches = regex.matches(in: result, options: [], range: NSRange(result.startIndex..<result.endIndex, in: result)).reversed()

        for match in matches {
            guard let range = Range(match.range, in: result) else { continue }
            let yearString = String(result[range])
            let pinyinDigits = formatYearToPinyinDigits(yearString)
            result.replaceSubrange(range, with: pinyinDigits)
        }
        return result
    }

    private func preprocessText(_ text: String) -> String {
        // --- 修改点 ---
        // 第一步：移除数字中的千位分隔符，解决 "1,500" 读成 "一，五百" 的问题
        let textWithoutCommas = removeCommasFromNumbers(text)

        // 后续处理都基于移除了逗号的文本
        let processedSpecialTerms = processEnglishText(textWithoutCommas)

        // 特化：处理“1944-1947年”→“一九四四到1947年”
        let withChineseYearRange = replaceYearRangesForChinese(processedSpecialTerms)

        // 新增：将所有以 "20" 开头的四位数字（如 2024）转为逐位朗读
        let withModernYears = replaceModernYearsForChinese(withChineseYearRange)

        // 中英夹杂在汉字和英文之间加逗号，便于中文 TTS 断句
        let pattern = "([\\u4e00-\\u9fa5])(\\s*[a-zA-Z]+\\s*)([\\u4e00-\\u9fa5])"
        let regex = try? NSRegularExpression(pattern: pattern, options: [])
        let range = NSRange(withModernYears.startIndex..<withModernYears.endIndex, in: withModernYears)
        let modifiedText = regex?.stringByReplacingMatches(
            in: withModernYears,
            options: [],
            range: range,
            withTemplate: "$1, $2, $3"
        ) ?? withModernYears
        return modifiedText
    }

    private func processEnglishText(_ text: String) -> String {
        var processed = text

        processed = processed
            .replacingOccurrences(of: "“", with: "")
            .replacingOccurrences(of: "”", with: "")
            .replacingOccurrences(of: "\"", with: "")

        // 连字符数字范围：
        // - 若为 4位-4位（可能是年份范围），保留为“到”但不做通用替换，这部分交给 replaceYearRangesForChinese 处理中文场景；
        // - 一般情形的数字范围（至少左边有数字，右边可为空或数字），替换为“到”
        // 先避免对 4位-4位 直接替换
        // 再处理其它范围（如 3-5, 10- 等）
        let generalRangePattern = #"(?<!\d)(\d+)\s*-\s*(\d*)(?!\d)"#

        if let generalRegex = try? NSRegularExpression(pattern: generalRangePattern, options: []) {
            let nsRange = NSRange(processed.startIndex..<processed.endIndex, in: processed)
            // 用一个回调式替换，跳过 4位-4位 的匹配
            var result = processed
            var delta = 0
            generalRegex.enumerateMatches(in: processed, options: [], range: nsRange) { match, _, _ in
                guard let match = match else { return }
                // 检查是否是 4位-4位；如果是，跳过，交由中文年份函数处理
                if let leftRange = Range(match.range(at: 1), in: processed) {
                    let left = processed[leftRange]
                    var isFourFour = false
                    if match.numberOfRanges >= 3, let rightRange = Range(match.range(at: 2), in: processed) {
                        let right = processed[rightRange]
                        if left.count == 4, right.count == 4 {
                            isFourFour = true
                        }
                    }
                    if isFourFour {
                        return
                    }
                    // 不是 4位-4位：正常替换为 “左到右”
                    let leftStr = String(left)
                    let rightStr: String
                    if match.numberOfRanges >= 3, let rRange = Range(match.range(at: 2), in: processed) {
                        rightStr = String(processed[rRange])
                    } else {
                        rightStr = ""
                    }
                    let replacement = "\(leftStr)到\(rightStr)"
                    let start = result.index(result.startIndex, offsetBy: match.range.location + delta)
                    let end = result.index(start, offsetBy: match.range.length)
                    result.replaceSubrange(start..<end, with: replacement)
                    delta += replacement.count - match.range.length
                }
            }
            processed = result
        }

        let replacements = [
            "API": "A.P.I",
            "URL": "U.R.L",
            "HTTP": "H.T.T.P",
            "JSON": "Jason",
            "HTML": "H.T.M.L",
            "CSS": "C.S.S",
            "JS": "J.S",
            "AI": "A.I",
            "OpenAI": "Open.A.I",
            "SDK": "S.D.K",
            "iOS": "i O S",
            "PSA": "P.S.A",
            "Jeep": "吉普",
            "EV": "电动车",
            "iPhone": "i Phone",
            "iPad": "i Pad",
            "macOS": "mac O S",
            "UI": "U.I",
            "GUI": "G.U.I",
            "CLI": "C.L.I",
            "SQL": "S.Q.L",
            "NASA": "NASA",
            "JPEG": "J.PEG",
            "PNG": "P.N.G",
            "PDF": "P.D.F",
            "ID": "I.D",
            "vs": "对阵",
            "etc": "等等",
            "i.e": "也就是说",
            "e.g": "举例来说",
            "&": "和",
            "+": "加",
            "=": "等于",
            "@": "at",
            "~": "到",
            "/": "每",
            "DJI": "大疆",
            "Insta360": "Insta三六零",
            "Airbnb": "Air.B.N.B"
        ]

        for (key, value) in replacements {
            processed = processed.replacingOccurrences(of: key, with: value)
        }

        return processed
    }
}

struct AudioPlayerView: View {
    @ObservedObject var playerManager: AudioPlayerManager
    @State private var sliderValue: Double = 0.0
    @State private var isEditingSlider = false
    private let rates: [Float] = [1.0, 1.25, 1.5, 1.75, 2.0]
    var playNextAndStart: (() -> Void)?
    var toggleCollapse: (() -> Void)?

    private var playPauseIconName: String {
        playerManager.isPlaying ? "pause.circle.fill" : "play.circle.fill"
    }

    private func nextRate(from current: Float) -> Float {
        if let idx = rates.firstIndex(of: current) {
            let next = (idx + 1) % rates.count
            return rates[next]
        }
        return 1.0
    }

    private var rateLabel: String {
        String(format: "%.2fx", playerManager.playbackRate)
            .replacingOccurrences(of: ".00", with: "")
    }

    var body: some View {
        VStack(spacing: 12) { // 原 16 -> 12，整体更紧凑
            HStack(spacing: 10) { // 原 12 -> 10
                Text(playerManager.currentTimeString)
                    .font(.system(size: 12, weight: .medium, design: .monospaced))

                Slider(value: $sliderValue, in: 0...1, onEditingChanged: { editing in
                    self.isEditingSlider = editing
                    if !editing {
                        playerManager.seek(to: sliderValue)
                    }
                })
                .tint(.white)

                Text(playerManager.durationString)
                    .font(.system(size: 12, weight: .medium, design: .monospaced))
            }

            if playerManager.isSynthesizing {
                HStack(spacing: 10) {
                    ProgressView()
                    Text("正在合成语音，请稍候...")
                        .font(.subheadline)
                        .foregroundColor(.secondary)
                }
            } else {
                ZStack {
                    Button(action: { playerManager.playPause() }) {
                        Image(systemName: playPauseIconName)
                            .font(.system(size: 52, weight: .regular)) // 原 54 -> 52
                    }
                    .disabled(playerManager.isSynthesizing || !playerManager.isPlaybackActive)
                    .opacity(playerManager.isSynthesizing || !playerManager.isPlaybackActive ? 0.6 : 1.0)
                }
                .frame(height: 66) // 原 70 -> 66

                HStack {
                    HStack {
                        Button(action: {
                            playerManager.isAutoPlayEnabled.toggle()
                        }) {
                            Image(systemName: playerManager.isAutoPlayEnabled ? "repeat.circle.fill" : "repeat.1.circle.fill")
                                .font(.system(size: 35, weight: .semibold))
                                .symbolRenderingMode(.hierarchical)
                                .foregroundColor(playerManager.isAutoPlayEnabled ? .white : .white.opacity(0.45))
                        }
                        .accessibilityLabel(playerManager.isAutoPlayEnabled ? "自动连播" : "单次播放")
                        Spacer(minLength: 0)
                    }
                    .frame(maxWidth: .infinity)

                    HStack {
                        Spacer(minLength: 0)
                        Button(action: {
                            let newRate = nextRate(from: playerManager.playbackRate)
                            playerManager.playbackRate = newRate
                        }) {
                            Text(rateLabel)
                                .font(.system(size: 18, weight: .semibold, design: .rounded)) // 字号略微缩小
                                .foregroundColor(.white)
                                .padding(.vertical, 7) // 原 6 -> 5
                                .padding(.horizontal, 12) // 原 10 -> 9
                                .background(Color.white.opacity(0.18))
                                .clipShape(Capsule())
                        }
                        .accessibilityLabel("播放速度 \(rateLabel)")
                        Spacer(minLength: 0)
                    }
                    .frame(maxWidth: .infinity)

                    HStack {
                        Spacer(minLength: 0)
                        Button(action: {
                            playNextAndStart?()
                        }) {
                            Image(systemName: "forward.end.fill")
                                .font(.system(size: 21, weight: .semibold)) // 原 22 -> 21
                                .symbolRenderingMode(.hierarchical)
                        }
                        .disabled(!playerManager.isPlaybackActive || playerManager.isSynthesizing)
                        .opacity((!playerManager.isPlaybackActive || playerManager.isSynthesizing) ? 0.6 : 1.0)
                    }
                    .frame(maxWidth: .infinity)
                }
            }
        }
        .foregroundColor(.white)
        // 顶部和底部 padding 调整，让整体更贴近底部
        .padding(EdgeInsets(top: 28, leading: 16, bottom: 10, trailing: 16)) // 原 top:35, leading:20, bottom:15, trailing:20
        .background(.black.opacity(0.8))
        .cornerRadius(18) // 原 20 -> 18 更贴边
        .overlay(
            Button(action: { toggleCollapse?() }) {
                Image(systemName: "minus")
                    .font(.system(size: 20, weight: .bold)) // 原 22 -> 20
                    .foregroundColor(.white)
                    .padding(6)
                    .clipShape(Circle())
                    .accessibilityLabel("最小化播放器")
            }
            .padding(6), // 原 8 -> 6
            alignment: .topLeading
        )
        .overlay(
            Button(action: { playerManager.stop() }) {
                Image(systemName: "xmark")
                    .font(.system(size: 11, weight: .bold)) // 原 12 -> 11
                    .foregroundColor(.black)
                    .padding(6)
                    .background(Color.white.opacity(0.8))
                    .clipShape(Circle())
            }
            .padding(6), // 原 8 -> 6
            alignment: .topTrailing
        )
        // 让卡片更靠近屏幕底部：原 offset(y: -50) -> -18
        .offset(y: -18)
        // 横向外边距略小，减少占据正文面积
        .padding(.horizontal, 12) // 原 .padding(.horizontal)
        .onChange(of: playerManager.progress) { _, newValue in
            if !isEditingSlider { self.sliderValue = newValue }
        }
        // 贴近屏幕底部时保证不压住 Home 指示条
        .safeAreaInset(edge: .bottom) {
            Color.clear.frame(height: 0)
        }
    }
}

