class NewsViewModel: ObservableObject {
    @Published var sources: [NewsSource] = []

    private let subscriptionManager = SubscriptionManager.shared

    private let readKey = "readTopics"
    private var readRecords: [String: Date] = [:]

    var badgeUpdater: ((Int) -> Void)?
    private var cancellables = Set<AnyCancellable>()

    private var documentsDirectory: URL {
        FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
    }

    var allArticlesSortedForDisplay: [(article: Article, sourceName: String)] {
        let flatList = self.sources.flatMap { source in
            source.articles.map { (article: $0, sourceName: source.name) }
        }

        return flatList.sorted { item1, item2 in
            if item1.article.timestamp != item2.article.timestamp {
                return item1.article.timestamp < item2.article.timestamp
            }
            return item1.article.topic < item2.article.topic
        }
    }

    init() {
        loadReadRecords()
        $sources
            .map { sources in
                sources.flatMap { $0.articles }.filter { !$0.isRead }.count
            }
            .removeDuplicates()
            .sink { [weak self] unreadCount in
                print("检测到未读数变化，准备更新角标: \(unreadCount)")
                self?.badgeUpdater?(unreadCount)
            }
            .store(in: &cancellables)
    }

    private func loadReadRecords() {
        self.readRecords = UserDefaults.standard.dictionary(forKey: readKey) as? [String: Date] ?? [:]
    }

    private func saveReadRecords() {
        UserDefaults.standard.set(self.readRecords, forKey: readKey)
    }

    func loadNews() {
        let subscribed = subscriptionManager.subscribedSources
        if subscribed.isEmpty {
            print("没有订阅任何新闻源。列表将为空。")
            DispatchQueue.main.async {
                self.sources = []
            }
            return
        }
        print("开始加载新闻，订阅源为: \(subscribed)")

        guard let allFileURLs = try? FileManager.default.contentsOfDirectory(at: documentsDirectory, includingPropertiesForKeys: nil) else {
            print("无法读取 Documents 目录。")
            return
        }

        let newsJSONURLs = allFileURLs.filter {
            $0.lastPathComponent.starts(with: "onews_") && $0.pathExtension == "json"
        }

        guard !newsJSONURLs.isEmpty else {
            print("错误：在 Documents 目录中没有找到任何 'onews_*.json' 文件。请先同步资源。")
            return
        }

        var allArticlesBySource = [String: [Article]]()
        let decoder = JSONDecoder()

        for url in newsJSONURLs {
            let fileName = url.deletingPathExtension().lastPathComponent
            guard let timestamp = fileName.components(separatedBy: "_").last, !timestamp.isEmpty else {
                continue
            }

            guard let data = try? Data(contentsOf: url) else {
                continue
            }

            guard let decoded = try? decoder.decode([String: [Article]].self, from: data) else {
                continue
            }

            for (sourceName, articles) in decoded {
                guard subscribed.contains(sourceName) else { continue }

                let articlesWithTimestamp = articles.map { article -> Article in
                    var mutableArticle = article
                    mutableArticle.timestamp = timestamp
                    return mutableArticle
                }
                allArticlesBySource[sourceName, default: []].append(contentsOf: articlesWithTimestamp)
            }
        }

        var tempSources = allArticlesBySource.map { sourceName, articles -> NewsSource in
            let sortedArticles = articles.sorted {
                if $0.timestamp != $1.timestamp {
                    return $0.timestamp < $1.timestamp
                }
                return $0.topic < $1.topic
            }
            return NewsSource(name: sourceName, articles: sortedArticles)
        }
        .sorted { $0.name < $1.name }

        for i in tempSources.indices {
            for j in tempSources[i].articles.indices {
                let article = tempSources[i].articles[j]
                if readRecords.keys.contains(article.topic) {
                    tempSources[i].articles[j].isRead = true
                }
            }
        }

        DispatchQueue.main.async {
            self.sources = tempSources
            print("新闻数据加载/刷新完成！共 \(self.sources.count) 个已订阅来源。")
        }
    }

    func markAsRead(articleID: UUID) {
        DispatchQueue.main.async {
            for i in self.sources.indices {
                if let j = self.sources[i].articles.firstIndex(where: { $0.id == articleID }) {
                    if !self.sources[i].articles[j].isRead {
                        self.sources[i].articles[j].isRead = true
                        let topic = self.sources[i].articles[j].topic
                        self.readRecords[topic] = Date()
                        self.saveReadRecords()
                    }
                    return
                }
            }
        }
    }

    func markAsUnread(articleID: UUID) {
        DispatchQueue.main.async {
            for i in self.sources.indices {
                if let j = self.sources[i].articles.firstIndex(where: { $0.id == articleID }) {
                    if self.sources[i].articles[j].isRead {
                        self.sources[i].articles[j].isRead = false
                        let topic = self.sources[i].articles[j].topic
                        self.readRecords.removeValue(forKey: topic)
                        self.saveReadRecords()
                    }
                    return
                }
            }
        }
    }

    func markAllAboveAsRead(articleID: UUID, inVisibleList visibleArticles: [Article]) {
        DispatchQueue.main.async {
            guard let pivotIndex = visibleArticles.firstIndex(where: { $0.id == articleID }) else { return }
            guard pivotIndex > 0 else { return }
            let articlesAbove = visibleArticles[0..<pivotIndex]
            for article in articlesAbove where !article.isRead {
                self.markAsRead(articleID: article.id)
            }
        }
    }

    func markAllBelowAsRead(articleID: UUID, inVisibleList visibleArticles: [Article]) {
        DispatchQueue.main.async {
            guard let pivotIndex = visibleArticles.firstIndex(where: { $0.id == articleID }) else { return }
            guard pivotIndex < visibleArticles.count - 1 else { return }
            let articlesBelow = visibleArticles[(pivotIndex + 1)...]
            for article in articlesBelow where !article.isRead {
                self.markAsRead(articleID: article.id)
            }
        }
    }

    private func getArticleList(for sourceName: String?) -> [Article] {
        if let name = sourceName, let source = self.sources.first(where: { $0.name == name }) {
            return source.articles
        } else {
            return self.allArticlesSortedForDisplay.map { $0.article }
        }
    }

    var totalUnreadCount: Int {
        sources.flatMap { $0.articles }.filter { !$0.isRead }.count
    }

    func findNextUnread(after id: UUID, inSource sourceName: String?) -> (article: Article, sourceName: String)? {
        let list: [(article: Article, sourceName: String)]

        if let name = sourceName, let source = self.sources.first(where: { $0.name == name }) {
            list = source.articles
                .filter { !$0.isRead }
                .map { (article: $0, sourceName: name) }
        } else {
            list = self.allArticlesSortedForDisplay.filter { !$0.article.isRead }
        }

        guard !list.isEmpty else { return nil }

        guard let currentIndex = list.firstIndex(where: { $0.article.id == id }) else {
            return list.first
        }

        let nextIndex = (currentIndex + 1) % list.count
        return list[nextIndex]
    }

    func findPreviousUnread(before id: UUID, inSource sourceName: String?) -> (article: Article, sourceName: String)? {
        let list: [(article: Article, sourceName: String)]

        if let name = sourceName, let source = sources.first(where: { $0.name == name }) {
            list = source.articles
                .filter { !$0.isRead }
                .map { (article: $0, sourceName: name) }
        } else {
            list = self.allArticlesSortedForDisplay.filter { !$0.article.isRead }
        }

        guard !list.isEmpty else { return nil }

        if let currentIndex = list.firstIndex(where: { $0.article.id == id }), currentIndex > 0 {
            return list[currentIndex - 1]
        }

        return nil
    }
}


struct NewsSource: Identifiable {
    let id = UUID()
    let name: String
    var articles: [Article]

    var unreadCount: Int {
        articles.filter { !$0.isRead }.count
    }
}

struct Article: Identifiable, Codable {
    var id = UUID()
    let topic: String
    let article: String
    let images: [String]

    var isRead: Bool = false
    var timestamp: String = ""

    enum CodingKeys: String, CodingKey {
        case topic, article, images
    }
}

@MainActor
class AppBadgeManager {
    func requestAuthorization() {
        UNUserNotificationCenter.current().requestAuthorization(options: [.badge]) { granted, error in
            if granted {
                print("用户已授予角标权限。")
            } else {
                print("用户未授予角标权限。")
            }
        }
    }

    func updateBadge(count: Int) {
        UNUserNotificationCenter.current().setBadgeCount(count) { error in
            if let error = error {
                print("更新角标失败: \(error.localizedDescription)")
            } else {
                print("应用角标已更新为: \(count)")
            }
        }
    }
}

import SwiftUI

struct SourceListView: View {
    @StateObject private var viewModel = NewsViewModel()
    @StateObject private var resourceManager = ResourceManager()
    private let badgeManager = AppBadgeManager()

    @State private var showErrorAlert = false
    @State private var errorMessage = ""

    // ==================== 核心修改: 添加 Sheet 状态 ====================
    @State private var showAddSourceSheet = false
    // ===============================================================

    @Environment(\.scenePhase) private var scenePhase

    // 这个计算属性现在依然有效，因为它操作的是 viewModel.sources，
    // 而 viewModel.sources 已经被过滤为只包含订阅的源了。
    private var sourcesWithUnread: [NewsSource] {
        viewModel.sources.filter { $0.unreadCount > 0 }
    }

    var body: some View {
        ZStack {
            NavigationView {
                // ==================== 核心修改: 空状态处理 ====================
                Group {
                    if viewModel.sources.isEmpty && !resourceManager.isSyncing {
                        VStack(spacing: 20) {
                            Text("您还没有订阅任何新闻源")
                                .font(.headline)
                                .foregroundColor(.secondary)
                            Button(action: { showAddSourceSheet = true }) {
                                Label("点击这里添加", systemImage: "plus.circle.fill")
                                    .font(.title2)
                            }
                            .buttonStyle(.bordered)
                        }
                    } else {
                        List {
                            // "ALL" 链接
                            ZStack {
                                HStack {
                                    Text("ALL")
                                        .font(.system(size: 28, weight: .bold))
                                        .foregroundColor(.primary)
                                    Spacer()
                                    Text("\(viewModel.totalUnreadCount)")
                                        .font(.system(size: 28, weight: .bold))
                                        .foregroundColor(.gray)
                                }
                                .padding()
                                NavigationLink(destination: AllArticlesListView(viewModel: viewModel)) {
                                    EmptyView()
                                }.opacity(0)
                            }
                            .listRowSeparator(.hidden)

                            // 订阅源列表
                            ForEach(sourcesWithUnread) { source in
                                ZStack {
                                    HStack {
                                        Text(source.name)
                                            .fontWeight(.semibold)
                                        Spacer()
                                        Text("\(source.unreadCount)")
                                            .foregroundColor(.gray)
                                    }
                                    .padding(.vertical, 8)

                                    NavigationLink(destination: ArticleListView(source: source, viewModel: viewModel)) {
                                        EmptyView()
                                    }.opacity(0)
                                }
                                .listRowSeparator(.hidden)
                            }
                        }
                        .listStyle(.plain)
                    }
                }
                // ===============================================================
                .navigationBarTitleDisplayMode(.inline)
                .toolbar {
                    // ==================== 移除“登出”按钮后，右侧保留：添加源、刷新 ====================
                    ToolbarItem(placement: .navigationBarTrailing) {
                        Button(action: {
                            showAddSourceSheet = true
                        }) {
                            Image(systemName: "plus")
                        }
                    }

                    ToolbarItem(placement: .navigationBarTrailing) {
                        Button(action: {
                            Task {
                                await syncResources()
                            }
                        }) {
                            Image(systemName: "arrow.clockwise")
                        }
                        .disabled(resourceManager.isSyncing)
                    }
                }
            }
            .accentColor(.gray)
            .preferredColorScheme(.dark)
            .onAppear {
                viewModel.badgeUpdater = badgeManager.updateBadge
                badgeManager.requestAuthorization()

                viewModel.loadNews()
                Task {
                    await syncResources()
                }
            }
            .onChange(of: scenePhase) { oldPhase, newPhase in
                if oldPhase == .active && (newPhase == .inactive || newPhase == .background) {
                    badgeManager.updateBadge(count: viewModel.totalUnreadCount)
                    print("应用从前台切换到后台，强制更新角标为: \(viewModel.totalUnreadCount)")
                }
            }
            // ==================== 核心修改: 弹出添加源页面 ====================
            .sheet(isPresented: $showAddSourceSheet, onDismiss: {
                // 当 sheet 关闭时，重新加载新闻以反映订阅变化
                print("AddSourceView 已关闭，重新加载新闻...")
                viewModel.loadNews()
            }) {
                // 将 AddSourceView 包装在 NavigationView 中，使其拥有自己的导航栏
                NavigationView {
                    AddSourceView(isFirstTimeSetup: false)
                }
                .preferredColorScheme(.dark)
            }
            // ===============================================================

            // 加载/进度覆盖层 (无变化)
            if resourceManager.isSyncing {
                VStack(spacing: 15) {
                    if resourceManager.isDownloading {
                        Text(resourceManager.syncMessage)
                            .font(.headline)
                            .foregroundColor(.white)

                        ProgressView(value: resourceManager.downloadProgress)
                            .progressViewStyle(LinearProgressViewStyle(tint: .white))
                            .padding(.horizontal, 50)

                        Text(resourceManager.progressText)
                            .font(.caption)
                            .foregroundColor(.secondary)

                    } else {
                        ProgressView()
                            .progressViewStyle(CircularProgressViewStyle(tint: .white))
                            .scaleEffect(1.5)

                        Text(resourceManager.syncMessage)
                            .padding(.top, 10)
                            .foregroundColor(.secondary)
                    }
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .background(Color.black.opacity(0.6))
                .edgesIgnoringSafeArea(.all)
                .contentShape(Rectangle())
            }
        }
        .alert("", isPresented: $showErrorAlert, actions: {
            Button("好的", role: .cancel) { }
        }, message: {
            Text(errorMessage)
        })
    }

    // syncResources 函数 (无变化)
    private func syncResources() async {
        do {
            try await resourceManager.checkAndDownloadUpdates()
            viewModel.loadNews()
        } catch {
            switch error {
            case is DecodingError:
                print("同步失败 (服务器返回数据格式错误，已静默处理): \(error)")

            case let urlError as URLError where
                urlError.code == .cannotConnectToHost ||
                urlError.code == .timedOut:

                print("同步失败 (无法连接或超时，已静默处理): \(error.localizedDescription)")

            default:
                print("同步失败 (客户端或其他问题): \(error)")
                self.errorMessage = "网络异常\n\nPlease click the refresh button ↻ in the upper right corner to try again"
                self.showErrorAlert = true
            }
        }
    }
}

import SwiftUI
import Foundation

// 文件名: AddSourceView.swift
// 职责: 提供一个可搜索的列表，让用户能够添加或移除新闻源订阅。
// 文件名: SubscriptionManager.swift
// 职责: 集中管理用户的新闻源订阅列表，使用 UserDefaults 进行持久化存储。

class SubscriptionManager: ObservableObject {
    static let shared = SubscriptionManager() // 使用单例模式，方便全局访问

    private let subscribedSourcesKey = "subscribedNewsSources"

    @Published var subscribedSources: Set<String> {
        didSet {
            // 当订阅列表变化时，自动保存到 UserDefaults
            saveSubscribedSources()
            print("订阅列表已更新并保存: \(subscribedSources)")
        }
    }

    private init() {
        // 初始化时从 UserDefaults 加载已保存的订阅列表
        let savedSources = UserDefaults.standard.stringArray(forKey: subscribedSourcesKey) ?? []
        self.subscribedSources = Set(savedSources)
        print("SubscriptionManager 初始化，加载的订阅源: \(self.subscribedSources)")
    }

    /// 将当前的订阅列表（Set）转换为数组并保存到 UserDefaults
    private func saveSubscribedSources() {
        UserDefaults.standard.set(Array(self.subscribedSources), forKey: subscribedSourcesKey)
    }

    /// 检查某个新闻源是否已被订阅
    func isSubscribed(to sourceName: String) -> Bool {
        return subscribedSources.contains(sourceName)
    }

    /// 添加一个新闻源到订阅列表
    func addSubscription(_ sourceName: String) {
        subscribedSources.insert(sourceName)
    }

    /// 从订阅列表移除一个新闻源
    func removeSubscription(_ sourceName: String) {
        subscribedSources.remove(sourceName)
    }

    /// 切换某个新闻源的订阅状态
    func toggleSubscription(for sourceName: String) {
        if isSubscribed(to: sourceName) {
            removeSubscription(sourceName)
        } else {
            addSubscription(sourceName)
        }
    }
}

struct AddSourceView: View {
    // 状态
    @State private var allAvailableSources: [String] = []
    @State private var searchText = ""
    @State private var isLoading = true
    @State private var errorMessage: String?

    // 新增：控制是否显示搜索框
    @State private var showSearchBar = false

    // 订阅管理器
    @ObservedObject private var subscriptionManager = SubscriptionManager.shared

    // 用于判断显示逻辑（首次设置 vs. 后续添加）
    let isFirstTimeSetup: Bool
    var onComplete: (() -> Void)? // 仅在首次设置时使用

    @Environment(\.presentationMode) var presentationMode

    // 计算属性，用于显示过滤后的列表
    private var filteredSources: [String] {
        let base = allAvailableSources
        if showSearchBar && !searchText.isEmpty {
            return base.filter { $0.lowercased().contains(searchText.lowercased()) }
        } else {
            return base
        }
    }

    var body: some View {
        ZStack {
            // 背景图与遮罩，和 WelcomeView 风格一致
            Image("welcome_background")
                .resizable()
                .aspectRatio(contentMode: .fill)
                .ignoresSafeArea()
                .overlay(Color.black.opacity(0.4).ignoresSafeArea())

            VStack {
                if isLoading {
                    ProgressView("正在加载新闻源...")
                        .frame(maxHeight: .infinity)
                        .tint(.white)
                        .foregroundColor(.white)
                } else if let error = errorMessage {
                    VStack(spacing: 20) {
                        Image(systemName: "exclamationmark.triangle.fill")
                            .font(.largeTitle)
                            .foregroundColor(.red)
                        Text(error)
                            .multilineTextAlignment(.center)
                            .padding()
                            .foregroundColor(.white)
                    }
                    .frame(maxHeight: .infinity)
                } else {
                    // 为了去掉分隔线，使用 .listRowSeparator(.hidden)
                    // 同时让列表背景透明，文本颜色适配深色背景
                    let list = List(filteredSources, id: \.self) { sourceName in
                        HStack {
                            Text(sourceName)
                                .fontWeight(.medium)
                                .foregroundColor(.white)

                            Spacer()

                            if subscriptionManager.isSubscribed(to: sourceName) {
                                Text("已添加")
                                    .font(.caption)
                                    .foregroundColor(.white.opacity(0.8))
                                    .padding(.trailing, 8)

                                Button(action: {
                                    subscriptionManager.removeSubscription(sourceName)
                                }) {
                                    Image(systemName: "minus.circle.fill")
                                        .foregroundColor(.red)
                                        .font(.title2)
                                }
                                .buttonStyle(BorderlessButtonStyle())

                            } else {
                                Button(action: {
                                    subscriptionManager.addSubscription(sourceName)
                                }) {
                                    Image(systemName: "plus.circle.fill")
                                        .foregroundColor(.blue)
                                        .font(.title2)
                                }
                                .buttonStyle(BorderlessButtonStyle())
                            }
                        }
                        .padding(.vertical, 8)
                        .listRowBackground(Color.clear)              // 行背景透明
                        .listRowSeparator(.hidden)                   // 隐藏分隔线
                    }
                    .listStyle(.plain)
                    .scrollContentBackground(.hidden)               // 列表整体背景透明

                    // 仅在 showSearchBar == true 时附加 .searchable
                    Group {
                        if showSearchBar {
                            list
                                .searchable(text: $searchText, prompt: "搜索新闻源")
                        } else {
                            list
                        }
                    }
                }
                // 仅在首次设置流程中显示“确定”按钮
                    Button(action: {
                        // 调用闭包，通知父视图完成设置
                        onComplete?()
                    }) {
                        Text("确定")
                            .font(.headline)
                            .foregroundColor(.white)
                            .frame(height: 50)
                            .frame(maxWidth: .infinity)
                            .background(Color.blue)
                            .cornerRadius(10)
                            .padding()
                    }
                    .disabled(subscriptionManager.subscribedSources.isEmpty) // 如果一个都没选，则禁用按钮
            }
        }
        .navigationTitle("添加新闻源")
        .navigationBarTitleDisplayMode(.inline)
        .toolbar {
            if !isFirstTimeSetup {
                ToolbarItem(placement: .navigationBarLeading) {
                    Button("完成") {
                        presentationMode.wrappedValue.dismiss()
                    }
                    .foregroundColor(.white)
                }
            }
            // 新增：导航栏右侧放大镜按钮
            ToolbarItem(placement: .navigationBarTrailing) {
                Button {
                    withAnimation(.easeInOut(duration: 0.2)) {
                        showSearchBar.toggle()
                        if !showSearchBar {
                            // 收起时清空搜索
                            searchText = ""
                        }
                    }
                } label: {
                    Image(systemName: showSearchBar ? "magnifyingglass.circle.fill" : "magnifyingglass")
                        .foregroundColor(.white)
                }
                .accessibilityLabel("搜索")
            }
        }
        .onAppear(perform: loadAvailableSources)
    }

    /// 从最新的 onews_*.json 文件中加载所有可用的新闻源名称
    private func loadAvailableSources() {
        isLoading = true
        errorMessage = nil

        DispatchQueue.global(qos: .userInitiated).async {
            do {
                let documentsDirectory = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
                let allFiles = try FileManager.default.contentsOfDirectory(at: documentsDirectory, includingPropertiesForKeys: nil)

                // 找到所有 onews_*.json 文件并按名称排序，最新的在最后
                let newsJSONURLs = allFiles
                    .filter { $0.lastPathComponent.starts(with: "onews_") && $0.pathExtension == "json" }
                    .sorted { $0.lastPathComponent < $1.lastPathComponent }

                guard let latestNewsURL = newsJSONURLs.last else {
                    throw NSError(domain: "AppError", code: 1, userInfo: [NSLocalizedDescriptionKey: "在 Documents 目录中没有找到任何 'onews_*.json' 文件。\n请先返回主页同步资源。"])
                }

                let data = try Data(contentsOf: latestNewsURL)
                // 我们只需要JSON的键，所以解码为 [String: [Article]]
                let decoded = try JSONDecoder().decode([String: [Article]].self, from: data)

                let sources = decoded.keys.sorted()

                DispatchQueue.main.async {
                    self.allAvailableSources = sources
                    self.isLoading = false
                }
            } catch {
                DispatchQueue.main.async {
                    self.errorMessage = error.localizedDescription
                    self.isLoading = false
                }
            }
        }
    }
}

