class AudioPlayerManager(private val context: Context) : ViewModel(), TextToSpeech.OnInitListener {

    // --- 状态 ---
    private val _isPlaybackActive = MutableStateFlow(false)
    val isPlaybackActive = _isPlaybackActive.asStateFlow()

    private val _isPlaying = MutableStateFlow(false)
    val isPlaying = _isPlaying.asStateFlow()

    private val _isSynthesizing = MutableStateFlow(false)
    val isSynthesizing = _isSynthesizing.asStateFlow()

    private val _progress = MutableStateFlow(0.0f)
    val progress = _progress.asStateFlow()

    private val _currentTimeString = MutableStateFlow("00:00")
    val currentTimeString = _currentTimeString.asStateFlow()

    private val _durationString = MutableStateFlow("00:00")
    val durationString = _durationString.asStateFlow()

    private val _isAutoPlayEnabled = mutableStateOf(true)
    val isAutoPlayEnabled: State<Boolean> = _isAutoPlayEnabled

    private val _playbackRate = mutableStateOf(1.0f)
    val playbackRate: State<Float> = _playbackRate

    // --- 回调 ---
    var onNextRequested: () -> Unit = {}
    var onPlaybackFinished: () -> Unit = {}

    // --- 内部属性 ---
    private var tts: TextToSpeech? = null
    private var mediaController: MediaController? = null
    private lateinit var mediaControllerFuture: ListenableFuture<MediaController>

    private var currentArticleTitle: String = "正在播放的文章"
    private var progressUpdateJob: Job? = null

    init {
        tts = TextToSpeech(context, this)
        val sessionToken =
            SessionToken(context, ComponentName(context, AudioPlaybackService::class.java))
        mediaControllerFuture = MediaController.Builder(context, sessionToken).buildAsync()
        mediaControllerFuture.addListener({
            mediaController = mediaControllerFuture.get()
            setupPlayerListener()
        }, MoreExecutors.directExecutor())
    }

    override fun onInit(status: Int) {
        if (status == TextToSpeech.SUCCESS) {
            // 默认设置为中文，可以根据文本内容动态改变
            tts?.language = Locale.CHINESE
        } else {
            println("TTS Initialization failed.")
        }
    }

    // --- 公共控制方法 ---

    fun startPlayback(text: String, title: String?) {
        if (text.isBlank()) {
            handleError("文本内容为空，无法播放。")
            return
        }

        prepareForNextTransition()

        currentArticleTitle = title ?: "正在播放的文章"

        viewModelScope.launch {
            _isSynthesizing.value = true
            _isPlaybackActive.value = true

            val processedText = preprocessText(text)
            val tempFile = File(context.cacheDir, "tts_audio.wav")
            val utteranceId = UUID.randomUUID().toString()

            tts?.setOnUtteranceProgressListener(object : UtteranceProgressListener() {
                override fun onStart(id: String?) {}
                override fun onDone(id: String?) {
                    if (id == utteranceId) {
                        viewModelScope.launch {
                            _isSynthesizing.value = false
                            playAudioFile(tempFile)
                        }
                    }
                }
                override fun onError(id: String?) { handleError("TTS合成失败") }
                override fun onStop(id: String?, interrupted: Boolean) {
                    if (interrupted) {
                        _isSynthesizing.value = false
                    }
                }
            })

            val params = Bundle()
            tts?.synthesizeToFile(processedText, params, tempFile, utteranceId)
        }
    }

    fun playPause() {
        mediaController?.let {
            if (it.isPlaying) it.pause() else it.play()
        }
    }

    fun stop() {
        tts?.stop()
        mediaController?.stop()
        mediaController?.clearMediaItems()
        _isPlaybackActive.value = false
        _isPlaying.value = false
        _isSynthesizing.value = false
        _progress.value = 0.0f
        _currentTimeString.value = "00:00"
        _durationString.value = "00:00"
        progressUpdateJob?.cancel()
    }

    fun seek(to: Float) {
        mediaController?.let {
            val duration = it.duration
            if (duration > 0) {
                it.seekTo((duration * to).toLong())
            }
        }
    }

    fun setAutoPlayEnabled(enabled: Boolean) {
        _isAutoPlayEnabled.value = enabled
        // 可以在这里更新通知或MediaSession元数据
    }

    fun setPlaybackRate(rate: Float) {
        _playbackRate.value = rate
        mediaController?.setPlaybackParameters(PlaybackParameters(rate))
    }

    fun prepareForNextTransition() {
        stop()
    }

    // --- 私有方法 ---

    private fun playAudioFile(file: File) {
        val mediaItem = MediaItem.Builder()
            .setUri(file.toURI().toString())
            .setMediaMetadata(
                MediaMetadata.Builder()
                    .setTitle(currentArticleTitle)
                    .setArtist(if (_isAutoPlayEnabled.value) "自动连播" else "单次播放")
                    .build()
            )
            .build()

        mediaController?.setMediaItem(mediaItem)
        mediaController?.prepare()
        mediaController?.play()
    }

    private fun setupPlayerListener() {
        mediaController?.addListener(object : Player.Listener {
            override fun onIsPlayingChanged(isPlaying: Boolean) {
                _isPlaying.value = isPlaying
                if (isPlaying) {
                    startProgressUpdater()
                } else {
                    stopProgressUpdater()
                }
            }

            override fun onPlaybackStateChanged(playbackState: Int) {
                if (playbackState == Player.STATE_ENDED) {
                    finishNaturally()
                }
            }
        })
    }

    private fun finishNaturally() {
        _isPlaying.value = false
        stopProgressUpdater()
        onPlaybackFinished()
        if (_isAutoPlayEnabled.value) {
            onNextRequested()
        }
    }

    private fun startProgressUpdater() {
        progressUpdateJob?.cancel()
        progressUpdateJob = viewModelScope.launch {
            while (true) {
                val player = mediaController ?: break
                if (player.isPlaying) {
                    val duration = player.duration.coerceAtLeast(1)
                    val position = player.currentPosition
                    _progress.value = (position.toFloat() / duration.toFloat()).coerceIn(0f, 1f)
                    _currentTimeString.value = formatTime(position)
                    _durationString.value = formatTime(duration)
                }
                delay(500)
            }
        }
    }

    private fun stopProgressUpdater() {
        progressUpdateJob?.cancel()
    }

    private fun handleError(message: String) {
        println("错误: $message")
        stop()
    }

    private fun formatTime(timeMs: Long): String {
        val totalSeconds = timeMs / 1000
        val minutes = totalSeconds / 60
        val seconds = totalSeconds % 60
        return String.format("%02d:%02d", minutes, seconds)
    }

    override fun onCleared() {
        super.onCleared()
        tts?.shutdown()
        MediaController.releaseFuture(mediaControllerFuture)
    }

    // --- 文本预处理逻辑 (从 Swift 翻译) ---

    private fun preprocessText(text: String): String {
        val textWithoutCommas = removeCommasFromNumbers(text)
        val normalized = normalizeDash(textWithoutCommas)
        val decimalBeforePercentWordFixed = insertDotForDecimalBeforePercentageWords(normalized)
        val processedSpecialTerms = processEnglishText(decimalBeforePercentWordFixed)
        val withYearFixed = replaceYearMentionsForChinese(processedSpecialTerms)

        val pattern = "(?<!年)([\\u4e00-\\u9fa5])(\\s*[A-Za-z]+\\s*)([\\u4e00-\\u9fa5])(?!年)".toRegex()
        return pattern.replace(withYearFixed, "$1, $2, $3")
    }

    private fun removeCommasFromNumbers(text: String): String {
        val pattern = "(\\d),(\\d{3})".toRegex()
        var result = text
        while (pattern.containsMatchIn(result)) {
            result = pattern.replace(result, "$1$2")
        }
        return result
    }

    private fun normalizeDash(text: String): String {
        val dashes = listOf("--", "—", "―", "–", "－", "‑", "‒", "〜", "~", "～", "----")
        var t = text
        dashes.forEach { d -> t = t.replace(d, "-") }
        while (t.contains("--")) {
            t = t.replace("--", "-")
        }
        return t
    }

    private fun insertDotForDecimalBeforePercentageWords(text: String): String {
        val pattern = "(?<!\\d)(\\d+)\\.(\\d+)\\s*(个百分点|百分比|百分点)".toRegex()
        return pattern.replace(text) { matchResult ->
            val (intPart, fracPart, unit) = matchResult.destructured
            "${intPart}点${fracPart}${unit}"
        }
    }

    private fun processEnglishText(input: String): String {
        var processed = input
            .replace("“", "").replace("”", "").replace("\"", "")

        processed = normalizeDash(processed)

        // 年龄段处理
        val ageRangePattern = "(?<!\\d)(\\d{1,2})\\s*-\\s*(\\d{1,2})\\s*(岁|岁龄|年龄段)".toRegex()
        processed = ageRangePattern.replace(processed) {
            val (lStr, rStr, unit) = it.destructured
            val l = lStr.toIntOrNull()
            val r = rStr.toIntOrNull()
            if (l != null && r != null && l in 10..99 && r in 10..99) {
                "${toChineseUpperForAge(l)}到${toChineseUpperForAge(r)}$unit"
            } else {
                it.value
            }
        }

        // 学年处理: YYYY-YY学年
        val academicYearPattern = "(?<!\\d)(\\d{4})\\s*-\\s*(\\d{2})(?=\\s*学年)".toRegex()
        processed = academicYearPattern.replace(processed) {
            val (leftYear, rightYear) = it.destructured
            "${formatDigitsToChinesePerChar(leftYear)}到${formatDigitsToChinesePerChar(rightYear)}"
        }

        // 年代处理: YYYY-YY年代
        val decadeRangePattern = "(?<!\\d)(\\d{4})\\s*-\\s*(\\d{2})(?=\\s*年代)".toRegex()
        processed = decadeRangePattern.replace(processed) {
            val (leftYear, rightSuffix) = it.destructured
            "${formatDigitsToChinesePerChar(leftYear)}到${formatDigitsToChinesePerChar(rightSuffix)}"
        }

        // 数字范围 + 量词
        val units = "[人名位个只辆架件次年条份所家台篇场例天月周小时分钟秒]"
        val numberRangeWithUnitPattern = "(?<!\\d)(\\d{1,6})\\s*-\\s*(\\d{1,6})\\s*($units)".toRegex()
        processed = numberRangeWithUnitPattern.replace(processed) {
            val (left, right, unit) = it.destructured
            val l = left.toIntOrNull()
            val r = right.toIntOrNull()
            if (l != null && r != null) {
                "${readChineseNumber(l)}到${readChineseNumber(r)}$unit"
            } else {
                it.value
            }
        }

        // 一般数值范围
        val generalRangePattern = "(?<!\\d)(\\d{1,6})\\s*-\\s*(\\d{1,6})(?!\\d)".toRegex()
        processed = generalRangePattern.replace(processed, "$1到$2")

        // 术语替换
        val replacements = mapOf(
            "API" to "A.P.I", "URL" to "U.R.L", "HTTP" to "H.T.T.P", "JSON" to "Jason",
            "HTML" to "H.T.M.L", "CSS" to "C.S.S", "JS" to "J.S", "AI" to "A.I",
            "OpenAI" to "Open.A.I", "SDK" to "S.D.K", "iOS" to "i O S", "PSA" to "P.S.A",
            "Jeep" to "吉普", "EV" to "电动车", "iPhone" to "i Phone", "iPad" to "i Pad",
            "macOS" to "mac O S", "UI" to "U.I", "GUI" to "G.U.I", "CLI" to "C.L.I",
            "SQL" to "S.Q.L", "NASA" to "NASA", "JPEG" to "J.PEG", "PNG" to "P.N.G",
            "PDF" to "P.D.F", "ID" to "I.D", "vs" to "对阵", "etc" to "等等",
            "i.e" to "也就是说", "e.g" to "举例来说", "&" to "和", "+" to "加",
            "=" to "等于", "@" to "at", "~" to "到", "/" to "每", "DJI" to "大疆",
            "Insta360" to "Insta三六零", "Airbnb" to "Air.B.N.B", "参加" to "餐加",
            "K-12" to "K十二", "K12" to "K十二"
        )
        replacements.forEach { (key, value) ->
            processed = processed.replace(key, value)
        }

        return processed
    }

    private fun replaceYearMentionsForChinese(text: String): String {
        var result = text
        // 范围年份: 2017-2020年
        val rangeWithYearPattern = "(?<!\\d)(\\d{4})(?:\\s*年)?\\s*-\\s*(\\d{4})(?=\\s*(?:年|年代))".toRegex()
        result = rangeWithYearPattern.replace(result) {
            val (leftYear, rightYear) = it.destructured
            "${formatDigitsToChinesePerChar(leftYear)}到${formatDigitsToChinesePerChar(rightYear)}"
        }

        // 单个年份: 2024年
        val singleYearPattern = "(?<!\\d)(\\d{4})(?=\\s*(?:年|年代))".toRegex()
        result = singleYearPattern.replace(result) {
            formatDigitsToChinesePerChar(it.groupValues[1])
        }
        return result
    }

    private fun formatDigitsToChinesePerChar(digits: String): String {
        val map = mapOf('0' to "零", '1' to "一", '2' to "二", '3' to "三", '4' to "四", '5' to "五", '6' to "六", '7' to "七", '8' to "八", '9' to "九")
        return digits.map { map[it] }.joinToString("")
    }

    private fun toChineseUpperForAge(n: Int): String {
        val upper = listOf("零","壹","贰","叁","肆","伍","陆","柒","捌","玖")
        if (n < 10) return upper[n]
        val tens = n / 10
        val ones = n % 10
        return when {
            ones == 0 -> if (tens == 1) "十" else upper[tens] + "十"
            tens == 1 -> "十" + upper[ones]
            else -> upper[tens] + "十" + upper[ones]
        }
    }

    private fun readChineseNumber(n: Int): String {
        val digits = listOf("零","一","二","三","四","五","六","七","八","九")
        if (n < 10) return digits[n]
        if (n < 20) return "十" + if (n % 10 == 0) "" else digits[n % 10]
        if (n < 100) return digits[n / 10] + "十" + if (n % 10 == 0) "" else digits[n % 10]
        // ... 更多实现可以根据 Swift 版本精确翻译
        return n.toString() // 简化版
    }
}

package com.sskeysskey.onews.manager

import android.content.Context
import com.sskeysskey.onews.data.FileInfo
import com.sskeysskey.onews.network.ApiClient
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.io.File
import java.io.FileInputStream
import java.io.FileOutputStream
import java.io.IOException
import java.security.MessageDigest

class ResourceManager(
    private val context: Context,
    private val externalScope: CoroutineScope
) {
    private val _isSyncing = MutableStateFlow(false)
    val isSyncing = _isSyncing.asStateFlow()

    private val _syncMessage = MutableStateFlow("启动中...")
    val syncMessage = _syncMessage.asStateFlow()

    private val _isDownloading = MutableStateFlow(false)
    val isDownloading = _isDownloading.asStateFlow()

    private val _downloadProgress = MutableStateFlow(0.0f)
    val downloadProgress = _downloadProgress.asStateFlow()

    private val _progressText = MutableStateFlow("")
    val progressText = _progressText.asStateFlow()

    private val documentsDirectory: File = context.filesDir
    private val apiService = ApiClient.apiService

    fun checkAndDownloadUpdates() {
        externalScope.launch {
            try {
                _isSyncing.value = true
                _isDownloading.value = false
                _syncMessage.value = "正在检查更新..."
                _progressText.value = ""
                _downloadProgress.value = 0.0f

                val serverVersion = apiService.getServerVersion()
                val localFiles = getLocalFiles()

                _syncMessage.value = "正在清理旧资源..."
                val validServerFiles = serverVersion.files.map { it.name }.toSet()
                val filesToDelete = localFiles.filterNot { validServerFiles.contains(it) }
                val oldNewsItemsToDelete = filesToDelete.filter {
                    it.startsWith("onews_") || it.startsWith("news_images_")
                }

                if (oldNewsItemsToDelete.isNotEmpty()) {
                    println("发现需要清理的过时资源: $oldNewsItemsToDelete")
                    oldNewsItemsToDelete.forEach { itemName ->
                        File(documentsDirectory, itemName).deleteRecursively()
                        println("🗑️ 已成功删除: $itemName")
                    }
                } else {
                    println("本地资源无需清理。")
                }

                val downloadTasks = mutableListOf<Pair<FileInfo, Boolean>>()
                val jsonFilesFromServer = serverVersion.files.filter { it.type == "json" }
                val imageDirsFromServer = serverVersion.files.filter { it.type == "images" }

                jsonFilesFromServer.forEach { jsonInfo ->
                    val localFile = File(documentsDirectory, jsonInfo.name)
                    val correspondingImageDirName = "news_images_" + jsonInfo.name.substringAfterLast('_').removeSuffix(".json")

                    if (localFile.exists()) {
                        val serverMD5 = jsonInfo.md5
                        val localMD5 = calculateMD5(localFile)
                        if (serverMD5 != null && serverMD5 != localMD5) {
                            println("MD5不匹配: ${jsonInfo.name}。计划更新。")
                            downloadTasks.add(jsonInfo to false) // full download
                            serverVersion.files.find { it.name == correspondingImageDirName }?.let {
                                downloadTasks.add(it to true) // incremental
                            }
                        }
                    } else {
                        println("新文件: ${jsonInfo.name}。计划下载。")
                        downloadTasks.add(jsonInfo to false)
                        serverVersion.files.find { it.name == correspondingImageDirName }?.let {
                            downloadTasks.add(it to false)
                        }
                    }
                }

                imageDirsFromServer.forEach { dirInfo ->
                    val localDir = File(documentsDirectory, dirInfo.name)
                    if (!localDir.exists() || !localDir.isDirectory) {
                        println("缺失图片目录，准备补齐下载: ${dirInfo.name}")
                        if (downloadTasks.none { it.first.name == dirInfo.name }) {
                            downloadTasks.add(dirInfo to false)
                        }
                    }
                }

                if (downloadTasks.isEmpty()) {
                    _syncMessage.value = "已是最新"
                    delay(500)
                    _isSyncing.value = false
                    return@launch
                }

                println("需要处理的任务列表: ${downloadTasks.map { it.first.name }}")

                _isDownloading.value = true
                val totalTasks = downloadTasks.count()

                downloadTasks.forEachIndexed { index, task ->
                    _progressText.value = "${index + 1}/$totalTasks"
                    _downloadProgress.value = (index + 1).toFloat() / totalTasks.toFloat()

                    val (fileInfo, isIncremental) = task
                    when {
                        fileInfo.type == "json" -> {
                            _syncMessage.value = "正在下载文件: ${fileInfo.name}..."
                            downloadSingleFile(fileInfo.name)
                        }
                        fileInfo.type == "images" && !isIncremental -> {
                            _syncMessage.value = "正在处理目录: ${fileInfo.name}..."
                            downloadDirectory(fileInfo.name)
                        }
                        fileInfo.type == "images" && isIncremental -> {
                            _syncMessage.value = "正在处理目录: ${fileInfo.name}..."
                            downloadDirectoryIncrementally(fileInfo.name)
                        }
                        else -> println("警告: 遇到未知的任务类型 '${fileInfo.type}'，跳过。")
                    }
                }

                _isDownloading.value = false
                _syncMessage.value = "更新完成！"
                _progressText.value = ""
                delay(1000)
                _isSyncing.value = false

            } catch (e: Exception) {
                _isSyncing.value = false
                _isDownloading.value = false
                e.printStackTrace()
                throw e
            }
        }
    }

    fun checkAndDownloadAllNewsManifests() {
        externalScope.launch {
            try {
                _isSyncing.value = true
                _isDownloading.value = false
                _syncMessage.value = "正在获取新闻清单列表..."
                _progressText.value = ""
                _downloadProgress.value = 0.0f

                val serverVersion = apiService.getServerVersion()
                val allJsonInfos = serverVersion.files
                    .filter { it.type == "json" && it.name.startsWith("onews_") }
                    .sortedBy { it.name }

                if (allJsonInfos.isEmpty()) {
                    println("服务器上未找到任何 'onews_*.json' 文件。")
                    _isSyncing.value = false
                    return@launch
                }

                val tasksToDownload = allJsonInfos.filter { jsonInfo ->
                    val localFile = File(documentsDirectory, jsonInfo.name)
                    if (localFile.exists()) {
                        val serverMD5 = jsonInfo.md5
                        val localMD5 = calculateMD5(localFile)
                        serverMD5 != null && serverMD5 != localMD5
                    } else {
                        true
                    }
                }

                if (tasksToDownload.isEmpty()) {
                    _syncMessage.value = "新闻清单已是最新。"
                    delay(500)
                    _isSyncing.value = false
                    return@launch
                }

                _isDownloading.value = true
                val total = tasksToDownload.count()
                tasksToDownload.forEachIndexed { index, info ->
                    _progressText.value = "${index + 1}/$total"
                    _downloadProgress.value = (index + 1).toFloat() / total.toFloat()
                    _syncMessage.value = "正在下载: ${info.name}..."
                    downloadSingleFile(info.name)
                }

                _isDownloading.value = false
                _syncMessage.value = "清单更新完成！"
                _progressText.value = ""
                delay(500)
                _isSyncing.value = false

            } catch (e: Exception) {
                _isSyncing.value = false
                _isDownloading.value = false
                e.printStackTrace()
                throw e
            }
        }
    }

    private suspend fun downloadSingleFile(filename: String) = withContext(Dispatchers.IO) {
        val response = apiService.downloadFile("download?filename=$filename")
        if (response.isSuccessful) {
            response.body()?.let { body ->
                val destinationFile = File(documentsDirectory, filename)
                try {
                    body.byteStream().use { input ->
                        FileOutputStream(destinationFile).use { output ->
                            input.copyTo(output)
                        }
                    }
                } catch (e: IOException) {
                    e.printStackTrace()
                }
            }
        }
    }

    private suspend fun downloadDirectory(directoryName: String) = withContext(Dispatchers.IO) {
        val fileList = apiService.getFileList(directoryName)
        if (fileList.isEmpty()) return@withContext

        val localDir = File(documentsDirectory, directoryName)
        if (localDir.exists()) localDir.deleteRecursively()
        localDir.mkdirs()

        fileList.forEachIndexed { index, remoteFilename ->
            _syncMessage.value = "正在下载新闻图片... (${index + 1}/${fileList.size})"
            val downloadPath = "$directoryName/$remoteFilename"
            downloadSingleFile(downloadPath)
        }
    }

    private suspend fun downloadDirectoryIncrementally(directoryName: String) =
        withContext(Dispatchers.IO) {
            val remoteFileList = apiService.getFileList(directoryName).toSet()
            if (remoteFileList.isEmpty()) return@withContext

            val localDir = File(documentsDirectory, directoryName)
            localDir.mkdirs()

            val localFileSet = localDir.listFiles()?.map { it.name }?.toSet() ?: emptySet()
            val filesToDownload = remoteFileList - localFileSet

            if (filesToDownload.isEmpty()) {
                println("目录 $directoryName 无需增量下载，文件已同步。")
                return@withContext
            }

            filesToDownload.forEachIndexed { index, remoteFilename ->
                _syncMessage.value = "下载新图片... (${index + 1}/${filesToDownload.size})"
                val downloadPath = "$directoryName/$remoteFilename"
                downloadSingleFile(downloadPath)
            }
        }

    private fun getLocalFiles(): List<String> {
        return documentsDirectory.listFiles()?.map { it.name } ?: emptyList()
    }

    private fun calculateMD5(file: File): String? {
        return try {
            val md = MessageDigest.getInstance("MD5")
            FileInputStream(file).use { fis ->
                val buffer = ByteArray(8192)
                var numRead: Int
                while (fis.read(buffer).also { numRead = it } != -1) {
                    md.update(buffer, 0, numRead)
                }
            }
            md.digest().joinToString("") { "%02x".format(it) }
        } catch (e: Exception) {
            e.printStackTrace()
            null
        }
    }
}

package com.sskeysskey.onews.manager

import android.annotation.SuppressLint
import android.content.Context
import android.content.SharedPreferences
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow

// 使用 object 使其成为一个单例
@SuppressLint("StaticFieldLeak")
object SubscriptionManager {

    private const val PREFS_NAME = "ONewsPrefs"
    private const val SUBSCRIBED_SOURCES_KEY = "subscribedNewsSources"
    private lateinit var prefs: SharedPreferences

    // 使用 StateFlow 以便 Compose UI 可以响应式地观察变化
    private val _subscribedSources = MutableStateFlow<Set<String>>(emptySet())
    val subscribedSources = _subscribedSources.asStateFlow()

    fun init(context: Context) {
        // Application Context 不会导致内存泄漏
        prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        loadSubscribedSources()
    }

    private fun loadSubscribedSources() {
        _subscribedSources.value = prefs.getStringSet(SUBSCRIBED_SOURCES_KEY, emptySet()) ?: emptySet()
    }

    private fun saveSubscribedSources() {
        prefs.edit().putStringSet(SUBSCRIBED_SOURCES_KEY, _subscribedSources.value).apply()
    }

    fun isSubscribed(to: String): Boolean {
        return _subscribedSources.value.contains(to)
    }

    fun addSubscription(sourceName: String) {
        _subscribedSources.value = _subscribedSources.value + sourceName
        saveSubscribedSources()
    }

    fun removeSubscription(sourceName: String) {
        _subscribedSources.value = _subscribedSources.value - sourceName
        saveSubscribedSources()
    }

    fun toggleSubscription(forSourceName: String) {
        if (isSubscribed(forSourceName)) {
            removeSubscription(forSourceName)
        } else {
            addSubscription(forSourceName)
        }
    }
}

