@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AddSourceScreen(
    navController: NavController,
    isFirstTimeSetup: Boolean,
    onComplete: () -> Unit
) {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()

    var allAvailableSources by remember { mutableStateOf<List<String>>(emptyList()) }
    var isLoading by remember { mutableStateOf(true) }
    var errorMessage by remember { mutableStateOf<String?>(null) }

    val subscribedSources by SubscriptionManager.subscribedSources.collectAsState()

    LaunchedEffect(Unit) {
        scope.launch(Dispatchers.IO) {
            try {
                val documentsDirectory = context.filesDir
                val allFiles = documentsDirectory.listFiles { _, name ->
                    name.startsWith("onews_") && name.endsWith(".json")
                }

                if (allFiles.isNullOrEmpty()) {
                    throw Exception("在目录中没有找到任何 'onews_*.json' 文件。\n请先返回主页同步资源。")
                }

                val union = mutableSetOf<String>()
                val gson = Gson()
                val articleType = object : TypeToken<Map<String, List<Article>>>() {}.type

                for (file in allFiles) {
                    try {
                        val jsonString = file.readText()
                        val decoded: Map<String, List<Article>> = gson.fromJson(jsonString, articleType)
                        union.addAll(decoded.keys)
                    } catch (e: Exception) {
                        println("解析 ${file.name} 失败: ${e.localizedMessage}")
                    }
                }
                withContext(Dispatchers.Main) {
                    allAvailableSources = union.sorted()
                    isLoading = false
                }
            } catch (e: Exception) {
                withContext(Dispatchers.Main) {
                    errorMessage = e.message
                    isLoading = false
                }
            }
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("添加新闻源") },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = Color.Transparent,
                    titleContentColor = Color.White
                )
            )
        },
        containerColor = Color.Transparent
    ) { paddingValues ->
        Box(modifier = Modifier.fillMaxSize()) {
            AppBackgroundImage()
            Box(modifier = Modifier.fillMaxSize().background(WelcomeBackgroundOverlay))

            when {
                isLoading -> {
                    Box(contentAlignment = Alignment.Center, modifier = Modifier.fillMaxSize()) {
                        CircularProgressIndicator(color = Color.White)
                    }
                }
                errorMessage != null -> {
                    Box(contentAlignment = Alignment.Center, modifier = Modifier.fillMaxSize().padding(20.dp)) {
                        Text(errorMessage!!, color = Color.White, textAlign = androidx.compose.ui.text.style.TextAlign.Center)
                    }
                }
                else -> {
                    Column(modifier = Modifier.fillMaxSize().padding(paddingValues)) {
                        LazyColumn(modifier = Modifier.weight(1f)) {
                            items(allAvailableSources) { sourceName ->
                                SourceItemRow(
                                    sourceName = sourceName,
                                    isSubscribed = subscribedSources.contains(sourceName),
                                    onToggle = { SubscriptionManager.toggleSubscription(sourceName) }
                                )
                            }
                        }
                        Button(
                            onClick = {
                                if (isFirstTimeSetup) onComplete() else navController.popBackStack()
                            },
                            modifier = Modifier.fillMaxWidth().padding(16.dp),
                            enabled = subscribedSources.isNotEmpty()
                        ) {
                            Text("确定")
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun SourceItemRow(sourceName: String, isSubscribed: Boolean, onToggle: () -> Unit) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp, vertical = 12.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Text(
            text = sourceName,
            color = Color.White,
            fontWeight = FontWeight.Medium,
            modifier = Modifier.weight(1f)
        )
        if (isSubscribed) {
            Text(
                "已添加",
                color = Color.White.copy(alpha = 0.8f),
                style = MaterialTheme.typography.bodySmall,
                modifier = Modifier.padding(end = 8.dp)
            )
            Icon(
                imageVector = Icons.Default.RemoveCircle,
                contentDescription = "Remove",
                tint = MaterialTheme.colorScheme.error,
                modifier = Modifier.size(28.dp).clickable(onClick = onToggle)
            )
        } else {
            Icon(
                imageVector = Icons.Default.AddCircle,
                contentDescription = "Add",
                tint = MaterialTheme.colorScheme.primary,
                modifier = Modifier.size(28.dp).clickable(onClick = onToggle)
            )
        }
    }
}

