package com.sskeysskey.onews.manager

import android.content.Context
import com.sskeysskey.onews.data.FileInfo
import com.sskeysskey.onews.network.ApiClient
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.io.File
import java.io.FileInputStream
import java.io.FileOutputStream
import java.io.IOException
import java.security.MessageDigest

class ResourceManager(
    private val context: Context,
    private val externalScope: CoroutineScope
) {
    private val _isSyncing = MutableStateFlow(false)
    val isSyncing = _isSyncing.asStateFlow()

    private val _syncMessage = MutableStateFlow("启动中...")
    val syncMessage = _syncMessage.asStateFlow()

    private val _isDownloading = MutableStateFlow(false)
    val isDownloading = _isDownloading.asStateFlow()

    private val _downloadProgress = MutableStateFlow(0.0f)
    val downloadProgress = _downloadProgress.asStateFlow()

    private val _progressText = MutableStateFlow("")
    val progressText = _progressText.asStateFlow()

    private val documentsDirectory: File = context.filesDir
    private val apiService = ApiClient.apiService

    fun checkAndDownloadUpdates() {
        externalScope.launch {
            try {
                _isSyncing.value = true
                _isDownloading.value = false
                _syncMessage.value = "正在检查更新..."
                _progressText.value = ""
                _downloadProgress.value = 0.0f

                val serverVersion = apiService.getServerVersion()
                val localFiles = getLocalFiles()

                _syncMessage.value = "正在清理旧资源..."
                val validServerFiles = serverVersion.files.map { it.name }.toSet()
                val filesToDelete = localFiles.filterNot { validServerFiles.contains(it) }
                val oldNewsItemsToDelete = filesToDelete.filter {
                    it.startsWith("onews_") || it.startsWith("news_images_")
                }

                if (oldNewsItemsToDelete.isNotEmpty()) {
                    println("发现需要清理的过时资源: $oldNewsItemsToDelete")
                    oldNewsItemsToDelete.forEach { itemName ->
                        File(documentsDirectory, itemName).deleteRecursively()
                        println("🗑️ 已成功删除: $itemName")
                    }
                } else {
                    println("本地资源无需清理。")
                }

                val downloadTasks = mutableListOf<Pair<FileInfo, Boolean>>()
                val jsonFilesFromServer = serverVersion.files.filter { it.type == "json" }
                val imageDirsFromServer = serverVersion.files.filter { it.type == "images" }

                jsonFilesFromServer.forEach { jsonInfo ->
                    val localFile = File(documentsDirectory, jsonInfo.name)
                    val correspondingImageDirName = "news_images_" + jsonInfo.name.substringAfterLast('_').removeSuffix(".json")

                    if (localFile.exists()) {
                        val serverMD5 = jsonInfo.md5
                        val localMD5 = calculateMD5(localFile)
                        if (serverMD5 != null && serverMD5 != localMD5) {
                            println("MD5不匹配: ${jsonInfo.name}。计划更新。")
                            downloadTasks.add(jsonInfo to false) // full download
                            serverVersion.files.find { it.name == correspondingImageDirName }?.let {
                                downloadTasks.add(it to true) // incremental
                            }
                        }
                    } else {
                        println("新文件: ${jsonInfo.name}。计划下载。")
                        downloadTasks.add(jsonInfo to false)
                        serverVersion.files.find { it.name == correspondingImageDirName }?.let {
                            downloadTasks.add(it to false)
                        }
                    }
                }

                imageDirsFromServer.forEach { dirInfo ->
                    val localDir = File(documentsDirectory, dirInfo.name)
                    if (!localDir.exists() || !localDir.isDirectory) {
                        println("缺失图片目录，准备补齐下载: ${dirInfo.name}")
                        if (downloadTasks.none { it.first.name == dirInfo.name }) {
                            downloadTasks.add(dirInfo to false)
                        }
                    }
                }

                if (downloadTasks.isEmpty()) {
                    _syncMessage.value = "已是最新"
                    delay(500)
                    _isSyncing.value = false
                    return@launch
                }

                println("需要处理的任务列表: ${downloadTasks.map { it.first.name }}")

                _isDownloading.value = true
                val totalTasks = downloadTasks.count()

                downloadTasks.forEachIndexed { index, task ->
                    _progressText.value = "${index + 1}/$totalTasks"
                    _downloadProgress.value = (index + 1).toFloat() / totalTasks.toFloat()

                    val (fileInfo, isIncremental) = task
                    when {
                        fileInfo.type == "json" -> {
                            _syncMessage.value = "正在下载文件: ${fileInfo.name}..."
                            downloadSingleFile(fileInfo.name)
                        }
                        fileInfo.type == "images" && !isIncremental -> {
                            _syncMessage.value = "正在处理目录: ${fileInfo.name}..."
                            downloadDirectory(fileInfo.name)
                        }
                        fileInfo.type == "images" && isIncremental -> {
                            _syncMessage.value = "正在处理目录: ${fileInfo.name}..."
                            downloadDirectoryIncrementally(fileInfo.name)
                        }
                        else -> println("警告: 遇到未知的任务类型 '${fileInfo.type}'，跳过。")
                    }
                }

                _isDownloading.value = false
                _syncMessage.value = "更新完成！"
                _progressText.value = ""
                delay(1000)
                _isSyncing.value = false

            } catch (e: Exception) {
                _isSyncing.value = false
                _isDownloading.value = false
                e.printStackTrace()
                throw e
            }
        }
    }

    fun checkAndDownloadAllNewsManifests() {
        externalScope.launch {
            try {
                _isSyncing.value = true
                _isDownloading.value = false
                _syncMessage.value = "正在获取新闻清单列表..."
                _progressText.value = ""
                _downloadProgress.value = 0.0f

                val serverVersion = apiService.getServerVersion()
                val allJsonInfos = serverVersion.files
                    .filter { it.type == "json" && it.name.startsWith("onews_") }
                    .sortedBy { it.name }

                if (allJsonInfos.isEmpty()) {
                    println("服务器上未找到任何 'onews_*.json' 文件。")
                    _isSyncing.value = false
                    return@launch
                }

                val tasksToDownload = allJsonInfos.filter { jsonInfo ->
                    val localFile = File(documentsDirectory, jsonInfo.name)
                    if (localFile.exists()) {
                        val serverMD5 = jsonInfo.md5
                        val localMD5 = calculateMD5(localFile)
                        serverMD5 != null && serverMD5 != localMD5
                    } else {
                        true
                    }
                }

                if (tasksToDownload.isEmpty()) {
                    _syncMessage.value = "新闻清单已是最新。"
                    delay(500)
                    _isSyncing.value = false
                    return@launch
                }

                _isDownloading.value = true
                val total = tasksToDownload.count()
                tasksToDownload.forEachIndexed { index, info ->
                    _progressText.value = "${index + 1}/$total"
                    _downloadProgress.value = (index + 1).toFloat() / total.toFloat()
                    _syncMessage.value = "正在下载: ${info.name}..."
                    downloadSingleFile(info.name)
                }

                _isDownloading.value = false
                _syncMessage.value = "清单更新完成！"
                _progressText.value = ""
                delay(500)
                _isSyncing.value = false

            } catch (e: Exception) {
                _isSyncing.value = false
                _isDownloading.value = false
                e.printStackTrace()
                throw e
            }
        }
    }

    private suspend fun downloadSingleFile(filename: String) = withContext(Dispatchers.IO) {
        val response = apiService.downloadFile("download?filename=$filename")
        if (response.isSuccessful) {
            response.body()?.let { body ->
                val destinationFile = File(documentsDirectory, filename)
                try {
                    body.byteStream().use { input ->
                        FileOutputStream(destinationFile).use { output ->
                            input.copyTo(output)
                        }
                    }
                } catch (e: IOException) {
                    e.printStackTrace()
                }
            }
        }
    }

    private suspend fun downloadDirectory(directoryName: String) = withContext(Dispatchers.IO) {
        val fileList = apiService.getFileList(directoryName)
        if (fileList.isEmpty()) return@withContext

        val localDir = File(documentsDirectory, directoryName)
        if (localDir.exists()) localDir.deleteRecursively()
        localDir.mkdirs()

        fileList.forEachIndexed { index, remoteFilename ->
            _syncMessage.value = "正在下载新闻图片... (${index + 1}/${fileList.size})"
            val downloadPath = "$directoryName/$remoteFilename"
            downloadSingleFile(downloadPath)
        }
    }

    private suspend fun downloadDirectoryIncrementally(directoryName: String) =
        withContext(Dispatchers.IO) {
            val remoteFileList = apiService.getFileList(directoryName).toSet()
            if (remoteFileList.isEmpty()) return@withContext

            val localDir = File(documentsDirectory, directoryName)
            localDir.mkdirs()

            val localFileSet = localDir.listFiles()?.map { it.name }?.toSet() ?: emptySet()
            val filesToDownload = remoteFileList - localFileSet

            if (filesToDownload.isEmpty()) {
                println("目录 $directoryName 无需增量下载，文件已同步。")
                return@withContext
            }

            filesToDownload.forEachIndexed { index, remoteFilename ->
                _syncMessage.value = "下载新图片... (${index + 1}/${filesToDownload.size})"
                val downloadPath = "$directoryName/$remoteFilename"
                downloadSingleFile(downloadPath)
            }
        }

    private fun getLocalFiles(): List<String> {
        return documentsDirectory.listFiles()?.map { it.name } ?: emptyList()
    }

    private fun calculateMD5(file: File): String? {
        return try {
            val md = MessageDigest.getInstance("MD5")
            FileInputStream(file).use { fis ->
                val buffer = ByteArray(8192)
                var numRead: Int
                while (fis.read(buffer).also { numRead = it } != -1) {
                    md.update(buffer, 0, numRead)
                }
            }
            md.digest().joinToString("") { "%02x".format(it) }
        } catch (e: Exception) {
            e.printStackTrace()
            null
        }
    }
}

package com.sskeysskey.onews.manager

import android.annotation.SuppressLint
import android.content.Context
import android.content.SharedPreferences
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow

// 使用 object 使其成为一个单例
@SuppressLint("StaticFieldLeak")
object SubscriptionManager {

    private const val PREFS_NAME = "ONewsPrefs"
    private const val SUBSCRIBED_SOURCES_KEY = "subscribedNewsSources"
    private lateinit var prefs: SharedPreferences

    // 使用 StateFlow 以便 Compose UI 可以响应式地观察变化
    private val _subscribedSources = MutableStateFlow<Set<String>>(emptySet())
    val subscribedSources = _subscribedSources.asStateFlow()

    fun init(context: Context) {
        // Application Context 不会导致内存泄漏
        prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        loadSubscribedSources()
    }

    private fun loadSubscribedSources() {
        _subscribedSources.value = prefs.getStringSet(SUBSCRIBED_SOURCES_KEY, emptySet()) ?: emptySet()
    }

    private fun saveSubscribedSources() {
        prefs.edit().putStringSet(SUBSCRIBED_SOURCES_KEY, _subscribedSources.value).apply()
    }

    fun isSubscribed(to: String): Boolean {
        return _subscribedSources.value.contains(to)
    }

    fun addSubscription(sourceName: String) {
        _subscribedSources.value = _subscribedSources.value + sourceName
        saveSubscribedSources()
    }

    fun removeSubscription(sourceName: String) {
        _subscribedSources.value = _subscribedSources.value - sourceName
        saveSubscribedSources()
    }

    fun toggleSubscription(forSourceName: String) {
        if (isSubscribed(forSourceName)) {
            removeSubscription(forSourceName)
        } else {
            addSubscription(forSourceName)
        }
    }
}

