class MainActivity : ComponentActivity() {

    // 权限请求
    private val requestPermissionLauncher =
        registerForActivityResult(ActivityResultContracts.RequestPermission()) { isGranted: Boolean ->
            if (isGranted) {
                println("通知权限已授予")
            } else {
                println("通知权限被拒绝")
            }
        }

    private fun askNotificationPermission() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            requestPermissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS)
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        askNotificationPermission()

        setContent {
            ONewsTheme {
                Surface(
                    modifier = Modifier.fillMaxSize(),
                    color = MaterialTheme.colorScheme.background
                ) {
                    val context = LocalContext.current
                    val prefs =
                        remember { context.getSharedPreferences("ONewsPrefs", MODE_PRIVATE) }
                    var hasCompletedInitialSetup by remember {
                        mutableStateOf(prefs.getBoolean("hasCompletedInitialSetup", false))
                    }

                    if (hasCompletedInitialSetup) {
                        // 如果已完成初始设置，显示主应用
                        AppNavigation()
                    } else {
                        // 否则，显示欢迎屏幕
                        WelcomeScreen(onComplete = {
                            prefs.edit().putBoolean("hasCompletedInitialSetup", true).apply()
                            hasCompletedInitialSetup = true
                        })
                    }
                }
            }
        }
    }
}

package com.sskeysskey.onews

import com.google.gson.annotations.SerializedName
import java.util.UUID

// 新闻源模型
data class NewsSource(
    val id: UUID = UUID.randomUUID(),
    val name: String,
    val articles: List<Article>,
    val unreadCount: Int = articles.count { !it.isRead }
)

// 文章模型
// 增强对 GSON 反序列化的容错：
// 1) 为可缺失字段提供安全默认值（包括 url、images、id、isRead、timestamp）。
// 2) 将 images 默认值改为 emptyList()，并允许 GSON 将 null 解析为 null 后由默认值接管。
// 3) url 在 JSON 中有的源缺失，因此设为可空并提供默认 null。
data class Article(
    @SerializedName("topic") val topic: String,
    @SerializedName("article") val articleContent: String,
    @SerializedName("images") val images: List<String> = emptyList(),
    @SerializedName("url") val url: String? = null,
    // 以下字段即使 JSON 完全缺失，也会有默认值，避免 copy 调用时出现空参
    val id: UUID = UUID.randomUUID(),
    val isRead: Boolean = false,
    val timestamp: String = ""
)

// 服务器版本信息模型 (用于 UpdateManager)
data class ServerVersion(
    @SerializedName("version") val version: String,
    @SerializedName("files") val files: List<FileInfo>
)

// 文件信息模型 (用于 UpdateManager)
data class FileInfo(
    @SerializedName("name") val name: String,
    @SerializedName("type") val type: String,
    @SerializedName("md5") val md5: String?
)

// 用于 allArticlesSortedForDisplay 的包装类
data class ArticleWithSource(
    val article: Article,
    val sourceName: String
)

package com.sskeysskey.onews

import android.app.Application
import android.content.Context
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.viewModelScope
import com.google.gson.Gson
import com.google.gson.reflect.TypeToken
import com.sskeysskey.onews.AppBadgeManager
import com.sskeysskey.onews.SubscriptionManager
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.io.File
import java.util.Date
import java.util.UUID

class NewsViewModelFactory(private val application: Application) : ViewModelProvider.Factory {
    override fun <T : ViewModel> create(modelClass: Class<T>): T {
        if (modelClass.isAssignableFrom(NewsViewModel::class.java)) {
            @Suppress("UNCHECKED_CAST")
            return NewsViewModel(application) as T
        }
        throw IllegalArgumentException("Unknown ViewModel class")
    }
}

class NewsViewModel(application: Application) : AndroidViewModel(application) {
    private val gson = Gson()
    private val documentsDirectory: File = application.filesDir
    private val badgeManager = AppBadgeManager(application)

    private val readPrefs = application.getSharedPreferences("ReadRecords", Context.MODE_PRIVATE)

    // --- StateFlows for UI ---
    private val _sources = MutableStateFlow<List<NewsSource>>(emptyList())
    val sources = _sources.asStateFlow()

    private val _readRecords = MutableStateFlow<Map<String, Long>>(emptyMap())

    val allArticlesSortedForDisplay = combine(_sources, _readRecords) { sources, _ ->
        sources.flatMap { source ->
            source.articles.map { article ->
                ArticleWithSource(article = article, sourceName = source.name)
            }
        }.sortedWith(compareBy({ it.article.timestamp }, { it.article.topic }))
    }.stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptyList())

    val totalUnreadCount = combine(_sources, _readRecords) { sources, _ ->
        sources.sumOf { source -> source.articles.count { !it.isRead } }
    }.stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), 0)

    init {
        loadReadRecords()
        viewModelScope.launch {
            totalUnreadCount.collect { count ->
                badgeManager.updateBadge(count)
            }
        }
    }

    private fun loadReadRecords() {
        val map = mutableMapOf<String, Long>()
        readPrefs.all.forEach { (key, value) ->
            if (value is Long) {
                map[key] = value
            }
        }
        _readRecords.value = map
    }

    private fun saveReadRecords() {
        val editor = readPrefs.edit()
        editor.clear()
        _readRecords.value.forEach { (key, value) ->
            editor.putLong(key, value)
        }
        editor.apply()
    }

    fun loadNews() {
        viewModelScope.launch(Dispatchers.IO) {
            val subscribed = SubscriptionManager.subscribedSources.value
            if (subscribed.isEmpty()) {
                withContext(Dispatchers.Main) { _sources.value = emptyList() }
                return@launch
            }

            val allFiles = documentsDirectory.listFiles { _, name ->
                name.startsWith("onews_") && name.endsWith(".json")
            } ?: run {
                withContext(Dispatchers.Main) { _sources.value = emptyList() }
                return@launch
            }

            val allArticlesBySource = mutableMapOf<String, MutableList<Article>>()
            val articleType = object : TypeToken<Map<String, List<Article>>>() {}.type

            for (file in allFiles) {
                val timestamp = file.name.substringAfter("onews_").substringBefore(".json")
                try {
                    val jsonString = file.readText()
                    val decoded: Map<String, List<Article>> = gson.fromJson(jsonString, articleType)

                    decoded.forEach { (sourceName, articles) ->
                        if (subscribed.contains(sourceName)) {

                            // 标准化每篇文章，确保 id 非空、images 非空列表、timestamp 写入
                            val normalized = articles.map { a ->
                                val safeId = a.id ?: UUID.randomUUID()
                                val safeImages = a.images ?: emptyList()
                                // 用 copy 只改必要字段，避免把 null 传播到非空参数
                                a.copy(
                                    id = safeId,
                                    images = safeImages,
                                    timestamp = timestamp
                                )
                            }

                            allArticlesBySource.getOrPut(sourceName) { mutableListOf() }.addAll(normalized)
                        }
                    }
                } catch (e: Exception) {
                    e.printStackTrace()
                    println("解析 ${file.name} 失败: ${e.message}")
                }
            }

            val tempSources = allArticlesBySource.map { (sourceName, articles) ->
                val articlesWithReadStatus = articles.map { article ->
                    if (_readRecords.value.containsKey(article.topic)) {
                        article.copy(isRead = true)
                    } else {
                        article
                    }
                }

                val sortedArticles = articlesWithReadStatus.sortedWith(compareBy({ it.timestamp }, { it.topic }))
                NewsSource(name = sourceName, articles = sortedArticles)
            }.sortedBy { it.name }

            withContext(Dispatchers.Main) {
                _sources.value = tempSources
            }
        }
    }

    fun markAsRead(articleID: UUID) {
        viewModelScope.launch(Dispatchers.Main) {
            val newSources = _sources.value.map { source ->
                val newArticles = source.articles.map { article ->
                    if (article.id == articleID && !article.isRead) {
                        _readRecords.value = _readRecords.value + (article.topic to Date().time)
                        saveReadRecords()
                        article.copy(isRead = true)
                    } else {
                        article
                    }
                }
                source.copy(articles = newArticles)
            }
            _sources.value = newSources
        }
    }

    fun markAsUnread(articleID: UUID) {
        viewModelScope.launch(Dispatchers.Main) {
            val newSources = _sources.value.map { source ->
                val newArticles = source.articles.map { article ->
                    if (article.id == articleID && article.isRead) {
                        _readRecords.value = _readRecords.value - article.topic
                        saveReadRecords()
                        article.copy(isRead = false)
                    } else {
                        article
                    }
                }
                source.copy(articles = newArticles)
            }
            _sources.value = newSources
        }
    }

    fun markAllAboveAsRead(articleID: UUID, inVisibleList: List<Article>) {
        viewModelScope.launch {
            val pivotIndex = inVisibleList.indexOfFirst { it.id == articleID }
            if (pivotIndex > 0) {
                inVisibleList.subList(0, pivotIndex).forEach { article ->
                    if (!article.isRead) markAsRead(article.id)
                }
            }
        }
    }

    fun markAllBelowAsRead(articleID: UUID, inVisibleList: List<Article>) {
        viewModelScope.launch {
            val pivotIndex = inVisibleList.indexOfFirst { it.id == articleID }
            if (pivotIndex != -1 && pivotIndex < inVisibleList.size - 1) {
                inVisibleList.subList(pivotIndex + 1, inVisibleList.size).forEach { article ->
                    if (!article.isRead) markAsRead(article.id)
                }
            }
        }
    }

    fun findNextUnread(afterId: UUID, inSource: String?): ArticleWithSource? {
        val list: List<ArticleWithSource> = if (inSource != null) {
            _sources.value.find { it.name == inSource }
                ?.articles
                ?.filter { !it.isRead }
                ?.map { ArticleWithSource(it, inSource) }
                ?: emptyList()
        } else {
            allArticlesSortedForDisplay.value.filter { !it.article.isRead }
        }

        if (list.isEmpty()) return null

        val currentIndex = list.indexOfFirst { it.article.id == afterId }

        return if (currentIndex == -1) {
            list.first()
        } else {
            val nextIndex = (currentIndex + 1) % list.size
            list[nextIndex]
        }
    }
}

package com.sskeysskey.onews

import android.app.Application
import android.app.NotificationChannel
import android.app.NotificationManager
import android.content.Context
import android.os.Build
import com.sskeysskey.onews.SubscriptionManager

class ONewsApplication : Application() {

    companion object {
        const val BADGE_NOTIFICATION_CHANNEL_ID = "onews_badge_channel"
    }

    override fun onCreate() {
        super.onCreate()
        // 初始化订阅管理（关键修复）
        SubscriptionManager.init(applicationContext)

        createNotificationChannels()
    }

    private fun createNotificationChannels() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val badgeChannel = NotificationChannel(
                BADGE_NOTIFICATION_CHANNEL_ID,
                "App Badge Notifications",
                NotificationManager.IMPORTANCE_DEFAULT
            ).apply {
                description = "Channel used to show the unread count on the app icon."
                setShowBadge(true) // 允许此渠道的通知显示角标
            }

            val notificationManager = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
            notificationManager.createNotificationChannel(badgeChannel)
        }
    }
}

package com.sskeysskey.onews

import android.content.Context
import com.sskeysskey.onews.ApiClient
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.io.File
import java.io.FileInputStream
import java.io.FileOutputStream
import java.io.IOException
import java.security.MessageDigest

class ResourceManager(
    private val context: Context,
    private val externalScope: CoroutineScope
) {
    private val _isSyncing = MutableStateFlow(false)
    val isSyncing = _isSyncing.asStateFlow()

    private val _syncMessage = MutableStateFlow("启动中...")
    val syncMessage = _syncMessage.asStateFlow()

    private val _isDownloading = MutableStateFlow(false)
    val isDownloading = _isDownloading.asStateFlow()

    private val _downloadProgress = MutableStateFlow(0.0f)
    val downloadProgress = _downloadProgress.asStateFlow()

    private val _progressText = MutableStateFlow("")
    val progressText = _progressText.asStateFlow()

    private val documentsDirectory: File = context.filesDir
    private val apiService = ApiClient.apiService

    fun checkAndDownloadUpdates() {
        externalScope.launch {
            try {
                _isSyncing.value = true
                _isDownloading.value = false
                _syncMessage.value = "正在检查更新..."
                _progressText.value = ""
                _downloadProgress.value = 0.0f

                val serverVersion = apiService.getServerVersion()
                val localFiles = getLocalFiles()

                _syncMessage.value = "正在清理旧资源..."
                val validServerFiles = serverVersion.files.map { it.name }.toSet()
                val filesToDelete = localFiles.filterNot { validServerFiles.contains(it) }
                val oldNewsItemsToDelete = filesToDelete.filter {
                    it.startsWith("onews_") || it.startsWith("news_images_")
                }

                if (oldNewsItemsToDelete.isNotEmpty()) {
                    println("发现需要清理的过时资源: $oldNewsItemsToDelete")
                    oldNewsItemsToDelete.forEach { itemName ->
                        File(documentsDirectory, itemName).deleteRecursively()
                        println("🗑️ 已成功删除: $itemName")
                    }
                } else {
                    println("本地资源无需清理。")
                }

                val downloadTasks = mutableListOf<Pair<FileInfo, Boolean>>()
                val jsonFilesFromServer = serverVersion.files.filter { it.type == "json" }
                val imageDirsFromServer = serverVersion.files.filter { it.type == "images" }

                jsonFilesFromServer.forEach { jsonInfo ->
                    val localFile = File(documentsDirectory, jsonInfo.name)
                    val correspondingImageDirName = "news_images_" + jsonInfo.name.substringAfterLast('_').removeSuffix(".json")

                    if (localFile.exists()) {
                        val serverMD5 = jsonInfo.md5
                        val localMD5 = calculateMD5(localFile)
                        if (serverMD5 != null && serverMD5 != localMD5) {
                            println("MD5不匹配: ${jsonInfo.name}。计划更新。")
                            downloadTasks.add(jsonInfo to false) // full download
                            serverVersion.files.find { it.name == correspondingImageDirName }?.let {
                                downloadTasks.add(it to true) // incremental
                            }
                        }
                    } else {
                        println("新文件: ${jsonInfo.name}。计划下载。")
                        downloadTasks.add(jsonInfo to false)
                        serverVersion.files.find { it.name == correspondingImageDirName }?.let {
                            downloadTasks.add(it to false)
                        }
                    }
                }

                imageDirsFromServer.forEach { dirInfo ->
                    val localDir = File(documentsDirectory, dirInfo.name)
                    if (!localDir.exists() || !localDir.isDirectory) {
                        println("缺失图片目录，准备补齐下载: ${dirInfo.name}")
                        if (downloadTasks.none { it.first.name == dirInfo.name }) {
                            downloadTasks.add(dirInfo to false)
                        }
                    }
                }

                if (downloadTasks.isEmpty()) {
                    _syncMessage.value = "已是最新"
                    delay(500)
                    _isSyncing.value = false
                    return@launch
                }

                println("需要处理的任务列表: ${downloadTasks.map { it.first.name }}")

                _isDownloading.value = true
                val totalTasks = downloadTasks.count()

                downloadTasks.forEachIndexed { index, task ->
                    _progressText.value = "${index + 1}/$totalTasks"
                    _downloadProgress.value = (index + 1).toFloat() / totalTasks.toFloat()

                    val (fileInfo, isIncremental) = task
                    when {
                        fileInfo.type == "json" -> {
                            _syncMessage.value = "正在下载文件: ${fileInfo.name}..."
                            downloadSingleFile(fileInfo.name)
                        }
                        fileInfo.type == "images" && !isIncremental -> {
                            _syncMessage.value = "正在处理目录: ${fileInfo.name}..."
                            downloadDirectory(fileInfo.name)
                        }
                        fileInfo.type == "images" && isIncremental -> {
                            _syncMessage.value = "正在处理目录: ${fileInfo.name}..."
                            downloadDirectoryIncrementally(fileInfo.name)
                        }
                        else -> println("警告: 遇到未知的任务类型 '${fileInfo.type}'，跳过。")
                    }
                }

                _isDownloading.value = false
                _syncMessage.value = "更新完成！"
                _progressText.value = ""
                delay(1000)
                _isSyncing.value = false

            } catch (e: Exception) {
                _isSyncing.value = false
                _isDownloading.value = false
                e.printStackTrace()
                throw e
            }
        }
    }

    fun checkAndDownloadAllNewsManifests() {
        externalScope.launch {
            try {
                _isSyncing.value = true
                _isDownloading.value = false
                _syncMessage.value = "正在获取新闻清单列表..."
                _progressText.value = ""
                _downloadProgress.value = 0.0f

                val serverVersion = apiService.getServerVersion()
                val allJsonInfos = serverVersion.files
                    .filter { it.type == "json" && it.name.startsWith("onews_") }
                    .sortedBy { it.name }

                if (allJsonInfos.isEmpty()) {
                    println("服务器上未找到任何 'onews_*.json' 文件。")
                    _isSyncing.value = false
                    return@launch
                }

                val tasksToDownload = allJsonInfos.filter { jsonInfo ->
                    val localFile = File(documentsDirectory, jsonInfo.name)
                    if (localFile.exists()) {
                        val serverMD5 = jsonInfo.md5
                        val localMD5 = calculateMD5(localFile)
                        serverMD5 != null && serverMD5 != localMD5
                    } else {
                        true
                    }
                }

                if (tasksToDownload.isEmpty()) {
                    _syncMessage.value = "新闻清单已是最新。"
                    delay(500)
                    _isSyncing.value = false
                    return@launch
                }

                _isDownloading.value = true
                val total = tasksToDownload.count()
                tasksToDownload.forEachIndexed { index, info ->
                    _progressText.value = "${index + 1}/$total"
                    _downloadProgress.value = (index + 1).toFloat() / total.toFloat()
                    _syncMessage.value = "正在下载: ${info.name}..."
                    downloadSingleFile(info.name)
                }

                _isDownloading.value = false
                _syncMessage.value = "清单更新完成！"
                _progressText.value = ""
                delay(500)
                _isSyncing.value = false

            } catch (e: Exception) {
                _isSyncing.value = false
                _isDownloading.value = false
                e.printStackTrace()
                throw e
            }
        }
    }

    private suspend fun downloadSingleFile(filename: String) = withContext(Dispatchers.IO) {
        val response = apiService.downloadFile("download?filename=$filename")
        if (response.isSuccessful) {
            response.body()?.let { body ->
                val destinationFile = File(documentsDirectory, filename)
                try {
                    body.byteStream().use { input ->
                        FileOutputStream(destinationFile).use { output ->
                            input.copyTo(output)
                        }
                    }
                } catch (e: IOException) {
                    e.printStackTrace()
                }
            }
        }
    }

    private suspend fun downloadDirectory(directoryName: String) = withContext(Dispatchers.IO) {
        val fileList = apiService.getFileList(directoryName)
        if (fileList.isEmpty()) return@withContext

        val localDir = File(documentsDirectory, directoryName)
        if (localDir.exists()) localDir.deleteRecursively()
        localDir.mkdirs()

        fileList.forEachIndexed { index, remoteFilename ->
            _syncMessage.value = "正在下载新闻图片... (${index + 1}/${fileList.size})"
            val downloadPath = "$directoryName/$remoteFilename"
            downloadSingleFile(downloadPath)
        }
    }

    private suspend fun downloadDirectoryIncrementally(directoryName: String) =
        withContext(Dispatchers.IO) {
            val remoteFileList = apiService.getFileList(directoryName).toSet()
            if (remoteFileList.isEmpty()) return@withContext

            val localDir = File(documentsDirectory, directoryName)
            localDir.mkdirs()

            val localFileSet = localDir.listFiles()?.map { it.name }?.toSet() ?: emptySet()
            val filesToDownload = remoteFileList - localFileSet

            if (filesToDownload.isEmpty()) {
                println("目录 $directoryName 无需增量下载，文件已同步。")
                return@withContext
            }

            filesToDownload.forEachIndexed { index, remoteFilename ->
                _syncMessage.value = "下载新图片... (${index + 1}/${filesToDownload.size})"
                val downloadPath = "$directoryName/$remoteFilename"
                downloadSingleFile(downloadPath)
            }
        }

    private fun getLocalFiles(): List<String> {
        return documentsDirectory.listFiles()?.map { it.name } ?: emptyList()
    }

    private fun calculateMD5(file: File): String? {
        return try {
            val md = MessageDigest.getInstance("MD5")
            FileInputStream(file).use { fis ->
                val buffer = ByteArray(8192)
                var numRead: Int
                while (fis.read(buffer).also { numRead = it } != -1) {
                    md.update(buffer, 0, numRead)
                }
            }
            md.digest().joinToString("") { "%02x".format(it) }
        } catch (e: Exception) {
            e.printStackTrace()
            null
        }
    }
}

