@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun ArticleListContent(
    navController: NavController,
    title: String,
    articlesWithSource: List<ArticleWithSource>,
    viewModel: NewsViewModel,
    isAllArticles: Boolean
) {
    var filterMode by remember { mutableStateOf(ArticleFilterMode.Unread) }
    var searchText by remember { mutableStateOf("") }
    var isSearching by remember { mutableStateOf(false) }

    val filteredArticles = remember(articlesWithSource, filterMode, searchText, isSearching) {
        val baseList = if (searchText.isNotBlank() && isSearching) {
            articlesWithSource.filter {
                it.article.topic.contains(searchText, ignoreCase = true)
            }
        } else {
            articlesWithSource.filter {
                if (filterMode == ArticleFilterMode.Unread) !it.article.isRead else it.article.isRead
            }
        }
        baseList.groupBy { it.article.timestamp }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text(title) },
                navigationIcon = {
                    IconButton(onClick = { navController.popBackStack() }) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
                    }
                },
                actions = {
                    IconButton(onClick = {
                        isSearching = !isSearching
                        if (!isSearching) searchText = ""
                    }) {
                        Icon(Icons.Default.Search, contentDescription = "Search")
                    }
                }
            )
        },
        bottomBar = {
            if (!isSearching) {
                val unreadCount = articlesWithSource.count { !it.article.isRead }
                val readCount = articlesWithSource.count { it.article.isRead }
                SegmentedControl(
                    filterMode = filterMode,
                    unreadCount = unreadCount,
                    readCount = readCount,
                    onFilterChanged = { filterMode = it }
                )
            }
        }
    ) { paddingValues ->
        Column(modifier = Modifier.padding(paddingValues)) {
            if (isSearching) {
                OutlinedTextField(
                    value = searchText,
                    onValueChange = { searchText = it },
                    label = { Text("搜索标题关键字") },
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp, vertical = 8.dp),
                    singleLine = true
                )
            }

            if (filteredArticles.isEmpty()) {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    Text("没有文章", color = Color.Gray)
                }
            } else {
                LazyColumn(
                    contentPadding = PaddingValues(horizontal = 8.dp, vertical = 8.dp),
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    filteredArticles.keys.sortedDescending().forEach { timestamp ->
                        item {
                            Text(
                                text = formatTimestamp(timestamp),
                                style = MaterialTheme.typography.titleMedium,
                                modifier = Modifier.padding(start = 8.dp, top = 16.dp, bottom = 8.dp),
                                color = MaterialTheme.colorScheme.primary
                            )
                        }
                        items(filteredArticles[timestamp] ?: emptyList(), key = { it.article.id }) { item ->
                            ArticleRowCard(
                                article = item.article,
                                sourceName = if (isAllArticles) item.sourceName else null,
                                onClick = {
                                    val fromContext = if (isAllArticles) "all" else "source"
                                    navController.navigate("article_container/${item.article.id}/${item.sourceName}/$fromContext")
                                }
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun SegmentedControl(
    filterMode: ArticleFilterMode,
    unreadCount: Int,
    readCount: Int,
    onFilterChanged: (ArticleFilterMode) -> Unit
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(16.dp),
        horizontalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        val selectedContainer = MaterialTheme.colorScheme.primary
        val selectedContent = MaterialTheme.colorScheme.onPrimary
        val unselectedContainer = MaterialTheme.colorScheme.surfaceVariant
        val unselectedContent = MaterialTheme.colorScheme.onSurfaceVariant

        val unreadSelected = filterMode == ArticleFilterMode.Unread
        val readSelected = filterMode == ArticleFilterMode.Read

        FilledTonalButton(
            onClick = { onFilterChanged(ArticleFilterMode.Unread) },
            modifier = Modifier
                .weight(1f)
                .clip(RoundedCornerShape(topStart = 12.dp, bottomStart = 12.dp)),
            colors = ButtonDefaults.filledTonalButtonColors(
                containerColor = if (unreadSelected) selectedContainer else unselectedContainer,
                contentColor = if (unreadSelected) selectedContent else unselectedContent
            )
        ) {
            Text("Unread ($unreadCount)")
        }

        FilledTonalButton(
            onClick = { onFilterChanged(ArticleFilterMode.Read) },
            modifier = Modifier
                .weight(1f)
                .clip(RoundedCornerShape(topEnd = 12.dp, bottomEnd = 12.dp)),
            colors = ButtonDefaults.filledTonalButtonColors(
                containerColor = if (readSelected) selectedContainer else unselectedContainer,
                contentColor = if (readSelected) selectedContent else unselectedContent
            )
        ) {
            Text("Read ($readCount)")
        }
    }
}

@Composable
private fun ArticleRowCard(
    article: Article,
    sourceName: String?,
    onClick: () -> Unit
) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .clickable(onClick = onClick),
        colors = CardDefaults.cardColors(
            containerColor = MaterialTheme.colorScheme.surfaceVariant
        ),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
    ) {
        Column(modifier = Modifier.padding(12.dp)) {
            sourceName?.let {
                Text(
                    text = it.replace("_", " "),
                    style = MaterialTheme.typography.bodySmall,
                    color = Color.Gray
                )
                Spacer(modifier = Modifier.height(4.dp))
            }
            Text(
                text = article.topic,
                style = MaterialTheme.typography.titleMedium,
                fontWeight = FontWeight.SemiBold,
                color = if (article.isRead) Color.Gray else MaterialTheme.colorScheme.onSurface,
                maxLines = 3,
                overflow = TextOverflow.Ellipsis
            )
        }
    }
}

private fun formatTimestamp(timestamp: String): String {
    return try {
        val inputFormat = SimpleDateFormat("yyMMdd", Locale.CHINA)
        val date = inputFormat.parse(timestamp)
        val outputFormat = SimpleDateFormat("yyyy年M月d日, EEEE", Locale.CHINA)
        date?.let { outputFormat.format(it) } ?: timestamp
    } catch (e: Exception) {
        timestamp
    }
}

package com.sskeysskey.onews

import android.app.Application
import android.content.Context
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.viewModelScope
import com.google.gson.Gson
import com.google.gson.annotations.SerializedName
import com.google.gson.reflect.TypeToken
import com.sskeysskey.onews.SubscriptionManager
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.io.File
import java.util.Date
import java.util.UUID

// 文章模型
// 增强对 GSON 反序列化的容错：
// 1) 为可缺失字段提供安全默认值（包括 url、images、id、isRead、timestamp）。
// 2) 将 images 默认值改为 emptyList()，并允许 GSON 将 null 解析为 null 后由默认值接管。
// 3) url 在 JSON 中有的源缺失，因此设为可空并提供默认 null。
data class Article(
    @SerializedName("topic") val topic: String,
    @SerializedName("article") val articleContent: String,
    @SerializedName("images") val images: List<String> = emptyList(),
    @SerializedName("url") val url: String? = null,
    // 以下字段即使 JSON 完全缺失，也会有默认值，避免 copy 调用时出现空参
    val id: UUID = UUID.randomUUID(),
    val isRead: Boolean = false,
    val timestamp: String = ""
)

// 用于 allArticlesSortedForDisplay 的包装类
data class ArticleWithSource(
    val article: Article,
    val sourceName: String
)

class NewsViewModelFactory(private val application: Application) : ViewModelProvider.Factory {
    override fun <T : ViewModel> create(modelClass: Class<T>): T {
        if (modelClass.isAssignableFrom(NewsViewModel::class.java)) {
            @Suppress("UNCHECKED_CAST")
            return NewsViewModel(application) as T
        }
        throw IllegalArgumentException("Unknown ViewModel class")
    }
}

class NewsViewModel(application: Application) : AndroidViewModel(application) {
    private val gson = Gson()
    private val documentsDirectory: File = application.filesDir
    private val badgeManager = AppBadgeManager(application)

    private val readPrefs = application.getSharedPreferences("ReadRecords", Context.MODE_PRIVATE)

    // --- StateFlows for UI ---
    private val _sources = MutableStateFlow<List<NewsSource>>(emptyList())
    val sources = _sources.asStateFlow()

    private val _readRecords = MutableStateFlow<Map<String, Long>>(emptyMap())

    val allArticlesSortedForDisplay = combine(_sources, _readRecords) { sources, _ ->
        sources.flatMap { source ->
            source.articles.map { article ->
                ArticleWithSource(article = article, sourceName = source.name)
            }
        }.sortedWith(compareBy({ it.article.timestamp }, { it.article.topic }))
    }.stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptyList())

    val totalUnreadCount = combine(_sources, _readRecords) { sources, _ ->
        sources.sumOf { source -> source.articles.count { !it.isRead } }
    }.stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), 0)

    init {
        loadReadRecords()
        viewModelScope.launch {
            totalUnreadCount.collect { count ->
                badgeManager.updateBadge(count)
            }
        }
    }

    private fun loadReadRecords() {
        val map = mutableMapOf<String, Long>()
        readPrefs.all.forEach { (key, value) ->
            if (value is Long) {
                map[key] = value
            }
        }
        _readRecords.value = map
    }

    private fun saveReadRecords() {
        val editor = readPrefs.edit()
        editor.clear()
        _readRecords.value.forEach { (key, value) ->
            editor.putLong(key, value)
        }
        editor.apply()
    }

    fun loadNews() {
        viewModelScope.launch(Dispatchers.IO) {
            val subscribed = SubscriptionManager.subscribedSources.value
            if (subscribed.isEmpty()) {
                withContext(Dispatchers.Main) { _sources.value = emptyList() }
                return@launch
            }

            val allFiles = documentsDirectory.listFiles { _, name ->
                name.startsWith("onews_") && name.endsWith(".json")
            } ?: run {
                withContext(Dispatchers.Main) { _sources.value = emptyList() }
                return@launch
            }

            val allArticlesBySource = mutableMapOf<String, MutableList<Article>>()
            val articleType = object : TypeToken<Map<String, List<Article>>>() {}.type

            for (file in allFiles) {
                val timestamp = file.name.substringAfter("onews_").substringBefore(".json")
                try {
                    val jsonString = file.readText()
                    val decoded: Map<String, List<Article>> = gson.fromJson(jsonString, articleType)

                    decoded.forEach { (sourceName, articles) ->
                        if (subscribed.contains(sourceName)) {

                            // 标准化每篇文章，确保 id 非空、images 非空列表、timestamp 写入
                            val normalized = articles.map { a ->
                                val safeId = a.id ?: UUID.randomUUID()
                                val safeImages = a.images ?: emptyList()
                                // 用 copy 只改必要字段，避免把 null 传播到非空参数
                                a.copy(
                                    id = safeId,
                                    images = safeImages,
                                    timestamp = timestamp
                                )
                            }

                            allArticlesBySource.getOrPut(sourceName) { mutableListOf() }.addAll(normalized)
                        }
                    }
                } catch (e: Exception) {
                    e.printStackTrace()
                    println("解析 ${file.name} 失败: ${e.message}")
                }
            }

            val tempSources = allArticlesBySource.map { (sourceName, articles) ->
                val articlesWithReadStatus = articles.map { article ->
                    if (_readRecords.value.containsKey(article.topic)) {
                        article.copy(isRead = true)
                    } else {
                        article
                    }
                }

                val sortedArticles = articlesWithReadStatus.sortedWith(compareBy({ it.timestamp }, { it.topic }))
                NewsSource(name = sourceName, articles = sortedArticles)
            }.sortedBy { it.name }

            withContext(Dispatchers.Main) {
                _sources.value = tempSources
            }
        }
    }

    fun markAsRead(articleID: UUID) {
        viewModelScope.launch(Dispatchers.Main) {
            val newSources = _sources.value.map { source ->
                val newArticles = source.articles.map { article ->
                    if (article.id == articleID && !article.isRead) {
                        _readRecords.value = _readRecords.value + (article.topic to Date().time)
                        saveReadRecords()
                        article.copy(isRead = true)
                    } else {
                        article
                    }
                }
                source.copy(articles = newArticles)
            }
            _sources.value = newSources
        }
    }

    fun markAsUnread(articleID: UUID) {
        viewModelScope.launch(Dispatchers.Main) {
            val newSources = _sources.value.map { source ->
                val newArticles = source.articles.map { article ->
                    if (article.id == articleID && article.isRead) {
                        _readRecords.value = _readRecords.value - article.topic
                        saveReadRecords()
                        article.copy(isRead = false)
                    } else {
                        article
                    }
                }
                source.copy(articles = newArticles)
            }
            _sources.value = newSources
        }
    }

    fun markAllAboveAsRead(articleID: UUID, inVisibleList: List<Article>) {
        viewModelScope.launch {
            val pivotIndex = inVisibleList.indexOfFirst { it.id == articleID }
            if (pivotIndex > 0) {
                inVisibleList.subList(0, pivotIndex).forEach { article ->
                    if (!article.isRead) markAsRead(article.id)
                }
            }
        }
    }

    fun markAllBelowAsRead(articleID: UUID, inVisibleList: List<Article>) {
        viewModelScope.launch {
            val pivotIndex = inVisibleList.indexOfFirst { it.id == articleID }
            if (pivotIndex != -1 && pivotIndex < inVisibleList.size - 1) {
                inVisibleList.subList(pivotIndex + 1, inVisibleList.size).forEach { article ->
                    if (!article.isRead) markAsRead(article.id)
                }
            }
        }
    }

    fun findNextUnread(afterId: UUID, inSource: String?): ArticleWithSource? {
        val list: List<ArticleWithSource> = if (inSource != null) {
            _sources.value.find { it.name == inSource }
                ?.articles
                ?.filter { !it.isRead }
                ?.map { ArticleWithSource(it, inSource) }
                ?: emptyList()
        } else {
            allArticlesSortedForDisplay.value.filter { !it.article.isRead }
        }

        if (list.isEmpty()) return null

        val currentIndex = list.indexOfFirst { it.article.id == afterId }

        return if (currentIndex == -1) {
            list.first()
        } else {
            val nextIndex = (currentIndex + 1) % list.size
            list[nextIndex]
        }
    }
}

package com.sskeysskey.onews

import android.app.Application
import androidx.compose.animation.*
import androidx.compose.foundation.layout.*
