                    value = progress,
                    onValueChange = { playerManager.seek(it) },
                    modifier = Modifier.weight(1f).padding(horizontal = 8.dp)
                )
                Text(duration, style = MaterialTheme.typography.bodySmall)
            }
            Spacer(modifier = Modifier.height(8.dp))

