class NewsViewModel: ObservableObject {
    @Published var sources: [NewsSource] = []

    private let subscriptionManager = SubscriptionManager.shared

    private let readKey = "readTopics"
    private var readRecords: [String: Date] = [:]

    var badgeUpdater: ((Int) -> Void)?
    private var cancellables = Set<AnyCancellable>()

    private var documentsDirectory: URL {
        FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
    }

    var allArticlesSortedForDisplay: [(article: Article, sourceName: String)] {
        let flatList = self.sources.flatMap { source in
            source.articles.map { (article: $0, sourceName: source.name) }
        }

        return flatList.sorted { item1, item2 in
            if item1.article.timestamp != item2.article.timestamp {
                return item1.article.timestamp < item2.article.timestamp
            }
            return item1.article.topic < item2.article.topic
        }
    }

    init() {
        loadReadRecords()
        $sources
            .map { sources in
                sources.flatMap { $0.articles }.filter { !$0.isRead }.count
            }
            .removeDuplicates()
            .sink { [weak self] unreadCount in
                print("检测到未读数变化，准备更新角标: \(unreadCount)")
                self?.badgeUpdater?(unreadCount)
            }
            .store(in: &cancellables)
    }

    private func loadReadRecords() {
        self.readRecords = UserDefaults.standard.dictionary(forKey: readKey) as? [String: Date] ?? [:]
    }

    private func saveReadRecords() {
        UserDefaults.standard.set(self.readRecords, forKey: readKey)
    }

    func loadNews() {
        let subscribed = subscriptionManager.subscribedSources
        if subscribed.isEmpty {
            print("没有订阅任何新闻源。列表将为空。")
            DispatchQueue.main.async {
                self.sources = []
            }
            return
        }
        print("开始加载新闻，订阅源为: \(subscribed)")

        guard let allFileURLs = try? FileManager.default.contentsOfDirectory(at: documentsDirectory, includingPropertiesForKeys: nil) else {
            print("无法读取 Documents 目录。")
            return
        }

        let newsJSONURLs = allFileURLs.filter {
            $0.lastPathComponent.starts(with: "onews_") && $0.pathExtension == "json"
        }

        guard !newsJSONURLs.isEmpty else {
            print("错误：在 Documents 目录中没有找到任何 'onews_*.json' 文件。请先同步资源。")
            return
        }

        var allArticlesBySource = [String: [Article]]()
        let decoder = JSONDecoder()

        for url in newsJSONURLs {
            let fileName = url.deletingPathExtension().lastPathComponent
            guard let timestamp = fileName.components(separatedBy: "_").last, !timestamp.isEmpty else {
                continue
            }

            guard let data = try? Data(contentsOf: url) else {
                continue
            }

            guard let decoded = try? decoder.decode([String: [Article]].self, from: data) else {
                continue
            }

            for (sourceName, articles) in decoded {
                guard subscribed.contains(sourceName) else { continue }

                let articlesWithTimestamp = articles.map { article -> Article in
                    var mutableArticle = article
                    mutableArticle.timestamp = timestamp
                    return mutableArticle
                }
                allArticlesBySource[sourceName, default: []].append(contentsOf: articlesWithTimestamp)
            }
        }

        var tempSources = allArticlesBySource.map { sourceName, articles -> NewsSource in
            let sortedArticles = articles.sorted {
                if $0.timestamp != $1.timestamp {
                    return $0.timestamp < $1.timestamp
                }
                return $0.topic < $1.topic
            }
            return NewsSource(name: sourceName, articles: sortedArticles)
        }
        .sorted { $0.name < $1.name }

        for i in tempSources.indices {
            for j in tempSources[i].articles.indices {
                let article = tempSources[i].articles[j]
                if readRecords.keys.contains(article.topic) {
                    tempSources[i].articles[j].isRead = true
                }
            }
        }

        DispatchQueue.main.async {
            self.sources = tempSources
            print("新闻数据加载/刷新完成！共 \(self.sources.count) 个已订阅来源。")
        }
    }

    func markAsRead(articleID: UUID) {
        DispatchQueue.main.async {
            for i in self.sources.indices {
                if let j = self.sources[i].articles.firstIndex(where: { $0.id == articleID }) {
                    if !self.sources[i].articles[j].isRead {
                        self.sources[i].articles[j].isRead = true
                        let topic = self.sources[i].articles[j].topic
                        self.readRecords[topic] = Date()
                        self.saveReadRecords()
                    }
                    return
                }
            }
        }
    }

    func markAsUnread(articleID: UUID) {
        DispatchQueue.main.async {
            for i in self.sources.indices {
                if let j = self.sources[i].articles.firstIndex(where: { $0.id == articleID }) {
                    if self.sources[i].articles[j].isRead {
                        self.sources[i].articles[j].isRead = false
                        let topic = self.sources[i].articles[j].topic
                        self.readRecords.removeValue(forKey: topic)
                        self.saveReadRecords()
                    }
                    return
                }
            }
        }
    }

    func markAllAboveAsRead(articleID: UUID, inVisibleList visibleArticles: [Article]) {
        DispatchQueue.main.async {
            guard let pivotIndex = visibleArticles.firstIndex(where: { $0.id == articleID }) else { return }
            guard pivotIndex > 0 else { return }
            let articlesAbove = visibleArticles[0..<pivotIndex]
            for article in articlesAbove where !article.isRead {
                self.markAsRead(articleID: article.id)
            }
        }
    }

    func markAllBelowAsRead(articleID: UUID, inVisibleList visibleArticles: [Article]) {
        DispatchQueue.main.async {
            guard let pivotIndex = visibleArticles.firstIndex(where: { $0.id == articleID }) else { return }
            guard pivotIndex < visibleArticles.count - 1 else { return }
            let articlesBelow = visibleArticles[(pivotIndex + 1)...]
            for article in articlesBelow where !article.isRead {
                self.markAsRead(articleID: article.id)
            }
        }
    }

    private func getArticleList(for sourceName: String?) -> [Article] {
        if let name = sourceName, let source = self.sources.first(where: { $0.name == name }) {
            return source.articles
        } else {
            return self.allArticlesSortedForDisplay.map { $0.article }
        }
    }

    var totalUnreadCount: Int {
        sources.flatMap { $0.articles }.filter { !$0.isRead }.count
    }

    func findNextUnread(after id: UUID, inSource sourceName: String?) -> (article: Article, sourceName: String)? {
        let list: [(article: Article, sourceName: String)]

        if let name = sourceName, let source = self.sources.first(where: { $0.name == name }) {
            list = source.articles
                .filter { !$0.isRead }
                .map { (article: $0, sourceName: name) }
        } else {
            list = self.allArticlesSortedForDisplay.filter { !$0.article.isRead }
        }

        guard !list.isEmpty else { return nil }

        guard let currentIndex = list.firstIndex(where: { $0.article.id == id }) else {
            return list.first
        }

        let nextIndex = (currentIndex + 1) % list.count
        return list[nextIndex]
    }

    func findPreviousUnread(before id: UUID, inSource sourceName: String?) -> (article: Article, sourceName: String)? {
        let list: [(article: Article, sourceName: String)]

        if let name = sourceName, let source = sources.first(where: { $0.name == name }) {
            list = source.articles
                .filter { !$0.isRead }
                .map { (article: $0, sourceName: name) }
        } else {
            list = self.allArticlesSortedForDisplay.filter { !$0.article.isRead }
        }

        guard !list.isEmpty else { return nil }

        if let currentIndex = list.firstIndex(where: { $0.article.id == id }), currentIndex > 0 {
            return list[currentIndex - 1]
        }

        return nil
    }
}


struct NewsSource: Identifiable {
    let id = UUID()
    let name: String
    var articles: [Article]

    var unreadCount: Int {
        articles.filter { !$0.isRead }.count
    }
}

struct Article: Identifiable, Codable {
    var id = UUID()
    let topic: String
    let article: String
    let images: [String]

    var isRead: Bool = false
    var timestamp: String = ""

    enum CodingKeys: String, CodingKey {
        case topic, article, images
    }
}

@MainActor
class AppBadgeManager {
    func requestAuthorization() {
        UNUserNotificationCenter.current().requestAuthorization(options: [.badge]) { granted, error in
            if granted {
                print("用户已授予角标权限。")
            } else {
                print("用户未授予角标权限。")
            }
        }
    }

    func updateBadge(count: Int) {
        UNUserNotificationCenter.current().setBadgeCount(count) { error in
            if let error = error {
                print("更新角标失败: \(error.localizedDescription)")
            } else {
                print("应用角标已更新为: \(count)")
            }
        }
    }
}

import SwiftUI

// ==================== 数据模型和枚举 ====================
enum ArticleFilterMode: String, CaseIterable {
    case unread = "Unread"
    case read = "Read"
}

// 公共：搜索输入视图（在导航栏下方显示）
private struct SearchBarInline: View {
    @Binding var text: String
    var onCommit: () -> Void
    var onCancel: () -> Void

    // 焦点绑定
    @FocusState private var isFocused: Bool

    var body: some View {
        HStack(spacing: 8) {
            HStack(spacing: 6) {
                Image(systemName: "magnifyingglass")
                    .foregroundColor(.secondary)
                TextField("搜索标题关键字", text: $text, onCommit: onCommit)
                    .textInputAutocapitalization(.never)
                    .autocorrectionDisabled(true)
                    .submitLabel(.search)
                    .focused($isFocused)
            }
            .padding(10)
            .background(Color(.secondarySystemBackground))
            .cornerRadius(10)

            if !text.isEmpty {
                Button("搜索") { onCommit() }
                    .buttonStyle(.borderedProminent)
            }

            Button("取消") {
                onCancel()
                // 取消时顺便收起键盘
                isFocused = false
            }
            .buttonStyle(.bordered)
        }
        .padding(.horizontal)
        .padding(.top, 8)
        .padding(.bottom, 4)
        .onAppear {
            // 出现时自动聚焦
            DispatchQueue.main.async {
                self.isFocused = true
            }
        }
    }
}

// ==================== 文章卡片视图 ====================
struct ArticleRowCardView: View {
    let article: Article
    let sourceName: String?

    var body: some View {
        VStack(alignment: .leading, spacing: 4) {
            if let name = sourceName {
                Text(name.replacingOccurrences(of: "_", with: " "))
                    .font(.caption)
                    .foregroundColor(.secondary)
            }

            Text(article.topic)
                .font(.system(size: 20, weight: .semibold))
                .foregroundColor(article.isRead ? .secondary : .primary)
                .lineLimit(3)
        }
        .padding(EdgeInsets(top: 12, leading: 12, bottom: 12, trailing: 12))
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(Color.viewBackground)
        .cornerRadius(12)
        .shadow(color: Color.black.opacity(0.08), radius: 4, x: 0, y: 2)
    }
}

// ==================== 单一来源列表 ====================
struct ArticleListView: View {
    let source: NewsSource
    @ObservedObject var viewModel: NewsViewModel

    @State private var filterMode: ArticleFilterMode = .unread

    // 新增：用于跟踪展开的日期分区
    @State private var expandedTimestamps: Set<String> = []

    // 搜索相关状态
    @State private var isSearching: Bool = false
    @State private var searchText: String = ""
    @State private var isSearchActive: Bool = false   // 表示当前是否显示搜索结果

    // 基础过滤（仅按已读/未读）----用于非搜索态
    private var baseFilteredArticles: [Article] {
        source.articles.filter { filterMode == .unread ? !$0.isRead : $0.isRead }
    }

    // 分组（通用，用于非搜索和搜索）
    private func groupedByTimestamp(_ articles: [Article]) -> [String: [Article]] {
        let initial = Dictionary(grouping: articles, by: { $0.timestamp })
        if filterMode == .read {
            return initial.mapValues { Array($0.reversed()) }
        } else {
            return initial
        }
    }

    // 非搜索态分组
    private var groupedArticles: [String: [Article]] {
        groupedByTimestamp(baseFilteredArticles)
    }

    // Section 的日期顺序：已读时降序，未读时升序（通用）
    private func sortedTimestamps(for groups: [String: [Article]]) -> [String] {
        if filterMode == .read {
            return groups.keys.sorted(by: >)
        } else {
            return groups.keys.sorted(by: <)
        }
    }

    // 用于上下文菜单“以上/以下全部已读”的可见列表（非搜索态使用）
    private var filteredArticles: [Article] {
        baseFilteredArticles
    }

    private var unreadCount: Int { source.articles.filter { !$0.isRead }.count }
    private var readCount: Int { source.articles.filter { $0.isRead }.count }

    // 搜索过滤（不受当前 filterMode 限制，合并已读+未读）
    private var searchResults: [Article] {
        guard isSearchActive, !searchText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            return []
        }
        let keyword = searchText.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        // 合并两类
        return source.articles.filter { $0.topic.lowercased().contains(keyword) }
    }

    // 搜索态分组（固定为最新在前）
    private func groupedSearchByTimestamp() -> [String: [Article]] {
        var initial = Dictionary(grouping: searchResults, by: { $0.timestamp })
        // 每个分组内也按“最新在前”排序：假设 source.articles 原本按时间升序，这里反转
        initial = initial.mapValues { Array($0.reversed()) }
        return initial
    }

    // 搜索态的时间戳顺序：固定为降序（最新在前）
    private func sortedSearchTimestamps(for groups: [String: [Article]]) -> [String] {
        return groups.keys.sorted(by: >)
    }

    var body: some View {
        VStack(spacing: 0) {
            if isSearching {
                SearchBarInline(
                    text: $searchText,
                    onCommit: {
                        isSearchActive = !searchText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                    },
                    onCancel: {
                        withAnimation {
                            isSearching = false
                            isSearchActive = false
                            searchText = ""
                        }
                    }
                )
            }

            List {
                if isSearchActive {
                    // 搜索结果区域保持不变，默认全部展开
                    let grouped = groupedSearchByTimestamp()
                    let timestamps = sortedSearchTimestamps(for: grouped)

                    if searchResults.isEmpty {
                        Section {
                            Text("未找到匹配的文章")
                                .foregroundColor(.secondary)
                                .padding(.vertical, 12)
                                .listRowBackground(Color.clear)
                        } header: {
                            Text("搜索结果")
                                .font(.headline)
                                .foregroundColor(.blue.opacity(0.7))
                                .padding(.vertical, 4)
                        }
                    } else {
                        ForEach(timestamps, id: \.self) { timestamp in
                            Section(header:
                                        VStack(alignment: .leading, spacing: 2) {
                                            Text("搜索结果")
                                                .font(.subheadline)
                                                .foregroundColor(.blue.opacity(0.7))
                                            // ==================== 修改点 1/4 ====================
                                            // 在搜索结果的日期右侧添加文章数量
                                            Text("\(formatTimestamp(timestamp)) \(grouped[timestamp]?.count ?? 0)")
                                                .font(.headline)
                                                .foregroundColor(.blue.opacity(0.85))
                                        }
                                        .padding(.vertical, 4)
                            ) {
                                ForEach(grouped[timestamp] ?? []) { article in
                                    NavigationLink(destination: ArticleContainerView(
                                        article: article,
                                        sourceName: source.name,
                                        context: .fromSource(source.name),
                                        viewModel: viewModel
                                    )) {
                                        ArticleRowCardView(article: article, sourceName: nil)
                                    }
                                    .listRowInsets(EdgeInsets(top: 4, leading: 6, bottom: 4, trailing: 6))
                                    .listRowSeparator(.hidden)
                                    .listRowBackground(Color.clear)
                                    .contextMenu {
                                        if article.isRead {
                                            Button { viewModel.markAsUnread(articleID: article.id) }
                                            label: { Label("标记为未读", systemImage: "circle") }
                                        } else {
                                            Button { viewModel.markAsRead(articleID: article.id) }
                                            label: { Label("标记为已读", systemImage: "checkmark.circle") }
                                        }
                                    }
                                }
                            }
                        }
                    }
                } else {
                    // 非搜索结果区域，实现折叠功能
                    let timestamps = sortedTimestamps(for: groupedArticles)
                    ForEach(timestamps, id: \.self) { timestamp in
                        Section {
                            // 修改：仅当分区展开时才显示内容
                            if !expandedTimestamps.contains(timestamp) {
                                ForEach(groupedArticles[timestamp] ?? []) { article in
                                    NavigationLink(destination: ArticleContainerView(
                                        article: article,
                                        sourceName: source.name,
                                        context: .fromSource(source.name),
                                        viewModel: viewModel
                                    )) {
                                        ArticleRowCardView(article: article, sourceName: nil)
                                    }
                                    .listRowInsets(EdgeInsets(top: 4, leading: 6, bottom: 4, trailing: 6))
                                    .listRowSeparator(.hidden)
                                    .listRowBackground(Color.clear)
                                    .contextMenu {
                                        if article.isRead {
                                            Button { viewModel.markAsUnread(articleID: article.id) }
                                            label: { Label("标记为未读", systemImage: "circle") }
                                        } else {
                                            Button { viewModel.markAsRead(articleID: article.id) }
                                            label: { Label("标记为已读", systemImage: "checkmark.circle") }
                                            if filterMode == .unread {
                                                Divider()
                                                Button {
                                                    viewModel.markAllAboveAsRead(articleID: article.id, inVisibleList: self.filteredArticles)
                                                }
                                                label: { Label("以上全部已读", systemImage: "arrow.up.to.line.compact") }

                                                Button {
                                                    viewModel.markAllBelowAsRead(articleID: article.id, inVisibleList: self.filteredArticles)
                                                }
                                                label: { Label("以下全部已读", systemImage: "arrow.down.to.line.compact") }
                                            }
                                        }
                                    }
                                }
                            }
                        } header: {
                            // 修改后的 Header：日期在左，数量靠右、箭头最右
                            HStack(spacing: 8) {
                                // 左侧日期
                                Text(formatTimestamp(timestamp))
                                    .font(.headline)
                                    .foregroundColor(.blue.opacity(0.7))

                                Spacer(minLength: 8)

                                // 数量在箭头左侧
                                Text("\(groupedArticles[timestamp]?.count ?? 0)")
                                    .font(.subheadline)
                                    .foregroundColor(.secondary)

                                // 折叠指示箭头
                                Image(systemName: expandedTimestamps.contains(timestamp) ? "chevron.down" : "chevron.right")
                                    .foregroundColor(.secondary)
                                    .font(.footnote.weight(.semibold))
                            }
                            .padding(.vertical, 4)
                            .contentShape(Rectangle()) // 使整个HStack区域都可点击
                            .onTapGesture {
                                withAnimation(.easeInOut(duration: 0.2)) {
                                    if expandedTimestamps.contains(timestamp) {
                                        expandedTimestamps.remove(timestamp)
                                    } else {
                                        expandedTimestamps.insert(timestamp)
                                    }
                                }
                            }
                        }
                    }
                }
            }
            .listStyle(PlainListStyle())
            .navigationTitle(source.name.replacingOccurrences(of: "_", with: " "))
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) {
                    Button {
                        withAnimation {
                            isSearching.toggle()
                            if !isSearching {
                                isSearchActive = false
                                searchText = ""
                            }
                        }
                    } label: {
                        Image(systemName: "magnifyingglass")
                    }
                    .accessibilityLabel("搜索")
                }
            }

            if !isSearchActive {
                Picker("Filter", selection: $filterMode) {
                    ForEach(ArticleFilterMode.allCases, id: \.self) { mode in
                        let count = (mode == .unread) ? unreadCount : readCount
                        Text("\(mode.rawValue) (\(count))").tag(mode)
                    }
                }
                .pickerStyle(.segmented)
                .padding([.horizontal, .bottom])
            }
        }
        .background(Color.viewBackground.ignoresSafeArea())
    }

    private func formatTimestamp(_ timestamp: String) -> String {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyMMdd"
        guard let date = formatter.date(from: timestamp) else { return timestamp }
        formatter.locale = Locale(identifier: "zh_CN")
        formatter.dateFormat = "yyyy年M月d日, EEEE"
        return formatter.string(from: date)
    }
}

// ==================== 所有文章列表 ====================
struct AllArticlesListView: View {
    @ObservedObject var viewModel: NewsViewModel
    @State private var filterMode: ArticleFilterMode = .unread

    // 搜索相关状态
    @State private var isSearching: Bool = false
    @State private var searchText: String = ""
    @State private var isSearchActive: Bool = false

    // 新增：用于跟踪展开的日期分区（默认全部折叠）
    @State private var expandedTimestamps: Set<String> = []

    // 基础过滤（仅按已读/未读）----用于非搜索态
    private var baseFilteredArticles: [(article: Article, sourceName: String)] {
        viewModel.allArticlesSortedForDisplay.filter { item in
            filterMode == .unread ? !item.article.isRead : item.article.isRead
        }
    }

    // 分组（通用）----用于非搜索态
    private func groupedByTimestamp(_ items: [(article: Article, sourceName: String)]) -> [String: [(article: Article, sourceName: String)]] {
        let initial = Dictionary(grouping: items, by: { $0.article.timestamp })
        if filterMode == .read {
            return initial.mapValues { Array($0.reversed()) }
        } else {
            return initial
        }
    }

    // 非搜索态分组
    private var groupedArticles: [String: [(article: Article, sourceName: String)]] {
        groupedByTimestamp(baseFilteredArticles)
    }

    // Section 顺序（未读升序、已读降序）
    private func sortedTimestamps(for groups: [String: [(article: Article, sourceName: String)]]) -> [String] {
        if filterMode == .read {
            return groups.keys.sorted(by: >)
        } else {
            return groups.keys.sorted(by: <)
        }
    }

    // 用于上下文菜单“以上/以下全部已读”的可见列表（非搜索态使用）
    private var filteredArticles: [(article: Article, sourceName: String)] {
        baseFilteredArticles
    }

    private var totalUnreadCount: Int { viewModel.totalUnreadCount }
    private var totalReadCount: Int { viewModel.sources.flatMap { $0.articles }.filter { $0.isRead }.count }

    // 搜索过滤（全量，合并已读+未读）
    private var searchResults: [(article: Article, sourceName: String)] {
        guard isSearchActive, !searchText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            return []
        }
        let keyword = searchText.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return viewModel.allArticlesSortedForDisplay.filter { $0.article.topic.lowercased().contains(keyword) }
    }

    // 搜索态分组（固定为最新在前）
    private func groupedSearchByTimestamp() -> [String: [(article: Article, sourceName: String)]] {
        var initial = Dictionary(grouping: searchResults, by: { $0.article.timestamp })
        // 每个分组内按最新在前
        initial = initial.mapValues { Array($0.reversed()) }
        return initial
    }

    // 搜索态的时间戳顺序：固定为降序（最新在前）
    private func sortedSearchTimestamps(for groups: [String: [(article: Article, sourceName: String)]]) -> [String] {
        return groups.keys.sorted(by: >)
    }

    var body: some View {
        VStack(spacing: 0) {
            if isSearching {
                SearchBarInline(
                    text: $searchText,
                    onCommit: {
                        isSearchActive = !searchText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                    },
                    onCancel: {
                        withAnimation {
                            isSearching = false
                            isSearchActive = false
                            searchText = ""
                        }
                    }
                )
            }

            List {
                if isSearchActive {
                    // 搜索结果按日期分组显示（固定最新在上）
                    let grouped = groupedSearchByTimestamp()
                    let timestamps = sortedSearchTimestamps(for: grouped)

                    if searchResults.isEmpty {
                        Section {
                            Text("未找到匹配的文章")
                                .foregroundColor(.secondary)
                                .padding(.vertical, 12)
                                .listRowBackground(Color.clear)
                        } header: {
                            Text("搜索结果")
                                .font(.headline)
                                .foregroundColor(.blue.opacity(0.7))
                                .padding(.vertical, 4)
                        }
                    } else {
                        ForEach(timestamps, id: \.self) { timestamp in
                            Section(header:
                                        VStack(alignment: .leading, spacing: 2) {
                                            Text("搜索结果")
                                                .font(.subheadline)
                                                .foregroundColor(.blue.opacity(0.7))
                                            // ==================== 修改点 3/4 ====================
                                            // 在搜索结果的日期右侧添加文章数量
                                            Text("\(formatTimestamp(timestamp)) \(grouped[timestamp]?.count ?? 0)")
                                                .font(.headline)
                                                .foregroundColor(.blue.opacity(0.85))
                                        }
                                        .padding(.vertical, 4)
                            ) {
                                ForEach(grouped[timestamp] ?? [], id: \.article.id) { item in
                                    NavigationLink(destination: ArticleContainerView(
                                        article: item.article,
                                        sourceName: item.sourceName,
                                        context: .fromAllArticles,
                                        viewModel: viewModel
                                    )) {
                                        // 行视图会自动根据 isRead 设置颜色：未读主色、已读灰色
                                        ArticleRowCardView(article: item.article, sourceName: item.sourceName)
                                    }
                                    .listRowInsets(EdgeInsets(top: 4, leading: 6, bottom: 4, trailing: 6))
                                    .listRowSeparator(.hidden)
                                    .listRowBackground(Color.clear)
                                    .contextMenu {
                                        if item.article.isRead {
                                            Button { viewModel.markAsUnread(articleID: item.article.id) }
                                            label: { Label("标记为未读", systemImage: "circle") }
                                        } else {
                                            Button { viewModel.markAsRead(articleID: item.article.id) }
                                            label: { Label("标记为已读", systemImage: "checkmark.circle") }
                                        }
                                        // 搜索态下不显示“以上/以下全部已读”
                                    }
                                }
                            }
                        }
                    }
                } else {
                    // 非搜索态：支持折叠
                    let timestamps = sortedTimestamps(for: groupedArticles)
                    ForEach(timestamps, id: \.self) { timestamp in
                        Section {
                            if !expandedTimestamps.contains(timestamp) {
                                ForEach(groupedArticles[timestamp] ?? [], id: \.article.id) { item in
                                    NavigationLink(destination: ArticleContainerView(
                                        article: item.article,
                                        sourceName: item.sourceName,
                                        context: .fromAllArticles,
                                        viewModel: viewModel
                                    )) {
                                        ArticleRowCardView(article: item.article, sourceName: item.sourceName)
                                    }
                                    .listRowInsets(EdgeInsets(top: 4, leading: 6, bottom: 4, trailing: 6))
                                    .listRowSeparator(.hidden)
                                    .listRowBackground(Color.clear)
                                    .contextMenu {
                                        if item.article.isRead {
                                            Button { viewModel.markAsUnread(articleID: item.article.id) }
                                            label: { Label("标记为未读", systemImage: "circle") }
                                        } else {
                                            Button { viewModel.markAsRead(articleID: item.article.id) }
                                            label: { Label("标记为已读", systemImage: "checkmark.circle") }
                                            if filterMode == .unread {
                                                Divider()
                                                Button {
                                                    let visibleArticleList = self.filteredArticles.map { $0.article }
                                                    viewModel.markAllAboveAsRead(articleID: item.article.id, inVisibleList: visibleArticleList)
                                                }
                                                label: { Label("以上全部已读", systemImage: "arrow.up.to.line.compact") }

                                                Button {
                                                    let visibleArticleList = self.filteredArticles.map { $0.article }
                                                    viewModel.markAllBelowAsRead(articleID: item.article.id, inVisibleList: visibleArticleList)
                                                }
                                                label: { Label("以下全部已读", systemImage: "arrow.down.to.line.compact") }
                                            }
                                        }
                                    }
                                }
                            }
                        } header: {
                            // 修改后的 Header：日期在左，数量靠右、箭头最右
                            HStack(spacing: 8) {
                                // 左侧日期
                                Text(formatTimestamp(timestamp))
                                    .font(.headline)
                                    .foregroundColor(.blue.opacity(0.7))

                                Spacer(minLength: 8)

                                // 数量在箭头左侧
                                Text("\(groupedArticles[timestamp]?.count ?? 0)")
                                    .font(.subheadline)
                                    .foregroundColor(.secondary)

                                // 折叠指示箭头
                                Image(systemName: expandedTimestamps.contains(timestamp) ? "chevron.down" : "chevron.right")
                                    .foregroundColor(.secondary)
                                    .font(.footnote.weight(.semibold))
                            }
                            .padding(.vertical, 4)
                            .contentShape(Rectangle())
                            .onTapGesture {
                                withAnimation(.easeInOut(duration: 0.2)) {
                                    if expandedTimestamps.contains(timestamp) {
                                        expandedTimestamps.remove(timestamp)
                                    } else {
                                        expandedTimestamps.insert(timestamp)
                                    }
                                }
                            }
                        }
                    }
                }
            }
            .listStyle(PlainListStyle())
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) {
                    Button {
                        withAnimation {
                            isSearching.toggle()
                            if !isSearching {
                                isSearchActive = false
                                searchText = ""
                            }
                        }
                    } label: {
                        Image(systemName: "magnifyingglass")
                    }
                    .accessibilityLabel("搜索")
                }
            }

            if !isSearchActive {
                Picker("Filter", selection: $filterMode) {
                    ForEach(ArticleFilterMode.allCases, id: \.self) { mode in
                        let count = (mode == .unread) ? totalUnreadCount : totalReadCount
                        Text("\(mode.rawValue) (\(count))").tag(mode)
                    }
                }
                .pickerStyle(.segmented)
                .padding([.horizontal, .bottom])
            }
        }
        .background(Color.viewBackground.ignoresSafeArea())
    }

    private func formatTimestamp(_ timestamp: String) -> String {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyMMdd"
        guard let date = formatter.date(from: timestamp) else { return timestamp }
        formatter.locale = Locale(identifier: "zh_CN")
        formatter.dateFormat = "yyyy年M月d日, EEEE"
        return formatter.string(from: date)
    }
}

import SwiftUI

struct ArticleContainerView: View {
    let initialArticle: Article
    let navigationContext: NavigationContext

    @ObservedObject var viewModel: NewsViewModel

    @StateObject private var audioPlayerManager = AudioPlayerManager()

    @State private var currentArticle: Article
    @State private var currentSourceName: String

    @State private var liveUnreadCount: Int
    @State private var readArticleIDsInThisSession: Set<UUID> = []

    @State private var showNoNextToast = false
    @State private var isMiniPlayerCollapsed = false

    enum NavigationContext {
        case fromSource(String)
        case fromAllArticles
    }

    private var initialUnreadCount: Int {
        switch navigationContext {
        case .fromAllArticles:
            return viewModel.totalUnreadCount
        case .fromSource(let sourceName):
            return viewModel.sources.first { $0.name == sourceName }?.unreadCount ?? 0
        }
    }

    init(article: Article, sourceName: String, context: NavigationContext, viewModel: NewsViewModel) {
        self.initialArticle = article
        self.navigationContext = context
        self.viewModel = viewModel

        self._currentArticle = State(initialValue: article)
        self._currentSourceName = State(initialValue: sourceName)

        let baseCount: Int
        switch context {
        case .fromAllArticles:
            baseCount = viewModel.totalUnreadCount
        case .fromSource(let name):
            baseCount = viewModel.sources.first { $0.name == name }?.unreadCount ?? 0
        }
        self._liveUnreadCount = State(initialValue: baseCount)
    }

    var body: some View {
        ZStack(alignment: .bottom) {
            ArticleDetailView(
                article: currentArticle,
                sourceName: currentSourceName,
                unreadCount: liveUnreadCount,
                viewModel: viewModel,
                audioPlayerManager: audioPlayerManager,
                // “读取下一篇”按钮：停止并跳转（不自动播放）
                requestNextArticle: {
                    self.switchToNextArticleAndStopAudio()
                }
            )
            .id(currentArticle.id)
            .transition(.asymmetric(
                insertion: .move(edge: .bottom).combined(with: .opacity),
                removal: .move(edge: .top).combined(with: .opacity))
            )

            if showNoNextToast {
                ToastView(message: "该分组内已无更多文章")
            }

            if audioPlayerManager.isPlaybackActive {
                if isMiniPlayerCollapsed {
                    MiniAudioBubbleView(
                        isCollapsed: $isMiniPlayerCollapsed,
                        isPlaying: audioPlayerManager.isPlaying
                    )
                    .padding(.bottom, 10)
                    .transition(.move(edge: .leading).combined(with: .opacity))
                    .zIndex(2)
                } else {
                    AudioPlayerView(
                        playerManager: audioPlayerManager,
                        playNextAndStart: {
                            // 播放器“双箭头”：跳转并自动播放
                            switchToNextArticle(shouldAutoplayNext: true)
                        },
                        toggleCollapse: {
                            withAnimation(.spring(response: 0.3, dampingFraction: 0.85, blendDuration: 0.1)) {
                                isMiniPlayerCollapsed = true
                            }
                        }
                    )
                    .padding(.horizontal)
                    .padding(.bottom, 6)
                    .transition(.move(edge: .bottom).combined(with: .opacity))
                    .zIndex(2)
                }
            }
        }
        .onAppear {
            // 远程“下一曲”（锁屏/控制中心）或耳机上的下一曲按钮
            audioPlayerManager.onNextRequested = {
                // 用户主动请求下一曲：无条件跳转并自动播放
                self.switchToNextArticle(shouldAutoplayNext: true)
            }
            // 自然结束：行为在 AudioPlayerManager.finishNaturally 内部已根据 isAutoPlayEnabled 处理
            audioPlayerManager.onPlaybackFinished = {
                // 已在 manager 内处理，无需重复
            }
        }
        .onDisappear {
            // 离开详情页才彻底停止与反激活会话
            audioPlayerManager.stop()

            if !currentArticle.isRead {
                readArticleIDsInThisSession.insert(currentArticle.id)
            }
            for articleID in readArticleIDsInThisSession {
                viewModel.markAsRead(articleID: articleID)
            }
        }
        .onChange(of: currentArticle.id) { oldValue, _ in
            let oldArticle = viewModel.sources.flatMap { $0.articles }.first { $0.id == oldValue }
            if let oldArticle, !oldArticle.isRead {
                let isNewToSession = !readArticleIDsInThisSession.contains(oldValue)
                if isNewToSession {
                    liveUnreadCount = max(0, liveUnreadCount - 1)
                    readArticleIDsInThisSession.insert(oldValue)
                }
            }
        }
        .background(Color.viewBackground.ignoresSafeArea())
    }

    // MARK: - 新增函数
    private func switchToNextArticleAndStopAudio() {
        audioPlayerManager.stop()

        if let currentInVM = viewModel.sources.flatMap({ $0.articles }).first(where: { $0.id == currentArticle.id }) {
            let wasUnread = !currentInVM.isRead
            let isNewToSession = !readArticleIDsInThisSession.contains(currentArticle.id)
            if wasUnread && isNewToSession {
                readArticleIDsInThisSession.insert(currentArticle.id)
                if liveUnreadCount > 0 {
                    liveUnreadCount -= 1
                }
            }
        }

        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        if let next = viewModel.findNextUnread(after: currentArticle.id, inSource: sourceNameToSearch) {
            if readArticleIDsInThisSession.contains(next.article.id) {
                showToast { shouldShow in self.showNoNextToast = shouldShow }
            } else {
                withAnimation(.easeInOut(duration: 0.4)) {
                    self.currentArticle = next.article
                    self.currentSourceName = next.sourceName
                }
                // 不自动播放
            }
        } else {
            showToast { shouldShow in self.showNoNextToast = shouldShow }
        }
    }

    private func switchToNextArticle(shouldAutoplayNext: Bool) {
        audioPlayerManager.prepareForNextTransition()

        if let currentInVM = viewModel.sources.flatMap({ $0.articles }).first(where: { $0.id == currentArticle.id }) {
            let wasUnread = !currentInVM.isRead
            let isNewToSession = !readArticleIDsInThisSession.contains(currentArticle.id)
            if wasUnread && isNewToSession {
                readArticleIDsInThisSession.insert(currentArticle.id)
                if liveUnreadCount > 0 {
                    liveUnreadCount -= 1
                }
            }
        }

        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        if let next = viewModel.findNextUnread(after: currentArticle.id, inSource: sourceNameToSearch) {
            if readArticleIDsInThisSession.contains(next.article.id) {
                showToast { shouldShow in self.showNoNextToast = shouldShow }
            } else {
                withAnimation(.easeInOut(duration: 0.4)) {
                    self.currentArticle = next.article
                    self.currentSourceName = next.sourceName
                }
                if shouldAutoplayNext {
                    DispatchQueue.main.async {
                        let paragraphs = next.article.article
                            .components(separatedBy: .newlines)
                            .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
                        let fullText = paragraphs.joined(separator: "\n\n")
                        self.audioPlayerManager.startPlayback(text: fullText, title: next.article.topic)
                    }
                }
            }
        } else {
            showToast { shouldShow in self.showNoNextToast = shouldShow }
        }
    }

    private func showToast(setter: @escaping (Bool) -> Void) {
        setter(true)
        DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
            withAnimation {
                setter(false)
            }
        }
    }
}

