                .padding(.vertical, 12)
                .padding(.horizontal, 20)
                .background(Color.black.opacity(0.75))
                .clipShape(Capsule())
                .shadow(radius: 10)

                Spacer()
            }
            .padding(.top, 5)
            .transition(.move(edge: .top).combined(with: .opacity))
            .zIndex(1)
        }
    }
    .toolbar {
        ToolbarItem(placement: .principal) {
            VStack(spacing: 2) {
                Text(sourceName.replacingOccurrences(of: "_", with: " "))
