struct ZoomableImageView: View {
let imageName: String
let timestamp: String
@Binding var isPresented: Bool

@State private var showSaveAlert = false
@State private var saveAlertMessage = ""

private var imagePath: String {
    let documentsDirectory = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
    return documentsDirectory.appendingPathComponent("news_images_\(timestamp)/\(imageName)").path
}

private func loadImage() -> UIImage? {
    return UIImage(contentsOfFile: imagePath)
}

var body: some View {
    ZStack {
        Color.black.edgesIgnoringSafeArea(.all)
        ZoomableScrollView(imageName: imageName, timestamp: timestamp)
        VStack {
            HStack {
                Spacer()
                Button(action: { isPresented = false }) {
                    Image(systemName: "xmark.circle.fill").font(.largeTitle).foregroundColor(.white.opacity(0.7))
                        .background(Color.black.opacity(0.5).clipShape(Circle()))
                }.padding()
            }
            Spacer()
        }
        VStack {
            Spacer()
            HStack {
                Spacer()
                Button(action: saveImageToPhotoLibrary) {
                    Image(systemName: "arrow.down.circle.fill").font(.largeTitle).foregroundColor(.white.opacity(0.7))
                        .background(Color.black.opacity(0.5).clipShape(Circle()))
                }.padding()
            }
        }
    }
    .gesture(DragGesture().onEnded { value in
        if value.translation.height > 100 { isPresented = false }
    })
    .alert(isPresented: $showSaveAlert) { Alert(title: Text(saveAlertMessage)) }
}

private func saveImageToPhotoLibrary() {
    guard let uiImage = loadImage() else {
        saveAlertMessage = "图片加载失败，无法保存"
        showSaveAlert = true
        return
    }

    guard let imageData = uiImage.jpegData(compressionQuality: 1.0) else {
        saveAlertMessage = "图片转换失败"; showSaveAlert = true; return
    }

    let requestAuth: (@escaping (PHAuthorizationStatus) -> Void) -> Void = { callback in
        if #available(iOS 14, *) { PHPhotoLibrary.requestAuthorization(for: .addOnly, handler: callback) }
        else { PHPhotoLibrary.requestAuthorization(callback) }
    }
    requestAuth { status in
        DispatchQueue.main.async {
            switch status {
            case .authorized, .limited:
                PHPhotoLibrary.shared().performChanges {
                    let req = PHAssetCreationRequest.forAsset()
                    req.addResource(with: .photo, data: imageData, options: nil)
                } completionHandler: { success, error in
                    DispatchQueue.main.async {
                        saveAlertMessage = success ? "已保存到相册" : "保存失败：\(error?.localizedDescription ?? "未知错误")"
                        showSaveAlert = true
                    }
                }
            default:
                saveAlertMessage = "没有相册权限，保存失败"; showSaveAlert = true
            }
        }
    }
}
}

struct ZoomableScrollView: UIViewRepresentable {
let imageName: String
let timestamp: String

func makeUIView(context: Context) -> UIScrollView {
    let documentsDirectory = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
    let imagePath = documentsDirectory.appendingPathComponent("news_images_\(timestamp)/\(imageName)").path
    guard let image = UIImage(contentsOfFile: imagePath) else {
        print("ZoomableScrollView 无法加载图片于: \(imagePath)")
        return UIScrollView()
    }

    let scrollView = UIScrollView()
    let imageView = UIImageView(image: image)
    imageView.contentMode = .scaleAspectFit
    imageView.translatesAutoresizingMaskIntoConstraints = false
    scrollView.addSubview(imageView)

    NSLayoutConstraint.activate([
        imageView.widthAnchor.constraint(equalTo: scrollView.widthAnchor),
        imageView.heightAnchor.constraint(equalTo:scrollView.heightAnchor),
        imageView.centerXAnchor.constraint(equalTo: scrollView.centerXAnchor),
        imageView.centerYAnchor.constraint(equalTo: scrollView.centerYAnchor)
    ])

    scrollView.delegate = context.coordinator
    scrollView.maximumZoomScale = 5.0
    scrollView.minimumZoomScale = 1.0
    scrollView.bouncesZoom = true
    scrollView.showsHorizontalScrollIndicator = false
    scrollView.showsVerticalScrollIndicator = false

    context.coordinator.imageView = imageView

    let doubleTapGesture = UITapGestureRecognizer(target: context.coordinator, action: #selector(Coordinator.handleDoubleTap))
    doubleTapGesture.numberOfTapsRequired = 2
    scrollView.addGestureRecognizer(doubleTapGesture)

    return scrollView
}

func updateUIView(_ uiView: UIScrollView, context: Context) {}

func makeCoordinator() -> Coordinator { Coordinator(self) }

class Coordinator: NSObject, UIScrollViewDelegate {
    var parent: ZoomableScrollView
    var imageView: UIImageView?
    init(_ parent: ZoomableScrollView) { self.parent = parent }
    func viewForZooming(in scrollView: UIScrollView) -> UIView? { imageView }
    @objc func handleDoubleTap(_ gesture: UITapGestureRecognizer) {
        guard let scrollView = gesture.view as? UIScrollView else { return }
        if scrollView.zoomScale > scrollView.minimumZoomScale {
            scrollView.setZoomScale(scrollView.minimumZoomScale, animated: true)
        } else {
            let point = gesture.location(in: imageView)
            let zoomRect = zoomRect(for: scrollView, with: point, scale: scrollView.maximumZoomScale / 2)
            scrollView.zoom(to: zoomRect, animated: true)
        }
    }
    private func zoomRect(for scrollView: UIScrollView, with point: CGPoint, scale: CGFloat) -> CGRect {
        let newSize = CGSize(width: scrollView.frame.width / scale, height: scrollView.frame.height / scale)
        let newOrigin = CGPoint(x: point.x - newSize.width / 2.0, y: point.y - newSize.height / 2.0)
        return CGRect(origin: newOrigin, size: newSize)
    }
}
}

import SwiftUI

struct ArticleContainerView: View {
    let initialArticle: Article
    let navigationContext: NavigationContext

    @ObservedObject var viewModel: NewsViewModel

    @StateObject private var audioPlayerManager = AudioPlayerManager()

    @State private var currentArticle: Article
    @State private var currentSourceName: String

    // 去除会话内“未读计数”和“本会话已读集合”，改为实时从 viewModel 读取
    @State private var showNoNextToast = false
    @State private var isMiniPlayerCollapsed = false

    enum NavigationContext {
        case fromSource(String)
        case fromAllArticles
    }

    private var currentUnreadCount: Int {
        switch navigationContext {
        case .fromAllArticles:
            return viewModel.totalUnreadCount
        case .fromSource(let sourceName):
            return viewModel.sources.first { $0.name == sourceName }?.unreadCount ?? 0
        }
    }

    init(article: Article, sourceName: String, context: NavigationContext, viewModel: NewsViewModel) {
        self.initialArticle = article
        self.navigationContext = context
        self.viewModel = viewModel

        self._currentArticle = State(initialValue: article)
        self._currentSourceName = State(initialValue: sourceName)
    }

    var body: some View {
        ZStack(alignment: .bottom) {
            ArticleDetailView(
                article: currentArticle,
                sourceName: currentSourceName,
                unreadCount: currentUnreadCount, // 实时读取
                viewModel: viewModel,
                audioPlayerManager: audioPlayerManager,
                // “读取下一篇”按钮：停止并跳转（不自动播放）
                requestNextArticle: {
                    self.switchToNextArticleAndStopAudio()
                }
            )
            // 关键修复：不要使用 .id(currentArticle.id)，避免触发导航栈重建导致弹回列表
            .transition(.asymmetric(
                insertion: .move(edge: .bottom).combined(with: .opacity),
                removal: .move(edge: .top).combined(with: .opacity))
            )

            if showNoNextToast {
                ToastView(message: "该分组内已无更多文章")
            }

            if audioPlayerManager.isPlaybackActive {
                if isMiniPlayerCollapsed {
                    MiniAudioBubbleView(
                        isCollapsed: $isMiniPlayerCollapsed,
                        isPlaying: audioPlayerManager.isPlaying
                    )
                    .padding(.bottom, 10)
                    .transition(.move(edge: .leading).combined(with: .opacity))
                    .zIndex(2)
                } else {
                    AudioPlayerView(
                        playerManager: audioPlayerManager,
                        playNextAndStart: {
                            // 播放器“双箭头”：跳转并自动播放
                            switchToNextArticle(shouldAutoplayNext: true)
                        },
                        toggleCollapse: {
                            withAnimation(.spring(response: 0.3, dampingFraction: 0.85, blendDuration: 0.1)) {
                                isMiniPlayerCollapsed = true
                            }
                        }
                    )
                    .padding(.horizontal)
                    .padding(.bottom, 6)
                    .transition(.move(edge: .bottom).combined(with: .opacity))
                    .zIndex(2)
                }
            }
        }
        .onAppear {
            audioPlayerManager.onNextRequested = {
                // 用户主动请求下一曲：无条件跳转并自动播放
                self.switchToNextArticle(shouldAutoplayNext: true)
            }
            audioPlayerManager.onPlaybackFinished = {
                // 已在 manager 内部处理
            }
        }
        .onDisappear {
            // 离开详情页时不再批量提交已读；一切即时提交
            audioPlayerManager.stop()
        }
        .background(Color.viewBackground.ignoresSafeArea())
    }

    // MARK: - 新逻辑：先“立即标记已读”，再找下一篇
    private func switchToNextArticleAndStopAudio() {
        audioPlayerManager.stop()

        // 立即设置当前为已读（全局、持久化）
        viewModel.markArticleAsReadAndPersist(currentArticle.id)

        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        if let next = viewModel.nextUnreadAfter(currentID: currentArticle.id, inSourceName: sourceNameToSearch) {
            withAnimation(.easeInOut(duration: 0.4)) {
                self.currentArticle = next.article
                self.currentSourceName = next.sourceName
            }
            // 不自动播放
        } else {
            showToast { shouldShow in self.showNoNextToast = shouldShow }
        }
    }

    private func switchToNextArticle(shouldAutoplayNext: Bool) {
        audioPlayerManager.prepareForNextTransition()

        // 立即设置当前为已读（全局、持久化）
        viewModel.markArticleAsReadAndPersist(currentArticle.id)

        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        if let next = viewModel.nextUnreadAfter(currentID: currentArticle.id, inSourceName: sourceNameToSearch) {
            withAnimation(.easeInOut(duration: 0.4)) {
                self.currentArticle = next.article
                self.currentSourceName = next.sourceName
            }
            if shouldAutoplayNext {
                DispatchQueue.main.async {
                    let paragraphs = next.article.article
                        .components(separatedBy: .newlines)
                        .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
                    let fullText = paragraphs.joined(separator: "\n\n")
                    self.audioPlayerManager.startPlayback(text: fullText, title: next.article.topic)
                }
            }
        } else {
            showToast { shouldShow in self.showNoNextToast = shouldShow }
        }
    }

    private func showToast(setter: @escaping (Bool) -> Void) {
        setter(true)
        DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
            withAnimation {
                setter(false)
            }
        }
    }
}

