struct ArticleContainerView: View {
    let initialArticle: Article
    let navigationContext: NavigationContext

    @ObservedObject var viewModel: NewsViewModel

    @StateObject private var audioPlayerManager = AudioPlayerManager()

    @State private var currentArticle: Article
    @State private var currentSourceName: String

    @State private var showNoNextToast = false
    @State private var isMiniPlayerCollapsed = false

    enum NavigationContext {
        case fromSource(String)
        case fromAllArticles
    }

    private var currentUnreadCount: Int {
        switch navigationContext {
        case .fromAllArticles:
            return viewModel.totalUnreadCount
        case .fromSource(let sourceName):
            return viewModel.sources.first { $0.name == sourceName }?.unreadCount ?? 0
        }
    }

    init(article: Article, sourceName: String, context: NavigationContext, viewModel: NewsViewModel) {
        self.initialArticle = article
        self.navigationContext = context
        self.viewModel = viewModel
        self._currentArticle = State(initialValue: article)
        self._currentSourceName = State(initialValue: sourceName)
    }

    var body: some View {
        ZStack(alignment: .bottom) {
            // 使用一个清晰的背景来承载 NavigationDetectionHelper
            Color.clear
                .background(
                    NavigationDetectionHelper {
                        // 这个回调只在用户真正“返回”时触发
                        handleProperDisappearance()
                    }
                )

            ArticleDetailView(
                article: currentArticle,
                sourceName: currentSourceName,
                unreadCount: currentUnreadCount,
                viewModel: viewModel,
                audioPlayerManager: audioPlayerManager,
                requestNextArticle: {
                    // "读取下一篇"按钮的动作保持不变
                    self.switchToNextArticle(shouldAutoplayNext: false)
                }
            )
            .id(currentArticle.id) // .id 是实现切换动画的关键
            .transition(.asymmetric(
                insertion: .move(edge: .bottom).combined(with: .opacity),
                removal: .move(edge: .top).combined(with: .opacity))
            )

            // Toast 和音频播放器视图保持不变
            if showNoNextToast {
                ToastView(message: "该分组内已无更多文章")
            }

            if audioPlayerManager.isPlaybackActive {
                if isMiniPlayerCollapsed {
                    MiniAudioBubbleView(
                        isCollapsed: $isMiniPlayerCollapsed,
                        isPlaying: audioPlayerManager.isPlaying
                    )
                    .padding(.bottom, 10)
                    .transition(.move(edge: .leading).combined(with: .opacity))
                    .zIndex(2)
                } else {
                    AudioPlayerView(
                        playerManager: audioPlayerManager,
                        playNextAndStart: {
                            switchToNextArticle(shouldAutoplayNext: true)
                        },
                        toggleCollapse: {
                            withAnimation(.spring(response: 0.3, dampingFraction: 0.85, blendDuration: 0.1)) {
                                isMiniPlayerCollapsed = true
                            }
                        }
                    )
                    .padding(.horizontal)
                    .padding(.bottom, 6)
                    .transition(.move(edge: .bottom).combined(with: .opacity))
                    .zIndex(2)
                }
            }
        }
        .onAppear {
            // 远程控制回调
            audioPlayerManager.onNextRequested = {
                self.switchToNextArticle(shouldAutoplayNext: true)
            }
        }
        .onDisappear {
            // onDisappear 现在只负责停止音频，不再处理已读标记
            audioPlayerManager.stop()
        }
        .background(Color.viewBackground.ignoresSafeArea())
    }

    // MARK: - 核心修正：统一的跳转函数

    /// 统一处理切换到下一篇文章的逻辑。
    /// 这个函数现在是所有“下一篇”操作的唯一入口。
    /// - Parameter shouldAutoplayNext: 切换后是否自动开始播放音频。
    private func switchToNextArticle(shouldAutoplayNext: Bool) {
        // 1. 捕获当前文章的信息，因为状态即将改变
        let articleToMarkAsRead = currentArticle

        // 2. 立即将当前文章标记为已读（如果需要）
        // 这是修复 bug 的关键之一：在查找下一篇之前就标记，确保它不会被再次选中
        if !articleToMarkAsRead.isRead {
            viewModel.markAsRead(articleID: articleToMarkAsRead.id)
        }

        // 3. 停止或准备音频播放器
        if shouldAutoplayNext {
            audioPlayerManager.prepareForNextTransition()
        } else {
            audioPlayerManager.stop()
        }

        // 4. 确定搜索范围（来自特定来源还是所有文章）
        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name):
            sourceNameToSearch = name
        case .fromAllArticles:
            sourceNameToSearch = nil
        }

        // 5. 从 ViewModel 查找下一篇未读文章
        // 注意：我们使用 articleToMarkAsRead.id 作为查找的起点
        if let next = viewModel.findNextUnread(after: articleToMarkAsRead.id, inSource: sourceNameToSearch) {
            // 6. 如果找到，执行视图切换动画
            withAnimation(.easeInOut(duration: 0.4)) {
                self.currentArticle = next.article
                self.currentSourceName = next.sourceName
            }

            // 7. 如果需要，在新文章上启动音频播放
            if shouldAutoplayNext {
                DispatchQueue.main.async {
                    let paragraphs = next.article.article
                        .components(separatedBy: .newlines)
                        .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
                    let fullText = paragraphs.joined(separator: "\n\n")
                    self.audioPlayerManager.startPlayback(text: fullText, title: next.article.topic)
                }
            }
        } else {
            // 8. 如果没有更多未读文章，显示提示
            showToast { shouldShow in self.showNoNextToast = shouldShow }
        }
    }

    // MARK: - 新增：处理真实“返回”操作的函数

    /// 当视图确定要从导航堆栈中移除时调用。
    private func handleProperDisappearance() {
        print("视图正在被 pop，确保当前文章 '\(currentArticle.topic)' 已读。")
        // 这是一个安全保障，确保用户通过返回手势离开时，当前文章也被标记为已读。
        if !currentArticle.isRead {
            viewModel.markAsRead(articleID: currentArticle.id)
        }
        // 音频播放器已经在 .onDisappear 中停止了，这里无需重复。
    }

    // MARK: - 辅助函数

    private func showToast(setter: @escaping (Bool) -> Void) {
        setter(true)
        DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
            withAnimation {
                setter(false)
            }
        }
    }
}

