import SwiftUI
import UIKit // 为了使用 UIViewController

// ==================== 新增：用于检测导航返回的辅助工具 ====================

/// 一个包装了 UIViewController 的 SwiftUI 视图，用于访问其 `isMovingFromParent` 属性。
/// 这可以帮助我们精确判断视图是否因为用户点击“返回”或滑动返回手势而被移除。
struct NavigationDetectionHelper: UIViewControllerRepresentable {
    var onDeinit: () -> Void

    func makeUIViewController(context: Context) -> UIViewController {
        // 创建一个带有自定义生命周期回调的轻量级 UIViewController
        return DeinitCallbackViewController(onDeinit: onDeinit)
    }

    func updateUIViewController(_ uiViewController: UIViewController, context: Context) {}

    // 自定义 UIViewController，在 `isMovingFromParent` 为 true 时（即视图被 pop），执行回调
    private class DeinitCallbackViewController: UIViewController {
        let onDeinit: () -> Void

        init(onDeinit: @escaping () -> Void) {
            self.onDeinit = onDeinit
            super.init(nibName: nil, bundle: nil)
        }

        required init?(coder: NSCoder) {
            fatalError("init(coder:) has not been implemented")
        }

        override func viewDidDisappear(_ animated: Bool) {
            super.viewDidDisappear(animated)
            // 当视图控制器从其父控制器（如 NavigationController）中被移除时，执行回调
            if isMovingFromParent {
                onDeinit()
            }
        }
    }
}


