        }
    }
}

import SwiftUI

struct SourceListView: View {
@StateObject private var viewModel = NewsViewModel()
@StateObject private var resourceManager = ResourceManager()
private let badgeManager = AppBadgeManager()

@State private var showErrorAlert = false
@State private var errorMessage = ""

@State private var showAddSourceSheet = false

@Environment(\.scenePhase) private var scenePhase

var body: some View {
    NavigationView {
        ZStack {
            Image("welcome_background")
                .resizable()
                .aspectRatio(contentMode: .fill)
                .ignoresSafeArea()
                .overlay(Color.black.opacity(0.4).ignoresSafeArea())

            Group {
                if viewModel.sources.isEmpty && !resourceManager.isSyncing {
                    VStack(spacing: 20) {
                        Text("您还没有订阅任何新闻源")
                            .font(.headline)
                            .foregroundColor(.white.opacity(0.9))
                        Button(action: { showAddSourceSheet = true }) {
                            Label("点击这里添加", systemImage: "plus.circle.fill")
                                .font(.title2)
                        }
                        .buttonStyle(.bordered)
                    }
                } else {
                    List {
                        ZStack {
                            HStack {
                                Text("ALL")
                                    .font(.system(size: 28, weight: .bold))
                                    .foregroundColor(.white)
                                Spacer()
                                Text("\(viewModel.totalUnreadCount)")
                                    .font(.system(size: 28, weight: .bold))
                                    .foregroundColor(.white.opacity(0.7))
                            }
                            .padding()
                            NavigationLink(destination: AllArticlesListView(viewModel: viewModel)) {
                                EmptyView()
                            }.opacity(0)
                        }
                        .listRowBackground(Color.clear)
                        .listRowSeparator(.hidden)

                        ForEach(viewModel.sources) { source in
                            ZStack {
                                HStack {
                                    Text(source.name)
                                        .fontWeight(.semibold)
                                        .foregroundColor(.white)
                                    Spacer()
                                    Text("\(source.unreadCount)")
                                        .foregroundColor(.white.opacity(0.7))
                                }
                                .padding(.vertical, 8)

                                NavigationLink(destination: ArticleListView(source: source, viewModel: viewModel)) {
                                    EmptyView()
                                }.opacity(0)
                            }
                            .listRowBackground(Color.clear)
                            .listRowSeparator(.hidden)
                        }
                    }
                    .listStyle(.plain)
                    .scrollContentBackground(.hidden)
                    .background(Color.clear)
                }
            }
        }
        .navigationBarTitleDisplayMode(.inline)
        .toolbar {
            ToolbarItem(placement: .navigationBarTrailing) {
                Button(action: {
                    showAddSourceSheet = true
                }) {
                    Image(systemName: "plus")
                        .foregroundColor(.white)
                }
            }

            ToolbarItem(placement: .navigationBarTrailing) {
                Button(action: {
                    Task {
                        await syncResources()
                    }
                }) {
                    Image(systemName: "arrow.clockwise")
                        .foregroundColor(.white)
                }
                .disabled(resourceManager.isSyncing)
            }
        }
    }
    .accentColor(.white)
    .preferredColorScheme(.dark)
    .onAppear {
        let tv = UITableView.appearance()
        tv.backgroundColor = .clear
        tv.separatorStyle = .none

        viewModel.badgeUpdater = badgeManager.updateBadge
        badgeManager.requestAuthorization()

        viewModel.loadNews()
        Task {
            await syncResources()
        }
    }
    .onDisappear {
        // 可选恢复
    }
    .onChange(of: scenePhase) { oldPhase, newPhase in
        // 当应用从前台切换到后台或非激活状态时
        if oldPhase == .active && (newPhase == .inactive || newPhase == .background) {
            // 使用“静默提交”：只更新持久化与角标，不刷新 sources，避免导航栈被重建
            viewModel.commitPendingReadsSilently()

            // 用静默计算得到的未读数更新角标（也可依赖 viewModel.badgeUpdater 内部逻辑）
            let unread = viewModel.totalUnreadCount // 此处使用当前内存态，不触发刷新
            badgeManager.updateBadge(count: unread)

            print("应用进入后台，已静默提交暂存的已读文章并更新角标为: \(unread)")
        }

        // 当应用从后台/非激活回到前台时
        if (oldPhase == .inactive || oldPhase == .background) && newPhase == .active {
            // 将静默提交所反映在 readRecords 中的状态，同步到内存 sources
            // 不会改变当前导航栈，不会强制返回列表
            viewModel.applySilentReadsToSources()
        }
    }
    .sheet(isPresented: $showAddSourceSheet, onDismiss: {
        print("AddSourceView 已关闭，重新加载新闻...")
        viewModel.loadNews()
    }) {
        NavigationView {
            AddSourceView(
                isFirstTimeSetup: false,
                onConfirm: {
                    print("AddSourceView 确定：关闭并刷新")
                    showAddSourceSheet = false
                }
            )
        }
        .preferredColorScheme(.dark)
    }
    .overlay(
        Group {
            if resourceManager.isSyncing {
                VStack(spacing: 15) {
                    if resourceManager.isDownloading {
                        Text(resourceManager.syncMessage)
                            .font(.headline)
                            .foregroundColor(.white)

                        ProgressView(value: resourceManager.downloadProgress)
                            .progressViewStyle(LinearProgressViewStyle(tint: .white))
                            .padding(.horizontal, 50)

                        Text(resourceManager.progressText)
                            .font(.caption)
                            .foregroundColor(.white.opacity(0.8))

                    } else {
                        ProgressView()
                            .progressViewStyle(CircularProgressViewStyle(tint: .white))
                            .scaleEffect(1.5)

                        Text(resourceManager.syncMessage)
                            .padding(.top, 10)
                            .foregroundColor(.white.opacity(0.9))
                    }
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .background(Color.black.opacity(0.6))
                .edgesIgnoringSafeArea(.all)
                .contentShape(Rectangle())
            }
        }
    )
    .alert("", isPresented: $showErrorAlert, actions: {
        Button("好的", role: .cancel) { }
    }, message: {
        Text(errorMessage)
    })
}

private func syncResources() async {
    do {
        try await resourceManager.checkAndDownloadUpdates()
        viewModel.loadNews()
    } catch {
        switch error {
        case is DecodingError:
            print("同步失败 (服务器返回数据格式错误，已静默处理): \(error)")
        case let urlError as URLError where
            urlError.code == .cannotConnectToHost ||
            urlError.code == .timedOut:
            print("同步失败 (无法连接或超时，已静默处理): \(urlError.localizedDescription)")
        default:
            print("同步失败 (客户端或其他问题): \(error)")
            self.errorMessage = "网络异常\n\nPlease click the refresh button ↻ in the upper right corner to try again"
            self.showErrorAlert = true
        }
    }
}
}

import SwiftUI

struct ArticleContainerView: View {
    let initialArticle: Article
    let navigationContext: NavigationContext

    @ObservedObject var viewModel: NewsViewModel

    @StateObject private var audioPlayerManager = AudioPlayerManager()

    @State private var currentArticle: Article
    @State private var currentSourceName: String

    @State private var liveUnreadCount: Int
    // 已移除: @State private var readArticleIDsInThisSession: Set<UUID> = []

    @State private var showNoNextToast = false
    @State private var isMiniPlayerCollapsed = false

    enum NavigationContext {
        case fromSource(String)
        case fromAllArticles
    }

    private var initialUnreadCount: Int {
        switch navigationContext {
        case .fromAllArticles:
            return viewModel.totalUnreadCount
        case .fromSource(let sourceName):
            return viewModel.sources.first { $0.name == sourceName }?.unreadCount ?? 0
        }
    }

    init(article: Article, sourceName: String, context: NavigationContext, viewModel: NewsViewModel) {
        self.initialArticle = article
        self.navigationContext = context
        self.viewModel = viewModel

        self._currentArticle = State(initialValue: article)
        self._currentSourceName = State(initialValue: sourceName)

        let baseCount: Int
        switch context {
        case .fromAllArticles:
            baseCount = viewModel.totalUnreadCount
        case .fromSource(let name):
            baseCount = viewModel.sources.first { $0.name == name }?.unreadCount ?? 0
        }
        self._liveUnreadCount = State(initialValue: baseCount)
    }

    var body: some View {
        ZStack(alignment: .bottom) {
            ArticleDetailView(
                article: currentArticle,
                sourceName: currentSourceName,
                unreadCount: liveUnreadCount,
                viewModel: viewModel,
                audioPlayerManager: audioPlayerManager,
                requestNextArticle: {
                    self.switchToNextArticleAndStopAudio()
                }
            )
            .id(currentArticle.id)
            .transition(.asymmetric(
                insertion: .move(edge: .bottom).combined(with: .opacity),
                removal: .move(edge: .top).combined(with: .opacity))
            )

            if showNoNextToast {
                ToastView(message: "该分组内已无更多文章")
            }

            if audioPlayerManager.isPlaybackActive {
                if isMiniPlayerCollapsed {
                    MiniAudioBubbleView(
                        isCollapsed: $isMiniPlayerCollapsed,
                        isPlaying: audioPlayerManager.isPlaying
                    )
                    .padding(.bottom, 10)
                    .transition(.move(edge: .leading).combined(with: .opacity))
                    .zIndex(2)
                } else {
                    AudioPlayerView(
                        playerManager: audioPlayerManager,
                        playNextAndStart: {
                            switchToNextArticle(shouldAutoplayNext: true)
                        },
                        toggleCollapse: {
                            withAnimation(.spring(response: 0.3, dampingFraction: 0.85, blendDuration: 0.1)) {
                                isMiniPlayerCollapsed = true
                            }
                        }
                    )
                    .padding(.horizontal)
                    .padding(.bottom, 6)
                    .transition(.move(edge: .bottom).combined(with: .opacity))
                    .zIndex(2)
                }
            }
        }
        .onAppear {
            // 修改：视图出现时，在ViewModel中记录当前正在查看的文章ID
            viewModel.currentlyVisibleArticleID = currentArticle.id

            audioPlayerManager.onNextRequested = {
                self.switchToNextArticle(shouldAutoplayNext: true)
            }
            audioPlayerManager.onPlaybackFinished = {
                // 行为已在 AudioPlayerManager 内部处理
            }
        }
        .onDisappear {
            // 修改：视图消失时，清空ViewModel中的记录
            viewModel.currentlyVisibleArticleID = nil

            // 离开详情页，停止播放并提交所有在这个会话中阅读过的文章
            audioPlayerManager.stop()

            // 将当前正在看的、但还未切换走的文章也暂存起来
            _ = viewModel.stageArticleAsRead(articleID: currentArticle.id)

            // 统一提交
            viewModel.commitPendingReads()
        }
        // 已移除 .onChange(of: currentArticle.id) 修饰符，逻辑已合并
        .background(Color.viewBackground.ignoresSafeArea())
    }

    // MARK: - 修改后的函数
    private func switchToNextArticleAndStopAudio() {
        audioPlayerManager.stop()
        switchToNextArticle(shouldAutoplayNext: false)
    }

    private func switchToNextArticle(shouldAutoplayNext: Bool) {
        if shouldAutoplayNext {
            audioPlayerManager.prepareForNextTransition()
        }

        // 在切换前，将当前文章暂存为待读。如果暂存成功（即首次阅读），则更新UI上的未读计数器。
        if viewModel.stageArticleAsRead(articleID: currentArticle.id) {
            if liveUnreadCount > 0 {
                liveUnreadCount -= 1
            }
        }

        let sourceNameToSearch: String?
        switch navigationContext {
        case .fromSource(let name): sourceNameToSearch = name
        case .fromAllArticles: sourceNameToSearch = nil
        }

        if let next = viewModel.findNextUnread(after: currentArticle.id, inSource: sourceNameToSearch) {
            // 检查下一篇文章是否已在本会话中阅读过（即在待提交列表里）。如果是，说明已经循环了一圈。
            if viewModel.isArticlePendingRead(articleID: next.article.id) {
                showToast { shouldShow in self.showNoNextToast = shouldShow }
                audioPlayerManager.stop() // 如果没有下一篇了，也停止播放器
            } else {
                withAnimation(.easeInOut(duration: 0.4)) {
                    self.currentArticle = next.article
                    self.currentSourceName = next.sourceName
                }

                // 修改：切换文章后，同步更新ViewModel中当前可见的文章ID
                viewModel.currentlyVisibleArticleID = next.article.id

                if shouldAutoplayNext {
                    DispatchQueue.main.async {
                        let paragraphs = next.article.article
                            .components(separatedBy: .newlines)
                            .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
                        let fullText = paragraphs.joined(separator: "\n\n")
                        self.audioPlayerManager.startPlayback(text: fullText, title: next.article.topic)
                    }
                }
            }
        } else {
            showToast { shouldShow in self.showNoNextToast = shouldShow }
            audioPlayerManager.stop() // 如果没有下一篇了，也停止播放器
        }
    }

    private func showToast(setter: @escaping (Bool) -> Void) {
        setter(true)
        DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
            withAnimation {
                setter(false)
            }
        }
    }
}

